package proofcounter

import "strconv"

var count int

func Increment(_ realm) int {
	count++
	return count
}

func Render(path string) string {
	return "Count: " + strconv.Itoa(count)
}

package proofcounter

import "testing"

func TestIncrement(cur realm, t *testing.T) {
	val := Increment(cross(cur))
	if val != 1 {
		t.Fatalf("expected 1, got %d", val)
	}
}

package slotswitch

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

const (
	appointmentSeconds = 15 * 60
	maxClinicSeconds   = 24 * 60 * 60
	maxMembers         = 12
	maxIssuedSlots     = 32
)

type slot struct {
	issuer   address
	holder   address
	start    int64
	revision int
	active   bool
}

type plan struct {
	expiry      int64
	size        int
	slots       [3]int
	old         [3]slot
	approved    [3]bool
	settled     bool
	height      int64
	confirmedAt int64
}

type clinic struct {
	issuers        [2]address
	accepted       bool
	draftRevision  int
	startsAt       int64
	endsAt         int64
	cutoff         int64
	members        map[address]string
	enrolled       []address
	slots          map[int]slot
	plans          map[int]*plan
	openByProposer map[address]int
	nextPlanID     int
}

var clinics = make(map[int]*clinic)

func signer(cur realm) address {
	caller := cur.Previous()
	if !caller.IsUserCall() || len(unsafe.OriginSend()) != 0 {
		panic("use a direct wallet call with no attached funds")
	}
	return caller.Address()
}

// Create opens a draft clinic for the two desks to review.
func Create(cur realm, other address, startsAt, endsAt, cutoff int64) int {
	runtime.AssertOriginCall()
	issuer := signer(cur)
	if issuer == "" || other == "" || issuer == other {
		panic("distinct issuers required")
	}
	if now := time.Now().Unix(); cutoff <= now || cutoff > startsAt ||
		endsAt <= startsAt || endsAt-startsAt < appointmentSeconds || endsAt-startsAt > maxClinicSeconds {
		panic("invalid clinic window or cutoff")
	}
	id := len(clinics) + 1
	clinics[id] = &clinic{
		issuers:        [2]address{issuer, other},
		draftRevision:  1,
		startsAt:       startsAt,
		endsAt:         endsAt,
		cutoff:         cutoff,
		members:        make(map[address]string),
		slots:          make(map[int]slot),
		plans:          make(map[int]*plan),
		openByProposer: make(map[address]int),
		nextPlanID:     1,
	}
	return id
}

func Enroll(cur realm, clinicID int, member address, alias string) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireClinic(clinicID)
	if caller != c.issuers[0] || c.accepted || time.Now().Unix() >= c.cutoff {
		panic("only the first issuer may enroll in an open draft")
	}
	alias = strings.TrimSpace(alias)
	if member == "" || c.members[member] != "" || len(c.enrolled) >= maxMembers ||
		len(alias) == 0 || len(alias) > 24 {
		panic("invalid team enrollment")
	}
	for _, ch := range alias {
		if !((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == ' ' || ch == '-') {
			panic("use a short public alias")
		}
	}
	for _, enrolled := range c.enrolled {
		if strings.EqualFold(c.members[enrolled], alias) {
			panic("public alias already in use")
		}
	}
	c.members[member] = alias
	c.enrolled = append(c.enrolled, member)
	c.draftRevision++
}

func Accept(cur realm, clinicID, expectedRevision int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireClinic(clinicID)
	if caller != c.issuers[1] {
		panic("invited issuer required")
	}
	if c.draftRevision != expectedRevision {
		panic("clinic draft changed since preview")
	}
	if time.Now().Unix() >= c.cutoff || len(c.enrolled) < 2 {
		panic("clinic draft expired or has fewer than two teams")
	}
	c.accepted = true
}

func Issue(cur realm, clinicID int, start int64, member address) int {
	runtime.AssertOriginCall()
	issuer := signer(cur)
	c := requireAcceptedClinic(clinicID)
	if issuer != c.issuers[0] && issuer != c.issuers[1] {
		panic("issuer required")
	}
	if start <= time.Now().Unix() || start < c.startsAt || start > c.endsAt-appointmentSeconds ||
		c.members[member] == "" || len(c.slots) >= maxIssuedSlots {
		panic("invalid slot")
	}
	for _, existing := range c.slots {
		overlap := start > existing.start-appointmentSeconds && existing.start > start-appointmentSeconds
		if existing.active && (existing.holder == member || (existing.issuer == issuer && overlap)) {
			panic("active reservation conflicts with slot or holder")
		}
	}
	id := len(c.slots) + 1
	c.slots[id] = slot{issuer: issuer, holder: member, start: start, revision: 1, active: true}
	return id
}

func CancelSlot(cur realm, clinicID, slotID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	s := c.slots[slotID]
	if !s.active || s.issuer != caller {
		panic("active slot issuer required")
	}
	s.active = false
	s.revision++
	c.slots[slotID] = s
}

func Propose(cur realm, clinicID, first, second, third, firstRevision, secondRevision, thirdRevision int, expiry int64) int {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	now := time.Now().Unix()
	if now >= expiry || expiry > c.cutoff || expiry > now+maxClinicSeconds {
		panic("invalid expiry")
	}
	p := &plan{expiry: expiry, size: 2, slots: [3]int{first, second, third}}
	if third != 0 {
		p.size = 3
	}
	if first <= 0 || second <= 0 || first == second || first == third || second == third {
		panic("distinct slots required")
	}
	expected := [3]int{firstRevision, secondRevision, thirdRevision}
	for i := 0; i < p.size; i++ {
		s := c.slots[p.slots[i]]
		if !s.active || expiry >= s.start {
			panic("active future slots required")
		}
		if s.revision != expected[i] {
			panic("slot changed since preview")
		}
		p.old[i] = s
	}
	if p.old[0].holder != caller {
		panic("first holder must propose")
	}
	previousID := c.openByProposer[caller]
	if previousID != 0 {
		if planState(c, c.plans[previousID], now) == "open" {
			panic("withdraw or complete your open proposal")
		}
		delete(c.plans, previousID)
	}
	id := c.nextPlanID
	c.nextPlanID++
	c.plans[id] = p
	c.openByProposer[caller] = id
	return id
}

func Approve(cur realm, clinicID, planID int, approved bool) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	p := readyPlan(c, planID)
	for i := 0; i < p.size; i++ {
		if p.old[i].holder == caller {
			p.approved[i] = approved
			return
		}
	}
	panic("holder required")
}

func Withdraw(cur realm, clinicID, planID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	if c.openByProposer[caller] != planID || planID == 0 {
		panic("open proposal owner required")
	}
	delete(c.openByProposer, caller)
	delete(c.plans, planID)
}

func Settle(cur realm, clinicID, planID int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	c := requireAcceptedClinic(clinicID)
	p := readyPlan(c, planID)
	isHolder := false
	for i := 0; i < p.size; i++ {
		if p.old[i].holder == caller {
			isHolder = true
		}
		if !p.approved[i] {
			panic("all holders must approve")
		}
	}
	if !isHolder {
		panic("holder required")
	}
	for i := 0; i < p.size; i++ {
		c.slots[p.slots[i]] = rotatedSlot(p, i)
	}
	p.settled = true
	p.height = runtime.ChainHeight()
	p.confirmedAt = time.Now().Unix()
	delete(c.openByProposer, p.old[0].holder)
}

func rotatedSlot(p *plan, destination int) slot {
	s := p.old[destination]
	source := (destination + p.size - 1) % p.size
	s.holder = p.old[source].holder
	s.revision++
	return s
}

func requireClinic(id int) *clinic {
	c := clinics[id]
	if c == nil {
		panic("unknown clinic")
	}
	return c
}

func requireAcceptedClinic(id int) *clinic {
	c := requireClinic(id)
	if !c.accepted {
		panic("second issuer has not accepted")
	}
	return c
}

func planState(c *clinic, p *plan, now int64) string {
	if p == nil {
		return "closed"
	}
	if p.settled {
		return "settled"
	}
	if now >= p.expiry {
		return "expired"
	}
	for i := 0; i < p.size; i++ {
		if c.slots[p.slots[i]] != p.old[i] {
			return "stale"
		}
	}
	return "open"
}

func readyPlan(c *clinic, id int) *plan {
	p := c.plans[id]
	state := planState(c, p, time.Now().Unix())
	if state != "open" {
		panic("proposal is " + state)
	}
	return p
}

func Reservation(clinicID, slotID int) string {
	s := requireClinic(clinicID).slots[slotID]
	return s.issuer.String() + "," + s.holder.String() + "," + strconv.Itoa(s.revision) + "," + strconv.FormatBool(s.active)
}

package slotswitch

import (
	"chain/runtime"
	"time"
)

type transfer struct {
	clinics  [2]int
	slots    [2]int
	before   [2]slot
	approved [4]bool
	expiry   int64
	terminal string
	height   int64
	time     int64
}

var transfers = make(map[int]*transfer)

// ProposeTransfer swaps two existing appointments in accepted v2 clinics.
// Both appointments have the same fixed duration. The affected issuers decide
// whether their appointments are suitable by approving the exact exchange.
func ProposeTransfer(cur realm, fromClinic, fromSlot, fromRevision, toClinic, toSlot, toRevision int, expiry int64) int {
	runtime.AssertOriginCall()
	caller := signer(cur)
	if fromClinic == toClinic {
		panic("distinct clinics required")
	}
	from := requireAcceptedClinic(fromClinic)
	to := requireAcceptedClinic(toClinic)
	first := from.slots[fromSlot]
	second := to.slots[toSlot]
	if !first.active || !second.active {
		panic("active appointments required")
	}
	if first.revision != fromRevision || second.revision != toRevision {
		panic("appointment changed since preview")
	}
	if first.holder != caller {
		panic("source holder must propose")
	}
	if first.issuer == second.issuer || first.holder == second.holder {
		panic("distinct issuing desks and holders required")
	}
	now := time.Now().Unix()
	if expiry <= now || expiry > now+maxClinicSeconds || expiry > from.cutoff || expiry > to.cutoff ||
		expiry >= first.start || expiry >= second.start {
		panic("invalid transfer expiry")
	}
	if from.members[second.holder] == "" || to.members[first.holder] == "" {
		panic("both holders must be enrolled in the destination clinics")
	}
	if hasActiveBooking(from, second.holder) || hasActiveBooking(to, first.holder) {
		panic("holder already has an active appointment in destination clinic")
	}
	id := len(transfers) + 1
	transfers[id] = &transfer{clinics: [2]int{fromClinic, toClinic}, slots: [2]int{fromSlot, toSlot},
		before: [2]slot{first, second}, expiry: expiry}
	return id
}

// ApproveTransfer records or revokes consent for one exact role. A wallet
// serving more than one role must send a separate approval for each role.
// Roles 0 and 1 are the current holders. Roles 2 and 3 are the slot issuers.
func ApproveTransfer(cur realm, id, role int, approved bool) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := readyTransfer(id)
	participants := transferAccounts(p)
	if role < 0 || role >= len(participants) || participants[role] != caller {
		panic("transfer role signer required")
	}
	p.approved[role] = approved
}

func WithdrawTransfer(cur realm, id int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := readyTransfer(id)
	if p.before[0].holder != caller {
		panic("transfer proposer required")
	}
	p.terminal = "withdrawn"
}

func CancelTransfer(cur realm, id int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := readyTransfer(id)
	if p.before[0].issuer != caller && p.before[1].issuer != caller {
		panic("transfer issuer required")
	}
	p.terminal = "canceled"
}

func SettleTransfer(cur realm, id int) {
	runtime.AssertOriginCall()
	caller := signer(cur)
	p := readyTransfer(id)
	participating := false
	for _, account := range transferAccounts(p) {
		if account == caller {
			participating = true
		}
	}
	if !participating {
		panic("transfer participant required")
	}
	for _, approved := range p.approved {
		if !approved {
			panic("both holders and both issuers must approve")
		}
	}
	// readyTransfer validated both clinics and every booking and holder before
	// either roster write. Slot ownership and times remain with the issuers.
	for i, clinicID := range p.clinics {
		clinics[clinicID].slots[p.slots[i]] = transferredSlot(p, i)
	}
	p.terminal = "settled"
	p.height = runtime.ChainHeight()
	p.time = time.Now().Unix()
}

func transferAccounts(p *transfer) [4]address {
	return [4]address{p.before[0].holder, p.before[1].holder, p.before[0].issuer, p.before[1].issuer}
}

func transferredSlot(p *transfer, index int) slot {
	s := p.before[index]
	s.holder = p.before[1-index].holder
	s.revision++
	return s
}

func hasActiveBooking(c *clinic, holder address) bool {
	for _, s := range c.slots {
		if s.active && s.holder == holder {
			return true
		}
	}
	return false
}

func transferState(p *transfer, now int64) string {
	if p == nil {
		return "closed"
	}
	if p.terminal != "" {
		return p.terminal
	}
	if now >= p.expiry {
		return "expired"
	}
	for i, clinicID := range p.clinics {
		c := clinics[clinicID]
		incoming := p.before[1-i].holder
		if c == nil || !c.accepted || c.slots[p.slots[i]] != p.before[i] ||
			c.members[incoming] == "" || hasActiveBooking(c, incoming) {
			return "stale"
		}
	}
	return "open"
}

func readyTransfer(id int) *transfer {
	p := transfers[id]
	state := transferState(p, time.Now().Unix())
	if state != "open" {
		panic("transfer is " + state)
	}
	return p
}

package slotswitch

import (
	"strconv"
	"strings"
	"time"
)

type TransferLegView struct {
	ClinicID int
	Before   ReservationView
	After    ReservationView
}

type TransferParticipantView struct {
	Role     int
	Account  address
	Approved bool
}

type TransferView struct {
	ID           int
	State        string
	Expiry       int64
	Proposer     address
	Legs         []TransferLegView
	Participants []TransferParticipantView
}

type TransferReceiptView struct {
	ProposalID int
	Height     int64
	Time       int64
	Legs       []TransferLegView
}

func Transfer(id int) TransferView {
	p := transfers[id]
	result := TransferView{ID: id, State: transferState(p, time.Now().Unix())}
	if p == nil {
		return result
	}
	result.Expiry = p.expiry
	result.Proposer = p.before[0].holder
	result.Legs = transferLegs(p)
	for role, account := range transferAccounts(p) {
		result.Participants = append(result.Participants, TransferParticipantView{Role: role, Account: account, Approved: p.approved[role]})
	}
	return result
}

func TransferReceipt(id int) TransferReceiptView {
	p := transfers[id]
	if p == nil || p.terminal != "settled" {
		panic("settled transfer required")
	}
	return TransferReceiptView{ProposalID: id, Height: p.height, Time: p.time, Legs: transferLegs(p)}
}

func transferLegs(p *transfer) []TransferLegView {
	result := make([]TransferLegView, 0, len(p.clinics))
	for i, clinicID := range p.clinics {
		c := clinics[clinicID]
		result = append(result, TransferLegView{ClinicID: clinicID,
			Before: view(c, p.slots[i], p.before[i]), After: view(c, p.slots[i], transferredSlot(p, i))})
	}
	return result
}

func renderTransfer(path []string) string {
	if len(path) != 2 && len(path) != 3 {
		return "# Transfer unavailable"
	}
	id, err := strconv.Atoi(path[1])
	if err != nil || id <= 0 || transfers[id] == nil {
		return "# Transfer unavailable"
	}
	transfer := Transfer(id)
	var page strings.Builder
	if len(path) == 3 {
		if path[2] != "receipt" || transfer.State != "settled" {
			return "# Transfer receipt unavailable"
		}
		receipt := TransferReceipt(id)
		page.WriteString("# Transfer confirmed\n\nBlock " + strconv.FormatInt(receipt.Height, 10) + " at " + dateTime(receipt.Time) + ".")
	} else {
		page.WriteString("# Transfer " + strconv.Itoa(id) + "\n\nStatus: " + transfer.State + ".")
	}
	page.WriteString("\n\n| Clinic | Appointment | Original holder | ")
	if transfer.State == "settled" {
		page.WriteString("Confirmed holder")
	} else {
		page.WriteString("Proposed holder")
	}
	page.WriteString(" |\n|---|---|---|---|\n")
	for _, leg := range transfer.Legs {
		page.WriteString("| " + strconv.Itoa(leg.ClinicID) + " | " + dateTime(leg.Before.Start))
		page.WriteString(" | " + leg.Before.Alias + " | " + leg.After.Alias + " |\n")
	}
	return page.String()
}

package slotswitch

import (
	"strconv"
	"strings"
	"time"
)

type ReservationView struct {
	ID       int
	Issuer   address
	Holder   address
	Alias    string
	Start    int64
	Revision int
	Active   bool
}

type TeamView struct {
	Account address
	Alias   string
}

type ClinicView struct {
	ID            int
	Issuers       [2]address
	Accepted      bool
	DraftRevision int
	StartsAt      int64
	EndsAt        int64
	Cutoff        int64
	Teams         []TeamView
}

type ReceiptView struct {
	ClinicID   int
	ProposalID int
	Height     int64
	Time       int64
	Before     []ReservationView
	After      []ReservationView
}

type MoveView struct {
	Holder   address
	Gives    ReservationView
	Receives ReservationView
	Approved bool
}

type ProposalView struct {
	ClinicID   int
	ProposalID int
	State      string
	Expiry     int64
	Moves      []MoveView
}

func Clinic(clinicID int) ClinicView {
	c := requireClinic(clinicID)
	result := ClinicView{
		ID: clinicID, Issuers: c.issuers, Accepted: c.accepted, DraftRevision: c.draftRevision,
		StartsAt: c.startsAt, EndsAt: c.endsAt, Cutoff: c.cutoff,
	}
	for _, account := range c.enrolled {
		result.Teams = append(result.Teams, TeamView{Account: account, Alias: c.members[account]})
	}
	return result
}

func view(c *clinic, id int, s slot) ReservationView {
	return ReservationView{
		ID: id, Issuer: s.issuer, Holder: s.holder, Alias: c.members[s.holder], Start: s.start,
		Revision: s.revision, Active: s.active,
	}
}

func Roster(clinicID int) []ReservationView {
	c := requireClinic(clinicID)
	result := make([]ReservationView, 0, len(c.slots))
	for id := 1; id <= len(c.slots); id++ {
		result = append(result, view(c, id, c.slots[id]))
	}
	return result
}

func Accepted(clinicID int) bool {
	return requireClinic(clinicID).accepted
}

func ProposalState(clinicID, proposalID int) string {
	c := requireClinic(clinicID)
	return planState(c, c.plans[proposalID], time.Now().Unix())
}

func Proposal(clinicID, proposalID int) ProposalView {
	c := requireClinic(clinicID)
	p := c.plans[proposalID]
	result := ProposalView{
		ClinicID: clinicID, ProposalID: proposalID, State: planState(c, p, time.Now().Unix()),
	}
	if p == nil {
		return result
	}
	result.Expiry = p.expiry
	for source := 0; source < p.size; source++ {
		destination := (source + 1) % p.size
		result.Moves = append(result.Moves, MoveView{
			Holder:   p.old[source].holder,
			Gives:    view(c, p.slots[source], p.old[source]),
			Receives: view(c, p.slots[destination], rotatedSlot(p, destination)),
			Approved: p.approved[source],
		})
	}
	return result
}

func Receipt(clinicID, proposalID int) ReceiptView {
	c := requireClinic(clinicID)
	p := c.plans[proposalID]
	if p == nil || !p.settled {
		panic("settled proposal required")
	}
	receipt := ReceiptView{ClinicID: clinicID, ProposalID: proposalID, Height: p.height, Time: p.confirmedAt}
	for i := 0; i < p.size; i++ {
		receipt.Before = append(receipt.Before, view(c, p.slots[i], p.old[i]))
		receipt.After = append(receipt.After, view(c, p.slots[i], rotatedSlot(p, i)))
	}
	return receipt
}

func Render(path string) string {
	if path == "" {
		return "# SlotSwitch v2\n\nOpen a clinic by its numeric ID or a cross-clinic exchange at `transfer/ID`."
	}
	segments := strings.Split(path, "/")
	if segments[0] == "transfer" {
		return renderTransfer(segments)
	}
	id, err := strconv.Atoi(segments[0])
	if err != nil || clinics[id] == nil {
		return "# Clinic unavailable"
	}
	if len(segments) == 3 && segments[1] == "proposal" {
		proposalID, err := strconv.Atoi(segments[2])
		if err != nil || proposalID <= 0 {
			return "# Proposal unavailable"
		}
		return renderProposal(Proposal(id, proposalID))
	}
	if len(segments) == 3 && segments[1] == "receipt" {
		proposalID, err := strconv.Atoi(segments[2])
		if err != nil || ProposalState(id, proposalID) != "settled" {
			return "# Receipt unavailable"
		}
		return renderReceipt(Receipt(id, proposalID))
	}
	if len(segments) != 1 {
		return "# Clinic page unavailable"
	}
	if !Accepted(id) {
		draft := Clinic(id)
		var page strings.Builder
		page.WriteString("# Clinic awaiting acceptance\n\n")
		page.WriteString("Draft revision " + strconv.Itoa(draft.DraftRevision))
		page.WriteString("\n\nClinic starts " + dateTime(draft.StartsAt))
		page.WriteString(" and ends " + dateTime(draft.EndsAt) + ".")
		page.WriteString("\n\nExchange cutoff " + dateTime(draft.Cutoff) + ".")
		page.WriteString("\n\nThe second desk must accept before either desk can issue bookings.\n")
		for _, team := range draft.Teams {
			page.WriteString("\n- " + team.Alias + " (" + team.Account.String() + ")")
		}
		return page.String()
	}
	var page strings.Builder
	page.WriteString("# Clinic ")
	page.WriteString(strconv.Itoa(id))
	page.WriteString("\n\n| Appointment | Issuer | Current holder | Status |\n|---|---|---|---|\n")
	for _, reservation := range Roster(id) {
		status := "Confirmed"
		if !reservation.Active {
			status = "Canceled"
		}
		page.WriteString("| ")
		page.WriteString(dateTime(reservation.Start))
		page.WriteString(" | ")
		page.WriteString(reservation.Issuer.String())
		page.WriteString(" | ")
		page.WriteString(reservation.Alias + " (" + reservation.Holder.String() + ")")
		page.WriteString(" | ")
		page.WriteString(status)
		page.WriteString(" |\n")
	}
	return page.String()
}

func renderProposal(proposal ProposalView) string {
	var page strings.Builder
	page.WriteString("# Proposal ")
	page.WriteString(strconv.Itoa(proposal.ProposalID))
	page.WriteString("\n\nStatus: ")
	page.WriteString(proposal.State)
	page.WriteString("\n")
	if len(proposal.Moves) == 0 {
		return page.String()
	}
	page.WriteString("\nApproval cutoff: ")
	page.WriteString(dateTime(proposal.Expiry))
	page.WriteString("\n\n| Participant | Gives appointment | Receives appointment | Approval |\n|---|---|---|---|\n")
	for _, move := range proposal.Moves {
		approval := "Pending"
		if move.Approved {
			approval = "Approved"
		}
		page.WriteString("| " + move.Holder.String())
		page.WriteString(" | #" + strconv.Itoa(move.Gives.ID))
		page.WriteString(" | #" + strconv.Itoa(move.Receives.ID))
		page.WriteString(" | " + approval + " |\n")
	}
	return page.String()
}

func renderReceipt(receipt ReceiptView) string {
	var page strings.Builder
	page.WriteString("# Exchange confirmed\n\nBlock " + strconv.FormatInt(receipt.Height, 10))
	page.WriteString(" at " + dateTime(receipt.Time) + ".")
	page.WriteString("\n\n| Appointment | Previous holder | Confirmed holder |\n|---|---|---|\n")
	for index, before := range receipt.Before {
		after := receipt.After[index]
		page.WriteString("| " + dateTime(before.Start) + " | " + before.Alias + " | " + after.Alias + " |\n")
	}
	return page.String()
}

func dateTime(epochSeconds int64) string {
	return time.Unix(epochSeconds, 0).UTC().Format("02 Jan 15:04:05 UTC")
}

package aegis_pit

import (
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
)

// ======================= Fighters & Backer Tokens =======================

const shareScale int64 = 1_000_000

// BackerLedger wraps a real GRC20 token (gno.land/p/nt/grc20) minted per
// fighter. Holders earn 3% of every ranked pool their fighter wins through a
// reward-per-share accumulator (O(1) per payout, no loops over holders).
//
// The token's *Token / *PrivateLedger stay private to this realm: other realms
// read it through BackerToken(id), a standard read-only grc20.Teller, and
// holders move it with TransferBacker, which settles dividends first. Exposing
// the raw *Token would let any realm holding BACK tokens move them with
// RealmTeller and skip settlement, so it is deliberately never handed out.
type BackerLedger struct {
	Symbol      string
	Supply      int64
	token       *grc20.Token
	ledger      *grc20.PrivateLedger
	debt        *avl.Tree // addr -> int64 (already-accounted rewards)
	accPerShare int64     // scaled by shareScale
	Distributed int64
}

func (l *BackerLedger) BalanceOf(a address) int64 { return l.token.BalanceOf(a) }

func (l *BackerLedger) debtOf(a address) int64 {
	v := l.debt.Get(string(a))
	if v == nil {
		return 0
	}
	return v.(int64)
}

func (l *BackerLedger) Pending(a address) int64 {
	return l.BalanceOf(a)*l.accPerShare/shareScale - l.debtOf(a)
}

// settle moves pending rewards to the holder's claimable credits.
func (l *BackerLedger) settle(a address) {
	addCredit(a, l.Pending(a))
	l.debt.Set(string(a), l.BalanceOf(a)*l.accPerShare/shareScale)
}

func (l *BackerLedger) reward(amt int64) int64 {
	if amt <= 0 || l.Supply == 0 {
		return 0
	}
	inc := amt * shareScale / l.Supply
	l.accPerShare += inc
	paid := inc * l.Supply / shareScale
	l.Distributed += paid
	return amt - paid // dust
}

func (l *BackerLedger) transfer(from, to address, amt int64) {
	if amt <= 0 || l.BalanceOf(from) < amt {
		panic("aegis: insufficient backer tokens")
	}
	l.settle(from)
	l.settle(to)
	if err := l.ledger.Transfer(from, to, amt); err != nil {
		panic("aegis: " + err.Error())
	}
	l.debt.Set(string(from), l.BalanceOf(from)*l.accPerShare/shareScale)
	l.debt.Set(string(to), l.BalanceOf(to)*l.accPerShare/shareScale)
}

type Fighter struct {
	ID       int
	Name     string
	PkgPath  string // public Gno source of the fighter's strategy (read by rival AIs via gnomcp)
	Owner    address
	Agent    address // optional AI agent key allowed to commit/reveal
	Backers  *BackerLedger
	Wins     int
	Losses   int
	Draws    int
	Forfeits int
	Badges   []string
}

func getFighter(id int) *Fighter {
	v := fighters.Get(key(id))
	if v == nil {
		panic("aegis: fighter not found")
	}
	return v.(*Fighter)
}

func (f *Fighter) controls(a address) bool {
	return a == f.Owner || (f.Agent != "" && a == f.Agent)
}

// RegisterFighter registers an AI fighter and mints its Backer Tokens to the owner.
func RegisterFighter(cur realm, name, pkgPath string, backerSupply int64) int {
	if len(name) == 0 || len(name) > 24 {
		panic("aegis: name must be 1..24 chars")
	}
	if backerSupply < 1 || backerSupply > 1_000_000_000 {
		panic("aegis: backerSupply must be 1..1e9")
	}
	owner := caller(cur)
	nFighters++
	symbol := "BACK" + strconv.Itoa(nFighters)
	tok, led := grc20.NewToken(name+" Backer", symbol, 0, seqid.ID(nFighters), cur)
	if err := led.Mint(owner, backerSupply); err != nil {
		panic("aegis: " + err.Error())
	}
	l := &BackerLedger{Symbol: symbol, Supply: backerSupply, token: tok, ledger: led, debt: avl.NewTree()}
	f := &Fighter{ID: nFighters, Name: name, PkgPath: pkgPath, Owner: owner, Backers: l}
	fighters.Set(key(f.ID), f)
	return f.ID
}

// SetFighterAgent authorizes an AI agent key (e.g. a gnomcp session) to commit/reveal.
func SetFighterAgent(cur realm, fighterID int, agent address) {
	f := getFighter(fighterID)
	if caller(cur) != f.Owner {
		panic("aegis: only the owner can set the agent")
	}
	f.Agent = agent
}

// TransferBacker transfers Backer Tokens of a fighter (rewards are settled first).
func TransferBacker(cur realm, fighterID int, to address, amount int64) {
	if !to.IsValid() {
		panic("aegis: invalid recipient")
	}
	getFighter(fighterID).Backers.transfer(caller(cur), to, amount)
}

// ClaimBackerRewards moves pending backer dividends into claimable credits.
func ClaimBackerRewards(cur realm, fighterID int) {
	getFighter(fighterID).Backers.settle(caller(cur))
}

// BackerToken returns the fighter's GRC20 Backer Token as a standard,
// read-only grc20.Teller (name, symbol, supply, balances).
func BackerToken(fighterID int) grc20.Teller {
	return getFighter(fighterID).Backers.token.ReadonlyTeller()
}

func BackerTokenID(fighterID int) string { return getFighter(fighterID).Backers.token.ID() }

func BackerBalance(fighterID int, a address) int64 { return getFighter(fighterID).Backers.BalanceOf(a) }
func BackerPending(fighterID int, a address) int64 { return getFighter(fighterID).Backers.Pending(a) }

// ======================= Trust =======================

func trustOf(a address) *core.TrustRecord {
	v := trust.Get(string(a))
	if v == nil {
		r := &core.TrustRecord{}
		trust.Set(string(a), r)
		return r
	}
	return v.(*core.TrustRecord)
}

// TrustScore is exported for other realms to import: reputation that only
// moves when real ugnot was at stake.
func TrustScore(a address) int64 {
	v := trust.Get(string(a))
	if v == nil {
		return core.TrustScore(core.TrustRecord{})
	}
	return core.TrustScore(*v.(*core.TrustRecord))
}

// ======================= Matches =======================

const (
	StatusOpen     = "open"     // waiting for opponent
	StatusLive     = "live"     // commits + bets open until CommitDeadline
	StatusResolved = "resolved" // both revealed
	StatusForfeit  = "forfeit"  // someone did not reveal: bond slashed
	StatusCanceled = "canceled"
)

type Match struct {
	ID             int
	Ranked         bool
	A, B           int // fighter IDs (B = 0 while open)
	Bond           int64
	CommitDeadline int64
	RevealDeadline int64
	CommitA        string
	CommitB        string
	MovesA         string
	MovesB         string
	Status         string
	Winner         int // 0 draw, 1 = A, 2 = B
	betsA          *avl.Tree
	betsB          *avl.Tree
	PoolA          int64
	PoolB          int64
	Log            []core.RoundResult
	Note           string
}

func getMatch(id int) *Match {
	v := matches.Get(key(id))
	if v == nil {
		panic("aegis: match not found")
	}
	return v.(*Match)
}

// CreateMatch opens a match for one of your fighters. Attach the bond in ugnot.
// ranked=false is a friendly match (no betting, no trust impact).
func CreateMatch(cur realm, fighterID int, ranked bool) int {
	bond := takeDeposit(cur)
	if bond < MinBond {
		panic("aegis: bond below minimum (" + strconv.FormatInt(MinBond, 10) + " ugnot)")
	}
	f := getFighter(fighterID)
	if !f.controls(caller(cur)) {
		panic("aegis: you do not control this fighter")
	}
	nMatches++
	m := &Match{ID: nMatches, Ranked: ranked, A: fighterID, Bond: bond, Status: StatusOpen,
		betsA: avl.NewTree(), betsB: avl.NewTree()}
	matches.Set(key(m.ID), m)
	return m.ID
}

// CancelMatch refunds the creator's bond while nobody has joined yet.
func CancelMatch(cur realm, matchID int) {
	m := getMatch(matchID)
	f := getFighter(m.A)
	if m.Status != StatusOpen || !f.controls(caller(cur)) {
		panic("aegis: only the creator can cancel an open match")
	}
	m.Status = StatusCanceled
	addCredit(f.Owner, m.Bond)
}

// JoinMatch joins with your fighter, attaching exactly the same bond.
// The commit deadline (and betting lock) is set at this block.
func JoinMatch(cur realm, matchID, fighterID int) {
	amt := takeDeposit(cur)
	m := getMatch(matchID)
	if m.Status != StatusOpen {
		panic("aegis: match is not open")
	}
	if amt != m.Bond {
		panic("aegis: bond must equal " + strconv.FormatInt(m.Bond, 10) + " ugnot")
	}
	fa := getFighter(m.A)
	fb := getFighter(fighterID)
	if !fb.controls(caller(cur)) {
		panic("aegis: you do not control this fighter")
	}
	if fa.Owner == fb.Owner {
		panic("aegis: cannot fight yourself")
	}
	m.B = fighterID
	m.Status = StatusLive
	m.CommitDeadline = height() + CommitWindow
	m.RevealDeadline = m.CommitDeadline + RevealWindow
}

// PlaceBet bets the attached ugnot on side 1 (A) or 2 (B) of a ranked, live match.
func PlaceBet(cur realm, matchID, side int) {
	amt := takeDeposit(cur)
	placeBet(getMatch(matchID), caller(cur), side, amt)
}

func placeBet(m *Match, bettor address, side int, amt int64) {
	if !m.Ranked {
		panic("aegis: friendly matches have no betting")
	}
	if m.Status != StatusLive || height() > m.CommitDeadline {
		panic("aegis: betting is locked")
	}
	if side != 1 && side != 2 {
		panic("aegis: side must be 1 or 2")
	}
	if amt < MinBet {
		panic("aegis: bet too small")
	}
	// Anti match-fixing: an owner can never bet against their own fighter.
	if (side == 2 && getFighter(m.A).Owner == bettor) || (side == 1 && getFighter(m.B).Owner == bettor) {
		panic("aegis: owners cannot bet against their own fighter")
	}
	t := m.betsA
	if side == 2 {
		t = m.betsB
	}
	prev := int64(0)
	if v := t.Get(string(bettor)); v != nil {
		prev = v.(int64)
	}
	t.Set(string(bettor), prev+amt)
	if side == 1 {
		m.PoolA += amt
	} else {
		m.PoolB += amt
	}
}

// CommitMove stores hash(moves:salt) — see aegis_core.CommitHash.
func CommitMove(cur realm, matchID int, commit string) {
	m := getMatch(matchID)
	if m.Status != StatusLive || height() > m.CommitDeadline {
		panic("aegis: commit window closed")
	}
	if len(commit) != 64 {
		panic("aegis: commit must be a 64-char sha256 hex")
	}
	who := caller(cur)
	switch {
	case getFighter(m.A).controls(who):
		if m.CommitA != "" {
			panic("aegis: already committed")
		}
		m.CommitA = commit
	case getFighter(m.B).controls(who):
		if m.CommitB != "" {
			panic("aegis: already committed")
		}
		m.CommitB = commit
	default:
		panic("aegis: not a fighter in this match")
	}
}

// Reveal opens your commitment. Only allowed after the commit deadline (so
// nobody — fighter or bettor — sees a move while bets are open). When both
// sides have revealed, the match resolves and pays out automatically.
func Reveal(cur realm, matchID int, moves, salt string) {
	m := getMatch(matchID)
	if m.Status != StatusLive {
		panic("aegis: match not live")
	}
	h := height()
	if h <= m.CommitDeadline {
		panic("aegis: reveal opens after block " + strconv.FormatInt(m.CommitDeadline, 10))
	}
	if h > m.RevealDeadline {
		panic("aegis: reveal window closed, use SlashNoReveal")
	}
	who := caller(cur)
	switch {
	case getFighter(m.A).controls(who) && m.MovesA == "":
		if err := core.VerifyReveal(m.CommitA, moves, salt); err != nil {
			panic(err.Error())
		}
		m.MovesA = moves
	case getFighter(m.B).controls(who) && m.MovesB == "":
		if err := core.VerifyReveal(m.CommitB, moves, salt); err != nil {
			panic(err.Error())
		}
		m.MovesB = moves
	default:
		panic("aegis: nothing to reveal for caller")
	}
	if m.MovesA != "" && m.MovesB != "" {
		resolve(m)
	}
}

func resolve(m *Match) {
	fa, fb := getFighter(m.A), getFighter(m.B)
	m.Winner, m.Log = core.ResolveDuel(m.MovesA, m.MovesB)
	m.Status = StatusResolved
	addCredit(fa.Owner, m.Bond)
	addCredit(fb.Owner, m.Bond)

	switch m.Winner {
	case 0:
		fa.Draws++
		fb.Draws++
	case 1:
		fa.Wins++
		fb.Losses++
	case 2:
		fb.Wins++
		fa.Losses++
	}

	total := m.PoolA + m.PoolB
	if !m.Ranked {
		m.Note = "friendly match: no pool, no trust change"
		awardBadges(m)
		return
	}
	if m.Winner == 0 {
		refundBets(m)
		m.Note = "draw: all bets refunded"
		return
	}
	winPool, winBets, wf, lf := m.PoolA, m.betsA, fa, fb
	if m.Winner == 2 {
		winPool, winBets, wf, lf = m.PoolB, m.betsB, fb, fa
	}
	tw := trustOf(wf.Owner)
	tl := trustOf(lf.Owner)
	tw.RankedWins++
	tl.RankedLosses++
	tw.StakedVolume += total
	tl.StakedVolume += total

	if winPool == 0 {
		refundBets(m)
		m.Note = "nobody backed the winner: all bets refunded"
		awardBadges(m)
		return
	}
	winners, backers, season := core.SplitPool(total)
	paid := int64(0)
	winBets.Iterate("", "", func(k string, v any) bool {
		share := core.ProRata(v.(int64), winners, winPool)
		addCredit(address(k), share)
		paid += share
		return false
	})
	dust := winners - paid
	dust += wf.Backers.reward(backers)
	seasonFund += season + dust
	m.Note = "pool " + strconv.FormatInt(total, 10) + " ugnot: 95% bettors / 3% backers of " + wf.Name + " / 2% season"
	awardBadges(m)
}

func refundBets(m *Match) {
	refund := func(k string, v any) bool {
		addCredit(address(k), v.(int64))
		return false
	}
	m.betsA.Iterate("", "", refund)
	m.betsB.Iterate("", "", refund)
}

func awardBadges(m *Match) {
	if m.Winner == 0 || len(m.Log) == 0 {
		return
	}
	last := m.Log[len(m.Log)-1]
	w, hp, underdog := getFighter(m.A), last.HPA, m.PoolA < m.PoolB
	if m.Winner == 2 {
		w, hp, underdog = getFighter(m.B), last.HPB, m.PoolB < m.PoolA
	}
	if w.Wins == 1 {
		w.Badges = append(w.Badges, "First Blood")
	}
	if hp == core.StartHP {
		w.Badges = append(w.Badges, "Untouched")
	}
	if m.Ranked && underdog {
		w.Badges = append(w.Badges, "Giant Slayer")
	}
	if w.Wins == 5 {
		w.Badges = append(w.Badges, "Pit Veteran")
	}
}

// SlashNoReveal can be called by anyone after the reveal deadline.
// A fighter who did not reveal loses its bond to the opponent; bettors are refunded.
// If neither revealed, both bonds go to the season fund.
func SlashNoReveal(cur realm, matchID int) {
	m := getMatch(matchID)
	if m.Status != StatusLive || height() <= m.RevealDeadline {
		panic("aegis: nothing to slash yet")
	}
	fa, fb := getFighter(m.A), getFighter(m.B)
	refundBets(m)
	m.Status = StatusForfeit
	id := "match #" + strconv.Itoa(m.ID)
	switch {
	case m.MovesA != "" && m.MovesB == "":
		m.Winner = 1
		addCredit(fa.Owner, 2*m.Bond)
		fb.Forfeits++
		fa.Wins++
		if m.Ranked {
			trustOf(fb.Owner).Forfeits++
		}
		logLab("slash", id+": "+fb.Name+" never revealed, bond "+strconv.FormatInt(m.Bond, 10)+" → "+fa.Name)
	case m.MovesB != "" && m.MovesA == "":
		m.Winner = 2
		addCredit(fb.Owner, 2*m.Bond)
		fa.Forfeits++
		fb.Wins++
		if m.Ranked {
			trustOf(fa.Owner).Forfeits++
		}
		logLab("slash", id+": "+fa.Name+" never revealed, bond "+strconv.FormatInt(m.Bond, 10)+" → "+fb.Name)
	default:
		seasonFund += 2 * m.Bond
		fa.Forfeits++
		fb.Forfeits++
		if m.Ranked {
			trustOf(fa.Owner).Forfeits++
			trustOf(fb.Owner).Forfeits++
		}
		logLab("slash", id+": neither fighter revealed, both bonds → season fund")
	}
	m.Note = "forfeit: bettors refunded"
}

// Read helpers
func MatchStatus(matchID int) string { return getMatch(matchID).Status }
func MatchWinner(matchID int) int    { return getMatch(matchID).Winner }

package aegis_pit

import (
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
)

// Box is a budget a human locks for an AI agent.
// The agent can only move funds inside the Policy; the owner can always exit.
type Box struct {
	ID      int
	Owner   address
	Agent   address
	Policy  *core.Policy
	Balance int64
	Spent   int64
	Blocked int
	Closed  bool
}

func getBox(id int) *Box {
	v := boxes.Get(key(id))
	if v == nil {
		panic("aegis: box not found")
	}
	return v.(*Box)
}

// CreateBox locks the attached ugnot under a spending policy.
// allowedTargets / allowedFns are comma-separated; allowedFns "" means any.
// Use this realm's address as a target + fn "PlaceBet" to let the agent bet via BoxBet.
func CreateBox(cur realm, agent address, allowedTargets, allowedFns string, maxPerTx, expireHeight int64) int {
	amt := takeDeposit(cur)
	if amt <= 0 {
		panic("aegis: attach ugnot to fund the box")
	}
	p, err := core.NewPolicy(allowedTargets, allowedFns, maxPerTx, expireHeight)
	if err != nil {
		panic(err.Error())
	}
	nBoxes++
	b := &Box{ID: nBoxes, Owner: caller(cur), Agent: agent, Policy: p, Balance: amt}
	boxes.Set(key(b.ID), b)
	return b.ID
}

// TopUpBox adds the attached ugnot to an open box (owner only).
func TopUpBox(cur realm, boxID int) {
	amt := takeDeposit(cur)
	b := getBox(boxID)
	if caller(cur) != b.Owner || b.Closed {
		panic("aegis: only the owner can top up an open box")
	}
	b.Balance += amt
}

func checkBoxSpend(b *Box, who address, target address, fn string, amount int64) error {
	if b.Closed {
		return errBox("box closed")
	}
	if who != b.Owner && who != b.Agent {
		return errBox("caller is not the box owner or its agent")
	}
	if err := core.ValidateSpend(b.Policy, target, fn, amount, height()); err != nil {
		return err
	}
	if amount > b.Balance {
		return errBox("insufficient box balance")
	}
	return nil
}

// BoxSpend sends ugnot from the box to target. Any policy violation panics,
// so the whole transaction reverts on-chain.
func BoxSpend(cur realm, boxID int, target address, fn string, amount int64) {
	b := getBox(boxID)
	if err := checkBoxSpend(b, caller(cur), target, fn, amount); err != nil {
		panic(err.Error())
	}
	b.Balance -= amount
	b.Spent += amount
	send(cur, target, amount)
}

// GuardedSpend is the "soft" variant used by the Breaker Lab: instead of
// reverting, a violation is recorded publicly and no coin moves.
func GuardedSpend(cur realm, boxID int, target address, fn string, amount int64) bool {
	b := getBox(boxID)
	if err := checkBoxSpend(b, caller(cur), target, fn, amount); err != nil {
		b.Blocked++
		logLab("blocked", "box #"+strconv.Itoa(boxID)+" → "+string(target)+" "+fn+"("+strconv.FormatInt(amount, 10)+" ugnot): "+err.Error())
		return false
	}
	b.Balance -= amount
	b.Spent += amount
	send(cur, target, amount)
	return true
}

// BoxBet lets an agent bet from a box. The policy must allow this realm's
// address as target and "PlaceBet" as fn. The bet belongs to the box owner.
func BoxBet(cur realm, boxID, matchID, side int, amount int64) {
	b := getBox(boxID)
	if err := checkBoxSpend(b, caller(cur), cur.Address(), "PlaceBet", amount); err != nil {
		panic(err.Error())
	}
	b.Balance -= amount
	b.Spent += amount
	placeBet(getMatch(matchID), b.Owner, side, amount)
}

// LogPreflight lets a box owner/agent publish a pre-flight report (qeval/qrender summary).
func LogPreflight(cur realm, boxID int, report string) {
	b := getBox(boxID)
	who := caller(cur)
	if who != b.Owner && who != b.Agent {
		panic("aegis: only the box owner or agent can log preflight")
	}
	if len(report) > 280 {
		report = report[:280]
	}
	logLab("preflight", "box #"+strconv.Itoa(boxID)+": "+report)
}

// EmergencyWithdraw returns the whole box balance to the owner and closes it.
// Reachable straight from gnoweb via Render("exit"); no external website needed.
func EmergencyWithdraw(cur realm, boxID int) int64 {
	b := getBox(boxID)
	if caller(cur) != b.Owner {
		panic("aegis: only the box owner can withdraw")
	}
	amt := b.Balance
	b.Balance = 0
	b.Closed = true
	send(cur, b.Owner, amt)
	logLab("exit", "box #"+strconv.Itoa(boxID)+" emergency-withdrawn: "+strconv.FormatInt(amt, 10)+" ugnot")
	return amt
}

// BoxBalance is a read helper.
func BoxBalance(boxID int) int64 { return getBox(boxID).Balance }

type boxErr struct{ msg string }

func (e boxErr) Error() string { return "aegis: " + e.msg }

func errBox(msg string) error { return boxErr{msg} }

package aegis_pit

import (
	"strconv"
	"strings"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
)

// Render serves 5 gnoweb screens:
//
//	""            arena lobby
//	"match/<id>"  duel board + combat log
//	"fighters"    leaderboard, trust, backer tokens, badges
//	"lab"         breaker lab: blocked attacks, slashes, preflight reports
//	"exit"        emergency exit (plain text + direct withdraw links)
func Render(path string) string {
	switch {
	case path == "":
		return renderLobby()
	case strings.HasPrefix(path, "match/"):
		id, err := strconv.Atoi(strings.TrimPrefix(path, "match/"))
		if err != nil || matches.Get(key(id)) == nil {
			return "# 404\nMatch not found. [Back to lobby](" + linkPath() + ")"
		}
		return renderMatch(getMatch(id))
	case path == "fighters":
		return renderFighters()
	case path == "lab":
		return renderLab()
	case path == "exit":
		return renderExit()
	}
	return "# 404\n[Back to lobby](" + linkPath() + ")"
}

func nav() string {
	p := linkPath()
	return "[Arena](" + p + ") · [Fighters](" + p + ":fighters) · [Breaker Lab](" + p + ":lab) · [Emergency Exit](" + p + ":exit)\n\n"
}

func renderLobby() string {
	out := "# ⚔️ Aegis Pit\n" + nav()
	out += "Oracle-free prediction market on deterministic AI duels. Commit-reveal locks moves **and** bets at the same block; no-shows lose their bond.\n\n"
	out += "**Block:** " + strconv.FormatInt(height(), 10) + " · **Season fund:** " + strconv.FormatInt(seasonFund, 10) + " ugnot · "
	out += "[Register fighter](" + txLink("RegisterFighter") + ") · [Create match](" + txLink("CreateMatch") + ") · [Claim winnings](" + txLink("Claim") + ")\n\n"
	if matches.Size() == 0 {
		return out + "_No matches yet. Register a fighter and open one._\n"
	}
	out += "## Matches\n\n"
	count := 0
	matches.ReverseIterate("", "", func(k string, v any) bool {
		m := v.(*Match)
		out += "[" + matchCardSVG(m) + "](" + linkPath() + ":match/" + itoa(m.ID) + ")\n\n"
		count++
		return count >= 10
	})
	return out
}

func renderMatch(m *Match) string {
	id := itoa(m.ID)
	fa := getFighter(m.A)
	out := "# Match #" + id + "\n" + nav() + matchCardSVG(m) + "\n\n"
	out += "| | " + fa.Name + " (A)"
	nameB := "—"
	if m.B != 0 {
		nameB = getFighter(m.B).Name
	}
	out += " | " + nameB + " (B) |\n|---|---|---|\n"
	out += "| Commit | " + yesNo(m.CommitA != "") + " | " + yesNo(m.CommitB != "") + " |\n"
	out += "| Reveal | " + orDash(m.MovesA) + " | " + orDash(m.MovesB) + " |\n"
	out += "| Pool (ugnot) | " + strconv.FormatInt(m.PoolA, 10) + " | " + strconv.FormatInt(m.PoolB, 10) + " |\n\n"
	out += "**Mode:** " + modeLabel(m) + " · **Bond:** " + strconv.FormatInt(m.Bond, 10) + " ugnot · **Phase:** " + phase(m) + "\n\n"

	switch m.Status {
	case StatusOpen:
		out += "[Join this match](" + txLink("JoinMatch", "matchID", id) + ") (attach exactly the bond)\n"
	case StatusLive:
		if height() <= m.CommitDeadline {
			out += "[Commit move](" + txLink("CommitMove", "matchID", id) + ")"
			if m.Ranked {
				out += " · [Bet on A](" + txLink("PlaceBet", "matchID", id, "side", "1") + ") · [Bet on B](" + txLink("PlaceBet", "matchID", id, "side", "2") + ")"
			}
			out += "\n"
		} else if height() <= m.RevealDeadline {
			out += "[Reveal](" + txLink("Reveal", "matchID", id) + ")\n"
		} else {
			out += "[Slash no-show](" + txLink("SlashNoReveal", "matchID", id) + ")\n"
		}
	}
	if len(m.Log) > 0 {
		out += "\n## Combat log\n\n| Round | A | B | HP A | HP B |\n|---|---|---|---|---|\n"
		for i, r := range m.Log {
			out += "| " + itoa(i+1) + " | " + core.MoveName(r.MoveA) + " | " + core.MoveName(r.MoveB) + " | " + itoa(r.HPA) + " | " + itoa(r.HPB) + " |\n"
		}
	}
	if m.Note != "" {
		out += "\n> " + m.Note + "\n"
	}
	return out
}

func renderFighters() string {
	out := "# 🏆 Fighters\n" + nav()
	if fighters.Size() == 0 {
		return out + "_No fighters yet._ [Register one](" + txLink("RegisterFighter") + ")\n"
	}
	out += "| # | Fighter | W / L / D | Forfeits | Trust (owner) | Backer token | Supply | Paid to backers | Source |\n|---|---|---|---|---|---|---|---|---|\n"
	badges := ""
	fighters.Iterate("", "", func(k string, v any) bool {
		f := v.(*Fighter)
		out += "| " + itoa(f.ID) + " | **" + escapeMd(f.Name) + "** | " + itoa(f.Wins) + " / " + itoa(f.Losses) + " / " + itoa(f.Draws) +
			" | " + itoa(f.Forfeits) + " | " + strconv.FormatInt(TrustScore(f.Owner), 10) +
			" | " + f.Backers.Symbol + " | " + strconv.FormatInt(f.Backers.Supply, 10) +
			" | " + strconv.FormatInt(f.Backers.Distributed, 10) + " ugnot | `" + orDash(f.PkgPath) + "` |\n"
		if len(f.Badges) > 0 {
			badges += "**" + escapeMd(f.Name) + "** "
			for _, b := range f.Badges {
				badges += badgeSVG(b) + " "
			}
			badges += "\n\n"
		}
		return false
	})
	if badges != "" {
		out += "\n## Badges\n\n" + badges
	}
	out += "\nTrust only moves on **ranked** matches with real ugnot at stake. Other realms can read it via `TrustScore(addr)`.\n"
	return out
}

func renderLab() string {
	out := "# 🧪 Breaker Lab\n" + nav()
	out += "Prompt-injection attempts, slashed no-shows and pre-flight reports. Every blocked line is a spend the AI tried that the on-chain policy refused.\n\n"
	if len(lab) == 0 {
		return out + "_No events yet._\n"
	}
	out += "| Block | Kind | Detail |\n|---|---|---|\n"
	for i := len(lab) - 1; i >= 0; i-- {
		e := lab[i]
		out += "| " + strconv.FormatInt(e.Height, 10) + " | " + kindIcon(e.Kind) + " | " + escapeMd(e.Detail) + " |\n"
	}
	return out
}

func renderExit() string {
	out := "# Emergency Exit\n\n"
	out += "This page is plain text on purpose: it works even if every external website is down.\n\n"
	out += "1. Withdraw a whole budget box: [EmergencyWithdraw](" + txLink("EmergencyWithdraw") + ") (owner only)\n"
	out += "2. Withdraw winnings, refunds, bonds and backer dividends: [Claim](" + txLink("Claim") + ")\n\n"
	out += "CLI:\n\n```\ngnokey maketx call -pkgpath " + selfPath + " -func EmergencyWithdraw -args <boxID> \\\n  -gas-fee 1000000ugnot -gas-wanted 5000000 -broadcast -chainid onyx-1 \\\n  -remote https://rpc.onyx.testnets.gno.land:443 <your-key>\n```\n\n"
	open := ""
	boxes.Iterate("", "", func(k string, v any) bool {
		b := v.(*Box)
		if !b.Closed && b.Balance > 0 {
			open += "- Box #" + itoa(b.ID) + " · owner " + string(b.Owner) + " · " + strconv.FormatInt(b.Balance, 10) +
				" ugnot · [withdraw](" + txLink("EmergencyWithdraw", "boxID", itoa(b.ID)) + ")\n"
		}
		return false
	})
	if open != "" {
		out += "Open boxes:\n\n" + open
	}
	return out
}

func yesNo(b bool) string {
	if b {
		return "✅"
	}
	return "⏳"
}

func orDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

func kindIcon(k string) string {
	switch k {
	case "blocked":
		return "🛡️ blocked"
	case "slash":
		return "🔪 slash"
	case "preflight":
		return "🔍 preflight"
	case "exit":
		return "🚪 exit"
	}
	return k
}

func escapeMd(s string) string {
	s = strings.ReplaceAll(s, "|", "\\|")
	s = strings.ReplaceAll(s, "\n", " ")
	return s
}

// Package aegis_pit is the main Aegis Pit realm:
// an oracle-free prediction market on deterministic AI duels,
// with policy-locked budget boxes for AI agents and an always-on exit.
package aegis_pit

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	Denom              = "ugnot"
	MinBond      int64 = 1_000
	MinBet       int64 = 1
	CommitWindow int64 = 30 // blocks after both fighters are in
	RevealWindow int64 = 30 // blocks after the commit deadline
	MaxLab             = 50
)

var (
	selfPath   string          // e.g. gno.land/r/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_pit
	fighters   = avl.NewTree() // id -> *Fighter
	matches    = avl.NewTree() // id -> *Match
	boxes      = avl.NewTree() // id -> *Box
	credits    = avl.NewTree() // addr -> int64 claimable ugnot
	trust      = avl.NewTree() // owner addr -> *core.TrustRecord
	seasonFund int64
	nFighters  int
	nMatches   int
	nBoxes     int
	lab        []LabEvent
)

// LabEvent is a line in the Breaker Lab (blocked attacks, slashes, preflight reports).
type LabEvent struct {
	Height int64
	Kind   string
	Detail string
}

func init(cur realm) {
	selfPath = cur.PkgPath()
}

// ---------- helpers ----------

func height() int64 { return runtime.ChainHeight() }

func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 8 {
		s = "0" + s
	}
	return s
}

// takeDeposit returns the ugnot attached to a direct user call.
// Indirect calls are refused so OriginSend can't describe a phantom payment.
func takeDeposit(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("aegis: deposits must come from a direct user call (gnokey maketx call / gnoweb)")
	}
	return unsafe.OriginSend().AmountOf(Denom)
}

func caller(cur realm) address { return cur.Previous().Address() }

func send(cur realm, to address, amt int64) {
	if amt <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{Denom, amt}})
}

func addCredit(a address, amt int64) {
	if amt <= 0 {
		return
	}
	credits.Set(string(a), CreditOf(a)+amt)
}

func logLab(kind, detail string) {
	lab = append(lab, LabEvent{Height: height(), Kind: kind, Detail: detail})
	if len(lab) > MaxLab {
		lab = lab[len(lab)-MaxLab:]
	}
}

func linkPath() string {
	return strings.TrimPrefix(selfPath, "gno.land")
}

// txLink builds a gnoweb "$help" link that pre-fills a call form.
func txLink(fn string, kv ...string) string {
	s := linkPath() + "$help&func=" + fn
	for i := 0; i+1 < len(kv); i += 2 {
		s += "&" + kv[i] + "=" + kv[i+1]
	}
	return s
}

// ---------- credits (pull payments) ----------

// CreditOf returns claimable ugnot for an address (winnings, refunds, bonds, dividends).
func CreditOf(a address) int64 {
	v := credits.Get(string(a))
	if v == nil {
		return 0
	}
	return v.(int64)
}

// Claim withdraws all claimable ugnot to the caller.
func Claim(cur realm) int64 {
	who := caller(cur)
	amt := CreditOf(who)
	if amt <= 0 {
		panic("aegis: nothing to claim")
	}
	credits.Remove(string(who))
	send(cur, who, amt)
	return amt
}

// SeasonFund returns the season prize pool (2% of every ranked pool).
func SeasonFund() int64 { return seasonFund }

package aegis_pit

import (
	"encoding/base64"
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
)

// All visuals are generated on-chain and embedded as data-URI images,
// so gnoweb shows them with no external hosting.

const (
	cBg     = "#14110f"
	cPanel  = "#221c17"
	cGold   = "#e8b44a"
	cRed    = "#d9534f"
	cTeal   = "#3fb6a8"
	cText   = "#f3e9dc"
	cMuted  = "#9c8f80"
	svgFont = "font-family='ui-monospace,Menlo,monospace'"
)

func itoa(i int) string { return strconv.Itoa(i) }

func svgImage(alt, body string, w, h int) string {
	s := "<svg xmlns='http://www.w3.org/2000/svg' width='" + itoa(w) + "' height='" + itoa(h) +
		"' viewBox='0 0 " + itoa(w) + " " + itoa(h) + "'>" +
		"<rect width='100%' height='100%' rx='14' fill='" + cBg + "'/>" + body + "</svg>"
	return "![" + alt + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(s)) + ")"
}

func text(x, y int, size int, fill, anchor, s string) string {
	return "<text x='" + itoa(x) + "' y='" + itoa(y) + "' font-size='" + itoa(size) + "' fill='" + fill +
		"' text-anchor='" + anchor + "' " + svgFont + ">" + escape(s) + "</text>"
}

func rect(x, y, w, h int, fill string) string {
	return "<rect x='" + itoa(x) + "' y='" + itoa(y) + "' width='" + itoa(w) + "' height='" + itoa(h) +
		"' rx='4' fill='" + fill + "'/>"
}

func escape(s string) string {
	out := ""
	for _, r := range s {
		switch r {
		case '<':
			out += "&lt;"
		case '>':
			out += "&gt;"
		case '&':
			out += "&amp;"
		case '\'':
			out += "&#39;"
		default:
			out += string(r)
		}
	}
	return out
}

func hpBar(x, y, w, hp int, fill string) string {
	filled := w * hp / core.StartHP
	return rect(x, y, w, 14, cPanel) + rect(x, y, filled, 14, fill) +
		text(x+w/2, y+11, 11, cText, "middle", itoa(hp)+" HP")
}

// matchCardSVG draws the duel board: names, HP bars, pool split, phase.
func matchCardSVG(m *Match) string {
	fa := getFighter(m.A)
	nameB := "waiting…"
	if m.B != 0 {
		nameB = getFighter(m.B).Name
	}
	hpA, hpB := core.StartHP, core.StartHP
	if len(m.Log) > 0 {
		last := m.Log[len(m.Log)-1]
		hpA, hpB = last.HPA, last.HPB
	}
	if m.Status == StatusForfeit {
		if m.Winner == 1 {
			hpB = 0
		} else if m.Winner == 2 {
			hpA = 0
		} else {
			hpA, hpB = 0, 0
		}
	}
	body := text(20, 30, 13, cMuted, "start", "MATCH #"+itoa(m.ID)+" · "+modeLabel(m)+" · "+phase(m))
	body += text(20, 62, 18, cGold, "start", fa.Name)
	body += text(460, 62, 18, cTeal, "end", nameB)
	body += text(240, 62, 16, cMuted, "middle", "VS")
	body += hpBar(20, 74, 190, hpA, cGold)
	body += hpBar(270, 74, 190, hpB, cTeal)

	total := m.PoolA + m.PoolB
	wA := 220
	if total > 0 {
		wA = int(int64(440) * m.PoolA / total)
	}
	body += rect(20, 104, 440, 10, cTeal) + rect(20, 104, wA, 10, cGold)
	body += text(20, 134, 12, cText, "start", strconv.FormatInt(m.PoolA, 10)+" ugnot")
	body += text(460, 134, 12, cText, "end", strconv.FormatInt(m.PoolB, 10)+" ugnot")
	if m.Status == StatusResolved || m.Status == StatusForfeit {
		w := "DRAW"
		if m.Winner == 1 {
			w = fa.Name + " WINS"
		} else if m.Winner == 2 {
			w = nameB + " WINS"
		}
		body += text(240, 134, 13, cRed, "middle", w)
	}
	return svgImage("match "+itoa(m.ID), body, 480, 150)
}

func badgeSVG(name string) string {
	color := cGold
	switch name {
	case "Untouched":
		color = cTeal
	case "Giant Slayer":
		color = cRed
	}
	body := "<circle cx='40' cy='34' r='24' fill='" + cPanel + "' stroke='" + color + "' stroke-width='3'/>" +
		"<polygon points='40,18 45,30 58,31 48,39 51,52 40,45 29,52 32,39 22,31 35,30' fill='" + color + "'/>" +
		text(40, 78, 10, cText, "middle", name)
	return svgImage(name, body, 80, 88)
}

func modeLabel(m *Match) string {
	if m.Ranked {
		return "RANKED"
	}
	return "FRIENDLY"
}

func phase(m *Match) string {
	switch m.Status {
	case StatusLive:
		if height() <= m.CommitDeadline {
			return "COMMIT + BETS until #" + strconv.FormatInt(m.CommitDeadline, 10)
		}
		return "REVEAL until #" + strconv.FormatInt(m.RevealDeadline, 10)
	}
	return upper(m.Status)
}

func upper(s string) string {
	out := ""
	for _, r := range s {
		if r >= 'a' && r <= 'z' {
			r = r - 'a' + 'A'
		}
		out += string(r)
	}
	return out
}

// Package sample_consumer proves that other projects can reuse Aegis Pit:
//   - it imports the pure package /p/aegispit/aegis_core (policy + duel engine)
//   - it reads TrustScore from the /r/aegispit/aegis_pit realm
package sample_consumer

import (
	"strconv"

	core "gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core"
	pit "gno.land/r/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_pit/v2"
)

// MinTrust is the reputation required to enter the VIP table.
const MinTrust int64 = 520

var (
	vip      []address
	lastDuel string
)

// CheckSpend runs an arbitrary spend through an aegis_core Policy
// that only allows tipping the bartender up to 50 ugnot.
func CheckSpend(bartender, target address, fn string, amt int64) string {
	p, err := core.NewPolicy(string(bartender), "Tip", 50, 0)
	if err != nil {
		return "policy error: " + err.Error()
	}
	if err := core.ValidateSpend(p, target, fn, amt, 0); err != nil {
		return "DENIED: " + err.Error()
	}
	return "OK"
}

// PracticeDuel uses the same deterministic engine as the arena.
func PracticeDuel(cur realm, movesA, movesB string) int {
	if err := core.ValidateMoves(movesA); err != nil {
		panic(err.Error())
	}
	if err := core.ValidateMoves(movesB); err != nil {
		panic(err.Error())
	}
	w, _ := core.ResolveDuel(movesA, movesB)
	lastDuel = movesA + " vs " + movesB + " → winner " + strconv.Itoa(w)
	return w
}

// EnterVIP gates access on the caller's Aegis Pit trust score.
func EnterVIP(cur realm) {
	who := cur.Previous().Address()
	score := pit.TrustScore(who)
	if score < MinTrust {
		panic("trust " + strconv.FormatInt(score, 10) + " < " + strconv.FormatInt(MinTrust, 10) + ": win a ranked match in Aegis Pit first")
	}
	vip = append(vip, who)
}

func Render(path string) string {
	out := "# 🍺 Sample Consumer — The VIP Table\n\n"
	out += "This realm imports `gno.land/p/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_core` and reads `TrustScore` from `gno.land/r/g1tjs9agmvxqn4r245avwht57j8jgy5sapxq96ym/aegis_pit/v2`.\n\n"
	out += "- VIP entry needs trust ≥ " + strconv.FormatInt(MinTrust, 10) + "\n"
	out += "- VIP guests: " + strconv.Itoa(len(vip)) + "\n"
	if lastDuel != "" {
		out += "- Last practice duel: " + lastDuel + "\n"
	}
	return out
}

