func renderCheck(text string) string {
	out := "![soup](" + logo + ")\n\n"
	if strings.TrimSpace(text) == "" {
		return out + "Type a message first.\n\n" + form()
	}
	toxic, secret, flavor, conf := filter.Check(text)
	switch {
	case secret != "":
		out += "> [!CAUTION] Blocked: it leaks a secret (" + secret + ")\n> Do not store this message.\n\n"
	case toxic != "":
		out += "> [!CAUTION] Blocked: it is toxic (" + toxic + ")\n> Do not store this message.\n\n"
	default:
		out += "> [!SUCCESS] Safe to store\n> No secret, nothing toxic.\n\n"
	}
	out += "| Check | Result |\n|---|---|\n"
	out += "| secret | " + dash(secret) + " |\n"
	out += "| toxic | " + dash(toxic) + " |\n"
	out += "| flavor | " + dash(flavor) + " (" + ufmt.Sprintf("%d", conf) + "% sure) |\n\n"
	out += "Nothing was written on chain. Use made-up text here, never a real secret: the sentence is part of the page address.\n\n"
	out += "Check another:\n\n" + form()
	out += "<gno-button href=\"" + selfPath + "\" label=\"Back to soup\" variant=\"outline\" />\n"
	return out
}

func dash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

package soup

import (
	"strings"
	"testing"
)

func TestRender(t *testing.T) {
	home := Render("")
	for _, want := range []string{"version", "<gno-form", "gno-columns", "data:image/svg+xml"} {
		if !strings.Contains(home, want) {
			t.Errorf("home misses %q", want)
		}
	}
	s := Render("check?text=" + "%C5%9Fifrem+kartal1907")
	if !strings.Contains(s, "password") || !strings.Contains(s, "Blocked") {
		t.Errorf("form check: %s", s)
	}
	if strings.Contains(s, "kartal1907") {
		t.Errorf("the checked text must not be echoed")
	}
	s = Render("check/my%20password%20is%20eagle1907")
	if !strings.Contains(s, "Blocked") {
		t.Errorf("link check: %s", s)
	}
	s = Render("check?text=I+forgot+my+password+again")
	if !strings.Contains(s, "Safe to store") {
		t.Errorf("safe check: %s", s)
	}
	if !strings.Contains(Render("check?text="), "Type a message") {
		t.Errorf("empty check")
	}
}

// Package auditrules is a pure, stateless Gnolang package that audits the
// source text of a Gno.land realm and returns deterministic findings.
//
// It does not read chain state, it does not call other realms, and it does
// not depend on any realm package. The rules are lexical: they scan source
// text line by line, track function spans and brace depth, and look for
// known risky shapes. They are signals, not proofs. A finding means "a
// human should look at this line", and a clean result means "no known
// shape was found", not "this realm is safe".
//
// The package deliberately uses only the strings and strconv standard
// libraries. See README.md for the full list of Gnolang limits that
// shaped this design.
package auditrules

import (
	"strconv"
	"strings"
)

// MaxSourceBytes caps the audited input. Longer sources are truncated to
// this size before scanning, so a hostile or accidental huge input cannot
// make an audit consume unbounded gas.
const MaxSourceBytes = 262144

// MaxLines caps the number of source lines scanned.
const MaxLines = 20000

// MaxFindings caps the number of findings Audit returns.
const MaxFindings = 256

// Severity grades how serious a finding is.
type Severity string

const (
	// SeverityCritical marks a finding that can directly lose funds or
	// hand full control of a realm to one party.
	SeverityCritical Severity = "critical"
	// SeverityHigh marks a finding that can lose funds or break access
	// control when the flagged code is reachable.
	SeverityHigh Severity = "high"
	// SeverityMedium marks a finding that is risky or unfair but needs
	// extra conditions to cause harm.
	SeverityMedium Severity = "medium"
	// SeverityLow marks a finding worth fixing but unlikely to cause
	// direct harm on its own.
	SeverityLow Severity = "low"
)

// Finding is one audit result. Line is 1-based. SourceLine is the exact
// source line (trimmed) that triggered the finding, so a report can cite
// it verbatim. File is empty when the caller audited a bare source
// string; AuditFile fills it in.
type Finding struct {
	RuleID      string
	Severity    Severity
	Title       string
	Description string
	File        string
	Line        int
	SourceLine  string
}

// Report is one stored audit report. It is defined here, in the rules
// package, so the report realm, the web UI, and the agent mode all share
// one shape. Height is the block height the report was stored at.
type Report struct {
	ID         int
	RealmPath  string
	SourceHash string
	Score      int
	Auditor    string
	Height     int64
	Findings   []Finding
}

// Rule describes one audit rule in the catalog.
type Rule struct {
	ID          string
	Name        string
	Severity    Severity
	Description string
}

// Rule IDs. Keep them stable: reports stored on chain cite them.
const (
	RuleNoCallerGuard     = "RC-01"
	RuleUnrestrictedMint  = "RC-02"
	RuleAdminBackdoor     = "RC-03"
	RuleUnboundedStorage  = "RC-04"
	RuleFundsWithoutCheck = "RC-05"
	RuleWeakRandomness    = "RC-06"
	RuleUncheckedCall     = "RC-07"
	RulePublicMutation    = "RC-08"
)

// Rules returns the full rule catalog in ID order.
func Rules() []Rule {
	return []Rule{
		{
			ID:          RuleNoCallerGuard,
			Name:        "Sensitive function without caller check",
			Severity:    SeverityHigh,
			Description: "An exported function moves funds or changes admin state but contains no caller guard such as IsUser, IsRealm, OriginCaller, or an owner check. Any caller can invoke it.",
		},
		{
			ID:          RuleUnrestrictedMint,
			Name:        "Unrestricted mint",
			Severity:    SeverityCritical,
			Description: "A mint function issues coins or grows supply with no access control. Anyone can mint new tokens.",
		},
		{
			ID:          RuleAdminBackdoor,
			Name:        "Single admin backdoor",
			Severity:    SeverityCritical,
			Description: "A single stored or hard-coded admin or owner address can drain funds or rewrite state, and the path has no timelock or multi-signature check. One key controls the funds.",
		},
		{
			ID:          RuleUnboundedStorage,
			Name:        "Unbounded storage growth",
			Severity:    SeverityMedium,
			Description: "A persistent collection is appended to with no length check or cap in the same function. Storage, and the deposit that pays for it, can grow without bound.",
		},
		{
			ID:          RuleFundsWithoutCheck,
			Name:        "Funds accepted without a check",
			Severity:    SeverityHigh,
			Description: "A function reads coins sent with the transaction through OriginSend but never verifies the sender amount with AmountOf, IsGTE, IsEqual, or an equivalent check.",
		},
		{
			ID:          RuleWeakRandomness,
			Name:        "Weak randomness",
			Severity:    SeverityMedium,
			Description: "Block height, block time, or time.Now is used with modulo or a random call to pick a winner or outcome. Block values are public and partly miner or proposer influenced, so the outcome is predictable.",
		},
		{
			ID:          RuleUncheckedCall,
			Name:        "Unchecked external realm call",
			Severity:    SeverityMedium,
			Description: "A cross-realm call is made as a bare statement and its return value or failure is ignored. A failed call in another realm can pass silently.",
		},
		{
			ID:          RulePublicMutation,
			Name:        "Public state mutation without guard",
			Severity:    SeverityHigh,
			Description: "An exported function mutates realm state with no caller guard at all. Anyone can rewrite that state.",
		},
	}
}

// RuleByID returns the catalog entry for id, or false when id is unknown.
func RuleByID(id string) (Rule, bool) {
	for _, r := range Rules() {
		if r.ID == id {
			return r, true
		}
	}
	return Rule{}, false
}

// SeverityWeight is the score cost of one finding of the given severity.
func SeverityWeight(s Severity) int {
	switch s {
	case SeverityCritical:
		return 25
	case SeverityHigh:
		return 15
	case SeverityMedium:
		return 8
	case SeverityLow:
		return 3
	default:
		return 0
	}
}

// Score turns findings into a 0 to 100 risk score. 100 means no findings.
// Each finding subtracts its severity weight, and the result never goes
// below 0. The score is deterministic: same source, same score.
func Score(findings []Finding) int {
	score := 100
	for _, f := range findings {
		score -= SeverityWeight(f.Severity)
	}
	if score < 0 {
		score = 0
	}
	return score
}

// Audit audits one realm source text and returns its findings in rule
// order, then line order. The input is capped at MaxSourceBytes.
func Audit(src string) []Finding {
	return AuditFile("", src)
}

// AuditFile is Audit with a file name attached to every finding, so a
// report can cite the file the line came from.
func AuditFile(file string, src string) []Finding {
	ps := parseSource(src)
	out := make([]Finding, 0, 16)
	out = append(out, checkNoCallerGuard(ps)...)
	out = append(out, checkUnrestrictedMint(ps)...)
	out = append(out, checkAdminBackdoor(ps)...)
	out = append(out, checkUnboundedStorage(ps)...)
	out = append(out, checkFundsWithoutCheck(ps)...)
	out = append(out, checkWeakRandomness(ps)...)
	out = append(out, checkUncheckedCall(ps)...)
	out = append(out, checkPublicMutation(ps)...)
	for i := range out {
		out[i].File = file
	}
	out = dedupeFindings(out)
	if len(out) > MaxFindings {
		out = out[:MaxFindings]
	}
	return out
}

func dedupeFindings(in []Finding) []Finding {
	seen := make(map[string]bool)
	out := make([]Finding, 0, len(in))
	for _, f := range in {
		key := f.RuleID + ":" + strconv.Itoa(f.Line)
		if seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, f)
	}
	return out
}

func newFinding(rule Rule, line int, rawLine string, desc string) Finding {
	return Finding{
		RuleID:      rule.ID,
		Severity:    rule.Severity,
		Title:       rule.Name,
		Description: desc,
		Line:        line,
		SourceLine:  strings.TrimSpace(rawLine),
	}
}

func ruleByIDMust(id string) Rule {
	r, _ := RuleByID(id)
	return r
}

// funcSpan is one top-level function or method in the audited source.
// Start and End are 1-based inclusive line numbers. Receiver is the
// receiver type name for a method, or "" for a plain function. Params
// are the parameter names in order, and Tainted marks the parameters
// that receive a randomness source through a call (RC-06 taint).
type funcSpan struct {
	name        string
	start       int
	end         int
	exported    bool
	receiver    string
	receiverVar string
	params      []string
	tainted     []bool
}

// parsedSource is the audited source after cleaning and structure scan.
type parsedSource struct {
	raw           []string
	clean         []string
	funcs         []funcSpan
	pkgVars       []string
	adminVars     []string
	adminConsts   []string
	adminAddrLine int
}

// parseSource splits src into lines, blanks out comments and string
// contents for matching (the raw lines are kept for excerpts), then
// records top-level functions and package-level variables.
func parseSource(src string) *parsedSource {
	if len(src) > MaxSourceBytes {
		src = src[:MaxSourceBytes]
	}
	raw := strings.Split(src, "\n")
	if len(raw) > MaxLines {
		raw = raw[:MaxLines]
	}
	ps := &parsedSource{
		raw:   raw,
		clean: make([]string, len(raw)),
	}
	inBlock := false
	inRaw := false
	for i, line := range raw {
		ps.clean[i] = cleanLine(line, &inBlock, &inRaw)
	}
	ps.scanStructure()
	return ps
}

// cleanLine returns a copy of line with comments and string or rune
// literal contents replaced by spaces. Positions are preserved, so
// brace counting and keyword search on the result cannot be fooled by
// a keyword sitting inside a comment or a string literal. inBlock and
// inRaw carry block comment and raw string state across lines.
func cleanLine(line string, inBlock *bool, inRaw *bool) string {
	out := []byte(line)
	i := 0
	for i < len(out) {
		if *inRaw {
			if out[i] == '`' {
				*inRaw = false
			} else {
				out[i] = ' '
			}
			i++
			continue
		}
		if *inBlock {
			if out[i] == '*' && i+1 < len(out) && out[i+1] == '/' {
				out[i] = ' '
				out[i+1] = ' '
				*inBlock = false
				i += 2
				continue
			}
			out[i] = ' '
			i++
			continue
		}
		c := out[i]
		if c == '`' {
			*inRaw = true
			out[i] = ' '
			i++
			continue
		}
		if c == '"' {
			out[i] = ' '
			i++
			for i < len(out) {
				if out[i] == '\\' {
					out[i] = ' '
					if i+1 < len(out) {
						out[i+1] = ' '
					}
					i += 2
					continue
				}
				if out[i] == '"' {
					out[i] = ' '
					i++
					break
				}
				out[i] = ' '
				i++
			}
			continue
		}
		if c == '\'' {
			out[i] = ' '
			i++
			for i < len(out) {
				if out[i] == '\\' {
					out[i] = ' '
					if i+1 < len(out) {
						out[i+1] = ' '
					}
					i += 2
					continue
				}
				if out[i] == '\'' {
					out[i] = ' '
					i++
					break
				}
				out[i] = ' '
				i++
			}
			continue
		}
		if c == '/' && i+1 < len(out) && out[i+1] == '/' {
			for ; i < len(out); i++ {
				out[i] = ' '
			}
			break
		}
		if c == '/' && i+1 < len(out) && out[i+1] == '*' {
			out[i] = ' '
			out[i+1] = ' '
			*inBlock = true
			i += 2
			continue
		}
		i++
	}
	return string(out)
}

func countBraces(line string) int {
	depth := 0
	for i := 0; i < len(line); i++ {
		if line[i] == '{' {
			depth++
		} else if line[i] == '}' {
			depth--
		}
	}
	return depth
}

func isExported(name string) bool {
	if len(name) == 0 {
		return false
	}
	return name[0] >= 'A' && name[0] <= 'Z'
}

// parseFuncName extracts the function name from a trimmed line that
// starts with "func ". It handles methods with a receiver in parens.
func parseFuncName(trimmed string) (string, bool) {
	rest := strings.TrimSpace(trimmed[len("func "):])
	if strings.HasPrefix(rest, "(") {
		idx := strings.Index(rest, ")")
		if idx < 0 {
			return "", false
		}
		rest = strings.TrimSpace(rest[idx+1:])
	}
	end := strings.Index(rest, "(")
	if end < 0 {
		return "", false
	}
	name := strings.TrimSpace(rest[:end])
	if name == "" {
		return "", false
	}
	return name, true
}

// parseFuncReceiver extracts the receiver variable name and type name
// from a trimmed line that starts with "func (", or "" and "" for a plain
// function. The type is the last field inside the receiver parens, with a
// leading * stripped and a package qualifier removed, so
// (ps *Proposals) yields variable ps and type Proposals. An unnamed
// receiver yields "" for the variable name.
func parseFuncReceiver(trimmed string) (string, string) {
	rest := strings.TrimSpace(trimmed[len("func "):])
	if !strings.HasPrefix(rest, "(") {
		return "", ""
	}
	idx := strings.Index(rest, ")")
	if idx < 0 {
		return "", ""
	}
	inner := strings.TrimSpace(rest[1:idx])
	if inner == "" {
		return "", ""
	}
	fields := strings.Fields(inner)
	typ := fields[len(fields)-1]
	typ = strings.TrimPrefix(typ, "*")
	if dot := strings.LastIndex(typ, "."); dot >= 0 {
		typ = typ[dot+1:]
	}
	if len(fields) == 1 {
		return "", typ
	}
	return fields[0], typ
}

// builtinTypeNames are single-word parameter spellings that name a type,
// not a parameter, so `func Foo(int, string)` records no parameters.
var builtinTypeNames = map[string]bool{
	"int": true, "int8": true, "int16": true, "int32": true, "int64": true,
	"uint": true, "uint8": true, "uint16": true, "uint32": true, "uint64": true,
	"string": true, "bool": true, "byte": true, "rune": true,
	"float32": true, "float64": true, "error": true, "address": true,
	"realm": true, "any": true,
}

// parseFuncParams extracts the parameter names of the function declared
// on trimmed, in order. It returns nil for a multi-line signature, whose
// closing paren is not on this line, and for a function with no named
// parameters. Grouped names (a, b int) and variadic parameters are
// handled; unnamed parameters are skipped. A single-word part that starts
// with an uppercase letter is a type name, not a parameter name, so an
// unnamed parameter of a named type is skipped too.
func parseFuncParams(trimmed string) []string {
	rest := strings.TrimSpace(trimmed[len("func "):])
	if strings.HasPrefix(rest, "(") {
		idx := strings.Index(rest, ")")
		if idx < 0 {
			return nil
		}
		rest = strings.TrimSpace(rest[idx+1:])
	}
	open := strings.Index(rest, "(")
	if open < 0 {
		return nil
	}
	depth := 0
	close := -1
	for i := open; i < len(rest); i++ {
		if rest[i] == '(' {
			depth++
		} else if rest[i] == ')' {
			depth--
			if depth == 0 {
				close = i
				break
			}
		}
	}
	if close < 0 {
		return nil
	}
	inner := rest[open+1 : close]
	if strings.TrimSpace(inner) == "" {
		return nil
	}
	var params []string
	for _, part := range splitTopLevel(inner, ',') {
		fields := strings.Fields(part)
		if len(fields) == 0 {
			continue
		}
		name := strings.TrimPrefix(fields[0], "*")
		if len(fields) == 1 {
			if builtinTypeNames[name] {
				continue
			}
			if len(name) > 0 && name[0] >= 'A' && name[0] <= 'Z' {
				continue
			}
		}
		params = append(params, name)
	}
	return params
}

// splitTopLevel splits s on sep, ignoring separators nested inside
// parentheses.
func splitTopLevel(s string, sep byte) []string {
	var out []string
	depth := 0
	start := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '(':
			depth++
		case ')':
			depth--
		case sep:
			if depth == 0 {
				out = append(out, s[start:i])
				start = i + 1
			}
		}
	}
	out = append(out, s[start:])
	return out
}

// isIdentStart reports whether c can start a Go identifier.
func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

// isIdentChar reports whether c can appear in a Go identifier.
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

// scanStructure walks the cleaned lines once, tracking brace depth to
// find top-level functions and package-level variables.
func (ps *parsedSource) scanStructure() {
	depth := 0
	curIdx := -1
	seenBrace := false
	inDeclBlock := false
	for i := 0; i < len(ps.clean); i++ {
		trimmed := strings.TrimSpace(ps.clean[i])
		before := depth
		if curIdx == -1 && before == 0 {
			if strings.HasPrefix(trimmed, "func ") {
				if name, ok := parseFuncName(trimmed); ok {
					receiverVar, receiver := parseFuncReceiver(trimmed)
					params := parseFuncParams(trimmed)
					ps.funcs = append(ps.funcs, funcSpan{
						name:        name,
						start:       i + 1,
						end:         i + 1,
						receiver:    receiver,
						receiverVar: receiverVar,
						params:      params,
						tainted:     make([]bool, len(params)),
						// A method on an unexported type is only
						// reachable from the realm's own code, even
						// when the method name is exported, so it
						// counts as non-exported for the access
						// control rules. Note that a capitalized type
						// name is exported by this test: gov/dao
						// Proposals is capitalized, so its methods
						// stay exported here, and RC-08 clears them
						// instead because their mutations target only
						// the receiver.
						exported: isExported(name) && (receiver == "" || isExported(receiver)),
					})
					curIdx = len(ps.funcs) - 1
					seenBrace = false
				}
			} else if strings.HasPrefix(trimmed, "var (") || strings.HasPrefix(trimmed, "const (") {
				inDeclBlock = true
			} else if inDeclBlock {
				if strings.HasPrefix(trimmed, ")") {
					inDeclBlock = false
				} else {
					// Inside a var or const block the name is the
					// first field, not the second, so prepend a
					// marker to keep addPkgVar's field positions.
					fields := append([]string{"var"}, strings.Fields(trimmed)...)
					ps.addPkgVar(fields, ps.raw[i])
				}
			} else if strings.HasPrefix(trimmed, "var ") || strings.HasPrefix(trimmed, "const ") {
				ps.addPkgVar(strings.Fields(trimmed), ps.raw[i])
			}
			// The address literal lives inside a string, and string
			// contents are blanked on the cleaned line, so this check
			// must read the raw line.
			lowerRaw := strings.ToLower(ps.raw[i])
			if strings.Contains(lowerRaw, "g1") && (strings.Contains(lowerRaw, "admin") || strings.Contains(lowerRaw, "owner")) {
				if ps.adminAddrLine == 0 {
					ps.adminAddrLine = i + 1
				}
			}
		}
		depth += countBraces(ps.clean[i])
		if curIdx >= 0 {
			if strings.Contains(ps.clean[i], "{") {
				seenBrace = true
			}
			ps.funcs[curIdx].end = i + 1
			if seenBrace && depth == 0 {
				curIdx = -1
			}
		}
	}
}

// addPkgVar records a package-level variable or constant name from the
// fields of its declaration line. fields[0] is "var" or "const" and
// fields[1] is the name. Admin or owner names are also recorded
// separately for the backdoor rule. A hard-coded admin constant is an
// admin or owner name initialized with an address literal on the raw
// line: the cleaned line cannot show it, because string contents are
// blanked before scanning.
func (ps *parsedSource) addPkgVar(fields []string, rawLine string) {
	if len(fields) < 2 {
		return
	}
	name := fields[1]
	name = strings.TrimSuffix(name, ",")
	if name == "" {
		return
	}
	ps.pkgVars = append(ps.pkgVars, name)
	lower := strings.ToLower(name)
	if strings.Contains(lower, "admin") || strings.Contains(lower, "owner") {
		ps.adminVars = append(ps.adminVars, name)
		if strings.Contains(rawLine, "\"g1") {
			ps.adminConsts = append(ps.adminConsts, name)
		}
	}
}

// bodyLine returns the cleaned text of line i that belongs to the
// function body. On the signature line only the text after the opening
// brace counts, so the function name itself can never match an action
// token such as Withdraw, while a single-line function still scans its
// body. When the brace opens on a later line, the signature line
// contributes nothing.
func (ps *parsedSource) bodyLine(fn funcSpan, i int) string {
	line := ps.clean[i]
	if i == fn.start-1 {
		if idx := strings.Index(line, "{"); idx >= 0 {
			return line[idx+1:]
		}
		return ""
	}
	return line
}

// firstLineWith returns the 1-based line number of the first line in fn
// whose cleaned text contains any token, or 0 when there is none.
func (ps *parsedSource) firstLineWith(fn funcSpan, tokens []string) int {
	for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
		for _, tok := range tokens {
			if strings.Contains(ps.bodyLine(fn, i), tok) {
				return i + 1
			}
		}
	}
	return 0
}

// bodyHasAny reports whether any line of fn contains any token.
func (ps *parsedSource) bodyHasAny(fn funcSpan, tokens []string) bool {
	return ps.firstLineWith(fn, tokens) != 0
}

// lineAssignsPkgVar reports whether the cleaned line assigns to one of
// the package-level variables, using =, :=, +=, or -=.
func (ps *parsedSource) lineAssignsPkgVar(line string) bool {
	trimmed := strings.TrimSpace(line)
	for _, v := range ps.pkgVars {
		if strings.HasPrefix(trimmed, v+" =") ||
			strings.HasPrefix(trimmed, v+" :=") ||
			strings.HasPrefix(trimmed, v+" +=") ||
			strings.HasPrefix(trimmed, v+" -=") {
			return true
		}
	}
	return false
}

// Rule implementations for auditrules.
//
// Each rule has one internal check that works on a parsed source (so
// Audit parses once) and one exported Check function that parses its
// input first (so a caller can run a single rule on its own).
//
// Overlap policy, so one root cause does not produce a stack of findings
// for the same line: IssueCoin is covered by RC-02, not RC-01. Mint and
// withdraw style functions are covered by RC-01, RC-02, and RC-03, not
// RC-08. Append growth is covered by RC-04, not RC-08. A guard that lives
// in a wrapper function does not count: the guard must appear in the same
// function body, because this scanner does not follow calls. That choice
// can produce a false positive when the guard is in the caller; the
// description of each rule says so where it matters. The same applies to
// a mutation inside a closure passed to another function, such as a DAO
// proposal executor: the closure body is scanned as part of the enclosing
// function, because the scanner cannot prove the callee only runs it
// after a vote, and trusting the callee name would hide a real finding in
// a realm that invokes the closure immediately.

package auditrules

import "strings"

// guardTokens are text shapes that count as a caller check inside a
// function body. They cover the standard Gno caller primitives
// (IsUser, IsRealm, OriginCaller, PreviousRealm, AssertOriginCall) and
// the common owner and admin guard idioms. Note: IsUser on its own is a
// weaker guard than IsUserCall for payment paths, because IsUser also
// accepts MsgRun ephemeral realms. This scanner counts it, per the rule
// definition; a stricter payment-path rule is future work.
// Any assert* helper call counts as a guard: by Gno convention an assert
// helper panics when its check fails, so a function that calls one is
// guarded on the condition it asserts. Admin and owner comparisons in
// either order count, so `caller != Admin` and `Admin != caller` are
// both recognized.
var guardTokens = []string{
	"IsUserCall", "IsUserRun", "IsUser(", "IsRealm(", "OriginCaller",
	"AssertOriginCall", "PreviousRealm", "AssertCaller", "IsCurrent(",
	"OnlyOwner", "AssertOwner", "RequireOwner", "MustBeOwner",
	"CheckOwner", "AssertAuthorized", "RequireAdmin", "AssertAdmin",
	"IsAdmin(", "IsOwner(", "Authorized",
	"assert", "Assert",
	"owner ==", "owner !=", "admin ==", "admin !=",
	"Owner ==", "Owner !=", "Admin ==", "Admin !=",
	"caller ==", "caller !=",
}

// timelockTokens suppress the admin backdoor rule: a drain that can only
// run after a delay, or only with several approvals, is not a silent
// single-key backdoor.
var timelockTokens = []string{
	"Timelock", "timelock", "TimeLock", "UnlockTime", "unlockTime",
	"ExecuteAfter", "executeAfter", "MinDelay", "minDelay",
	"TooEarly", "tooEarly", "NotYet", "Scheduled", "scheduled",
}

// multisigTokens suppress the admin backdoor rule for the same reason.
var multisigTokens = []string{
	"MultiSig", "multisig", "Threshold", "threshold",
	"Approvals", "approvals", "Confirmations", "confirmations",
	"Signers", "signers",
}

// CheckNoCallerGuard runs rule RC-01 on src.
func CheckNoCallerGuard(src string) []Finding {
	return checkNoCallerGuard(parseSource(src))
}

// checkNoCallerGuard implements RC-01: an exported function that moves
// funds or changes admin state with no caller guard in its own body.
func checkNoCallerGuard(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleNoCallerGuard)
	actions := []string{
		"SendCoins", "RemoveCoin", "TransferOwnership",
		"SetOwner", "SetAdmin", "ChangeOwner", "ChangeAdmin",
		"Withdraw", "Transfer(",
	}
	var out []Finding
	for _, fn := range ps.funcs {
		if !fn.exported {
			continue
		}
		if strings.Contains(fn.name, "Mint") {
			continue
		}
		if ps.bodyHasAny(fn, guardTokens) {
			continue
		}
		line := ps.firstLineWith(fn, actions)
		if line == 0 {
			continue
		}
		desc := "Function " + fn.name + " moves funds or changes admin state but contains no caller check in its own body. Add a guard such as cur.Previous().IsUserCall(), an OriginCaller comparison against the stored owner, or an AssertOwner call before the sensitive action. A guard in a wrapper function does not count for this check."
		out = append(out, newFinding(rule, line, ps.raw[line-1], desc))
	}
	return out
}

// CheckUnrestrictedMint runs rule RC-02 on src.
func CheckUnrestrictedMint(src string) []Finding {
	return checkUnrestrictedMint(parseSource(src))
}

// checkUnrestrictedMint implements RC-02: a function named Mint that
// issues coins or grows supply with no caller guard in its own body.
func checkUnrestrictedMint(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleUnrestrictedMint)
	mintEvidence := []string{"IssueCoin", "Supply", "balances", "Balance"}
	var out []Finding
	for _, fn := range ps.funcs {
		if !fn.exported {
			continue
		}
		if !strings.Contains(fn.name, "Mint") {
			continue
		}
		if ps.bodyHasAny(fn, guardTokens) {
			continue
		}
		if !ps.bodyHasAny(fn, mintEvidence) {
			continue
		}
		desc := "Function " + fn.name + " mints new coins with no caller check in its own body. Restrict minting to an authorized minter or owner, and cap total supply where the design allows it. A guard in a wrapper function does not count for this check."
		out = append(out, newFinding(rule, fn.start, ps.raw[fn.start-1], desc))
	}
	return out
}

// CheckAdminBackdoor runs rule RC-03 on src.
func CheckAdminBackdoor(src string) []Finding {
	return checkAdminBackdoor(parseSource(src))
}

// checkAdminBackdoor implements RC-03: a single admin or owner can drain
// funds or rewrite state, and the path has no timelock or multi-signature
// check. Two shapes are covered. The stored-admin shape: a package-level
// admin or owner variable is mentioned on the drain path of a function
// that calls SendCoins or Withdraw. The hard-coded shape: a package-level
// admin or owner constant initialized with an address literal is the guard
// on a function that drains funds or rewrites persistent state, so the
// single hard-coded key is the only access control on that path. This is
// a design level finding: the code may be intentional, but one key
// controls the funds, so it must be reviewed.
func checkAdminBackdoor(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleAdminBackdoor)
	drain := []string{"SendCoins", "Withdraw"}
	adminMention := []string{"admin", "Admin", "owner", "Owner"}
	var out []Finding
	for _, fn := range ps.funcs {
		if !fn.exported {
			continue
		}
		if ps.bodyHasAny(fn, timelockTokens) || ps.bodyHasAny(fn, multisigTokens) {
			continue
		}
		line := 0
		if len(ps.adminVars) > 0 {
			if l := ps.firstLineWith(fn, drain); l != 0 && ps.bodyHasAny(fn, adminMention) {
				line = l
			}
		}
		if line == 0 && len(ps.adminConsts) > 0 {
			line = ps.firstHardcodedAdminDrain(fn)
		}
		if line == 0 {
			continue
		}
		desc := "Function " + fn.name + " lets a single stored or hard-coded admin or owner drain funds or rewrite state, with no timelock or multi-signature check on the path. Consider a timelock, a multi-signature threshold, or a capped withdrawal before deploying with real funds."
		out = append(out, newFinding(rule, line, ps.raw[line-1], desc))
	}
	return out
}

// firstHardcodedAdminDrain returns the line of the first drain or
// persistent state rewrite in fn, when fn compares a value against a
// hard-coded admin or owner constant, or 0 otherwise. A drain is a
// SendCoins or Withdraw call. A rewrite is an assignment to a
// package-level variable or a Set, Delete, or Remove call. Append lines
// are skipped: unbounded appends belong to RC-04, not to this rule.
func (ps *parsedSource) firstHardcodedAdminDrain(fn funcSpan) int {
	guarded := false
	for _, name := range ps.adminConsts {
		if ps.bodyComparesAgainst(fn, name) {
			guarded = true
			break
		}
	}
	if !guarded {
		return 0
	}
	drain := []string{"SendCoins", "Withdraw"}
	if line := ps.firstLineWith(fn, drain); line != 0 {
		return line
	}
	mutateTokens := []string{".Set(", ".Delete(", ".Remove("}
	for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
		line := ps.bodyLine(fn, i)
		if strings.Contains(line, "append(") {
			continue
		}
		if containsAny(line, mutateTokens) {
			return i + 1
		}
		if ps.lineAssignsPkgVar(line) {
			return i + 1
		}
	}
	return 0
}

// bodyComparesAgainst reports whether any line of fn compares a value
// against name with == or !=, the shape of a guard such as
// caller != Admin.
func (ps *parsedSource) bodyComparesAgainst(fn funcSpan, name string) bool {
	for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
		line := ps.bodyLine(fn, i)
		if !strings.Contains(line, name) {
			continue
		}
		if strings.Contains(line, "==") || strings.Contains(line, "!=") {
			return true
		}
	}
	return false
}

// CheckUnboundedStorage runs rule RC-04 on src.
func CheckUnboundedStorage(src string) []Finding {
	return checkUnboundedStorage(parseSource(src))
}

// checkUnboundedStorage implements RC-04: a persistent collection, a
// package-level slice or a struct field, is appended to with no length
// check or cap token in the same function. Appends to local slices are
// not flagged, because they do not persist.
func checkUnboundedStorage(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleUnboundedStorage)
	capTokens := []string{"len(", "Max", "Limit", "limit"}
	var out []Finding
	for _, fn := range ps.funcs {
		if ps.bodyHasAny(fn, capTokens) {
			continue
		}
		for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
			line := ps.bodyLine(fn, i)
			if !strings.Contains(line, "append(") {
				continue
			}
			target := appendTarget(line)
			if target == "" {
				continue
			}
			if !isPersistentTarget(ps, target) {
				continue
			}
			desc := "Function " + fn.name + " appends to persistent collection " + target + " with no length check or cap in the same function. Add a maximum size and reject or prune entries past it, or the storage deposit grows without bound."
			out = append(out, newFinding(rule, i+1, ps.raw[i], desc))
			break
		}
	}
	return out
}

// appendTarget returns the first argument of the append call on line,
// or "" when the line has no well formed append call.
func appendTarget(line string) string {
	idx := strings.Index(line, "append(")
	if idx < 0 {
		return ""
	}
	rest := line[idx+len("append("):]
	comma := strings.Index(rest, ",")
	if comma < 0 {
		return ""
	}
	return strings.TrimSpace(rest[:comma])
}

// isPersistentTarget reports whether an append target is persistent
// state: a package-level variable, or a field access such as s.items.
func isPersistentTarget(ps *parsedSource, target string) bool {
	for _, v := range ps.pkgVars {
		if target == v {
			return true
		}
	}
	return strings.Contains(target, ".")
}

// CheckFundsWithoutCheck runs rule RC-05 on src.
func CheckFundsWithoutCheck(src string) []Finding {
	return checkFundsWithoutCheck(parseSource(src))
}

// checkFundsWithoutCheck implements RC-05: a function reads coins sent
// with the transaction through OriginSend but never verifies the amount
// with AmountOf, IsGTE, IsEqual, IsPositive, IsZero, or GetCoin.
func checkFundsWithoutCheck(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleFundsWithoutCheck)
	verifyTokens := []string{
		"AmountOf", "IsGTE", "IsEqual", "IsPositive", "IsZero",
		"GetCoin", "IsNegative",
	}
	var out []Finding
	for _, fn := range ps.funcs {
		line := ps.firstLineWith(fn, []string{"OriginSend"})
		if line == 0 {
			continue
		}
		if ps.bodyHasAny(fn, verifyTokens) {
			continue
		}
		desc := "Function " + fn.name + " reads coins sent with the transaction through OriginSend but never verifies the amount. Check the received amount against the expected price or minimum with AmountOf or an IsGTE comparison before crediting anything."
		out = append(out, newFinding(rule, line, ps.raw[line-1], desc))
	}
	return out
}

// CheckWeakRandomness runs rule RC-06 on src.
func CheckWeakRandomness(src string) []Finding {
	return checkWeakRandomness(parseSource(src))
}

// checkWeakRandomness implements RC-06: block height, block time, or
// time.Now is used on the same line as modulo or a random call, which is
// the classic weak randomness shape, or is passed as an argument to a
// helper that applies modulo or a random call to that parameter. Taint
// follows parameters across calls in the same file, so a split like
// DrawNumber passing ChainHeight into DrawNumberAt, which does the
// modulo, is caught at the modulo line in the helper. Height or time used
// for a deadline comparison, with no modulo or random call, is not
// flagged. A helper defined in another file of the same realm is not
// tracked, and taint does not follow local variables: only the parameter
// itself, used directly with modulo or a random call, is flagged.
func checkWeakRandomness(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleWeakRandomness)
	sources := []string{
		"ChainHeight", "BlockHeight", "blockHeight",
		"ChainTime", "BlockTime", "blockTime",
		"time.Now", "UnixNano", "Unix()",
	}
	use := []string{"%", "rand", "Random", "Seed"}
	ps.computeTaint(sources)
	var out []Finding
	for _, fn := range ps.funcs {
		for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
			line := ps.bodyLine(fn, i)
			direct := containsAny(line, sources) && containsAny(line, use)
			tainted := false
			if !direct {
				tainted = ps.lineUsesTaintedParam(fn, line, use)
			}
			if !direct && !tainted {
				continue
			}
			var desc string
			if direct {
				desc = "Function " + fn.name + " derives a random outcome from block height, block time, or time.Now. These values are public and partly predictable, so the outcome can be anticipated. Use a commit-reveal scheme or an external verifiable randomness source instead."
			} else {
				desc = "Function " + fn.name + " receives block height, block time, or time.Now as a parameter and applies modulo or a random call to it. The caller passes a public, partly predictable value, so the outcome can be anticipated. Use a commit-reveal scheme or an external verifiable randomness source instead."
			}
			out = append(out, newFinding(rule, i+1, ps.raw[i], desc))
			break
		}
	}
	return out
}

// computeTaint marks, for every function, which of its parameters receive
// a randomness source, directly as a call argument or transitively
// through another tainted parameter. It runs to a fixed point, capped at
// eight passes, so it always terminates. A call is only tracked when its
// callee is defined in the same audited source; calls into other files or
// packages are not followed.
func (ps *parsedSource) computeTaint(sources []string) {
	byName := make(map[string]int, len(ps.funcs))
	for i, fn := range ps.funcs {
		if _, ok := byName[fn.name]; !ok {
			byName[fn.name] = i
		}
	}
	for pass := 0; pass < 8; pass++ {
		changed := false
		for _, fn := range ps.funcs {
			for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
				line := ps.bodyLine(fn, i)
				if !strings.Contains(line, "(") {
					continue
				}
				for _, call := range findCalls(line, byName) {
					ci := byName[call.name]
					for j, arg := range call.args {
						if j >= len(ps.funcs[ci].params) {
							break
						}
						if ps.funcs[ci].tainted[j] {
							continue
						}
						if containsAny(arg, sources) || ps.argUsesTaintedParam(fn, arg) {
							ps.funcs[ci].tainted[j] = true
							changed = true
						}
					}
				}
			}
		}
		if !changed {
			break
		}
	}
}

// callSite is one call found on a line: the callee name and its argument
// texts, split at top-level commas.
type callSite struct {
	name string
	args []string
}

// findCalls extracts the calls on line whose callee is a function defined
// in the audited source. Candidate names are the identifiers immediately
// followed by "(", looked up in the defined function names.
func findCalls(line string, byName map[string]int) []callSite {
	var out []callSite
	for i := 0; i < len(line); i++ {
		if !isIdentStart(line[i]) {
			continue
		}
		j := i
		for j < len(line) && isIdentChar(line[j]) {
			j++
		}
		name := line[i:j]
		if j >= len(line) || line[j] != '(' {
			i = j
			continue
		}
		if _, ok := byName[name]; !ok {
			i = j
			continue
		}
		args, end := parseCallArgs(line, j)
		if end < 0 {
			i = j
			continue
		}
		out = append(out, callSite{name: name, args: args})
		i = end
	}
	return out
}

// parseCallArgs parses the argument list starting at the "(" at pos in
// line, returning the argument texts and the index just past the matching
// ")", or -1 when the call is not closed on this line.
func parseCallArgs(line string, pos int) ([]string, int) {
	depth := 0
	for i := pos; i < len(line); i++ {
		switch line[i] {
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				inner := line[pos+1 : i]
				if strings.TrimSpace(inner) == "" {
					return nil, i + 1
				}
				return splitTopLevel(inner, ','), i + 1
			}
		}
	}
	return nil, -1
}

// argUsesTaintedParam reports whether arg mentions, as a whole
// identifier, one of fn's tainted parameters.
func (ps *parsedSource) argUsesTaintedParam(fn funcSpan, arg string) bool {
	for k, name := range fn.params {
		if k < len(fn.tainted) && fn.tainted[k] && lineHasIdent(arg, name) {
			return true
		}
	}
	return false
}

// lineUsesTaintedParam reports whether line applies a randomness use
// (modulo or a random call) to one of fn's tainted parameters.
func (ps *parsedSource) lineUsesTaintedParam(fn funcSpan, line string, use []string) bool {
	if !containsAny(line, use) {
		return false
	}
	for k, name := range fn.params {
		if k < len(fn.tainted) && fn.tainted[k] && lineHasIdent(line, name) {
			return true
		}
	}
	return false
}

// lineHasIdent reports whether name appears in line as a whole
// identifier, bounded by characters that cannot be part of an identifier.
func lineHasIdent(line string, name string) bool {
	if name == "" {
		return false
	}
	for i := 0; i+len(name) <= len(line); i++ {
		if line[i:i+len(name)] != name {
			continue
		}
		if i > 0 && isIdentChar(line[i-1]) {
			continue
		}
		after := i + len(name)
		if after < len(line) && isIdentChar(line[after]) {
			continue
		}
		return true
	}
	return false
}

func containsAny(line string, tokens []string) bool {
	for _, tok := range tokens {
		if strings.Contains(line, tok) {
			return true
		}
	}
	return false
}

// CheckUncheckedExternalCall runs rule RC-07 on src.
func CheckUncheckedExternalCall(src string) []Finding {
	return checkUncheckedCall(parseSource(src))
}

// checkUncheckedCall implements RC-07: a cross-realm call made as a
// bare statement, with no assignment and no error mention on the line,
// so its return value and failure are ignored. Assigned calls and calls
// in an if or return statement count as handled for this check.
func checkUncheckedCall(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RuleUncheckedCall)
	var out []Finding
	for _, fn := range ps.funcs {
		for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
			line := ps.bodyLine(fn, i)
			if !strings.Contains(line, "cross(") {
				continue
			}
			trimmed := strings.TrimSpace(line)
			if strings.HasPrefix(trimmed, "if ") || strings.HasPrefix(trimmed, "return ") {
				continue
			}
			if strings.Contains(line, "=") || strings.Contains(line, "err") {
				continue
			}
			desc := "Function " + fn.name + " calls another realm through cross() as a bare statement and ignores the result. Capture the return value and handle the error, or a failure in the other realm passes silently."
			out = append(out, newFinding(rule, i+1, ps.raw[i], desc))
			break
		}
	}
	return out
}

// CheckPublicStateMutation runs rule RC-08 on src.
func CheckPublicStateMutation(src string) []Finding {
	return checkPublicMutation(parseSource(src))
}

// checkPublicMutation implements RC-08: an exported function mutates
// realm state, through a package-level variable assignment or a Set,
// Delete, or Remove call, with no caller guard in its own body.
// Functions already covered by the funds, mint, and backdoor rules are
// skipped, and append growth is left to RC-04. A method that only
// mutates its own receiver, such as ps.Set on a Proposals value, does not
// count: the receiver is a value the caller already holds, so the call
// rewrites the caller's own instance, not shared realm state. A method
// that assigns a package-level variable or calls Set on shared state
// still counts.
func checkPublicMutation(ps *parsedSource) []Finding {
	rule := ruleByIDMust(RulePublicMutation)
	skipNames := []string{"Mint", "Withdraw", "Transfer", "Drain"}
	var out []Finding
	for _, fn := range ps.funcs {
		if !fn.exported {
			continue
		}
		if fn.name == "Render" {
			continue
		}
		if containsAny(fn.name, skipNames) {
			continue
		}
		if ps.bodyHasAny(fn, guardTokens) {
			continue
		}
		line := 0
		for i := fn.start - 1; i < fn.end && i < len(ps.clean); i++ {
			body := ps.bodyLine(fn, i)
			if strings.Contains(body, "append(") {
				continue
			}
			if ps.lineHasNonReceiverMutation(fn, body) {
				line = i + 1
				break
			}
			if ps.lineAssignsPkgVar(body) {
				line = i + 1
				break
			}
		}
		if line == 0 {
			continue
		}
		desc := "Function " + fn.name + " mutates realm state but contains no caller check in its own body. Add a caller guard, or make the function non-exported when only other realm code should call it."
		out = append(out, newFinding(rule, line, ps.raw[line-1], desc))
	}
	return out
}

// lineHasNonReceiverMutation reports whether line calls Set, Delete, or
// Remove on anything other than the method receiver. The target is the
// identifier segment immediately before the dot, so ps.Set counts as a
// receiver call while store.Set and settings.Set do not.
func (ps *parsedSource) lineHasNonReceiverMutation(fn funcSpan, line string) bool {
	mutateTokens := []string{".Set(", ".Delete(", ".Remove("}
	for _, tok := range mutateTokens {
		start := 0
		for {
			rel := strings.Index(line[start:], tok)
			if rel < 0 {
				break
			}
			pos := start + rel
			if !ps.mutationTargetsReceiver(fn, line, pos) {
				return true
			}
			start = pos + len(tok)
		}
	}
	return false
}

// mutationTargetsReceiver reports whether the mutate call whose dot is at
// pos in line is a call on the method receiver, such as ps.Set(. The
// target is the identifier segment immediately before the dot.
func (ps *parsedSource) mutationTargetsReceiver(fn funcSpan, line string, pos int) bool {
	if fn.receiverVar == "" || pos == 0 {
		return false
	}
	end := pos
	start := end
	for start > 0 && isIdentChar(line[start-1]) {
		start--
	}
	return line[start:end] == fn.receiverVar
}

// Package realmcheck is the on-chain report store for RealmCheck, the
// Gno.land realm auditor built for the Gnome Tavern Hackathon.
//
// Audits run off chain: the UI runs the audit-rules package against a
// realm's source text. Their results are stored here, so any report is
// public, shareable, and verifiable. The stored source hash lets anyone
// re-run the audit against the same source and compare. This realm never
// audits; it only stores, indexes, and renders reports.
//
// Deploy order: deploy the audit-rules package first, then this realm,
// because this realm imports it.
package realmcheck

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/g1wt8ndw7u974eazjaxvfjw23w6xrw689cv0ueuu/auditrules"
)

// reports holds every stored report by numeric ID.
var reports = map[int]auditrules.Report{}

// latestByRealm maps a realm path to its newest report ID.
var latestByRealm = map[string]int{}

// nextID is the ID the next stored report gets.
var nextID = 1

// maxReportsShown caps how many reports Render lists.
const maxReportsShown = 20

// SubmitReport stores one audit report and returns its numeric ID.
//
// findings is one finding per line, fields separated by "|":
// RULEID|Severity|Line|Title|Description|SourceLine
// A malformed line is skipped, never fatal, so a stored report stays
// readable even when one line is bad. The severity stored for a finding
// is the catalog severity of its rule when the encoded severity is not
// one of the four known values.
//
// The caller address is recorded as Auditor, and the current block
// height is recorded as Height.
func SubmitReport(cur realm, realmPath string, sourceHash string, score int, findings string) int {
	if realmPath == "" {
		panic("realm path must not be empty")
	}
	if !isSafeRealmPath(realmPath) {
		panic("realm path must be a gno.land path with safe characters")
	}
	if !isHexHash(sourceHash) {
		panic("source hash must be a hex string of at most 128 characters")
	}
	if score < 0 || score > 100 {
		panic("score must be between 0 and 100")
	}
	parsed := parseFindings(findings)
	report := auditrules.Report{
		ID:         nextID,
		RealmPath:  realmPath,
		SourceHash: sourceHash,
		Score:      score,
		Auditor:    string(cur.Previous().Address()),
		Height:     runtime.ChainHeight(),
		Findings:   parsed,
	}
	reports[nextID] = report
	latestByRealm[realmPath] = nextID
	nextID++
	return report.ID
}

// isSafeRealmPath reports whether p looks like a realm path: it must start
// with gno.land/ and contain only letters, digits, slash, dot, underscore,
// and hyphen. This keeps Render output safe: a path with newlines or
// markdown could otherwise inject lines into the rendered page, and Render
// receives attacker-controlled input.
func isSafeRealmPath(p string) bool {
	if !strings.HasPrefix(p, "gno.land/") {
		return false
	}
	for i := 0; i < len(p); i++ {
		c := p[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
			c == '/' || c == '.' || c == '_' || c == '-' {
			continue
		}
		return false
	}
	return true
}

// isHexHash reports whether s is a hex string of at most 128 characters,
// which is the shape of a source hash (SHA-256 is 64 hex characters).
func isHexHash(s string) bool {
	if s == "" || len(s) > 128 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') {
			continue
		}
		return false
	}
	return true
}

// parseFindings decodes the findings encoding into a slice of findings.
func parseFindings(encoded string) []auditrules.Finding {
	trimmed := strings.TrimSpace(encoded)
	if trimmed == "" {
		return []auditrules.Finding{}
	}
	lines := strings.Split(trimmed, "\n")
	out := make([]auditrules.Finding, 0, len(lines))
	for _, line := range lines {
		parts := strings.Split(line, "|")
		if len(parts) != 6 {
			continue
		}
		rule, ok := auditrules.RuleByID(strings.TrimSpace(parts[0]))
		if !ok {
			continue
		}
		sev := auditrules.Severity(strings.TrimSpace(parts[1]))
		if sev != auditrules.SeverityCritical && sev != auditrules.SeverityHigh &&
			sev != auditrules.SeverityMedium && sev != auditrules.SeverityLow {
			sev = rule.Severity
		}
		lineNo, err := strconv.Atoi(strings.TrimSpace(parts[2]))
		if err != nil || lineNo < 1 {
			continue
		}
		out = append(out, auditrules.Finding{
			RuleID:      rule.ID,
			Severity:    sev,
			Title:       strings.TrimSpace(parts[3]),
			Description: strings.TrimSpace(parts[4]),
			Line:        lineNo,
			SourceLine:  strings.TrimSpace(parts[5]),
		})
	}
	return out
}

// ReportFindings returns the findings of the stored report with the given
// ID, one finding per line in the same "RULEID|Severity|Line|Title|
// Description|SourceLine" encoding SubmitReport accepts. It exists because
// the chain query printers show slices as references, not values, so a UI
// cannot read the findings list from GetReport directly. It returns "" for
// an unknown ID.
func ReportFindings(id int) string {
	r, ok := reports[id]
	if !ok {
		return ""
	}
	out := ""
	for i, f := range r.Findings {
		if i > 0 {
			out += "\n"
		}
		out += f.RuleID + "|" + string(f.Severity) + "|" + strconv.Itoa(f.Line) + "|" + f.Title + "|" + f.Description + "|" + f.SourceLine
	}
	return out
}

// GetReport returns the stored report with the given ID.
func GetReport(id int) (auditrules.Report, bool) {
	r, ok := reports[id]
	return r, ok
}

// LatestReport returns the newest stored report for a realm path.
func LatestReport(realmPath string) (auditrules.Report, bool) {
	id, ok := latestByRealm[realmPath]
	if !ok {
		return auditrules.Report{}, false
	}
	return GetReport(id)
}

// ReportCount returns how many reports are stored.
func ReportCount() int {
	return len(reports)
}

// Render returns a Markdown page listing recent reports, newest first.
func Render(path string) string {
	out := "# RealmCheck reports\n\n"
	out += "On-chain audit reports. Each report cites the realm path, the risk score, the finding count, and the auditor.\n\n"
	if len(reports) == 0 {
		return out + "No reports stored yet.\n"
	}
	shown := 0
	for id := nextID - 1; id >= 1 && shown < maxReportsShown; id-- {
		r, ok := reports[id]
		if !ok {
			continue
		}
		out += "- #" + strconv.Itoa(r.ID) + " " + r.RealmPath +
			" score " + strconv.Itoa(r.Score) +
			", " + strconv.Itoa(len(r.Findings)) + " findings" +
			", auditor " + r.Auditor + "\n"
		shown++
	}
	return out
}

// Package vulnmint is a deliberately vulnerable demo token realm for
// RealmCheck, the Gno.land audit demo entry for the Gnome Tavern Hackathon.
//
// It is a small GRC20-like token with an internal ledger. It is intentionally
// insecure: anyone can mint any amount of tokens to any address. The mint
// function has no access control at all, so the token supply is whatever any
// caller says it is. Do not use this code for a real token.
//
// Demo only. The ledger models token balances in memory so the realm is
// self-contained and testable offline with `gno test`.
package vulnmint

import (
	"errors"
	"strconv"
)

// Token metadata.
const (
	Name     = "VulnMint Token"
	Symbol   = "VULN"
	Decimals = 6
)

// balances holds the token balance of each address.
var balances = map[address]int64{}

// totalSupply holds the total number of tokens ever minted minus burned.
// There is no burn function in this demo, so it only grows.
var totalSupply int64

// Mint creates amount tokens and credits them to to.
//
// INTENTIONAL VULNERABILITY (demo): unrestricted mint. This function never
// checks who the caller is. There is no owner check, no minter role, no
// allowlist, and no supply cap. Any address can call Mint and create any
// amount of tokens for any address, which makes the token supply meaningless.
// A safe version would require the caller to be an authorized minter, for
// example by checking cur.Previous().Address() against a stored minter, and
// would enforce a supply cap.
func Mint(cur realm, to address, amount int64) {
	if to == "" {
		panic("mint to empty address")
	}
	if amount <= 0 {
		panic("mint amount must be positive")
	}
	balances[to] += amount
	totalSupply += amount
}

// Transfer moves amount tokens from the caller to to.
//
// The caller is the immediate previous realm or user, read from
// cur.Previous().Address(). Unlike Mint, Transfer does check that the sender
// actually holds the tokens, and it returns an error instead of panicking so
// that a calling realm can observe a failed transfer. Callers that ignore the
// returned error are demonstrating the unchecked external call pattern; see
// the adminbackdoor demo realm.
func Transfer(cur realm, to address, amount int64) error {
	from := cur.Previous().Address()
	if to == "" {
		return errors.New("transfer to empty address")
	}
	if amount <= 0 {
		return errors.New("transfer amount must be positive")
	}
	if balances[from] < amount {
		return errors.New("insufficient balance")
	}
	balances[from] -= amount
	balances[to] += amount
	return nil
}

// BalanceOf returns the token balance of addr.
func BalanceOf(addr address) int64 {
	return balances[addr]
}

// TotalSupply returns the total token supply.
func TotalSupply() int64 {
	return totalSupply
}

// Render returns a short human readable summary of the token.
func Render(path string) string {
	return "# " + Name + " (" + Symbol + ")\n\n" +
		"Demo token for RealmCheck. Anyone can mint.\n\n" +
		"Total supply: " + strconv.FormatInt(totalSupply, 10) + "\n"
}

// Package greedystore is a deliberately vulnerable demo registry realm for
// RealmCheck, the Gno.land audit demo entry for the Gnome Tavern Hackathon.
//
// It is a registry of entries that anyone can append to. It is intentionally
// insecure: there is no cap on the number of entries, no limit on the size of
// an entry, and no caller check at all, so storage (and the storage deposit
// that pays for it) grows without bound as long as anyone keeps calling
// Register.
//
// Demo only. Do not use this code for a real registry.
package greedystore

import "strconv"

// Entry is one stored registry record.
type Entry struct {
	ID     int64
	Author address
	Title  string
	Data   string
}

// entries holds every registered entry, in registration order. It is never
// pruned, capped, or paged.
var entries []Entry

// nextID is the ID assigned to the next entry.
var nextID int64

// Register appends a new entry to the registry and returns its ID.
//
// INTENTIONAL VULNERABILITY (demo): unbounded storage growth, and public
// state mutation with no guard. This function appends to a persistent slice
// on every call, with no maximum entry count, no maximum entry size, no
// per-user quota, no deduplication, and no caller check of any kind. Each
// call permanently grows on-chain state, so the storage deposit grows
// without bound and a single caller can bloat the realm forever at will.
// A safe version would cap the total count, cap the size of each entry,
// charge or rate limit callers, and restrict who may register.
func Register(cur realm, title string, data string) int64 {
	author := cur.Previous().Address()
	if title == "" {
		panic("title must not be empty")
	}
	id := nextID
	nextID++
	entries = append(entries, Entry{
		ID:     id,
		Author: author,
		Title:  title,
		Data:   data,
	})
	return id
}

// EntryCount returns the number of stored entries.
func EntryCount() int {
	return len(entries)
}

// GetEntry returns the entry with the given ID, and false if there is none.
func GetEntry(id int64) (Entry, bool) {
	for _, e := range entries {
		if e.ID == id {
			return e, true
		}
	}
	return Entry{}, false
}

// Render returns a short human readable summary of the registry.
func Render(path string) string {
	return "# Greedy Store\n\n" +
		"Demo registry for RealmCheck. Storage grows without bound.\n\n" +
		"Entries: " + strconv.Itoa(len(entries)) + "\n"
}

// Package luckydice is a deliberately vulnerable demo dice game realm for
// RealmCheck, the Gno.land audit demo entry for the Gnome Tavern Hackathon.
//
// Players buy chips and bet them on a dice roll. It is intentionally
// insecure: the winning number is derived from public chain data, the
// current block height and the current block time, and it is readable by
// anyone through DrawNumber before betting. Anyone can look up the winning
// number and then bet on it, so the game is perfectly predictable.
//
// Demo only. Chips are modeled as an internal ledger so the realm is
// self-contained and testable offline with `gno test`. Do not use this code
// for a real game.
package luckydice

import (
	"errors"
	"strconv"
	"time"

	"chain/runtime"
	"chain/runtime/unsafe"
)

// Game constants.
const (
	// BetCost is the chip cost of one bet.
	BetCost int64 = 100
	// Payout is what a winning bet pays, including the stake.
	Payout int64 = 500
	// Faces is the number of faces on the dice.
	Faces int64 = 6
)

// chips holds the chip balance of each player.
var chips = map[address]int64{}

// gamesPlayed counts resolved bets.
var gamesPlayed int64

// totalWagered counts chips staked in resolved bets.
var totalWagered int64

// totalPaid counts chips paid out to winners.
var totalPaid int64

// BuyChips credits amount chips to the caller.
//
// INTENTIONAL VULNERABILITY (demo): funds accepted without a check. This
// function reads the coins actually sent with the transaction through
// unsafe.OriginSend(), then ignores them and credits the claimed chip
// amount instead. It never compares the sent amount with the claimed
// amount. Any caller can claim chips of any size while sending nothing,
// or sending far less, and the game will treat the invented chips as real
// funds. A safe version would credit chips only for the amount actually
// sent.
func BuyChips(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if amount <= 0 {
		panic("chip amount must be positive")
	}
	sent := unsafe.OriginSend()
	_ = sent // the sent coins are read and then never checked
	chips[caller] += amount
}

// DrawNumberAt computes the winning number from a block height and a block
// time. It is a pure helper so the formula can be tested exactly.
func DrawNumberAt(height int64, unixTime int64) int {
	return int((height*31 + unixTime) % Faces)
}

// DrawNumber returns the winning number for the current block.
//
// INTENTIONAL VULNERABILITY (demo): weak randomness. The result is derived
// from runtime.ChainHeight() and time.Now().Unix(), which is the block
// time. Both values are public before the bet is placed: the height of the
// next block is known, and the block time is predictable within seconds, so
// any caller can compute the winning number in advance, or simply read it
// here, and then bet on it. Block height and block time are not secret and
// must never seed a game of chance. A safe version would use a commit and
// reveal scheme, a verifiable random function, or an oracle that reveals
// the result only after bets close.
func DrawNumber() int {
	return DrawNumberAt(runtime.ChainHeight(), time.Now().Unix())
}

// PlaceBet stakes BetCost chips on guess. It returns true when the bet wins
// and pays Payout chips to the caller.
//
// Because DrawNumber is public, a caller that bets the number DrawNumber
// returns wins whenever the block height and block time do not change
// between reading the number and placing the bet, which in practice is
// almost always.
func PlaceBet(cur realm, guess int) (bool, error) {
	caller := cur.Previous().Address()
	if guess < 0 || guess >= int(Faces) {
		return false, errors.New("guess must be between 0 and 5")
	}
	if chips[caller] < BetCost {
		return false, errors.New("insufficient chips")
	}
	chips[caller] -= BetCost
	totalWagered += BetCost
	gamesPlayed++
	if guess == DrawNumber() {
		chips[caller] += Payout
		totalPaid += Payout
		return true, nil
	}
	return false, nil
}

// ChipsOf returns the chip balance of addr.
func ChipsOf(addr address) int64 {
	return chips[addr]
}

// GamesPlayed returns the number of resolved bets.
func GamesPlayed() int64 {
	return gamesPlayed
}

// TotalWagered returns the total chips staked so far.
func TotalWagered() int64 {
	return totalWagered
}

// TotalPaid returns the total chips paid out to winners so far.
func TotalPaid() int64 {
	return totalPaid
}

// Render returns a short human readable summary of the game.
func Render(path string) string {
	return "# Lucky Dice\n\n" +
		"Demo dice game for RealmCheck. The draw is public, do not bet on it.\n\n" +
		"Games played: " + strconv.FormatInt(gamesPlayed, 10) + "\n" +
		"Next winning number: " + strconv.Itoa(DrawNumber()) + "\n"
}

// Package unguardedvault is a deliberately vulnerable demo vault realm for
// RealmCheck, the Gno.land audit demo entry for the Gnome Tavern Hackathon.
//
// The vault accepts deposits and lets anyone withdraw funds. It is
// intentionally insecure in two ways: deposits are credited without verifying
// that any coins were actually sent, and withdrawals have no caller check, so
// anyone can drain deposits that belong to someone else.
//
// Demo only. Funds are modeled as an internal ledger (ugnot amounts tracked
// in memory) so the realm is self-contained and testable offline with
// `gno test`. A production vault would move real ugnot with
// banker.SendCoins; the missing checks demonstrated here are identical in
// that version, because the checks belong around the ledger update and the
// payout, not inside the banker call.
package unguardedvault

import (
	"errors"
	"strconv"

	"chain/runtime/unsafe"
)

// deposits records how much each address has deposited.
var deposits = map[address]int64{}

// paidOut records how much has been paid out to each address by Withdraw.
var paidOut = map[address]int64{}

// vaultBalance is the total amount currently held by the vault.
var vaultBalance int64

// Deposit credits amount to the caller's deposit balance.
//
// INTENTIONAL VULNERABILITY (demo): funds accepted without a check. This
// function reads the coins actually sent with the transaction through
// unsafe.OriginSend(), then ignores them and credits the claimed amount
// instead. It never compares the sent amount with the claimed amount, and
// it does not require the caller to be a user call. Any caller can claim
// a deposit of any size while sending nothing, or sending far less, and
// the vault will treat the invented deposit as real funds. A safe version
// would credit exactly the sent amount, and only that amount.
func Deposit(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if amount <= 0 {
		panic("deposit amount must be positive")
	}
	sent := unsafe.OriginSend()
	_ = sent // the sent coins are read and then never checked
	deposits[caller] += amount
	vaultBalance += amount
}

// Withdraw pays amount out of the vault to to.
//
// INTENTIONAL VULNERABILITY (demo): missing caller check on a funds
// function. This function never checks who the caller is, and it never
// checks that the caller owns the funds being withdrawn. Any address can
// call Withdraw and send the vault's funds, including other users'
// deposits, to any address it chooses. The only check is that the vault
// holds enough in total. A safe version would require the caller to be the
// depositor (or an approved spender) and would debit that caller's own
// deposit balance, never the pooled balance of strangers.
func Withdraw(cur realm, to address, amount int64) error {
	if to == "" {
		return errors.New("withdraw to empty address")
	}
	if amount <= 0 {
		return errors.New("withdraw amount must be positive")
	}
	if amount > vaultBalance {
		return errors.New("insufficient vault balance")
	}
	vaultBalance -= amount
	paidOut[to] += amount
	return nil
}

// BalanceOf returns the recorded deposit balance of addr. Note that this
// bookkeeping can disagree with reality after an unguarded withdrawal,
// because Withdraw pays from the pooled balance without debiting any
// individual depositor. That disagreement is part of the demonstration.
func BalanceOf(addr address) int64 {
	return deposits[addr]
}

// VaultBalance returns the total amount currently held by the vault.
func VaultBalance() int64 {
	return vaultBalance
}

// PaidOut returns the total amount Withdraw has paid to addr.
func PaidOut(addr address) int64 {
	return paidOut[addr]
}

// Render returns a short human readable summary of the vault.
func Render(path string) string {
	return "# Unguarded Vault\n\n" +
		"Demo vault for RealmCheck. Anyone can withdraw.\n\n" +
		"Vault balance: " + strconv.FormatInt(vaultBalance, 10) + " ugnot\n"
}

// Package adminbackdoor is a deliberately vulnerable demo treasury realm
// for RealmCheck, the Gno.land audit demo entry for the Gnome Tavern
// Hackathon.
//
// A single hard-coded admin address controls the treasury. It is
// intentionally insecure: the admin can drain the entire treasury to any
// address in one call, with no timelock, no spending cap, no second
// approver, and no multisig. It also pays bonuses in vulnmint tokens
// through an external realm call whose result it never checks, so a failed
// payout is still recorded as paid.
//
// Demo only. Funds are modeled as an internal ledger (ugnot amounts tracked
// in memory) so the realm is self-contained and testable offline with
// `gno test`. Deploy vulnmint before this realm, because PayBonus calls it.
// The admin address below is a placeholder; replace it with the real admin
// address before any real use, and even then, do not use this code for a
// real treasury.
package adminbackdoor

import (
	"errors"
	"strconv"

	"chain"

	vulnmint "gno.land/r/g1wt8ndw7u974eazjaxvfjw23w6xrw689cv0ueuu/vulnmint"
)

// Admin is the single hard-coded admin address. Whoever controls this
// address controls the whole treasury.
var Admin = address("g1wt8ndw7u974eazjaxvfjw23w6xrw689cv0ueuu")

// treasury is the ugnot balance held by this realm, as an internal ledger.
var treasury int64

// drainedTo records how much Drain has paid to each address.
var drainedTo = map[address]int64{}

// paid records bonus amounts this realm claims to have paid to each
// address, whether or not the external transfer actually succeeded.
var paid = map[address]int64{}

// Fund credits amount to the treasury.
//
// Note: like the vault demo, this credits value without verifying that any
// payment was actually sent. That is a secondary demonstration of funds
// accepted without a check; the main vulnerability of this realm is the
// admin backdoor below.
func Fund(cur realm, amount int64) {
	if amount <= 0 {
		panic("fund amount must be positive")
	}
	treasury += amount
}

// Drain sends the entire treasury to to.
//
// INTENTIONAL VULNERABILITY (demo): owner/admin backdoor. Only the single
// hard-coded admin can call this, and once the admin calls it, the whole
// treasury moves at once: there is no timelock, no daily or per-call cap,
// no second approver, and no multisig. One compromised key, or one
// malicious admin, empties the treasury in a single transaction, and the
// payout address is freely chosen by the admin. A safe treasury would
// require multiple approvers, a timelock between proposal and execution,
// and a cap on each withdrawal.
func Drain(cur realm, to address) (int64, error) {
	caller := cur.Previous().Address()
	if caller != Admin {
		return 0, errors.New("only the admin can drain the treasury")
	}
	if to == "" {
		return 0, errors.New("drain to empty address")
	}
	amount := treasury
	treasury = 0
	drainedTo[to] += amount
	return amount, nil
}

// FundBonusPool mints amount vulnmint tokens into this realm's own balance
// so PayBonus has something to pay with. It works because vulnmint.Mint
// has no access control; anyone can mint.
func FundBonusPool(cur realm, amount int64) {
	vulnmint.Mint(cross(cur), cur.Address(), amount)
}

// BonusPool returns this realm's vulnmint balance, the pool PayBonus pays
// from.
func BonusPool() int64 {
	return vulnmint.BalanceOf(chain.PackageAddress("gno.land/r/g1wt8ndw7u974eazjaxvfjw23w6xrw689cv0ueuu/adminbackdoor"))
}

// PayBonus pays amount vulnmint tokens to to and records the payment.
//
// INTENTIONAL VULNERABILITY (demo): unchecked external realm call, and
// public state mutation with no guard. PayBonus calls
// vulnmint.Transfer, which returns an error when the bonus pool is empty,
// and discards that error with `_ =`. It then records the bonus as paid
// no matter what happened. If the transfer failed, the books claim to have
// paid money that never moved, and nobody is told. There is also no
// caller check, so anyone can trigger a bonus payment to anyone. A safe
// version would check the returned error and abort the payment, and would
// restrict who can pay bonuses.
func PayBonus(cur realm, to address, amount int64) {
	_ = vulnmint.Transfer(cross(cur), to, amount)
	paid[to] += amount
}

// Treasury returns the current treasury balance.
func Treasury() int64 {
	return treasury
}

// DrainedTo returns the total amount Drain has paid to addr.
func DrainedTo(addr address) int64 {
	return drainedTo[addr]
}

// PaidBonus returns the total bonus amount recorded as paid to addr.
func PaidBonus(addr address) int64 {
	return paid[addr]
}

// Render returns a short human readable summary of the treasury.
func Render(path string) string {
	return "# Admin Backdoor Treasury\n\n" +
		"Demo treasury for RealmCheck. One admin can drain it all.\n\n" +
		"Admin: " + string(Admin) + "\n" +
		"Treasury: " + strconv.FormatInt(treasury, 10) + " ugnot\n"
}

package hello_verify_b

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

type CallRecord struct {
	Seq           int
	Tag           string
	PrevAddr      string
	PrevPkgPath   string
	PrevIsUser    bool
	PrevIsEOA     bool
	OriginCaller  string
	BlockHeight   int64
	BlockTimeUnix int64
}

var (
	realmAddr address
	records   []CallRecord
)

func init(cur realm) {
	realmAddr = cur.Address()
}

// RecordCaller records caller identity (cur.Previous vs unsafe.OriginCaller)
// and deterministic block timestamp/height. Callable both directly by an EOA
// and via cross-realm call from hello_verify_a.
func RecordCaller(cur realm, tag string) string {
	prev := cur.Previous()
	origin := unsafe.OriginCaller()
	rec := CallRecord{
		Seq:           len(records) + 1,
		Tag:           tag,
		PrevAddr:      prev.Address().String(),
		PrevPkgPath:   prev.PkgPath(),
		PrevIsUser:    prev.IsUser(),
		PrevIsEOA:     prev.IsUserCall(),
		OriginCaller:  origin.String(),
		BlockHeight:   runtime.ChainHeight(),
		BlockTimeUnix: time.Now().Unix(),
	}
	records = append(records, rec)
	return formatRecord(rec)
}

func RecordCount() int {
	return len(records)
}

func LastRecord() string {
	if len(records) == 0 {
		return ""
	}
	return formatRecord(records[len(records)-1])
}

func formatRecord(r CallRecord) string {
	return "#" + strconv.Itoa(r.Seq) +
		" tag=" + r.Tag +
		" prevAddr=" + r.PrevAddr +
		" prevPkg=" + r.PrevPkgPath +
		" prevIsUser=" + strconv.FormatBool(r.PrevIsUser) +
		" prevIsEOA=" + strconv.FormatBool(r.PrevIsEOA) +
		" origin=" + r.OriginCaller +
		" height=" + strconv.FormatInt(r.BlockHeight, 10) +
		" unix=" + strconv.FormatInt(r.BlockTimeUnix, 10)
}

func Render(path string) string {
	if path == "json/state" {
		var sb strings.Builder
		sb.WriteString(`{"realm":"hello_verify_b","addr":"` + realmAddr.String() + `","count":` + strconv.Itoa(len(records)) + `,"records":[`)
		for i, r := range records {
			if i > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(`{"seq":` + strconv.Itoa(r.Seq) +
				`,"tag":"` + escapeJSON(r.Tag) +
				`","prevAddr":"` + r.PrevAddr +
				`","prevPkg":"` + escapeJSON(r.PrevPkgPath) +
				`","prevIsUser":` + strconv.FormatBool(r.PrevIsUser) +
				`,"prevIsEOA":` + strconv.FormatBool(r.PrevIsEOA) +
				`,"origin":"` + r.OriginCaller +
				`","height":` + strconv.FormatInt(r.BlockHeight, 10) +
				`,"unix":` + strconv.FormatInt(r.BlockTimeUnix, 10) + `}`)
		}
		sb.WriteString("]}")
		return sb.String()
	}

	var sb strings.Builder
	sb.WriteString("# hello_verify_b (Langkah 0 Scratch)\n\n")
	sb.WriteString("- Realm Address: `" + realmAddr.String() + "`\n")
	sb.WriteString("- Total Recorded Calls: `" + strconv.Itoa(len(records)) + "`\n\n")
	sb.WriteString("## Call Records\n\n")
	if len(records) == 0 {
		sb.WriteString("_No calls recorded yet._\n")
	} else {
		for _, r := range records {
			sb.WriteString("- `" + formatRecord(r) + "`\n")
		}
	}
	return sb.String()
}

func escapeJSON(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	return s
}

package hello_verify_b

import (
	"strings"
	"testing"
)

func TestRecordCallerDirect(cur realm, t *testing.T) {
	alice := address("g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv")
	testing.SetRealm(testing.NewUserRealm(alice))

	out := RecordCaller(cross(cur), "direct-test")
	if !strings.Contains(out, "prevIsEOA=true") {
		t.Fatalf("expected prevIsEOA=true, got: %s", out)
	}
	if !strings.Contains(out, "prevAddr="+alice.String()) {
		t.Fatalf("expected prevAddr=%s, got: %s", alice.String(), out)
	}
	if !strings.Contains(out, "origin="+alice.String()) {
		t.Fatalf("expected origin=%s, got: %s", alice.String(), out)
	}
	if RecordCount() < 1 {
		t.Fatalf("expected record count >= 1")
	}

	jsonOut := Render("json/state")
	if !strings.Contains(jsonOut, `"realm":"hello_verify_b"`) {
		t.Fatalf("unexpected json render: %s", jsonOut)
	}
}

// Package parimutuel is a reusable, coin-agnostic accounting engine for
// binary (YES/NO) pari-mutuel pools.
//
// Everyone who backs a side shares the whole pool, pro rata to their stake,
// if their side wins. There is no order book and no counterparty matching:
// a single bettor can always place a bet, which makes it a good fit for
// young markets with thin liquidity.
//
// The package never moves coins. It only keeps the ledger. The realm that
// owns a Pool is responsible for receiving stakes and sending payouts, which
// lets any realm (prediction markets, sports pools, tournament brackets,
// "will this ship by Friday" office pools) reuse the same audited math.
//
// Lifecycle:
//
//	pool := parimutuel.New(100)          // 1% fee, in basis points
//	pool.Place(alice, parimutuel.Yes, 5_000_000)
//	pool.Place(bob, parimutuel.No, 3_000_000)
//	pool.Resolve(parimutuel.Yes)         // or parimutuel.Void
//	amount, _ := pool.Claim(alice)       // realm then sends `amount`
//
// Rules:
//   - If the winning side has no stake, the pool is voided automatically and
//     everyone is refunded in full (no fee).
//   - A voided pool refunds every stake in full (no fee).
//   - The fee is taken once, from the total pool, only when there is a winner.
//   - Payouts round down; any dust stays with the owning realm.
package parimutuel

import (
	"errors"
	"math/bits"

	"gno.land/p/nt/avl/v0"
)

// Outcome is the state of a pool, and also identifies a side when placing.
type Outcome int

const (
	Pending Outcome = iota
	Yes
	No
	Void
)

// MaxFeeBps caps the fee a pool can charge (5%).
const MaxFeeBps int64 = 500

var (
	ErrInvalidSide     = errors.New("parimutuel: side must be Yes or No")
	ErrInvalidAmount   = errors.New("parimutuel: amount must be positive")
	ErrAlreadyResolved = errors.New("parimutuel: pool already resolved")
	ErrNotResolved     = errors.New("parimutuel: pool not resolved yet")
	ErrInvalidOutcome  = errors.New("parimutuel: outcome must be Yes, No or Void")
	ErrNoPosition      = errors.New("parimutuel: no position in this pool")
	ErrAlreadyClaimed  = errors.New("parimutuel: already claimed")
	ErrNothingToClaim  = errors.New("parimutuel: nothing to claim")
	ErrOverflow        = errors.New("parimutuel: pool too large")
)

// String returns a lowercase label for the outcome.
func (o Outcome) String() string {
	switch o {
	case Pending:
		return "pending"
	case Yes:
		return "yes"
	case No:
		return "no"
	case Void:
		return "void"
	}
	return "unknown"
}

// ParseSide converts "yes"/"no" (any case) into an Outcome.
func ParseSide(s string) (Outcome, error) {
	switch s {
	case "yes", "YES", "Yes", "y", "Y":
		return Yes, nil
	case "no", "NO", "No", "n", "N":
		return No, nil
	}
	return Pending, ErrInvalidSide
}

// Position is one address's stake in a pool.
type Position struct {
	Yes     int64
	No      int64
	Claimed bool
}

// Total returns the address's combined stake on both sides.
func (p *Position) Total() int64 { return p.Yes + p.No }

// Pool is a binary pari-mutuel pool.
type Pool struct {
	yes       int64
	no        int64
	feeBps    int64
	fee       int64 // fee actually taken, set on resolution
	outcome   Outcome
	positions avl.Tree // address.String() -> *Position
}

// New creates an empty pool charging feeBps basis points on resolution.
// feeBps is clamped to [0, MaxFeeBps].
func New(feeBps int64) *Pool {
	if feeBps < 0 {
		feeBps = 0
	}
	if feeBps > MaxFeeBps {
		feeBps = MaxFeeBps
	}
	return &Pool{feeBps: feeBps}
}

// Place records a stake of amount on side for who.
func (p *Pool) Place(who address, side Outcome, amount int64) error {
	if p.outcome != Pending {
		return ErrAlreadyResolved
	}
	if side != Yes && side != No {
		return ErrInvalidSide
	}
	if amount <= 0 {
		return ErrInvalidAmount
	}
	if p.yes+p.no+amount < p.yes+p.no { // int64 overflow guard
		return ErrOverflow
	}

	pos := p.position(who)
	if pos == nil {
		pos = &Position{}
		p.positions.Set(who.String(), pos)
	}
	if side == Yes {
		pos.Yes += amount
		p.yes += amount
	} else {
		pos.No += amount
		p.no += amount
	}
	return nil
}

// Resolve settles the pool. If the winning side is empty the pool is voided.
// It returns the final outcome actually applied.
func (p *Pool) Resolve(o Outcome) (Outcome, error) {
	if p.outcome != Pending {
		return p.outcome, ErrAlreadyResolved
	}
	if o != Yes && o != No && o != Void {
		return Pending, ErrInvalidOutcome
	}
	if (o == Yes && p.yes == 0) || (o == No && p.no == 0) {
		o = Void
	}
	p.outcome = o
	if o != Void {
		// Only charge a fee when someone actually lost money to winners.
		if p.loserPool() > 0 {
			p.fee = mulDiv(p.Total(), p.feeBps, 10_000)
		}
	}
	return o, nil
}

// Payout returns what who can claim, without claiming. Zero while pending.
func (p *Pool) Payout(who address) int64 {
	pos := p.position(who)
	if pos == nil || pos.Claimed {
		return 0
	}
	return p.payoutFor(pos)
}

// Claim marks who's position as claimed and returns the amount the owning
// realm must now send to who.
func (p *Pool) Claim(who address) (int64, error) {
	if p.outcome == Pending {
		return 0, ErrNotResolved
	}
	pos := p.position(who)
	if pos == nil {
		return 0, ErrNoPosition
	}
	if pos.Claimed {
		return 0, ErrAlreadyClaimed
	}
	amount := p.payoutFor(pos)
	pos.Claimed = true
	if amount == 0 {
		return 0, ErrNothingToClaim
	}
	return amount, nil
}

func (p *Pool) payoutFor(pos *Position) int64 {
	switch p.outcome {
	case Void:
		return pos.Total()
	case Yes:
		if pos.Yes == 0 {
			return 0
		}
		return mulDiv(pos.Yes, p.Total()-p.fee, p.yes)
	case No:
		if pos.No == 0 {
			return 0
		}
		return mulDiv(pos.No, p.Total()-p.fee, p.no)
	}
	return 0
}

func (p *Pool) loserPool() int64 {
	if p.outcome == Yes {
		return p.no
	}
	if p.outcome == No {
		return p.yes
	}
	return 0
}

func (p *Pool) position(who address) *Position {
	v := p.positions.Get(who.String())
	if v == nil {
		return nil
	}
	return v.(*Position)
}

// Position returns a copy of who's position (zero value if none).
func (p *Pool) Position(who address) Position {
	pos := p.position(who)
	if pos == nil {
		return Position{}
	}
	return *pos
}

// Outcome returns the pool's current state.
func (p *Pool) Outcome() Outcome { return p.outcome }

// YesStake returns the total staked on YES.
func (p *Pool) YesStake() int64 { return p.yes }

// NoStake returns the total staked on NO.
func (p *Pool) NoStake() int64 { return p.no }

// Total returns the whole pool.
func (p *Pool) Total() int64 { return p.yes + p.no }

// FeeBps returns the configured fee in basis points.
func (p *Pool) FeeBps() int64 { return p.feeBps }

// Fee returns the fee actually taken (0 until resolved, 0 if void).
func (p *Pool) Fee() int64 { return p.fee }

// Bettors returns how many distinct addresses hold a position.
func (p *Pool) Bettors() int { return p.positions.Size() }

// YesBps returns YES's share of the pool in basis points (0..10000).
// An empty pool reports 5000 (even).
func (p *Pool) YesBps() int64 {
	t := p.Total()
	if t == 0 {
		return 5000
	}
	return mulDiv(p.yes, 10_000, t)
}

// Multiplier returns, in basis points, the gross return per unit staked on
// side if that side won right now (e.g. 25000 = 2.5x). Zero if side is empty.
func (p *Pool) Multiplier(side Outcome) int64 {
	var s int64
	if side == Yes {
		s = p.yes
	} else if side == No {
		s = p.no
	}
	if s == 0 {
		return 0
	}
	if s == p.Total() {
		// Nobody on the other side: a win is a full refund, and no fee is taken.
		return 10_000
	}
	net := p.Total() - mulDiv(p.Total(), p.feeBps, 10_000)
	return mulDiv(net, 10_000, s)
}

// IterPositions calls fn for each position until fn returns true.
func (p *Pool) IterPositions(fn func(who string, pos Position) bool) {
	p.positions.Iterate("", "", func(key string, value any) bool {
		return fn(key, *(value.(*Position)))
	})
}

// mulDiv returns a*b/c using a 128-bit intermediate, for non-negative inputs.
// It panics on a zero divisor or if the result does not fit in int64.
func mulDiv(a, b, c int64) int64 {
	if a < 0 || b < 0 || c <= 0 {
		panic("parimutuel: mulDiv invalid input")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	if hi >= uint64(c) {
		panic(ErrOverflow.Error())
	}
	q, _ := bits.Div64(hi, lo, uint64(c))
	if q > uint64(1<<63-1) {
		panic(ErrOverflow.Error())
	}
	return int64(q)
}

package hello_verify_a

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/r/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/hello_verify_b"
)

var (
	admin           address
	realmAddr       address
	realmPkgPath    string
	totalAccepted   int64
	lastCrossResult string
	sendLogs        []string
	payoutLogs      []string
	timeLogs        []string
)

func init(cur realm) {
	admin = cur.Previous().Address()
	realmAddr = cur.Address()
	realmPkgPath = cur.PkgPath()
}

// MintTestDenom issues a secondary realm-scoped native coin (/<pkgpath>:dummy)
// to admin so Langkah 0 can genuinely test wrong-denom and multi-coin -send on onyx-1.
func MintTestDenom(cur realm, amount int64) string {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	if cur.Previous().Address() != admin {
		panic("unauthorized: only deployer admin")
	}
	if amount <= 0 {
		panic("amount must be > 0")
	}
	denom := chain.CoinDenom(cur.PkgPath(), "dummy")
	b := banker.NewBanker(banker.BankerTypeRealmIssue, cur)
	b.IssueCoin(admin, denom, amount)
	return denom
}

// InspectSend logs raw unsafe.OriginSend() without enforcing amount/denom rules.
// Used in Langkah 0 to observe OriginSend behavior with various -send payloads.
func InspectSend(cur realm, label string) string {
	if !cur.Previous().IsUserCall() {
		panic("InspectSend must be called directly by EOA")
	}
	sent := unsafe.OriginSend()
	b := banker.NewReadonlyBanker()
	bal := b.GetCoin(cur.Address(), "ugnot")
	entry := "label=" + label +
		" len=" + strconv.Itoa(len(sent)) +
		" coins=" + sent.String() +
		" realmUgnotBal=" + strconv.FormatInt(bal, 10) +
		" height=" + strconv.FormatInt(runtime.ChainHeight(), 10) +
		" unix=" + strconv.FormatInt(time.Now().Unix(), 10)
	sendLogs = append(sendLogs, entry)
	return entry
}

// DepositExact enforces strict coin validation:
// - direct EOA call (cur.Previous().IsUserCall())
// - single coin only (len == 1)
// - denom == "ugnot"
// - exact amount == expected (> 0)
func DepositExact(cur realm, expected int64) string {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	if expected <= 0 {
		panic("expected amount must be > 0")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 {
		panic("must send exactly one coin, got len=" + strconv.Itoa(len(sent)) + " coins=" + sent.String())
	}
	if sent[0].Denom != "ugnot" {
		panic("invalid denom: only ugnot allowed, got " + sent[0].Denom)
	}
	if sent[0].Amount != expected {
		panic("exact amount mismatch: expected " + strconv.FormatInt(expected, 10) + " got " + strconv.FormatInt(sent[0].Amount, 10))
	}

	totalAccepted += expected
	entry := "accepted=" + strconv.FormatInt(expected, 10) +
		" from=" + cur.Previous().Address().String() +
		" total=" + strconv.FormatInt(totalAccepted, 10) +
		" unix=" + strconv.FormatInt(time.Now().Unix(), 10)
	sendLogs = append(sendLogs, entry)
	return entry
}

// DepositThenPanic intentionally mutates state and panics AFTER receiving -send coins.
// Used in Langkah 0 to verify on testnet that coins are refunded and NOT stuck in the realm.
func DepositThenPanic(cur realm) string {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		panic("send at least 1 coin to test rollback")
	}
	totalAccepted += sent.AmountOf("ugnot")
	sendLogs = append(sendLogs, "should-rollback:"+sent.String())
	panic("intentional panic after receiving coins: " + sent.String())
}

// SendFromRealm sends ugnot from this realm's balance to `to` using BankerTypeRealmSend.
// Restricted to admin (deployer) so random testnet users cannot drain verification funds.
func SendFromRealm(cur realm, to address, amount int64) string {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	if cur.Previous().Address() != admin {
		panic("unauthorized: only deployer admin")
	}
	if amount <= 0 {
		panic("amount must be > 0")
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
	entry := "sent=" + strconv.FormatInt(amount, 10) + "ugnot" +
		" to=" + to.String() +
		" unix=" + strconv.FormatInt(time.Now().Unix(), 10)
	payoutLogs = append(payoutLogs, entry)
	return entry
}

// CallCrossB invokes hello_verify_b.RecordCaller using cross(cur) to verify
// cross-realm call semantics and PreviousRealm vs OriginCaller.
func CallCrossB(cur realm, tag string) string {
	res := hello_verify_b.RecordCaller(cross(cur), "via_a:"+tag)
	lastCrossResult = res
	return res
}

// RecordTimestamp records block height and time.Now().Unix() for gas/storage and clock verification.
func RecordTimestamp(cur realm, tag string) int64 {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by EOA")
	}
	nowUnix := time.Now().Unix()
	entry := "tag=" + tag +
		" height=" + strconv.FormatInt(runtime.ChainHeight(), 10) +
		" unix=" + strconv.FormatInt(nowUnix, 10)
	timeLogs = append(timeLogs, entry)
	return nowUnix
}

func TotalAccepted() int64 {
	return totalAccepted
}

func Render(path string) string {
	b := banker.NewReadonlyBanker()
	bal := b.GetCoin(realmAddr, "ugnot")

	if path == "json/state" {
		return `{"realm":"hello_verify_a","addr":"` + realmAddr.String() +
			`","pkgPath":"` + realmPkgPath +
			`","admin":"` + admin.String() +
			`","realmUgnotBal":` + strconv.FormatInt(bal, 10) +
			`,"totalAccepted":` + strconv.FormatInt(totalAccepted, 10) +
			`,"sendLogsCount":` + strconv.Itoa(len(sendLogs)) +
			`,"payoutLogsCount":` + strconv.Itoa(len(payoutLogs)) +
			`,"timeLogsCount":` + strconv.Itoa(len(timeLogs)) +
			`,"lastCrossResult":"` + escapeJSON(lastCrossResult) + `"}`
	}

	var sb strings.Builder
	sb.WriteString("# hello_verify_a (Langkah 0 Scratch)\n\n")
	sb.WriteString("- Realm Address: `" + realmAddr.String() + "`\n")
	sb.WriteString("- Admin: `" + admin.String() + "`\n")
	sb.WriteString("- Realm `ugnot` Balance: `" + strconv.FormatInt(bal, 10) + "`\n")
	sb.WriteString("- Total Accepted: `" + strconv.FormatInt(totalAccepted, 10) + "`\n")
	sb.WriteString("- Last Cross-Realm B Result: `" + lastCrossResult + "`\n\n")

	sb.WriteString("## Send Logs\n")
	for _, l := range sendLogs {
		sb.WriteString("- `" + l + "`\n")
	}
	sb.WriteString("\n## Payout Logs\n")
	for _, l := range payoutLogs {
		sb.WriteString("- `" + l + "`\n")
	}
	sb.WriteString("\n## Timestamp Logs\n")
	for _, l := range timeLogs {
		sb.WriteString("- `" + l + "`\n")
	}
	return sb.String()
}

func escapeJSON(s string) string {
	s = strings.ReplaceAll(s, `\`, `\\`)
	s = strings.ReplaceAll(s, `"`, `\"`)
	return s
}

package hello_verify_a

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"
)

func assertAborts(t *testing.T, name string, wantSubstr string, fn func()) {
	t.Helper()
	r := revive(fn)
	if r == nil {
		t.Fatalf("%s: expected abort/panic, but did not abort", name)
	}
	if s, ok := r.(string); ok {
		if wantSubstr != "" && !strings.Contains(s, wantSubstr) {
			t.Fatalf("%s: expected abort containing %q, got %q", name, wantSubstr, s)
		}
	}
}

func TestVerifyAllCompileAndLocalLogic(cur realm, t *testing.T) {
	alice := address("g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv")
	bob := address("g1syuz534wv9mugk5dnvaxvd9yxrzn05ke9dp0gq")

	admin = alice

	// 0. Mint secondary realm denom for realistic wrong-denom / multi-coin tests
	testing.SetRealm(testing.NewUserRealm(alice))
	dummyDenom := MintTestDenom(cross(cur), 5000)
	if !strings.HasSuffix(dummyDenom, ":dummy") {
		t.Fatalf("unexpected dummy denom: %s", dummyDenom)
	}

	// 1. Exact single ugnot deposit succeeds
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1000)))
	out := DepositExact(cross(cur), 1000)
	if !strings.Contains(out, "accepted=1000") {
		t.Fatalf("unexpected DepositExact output: %s", out)
	}

	// 2. Excess amount aborts
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1500)))
	assertAborts(t, "excess amount", "exact amount mismatch", func() {
		DepositExact(cross(cur), 1000)
	})

	// 3. Wrong denom aborts
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(dummyDenom, 1000)))
	assertAborts(t, "wrong denom", "invalid denom", func() {
		DepositExact(cross(cur), 1000)
	})

	// 4. Multi-coin aborts
	testing.SetOriginSend(chain.NewCoins(
		chain.NewCoin("ugnot", 1000),
		chain.NewCoin(dummyDenom, 500),
	))
	assertAborts(t, "multi coin", "must send exactly one coin", func() {
		DepositExact(cross(cur), 1000)
	})

	// 5. InspectSend records multi-coin raw
	rawOut := InspectSend(cross(cur), "multi-raw")
	if !strings.Contains(rawOut, "len=2") {
		t.Fatalf("expected len=2 in InspectSend, got: %s", rawOut)
	}

	// 6. DepositThenPanic aborts
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 777)))
	assertAborts(t, "deposit then panic", "intentional panic after receiving coins", func() {
		DepositThenPanic(cross(cur))
	})

	// 6b. Non-EOA code realm call to DepositExact aborts (anti-MITM guard)
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/hello_verify_b"))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1000)))
	assertAborts(t, "non-EOA deposit", "must be called directly by EOA", func() {
		DepositExact(cross(cur), 1000)
	})
	testing.SetRealm(testing.NewUserRealm(alice))

	// 7. Banker SendFromRealm transfers ugnot to bob
	testing.IssueCoins(realmAddr, chain.NewCoins(chain.NewCoin("ugnot", 5000)))
	testing.SetOriginSend(nil)
	beforeBob := banker.NewReadonlyBanker().GetCoin(bob, "ugnot")
	SendFromRealm(cross(cur), bob, 2000)
	afterBob := banker.NewReadonlyBanker().GetCoin(bob, "ugnot")
	if afterBob-beforeBob != 2000 {
		t.Fatalf("expected bob balance +2000, got delta=%d", afterBob-beforeBob)
	}

	// 8. Cross-realm call A -> B records prevPkg = hello_verify_a and origin = alice
	crossOut := CallCrossB(cross(cur), "unit")
	if !strings.Contains(crossOut, "prevIsEOA=false") {
		t.Fatalf("expected prevIsEOA=false on cross call, got: %s", crossOut)
	}
	if !strings.Contains(crossOut, "prevPkg=gno.land/r/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/hello_verify_a") {
		t.Fatalf("expected prevPkg=hello_verify_a, got: %s", crossOut)
	}
	if !strings.Contains(crossOut, "origin="+alice.String()) {
		t.Fatalf("expected origin=%s, got: %s", alice.String(), crossOut)
	}

	// 9. RecordTimestamp & Render
	ts := RecordTimestamp(cross(cur), "t1")
	if ts <= 0 {
		t.Fatalf("expected positive timestamp, got %d", ts)
	}
	if !strings.Contains(Render("json/state"), `"realm":"hello_verify_a"`) {
		t.Fatalf("unexpected json render: %s", Render("json/state"))
	}
}

