package verdict

import (
	"strconv"
	"strings"

	"gno.land/r/gov/dao"
)

// Proposal statuses as seen by Verdict.
const (
	statusActive   = "ACTIVE"
	statusAccepted = "ACCEPTED"
	statusDenied   = "DENIED"
	statusUnknown  = "UNKNOWN"
)

// govStatus returns the live status of a GovDAO proposal. It is a variable
// so tests can substitute a fake GovDAO.
var govStatus = fetchGovStatus

// fetchGovStatus reads the proposal page rendered by gno.land/r/gov/dao and
// extracts the status block.
//
// GovDAO keeps proposal statuses private to its implementation realm and
// exposes them only through Render, so Verdict reads the rendered page.
// The page is built as:
//
//	## Prop #N - <title>
//	<description>            <- written by the proposal author
//	...
//	### Stats
//	- **PROPOSAL HAS BEEN ACCEPTED** | **PROPOSAL HAS BEEN DENIED** | **Proposal is open for votes**
//	...
//	[Detailed voting list](...)
//
// The description is author-controlled, so a malicious author could paste a
// fake "### Stats" block into it. The real block is always rendered after
// the description, so we only trust the LAST "### Stats" heading, and only
// if the "[Detailed voting list]" link follows it.
//
// If GovDAO ever changes this format, parsing returns UNKNOWN: markets then
// stop accepting bets and cannot settle, and after their deadline anyone can
// call VoidExpired to refund every bettor. Funds can never be locked.
func fetchGovStatus(_ int, rlm realm, pid int64) string {
	page := dao.Render(cross(rlm), strconv.FormatInt(pid, 10))
	return parseGovStatus(page)
}

func parseGovStatus(page string) string {
	i := strings.LastIndex(page, "### Stats\n")
	if i < 0 {
		return statusUnknown
	}
	block := page[i+len("### Stats\n"):]
	if !strings.Contains(block, "[Detailed voting list](") {
		return statusUnknown
	}
	switch {
	case strings.HasPrefix(block, "- **PROPOSAL HAS BEEN ACCEPTED**"):
		return statusAccepted
	case strings.HasPrefix(block, "- **PROPOSAL HAS BEEN DENIED**"):
		return statusDenied
	case strings.HasPrefix(block, "- **Proposal is open for votes**"):
		return statusActive
	}
	return statusUnknown
}

// govTitle returns the proposal title, or "" if it can't be read.
func govTitle(pid int64) string {
	p, err := dao.GetProposal(dao.ProposalID(pid))
	if err != nil || p == nil {
		return ""
	}
	return strings.TrimSpace(strings.ReplaceAll(p.Title(), "\n", " "))
}

package verdict

import (
	"strconv"
	"strings"

	pm "gno.land/p/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/parimutuel"
)

// MarketsJSON returns up to limit markets as a JSON array, newest first,
// skipping the first offset. Built for frontends and bots, read it with
// the vm/qeval_json query: "<pkgpath>.MarketsJSON(0, 50)".
func MarketsJSON(offset, limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	if offset < 0 {
		offset = 0
	}
	var sb strings.Builder
	sb.WriteString("[")
	i, n := 0, 0
	markets.ReverseIterate("", "", func(_ string, v any) bool {
		if i < offset {
			i++
			return false
		}
		if n > 0 {
			sb.WriteString(",")
		}
		writeMarket(&sb, v.(*Market))
		n++
		return n >= limit
	})
	sb.WriteString("]")
	return sb.String()
}

// MarketJSON returns one market as a JSON object, or "null" if not found.
func MarketJSON(id int) string {
	v := markets.Get(idKey(id))
	if v == nil {
		return "null"
	}
	var sb strings.Builder
	writeMarket(&sb, v.(*Market))
	return sb.String()
}

// UserJSON returns addr's record and positions as JSON.
func UserJSON(addr address) string {
	var sb strings.Builder
	sb.WriteString(`{"address":` + jsonStr(addr.String()))
	if v := stats.Get(addr.String()); v != nil {
		s := v.(*Stats)
		sb.WriteString(`,"wagered":` + i64(s.Wagered) + `,"returned":` + i64(s.Returned) +
			`,"profit":` + i64(s.Profit()) + `,"bets":` + strconv.Itoa(s.Bets) + `,"wins":` + strconv.Itoa(s.Wins))
	}
	sb.WriteString(`,"positions":[`)
	n := 0
	markets.ReverseIterate("", "", func(_ string, v any) bool {
		m := v.(*Market)
		pos := m.Pool.Position(addr)
		if pos.Total() == 0 {
			return false
		}
		if n > 0 {
			sb.WriteString(",")
		}
		claimable := int64(0)
		if m.Pool.Outcome() != pm.Pending {
			claimable = m.Pool.Payout(addr)
		}
		sb.WriteString(`{"id":` + strconv.Itoa(m.ID) + `,"yes":` + i64(pos.Yes) + `,"no":` + i64(pos.No) +
			`,"claimed":` + strconv.FormatBool(pos.Claimed) + `,"claimable":` + i64(claimable) + `}`)
		n++
		return n >= 100
	})
	sb.WriteString("]}")
	return sb.String()
}

// LeaderboardJSON returns the top forecasters by realized profit.
func LeaderboardJSON(limit int) string {
	if limit <= 0 || limit > 100 {
		limit = 100
	}
	list := []lbEntry{}
	stats.Iterate("", "", func(k string, v any) bool {
		list = append(list, lbEntry{k, v.(*Stats)})
		return false
	})
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && list[j].s.Profit() > list[j-1].s.Profit(); j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
	var sb strings.Builder
	sb.WriteString("[")
	for i, e := range list {
		if i >= limit {
			break
		}
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`{"address":` + jsonStr(e.who) + `,"profit":` + i64(e.s.Profit()) +
			`,"wagered":` + i64(e.s.Wagered) + `,"bets":` + strconv.Itoa(e.s.Bets) + `,"wins":` + strconv.Itoa(e.s.Wins) + `}`)
	}
	sb.WriteString("]")
	return sb.String()
}

func writeMarket(sb *strings.Builder, m *Market) {
	p := m.Pool
	kind := "community"
	if m.Kind == KindGovDAO {
		kind = "govdao"
	}
	sb.WriteString(`{"id":` + strconv.Itoa(m.ID) +
		`,"kind":` + jsonStr(kind) +
		`,"question":` + jsonStr(m.Question) +
		`,"creator":` + jsonStr(m.Creator.String()) +
		`,"proposalId":` + i64(m.ProposalID) +
		`,"createdAt":` + i64(m.CreatedAt.Unix()) +
		`,"closeAt":` + unixOrZero(m) +
		`,"resolveBy":` + i64(m.ResolveBy.Unix()) +
		`,"resolvedAt":` + resolvedAt(m) +
		`,"outcome":` + jsonStr(p.Outcome().String()) +
		`,"note":` + jsonStr(m.Note) +
		`,"yes":` + i64(p.YesStake()) +
		`,"no":` + i64(p.NoStake()) +
		`,"yesBps":` + i64(p.YesBps()) +
		`,"multYes":` + i64(p.Multiplier(pm.Yes)) +
		`,"multNo":` + i64(p.Multiplier(pm.No)) +
		`,"bettors":` + strconv.Itoa(p.Bettors()) +
		`,"feeBps":` + i64(p.FeeBps()) + `}`)
}

func unixOrZero(m *Market) string {
	if m.Kind == KindGovDAO {
		return "0"
	}
	return i64(m.CloseAt.Unix())
}

func resolvedAt(m *Market) string {
	if m.ResolvedAt.IsZero() {
		return "0"
	}
	return i64(m.ResolvedAt.Unix())
}

func i64(n int64) string { return strconv.FormatInt(n, 10) }

// jsonStr encodes s as a JSON string. Non-ASCII runes are escaped as \uXXXX
// so the output is plain ASCII and safe everywhere.
func jsonStr(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			sb.WriteString(`\"`)
		case r == '\\':
			sb.WriteString(`\\`)
		case r == '\n':
			sb.WriteString(`\n`)
		case r == '\r':
			sb.WriteString(`\r`)
		case r == '\t':
			sb.WriteString(`\t`)
		case r < 0x20 || r > 0x7e:
			if r > 0xffff {
				// encode as a UTF-16 surrogate pair
				r -= 0x10000
				sb.WriteString(u4(0xd800 + (r >> 10)))
				sb.WriteString(u4(0xdc00 + (r & 0x3ff)))
			} else {
				sb.WriteString(u4(r))
			}
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func u4(r rune) string {
	h := strconv.FormatInt(int64(r), 16)
	for len(h) < 4 {
		h = "0" + h
	}
	return `\u` + h
}

package verdict

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/ufmt/v0"
	pm "gno.land/p/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/parimutuel"
)

const pageSize = 20

type posRow struct {
	who string
	pos pm.Position
}

type lbEntry struct {
	who string
	s   *Stats
}

// Render serves the gnoweb UI:
//
//	""             home: open markets, recently resolved, stats
//	"m/<id>"       a market page with odds and one-click bet buttons
//	"leaderboard"  top forecasters by profit
//	"u/<address>"  someone's positions
//	"new"          how to open a market
func Render(path string) string {
	path = strings.Trim(path, "/")
	switch {
	case path == "":
		return renderHome()
	case strings.HasPrefix(path, "m/"):
		id, err := strconv.Atoi(strings.TrimPrefix(path, "m/"))
		if err != nil {
			return "# Not found\n\nBad market id."
		}
		return renderMarket(id)
	case path == "leaderboard":
		return renderLeaderboard()
	case strings.HasPrefix(path, "u/"):
		return renderUser(address(strings.TrimPrefix(path, "u/")))
	case path == "new":
		return renderNew()
	}
	return "# Not found\n\n[Back home](" + realmLink("") + ")"
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Verdict\n\n")
	sb.WriteString("**Put your GNOT where your opinion is.** Bet on GovDAO votes and community questions. ")
	sb.WriteString("GovDAO markets settle straight from on-chain governance, with no oracle and no admin.\n\n")

	sb.WriteString(ufmt.Sprintf("%s markets · %s GNOT wagered · [Leaderboard](%s) · [Open a market](%s)\n\n",
		strconv.Itoa(MarketCount()), fmtGNOT(totalVolume), realmLink("leaderboard"), realmLink("new")))

	open, resolved := []*Market{}, []*Market{}
	markets.ReverseIterate("", "", func(_ string, v any) bool {
		m := v.(*Market)
		if m.Pool.Outcome() == pm.Pending {
			if len(open) < pageSize {
				open = append(open, m)
			}
		} else if len(resolved) < 10 {
			resolved = append(resolved, m)
		}
		return len(open) >= pageSize && len(resolved) >= 10
	})

	sb.WriteString("## Open markets\n\n")
	if len(open) == 0 {
		sb.WriteString("No open markets yet. [Open the first one](" + realmLink("new") + ").\n\n")
	} else {
		sb.WriteString("| Market | YES | Pool | Bettors | Closes |\n|---|---|---|---|---|\n")
		for _, m := range open {
			sb.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %s GNOT | %d | %s |\n",
				md.EscapeText(m.Question), realmLink("m/"+strconv.Itoa(m.ID)),
				fmtPct(m.Pool.YesBps()), fmtGNOT(m.Pool.Total()), m.Pool.Bettors(), closesLabel(m)))
		}
		sb.WriteString("\n")
	}

	if len(resolved) > 0 {
		sb.WriteString("## Recently resolved\n\n| Market | Result | Pool |\n|---|---|---|\n")
		for _, m := range resolved {
			sb.WriteString(ufmt.Sprintf("| [%s](%s) | **%s** | %s GNOT |\n",
				md.EscapeText(m.Question), realmLink("m/"+strconv.Itoa(m.ID)),
				strings.ToUpper(m.Pool.Outcome().String()), fmtGNOT(m.Pool.Total())))
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. Pick a side and stake GNOT (minimum " + fmtGNOT(MinBet) + " GNOT).\n")
	sb.WriteString("2. Everyone on the winning side splits the whole pool, in proportion to their stake.\n")
	sb.WriteString(ufmt.Sprintf("3. A %s fee is taken only when there are winners and losers. If nobody bet on the winning side, or a market is voided, everyone gets a full refund.\n", fmtPct(feeBps)))
	sb.WriteString("4. After the result, press **Claim** on the market page.\n\n")
	sb.WriteString("Payout math lives in a reusable package: [p/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/parimutuel](/p/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/parimutuel).\n")
	return sb.String()
}

func renderMarket(id int) string {
	v := markets.Get(idKey(id))
	if v == nil {
		return "# Market not found\n\n[Back home](" + realmLink("") + ")"
	}
	m := v.(*Market)
	p := m.Pool
	sid := strconv.Itoa(id)

	var sb strings.Builder
	sb.WriteString("# " + md.EscapeText(m.Question) + "\n\n")

	kind := "Community market · resolved by " + shortAddr(m.Creator)
	if m.Kind == KindGovDAO {
		kind = ufmt.Sprintf("GovDAO market · settles automatically from [proposal #%d](/r/gov/dao:%d)", m.ProposalID, m.ProposalID)
	}
	sb.WriteString(kind + "\n\n")

	// odds bar
	yb := p.YesBps()
	filled := int(yb / 500) // 20 cells
	bar := strings.Repeat("🟩", filled) + strings.Repeat("🟥", 20-filled)
	sb.WriteString(bar + "\n\n")
	sb.WriteString(ufmt.Sprintf("**YES %s** · %s GNOT · pays %s  \n", fmtPct(yb), fmtGNOT(p.YesStake()), fmtMult(p.Multiplier(pm.Yes))))
	sb.WriteString(ufmt.Sprintf("**NO %s** · %s GNOT · pays %s\n\n", fmtPct(10_000-yb), fmtGNOT(p.NoStake()), fmtMult(p.Multiplier(pm.No))))
	sb.WriteString(ufmt.Sprintf("Pool: **%s GNOT** from %d bettors · fee %s\n\n", fmtGNOT(p.Total()), p.Bettors(), fmtPct(p.FeeBps())))

	if p.Outcome() == pm.Pending {
		sb.WriteString("## Place a bet\n\n")
		if m.Kind == KindCommunity && !time.Now().Before(m.CloseAt) {
			sb.WriteString("Betting closed " + fmtTime(m.CloseAt) + ". Waiting for the creator to resolve (deadline " + fmtTime(m.ResolveBy) + ").\n\n")
			sb.WriteString(ufmt.Sprintf("Creator: [Resolve YES](%s) · [Resolve NO](%s) · [Void](%s)\n\n",
				txlink.NewLink("Resolve").AddArgs("id", sid, "outcome", "yes").URL(),
				txlink.NewLink("Resolve").AddArgs("id", sid, "outcome", "no").URL(),
				txlink.NewLink("Resolve").AddArgs("id", sid, "outcome", "void").URL()))
		} else {
			sb.WriteString("| | 1 GNOT | 10 GNOT | 100 GNOT |\n|---|---|---|---|\n")
			sb.WriteString("| **YES** | " + betLink(sid, "yes", 1) + " | " + betLink(sid, "yes", 10) + " | " + betLink(sid, "yes", 100) + " |\n")
			sb.WriteString("| **NO** | " + betLink(sid, "no", 1) + " | " + betLink(sid, "no", 10) + " | " + betLink(sid, "no", 100) + " |\n\n")
			sb.WriteString("Any other amount: [custom bet](" + txlink.NewLink("Bet").AddArgs("id", sid).URL() + ") and set the GNOT to send.\n\n")
			if m.Kind == KindCommunity {
				sb.WriteString("Betting closes " + fmtTime(m.CloseAt) + ".\n\n")
			} else {
				sb.WriteString("Betting closes automatically when GovDAO voting ends. Then anyone can [settle the market](" +
					txlink.NewLink("Settle").AddArgs("id", sid).URL() + ").\n\n")
			}
		}
		if !time.Now().Before(m.ResolveBy) {
			sb.WriteString("⚠️ Resolution deadline passed: [void and refund everyone](" + txlink.NewLink("VoidExpired").AddArgs("id", sid).URL() + ").\n\n")
		}
	} else {
		sb.WriteString(ufmt.Sprintf("## Result: %s\n\n", strings.ToUpper(p.Outcome().String())))
		sb.WriteString(md.EscapeText(m.Note) + " · " + fmtTime(m.ResolvedAt) + "\n\n")
		sb.WriteString("[**Claim your payout**](" + txlink.NewLink("Claim").AddArgs("id", sid).URL() + ")\n\n")
	}

	// positions
	rows := []posRow{}
	p.IterPositions(func(who string, pos pm.Position) bool {
		rows = append(rows, posRow{who, pos})
		return false
	})
	if len(rows) > 0 {
		sb.WriteString("## Positions\n\n| Bettor | YES | NO | Claimed |\n|---|---|---|---|\n")
		for i, r := range rows {
			if i >= 50 {
				sb.WriteString(ufmt.Sprintf("\n…and %d more\n", len(rows)-50))
				break
			}
			claimed := ""
			if r.pos.Claimed {
				claimed = "✅"
			}
			sb.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %s | %s |\n",
				shortAddr(address(r.who)), realmLink("u/"+r.who), fmtGNOT(r.pos.Yes), fmtGNOT(r.pos.No), claimed))
		}
		sb.WriteString("\n")
	}

	sb.WriteString("---\n\nShare: `" + "gno.land/r/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/verdict:m/" + sid + "` · [All markets](" + realmLink("") + ")\n")
	return sb.String()
}

func renderLeaderboard() string {
	list := []lbEntry{}
	stats.Iterate("", "", func(k string, v any) bool {
		list = append(list, lbEntry{k, v.(*Stats)})
		return false
	})
	// insertion sort by profit, descending
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && list[j].s.Profit() > list[j-1].s.Profit(); j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}

	var sb strings.Builder
	sb.WriteString("# Leaderboard\n\nTop forecasters by realized profit (claimed winnings minus GNOT wagered).\n\n")
	if len(list) == 0 {
		sb.WriteString("No bets yet.\n")
		return sb.String()
	}
	sb.WriteString("| # | Forecaster | Profit | Wagered | Bets | Wins |\n|---|---|---|---|---|---|\n")
	for i, e := range list {
		if i >= 50 {
			break
		}
		sb.WriteString(ufmt.Sprintf("| %d | [%s](%s) | %s | %s | %d | %d |\n",
			i+1, shortAddr(address(e.who)), realmLink("u/"+e.who), fmtSigned(e.s.Profit()), fmtGNOT(e.s.Wagered), e.s.Bets, e.s.Wins))
	}
	sb.WriteString("\n[Back to markets](" + realmLink("") + ")\n")
	return sb.String()
}

func renderUser(addr address) string {
	var sb strings.Builder
	sb.WriteString("# Forecaster " + shortAddr(addr) + "\n\n")
	if v := stats.Get(addr.String()); v != nil {
		s := v.(*Stats)
		sb.WriteString(ufmt.Sprintf("Profit %s · wagered %s GNOT · %d bets · %d wins\n\n", fmtSigned(s.Profit()), fmtGNOT(s.Wagered), s.Bets, s.Wins))
	}
	sb.WriteString("| Market | YES | NO | Status | Claimable |\n|---|---|---|---|---|\n")
	found := false
	markets.ReverseIterate("", "", func(_ string, v any) bool {
		m := v.(*Market)
		pos := m.Pool.Position(addr)
		if pos.Total() == 0 {
			return false
		}
		found = true
		claim := ""
		if pay := m.Pool.Payout(addr); pay > 0 && m.Pool.Outcome() != pm.Pending {
			claim = "[" + fmtGNOT(pay) + " GNOT](" + txlink.NewLink("Claim").AddArgs("id", strconv.Itoa(m.ID)).URL() + ")"
		}
		sb.WriteString(ufmt.Sprintf("| [%s](%s) | %s | %s | %s | %s |\n",
			md.EscapeText(clamp(m.Question, 80)), realmLink("m/"+strconv.Itoa(m.ID)),
			fmtGNOT(pos.Yes), fmtGNOT(pos.No), m.Pool.Outcome().String(), claim))
		return false
	})
	if !found {
		sb.WriteString("| no positions yet | | | | |\n")
	}
	return sb.String()
}

func renderNew() string {
	var sb strings.Builder
	sb.WriteString("# Open a market\n\n")
	sb.WriteString("## On a GovDAO proposal\n\nPick an [open proposal](/r/gov/dao) and enter its number. ")
	sb.WriteString("The market settles itself from the vote, so it's the most trustworthy kind.\n\n")
	sb.WriteString("[Create GovDAO market](" + txlink.NewLink("CreateGovDAOMarket").URL() + ")\n\n")
	sb.WriteString("## Community question\n\nAny yes/no question with a clear answer, for example *\"Will GNOT close above $0.10 on Dec 31?\"*. ")
	sb.WriteString("You set when betting closes (in hours). You resolve it afterwards and cannot bet on it yourself. ")
	sb.WriteString("If you don't resolve within 7 days, anyone can void it and refund every bettor.\n\n")
	sb.WriteString("[Create community market](" + txlink.NewLink("CreateMarket").URL() + ")\n")
	return sb.String()
}

// ---------------------------------------------------------------------------
// formatting

func betLink(id, side string, gnot int64) string {
	return "[" + strings.ToUpper(side) + " " + strconv.FormatInt(gnot, 10) + "](" +
		txlink.NewLink("Bet").AddArgs("id", id, "side", side).SetSend(strconv.FormatInt(gnot*1_000_000, 10)+"ugnot").URL() + ")"
}

func realmLink(sub string) string {
	if sub == "" {
		return "/r/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/verdict"
	}
	return "/r/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/verdict:" + sub
}

// fmtGNOT formats ugnot as GNOT with two decimals.
func fmtGNOT(u int64) string {
	neg := u < 0
	if neg {
		u = -u
	}
	s := strconv.FormatInt(u/1_000_000, 10) + "." + pad2((u%1_000_000)/10_000)
	if neg {
		return "-" + s
	}
	return s
}

func fmtSigned(u int64) string {
	if u > 0 {
		return "+" + fmtGNOT(u)
	}
	return fmtGNOT(u)
}

func fmtPct(bps int64) string {
	return strconv.FormatInt(bps/100, 10) + "." + strconv.FormatInt((bps%100)/10, 10) + "%"
}

func fmtMult(bps int64) string {
	if bps == 0 {
		return "—"
	}
	return strconv.FormatInt(bps/10_000, 10) + "." + pad2((bps%10_000)/100) + "x"
}

func pad2(n int64) string {
	if n < 10 {
		return "0" + strconv.FormatInt(n, 10)
	}
	return strconv.FormatInt(n, 10)
}

func fmtTime(t time.Time) string {
	return t.UTC().Format("Jan 2, 15:04 UTC")
}

func closesLabel(m *Market) string {
	if m.Kind == KindGovDAO {
		return "when vote ends"
	}
	if !time.Now().Before(m.CloseAt) {
		return "closed"
	}
	return fmtTime(m.CloseAt)
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// Package verdict is an on-chain prediction market for Gno.land, paid in GNOT.
//
// Two kinds of markets:
//
//   - GovDAO markets: "Will GovDAO proposal #N pass?". Anyone can open one for
//     an active proposal. They settle trustlessly: Settle() reads the proposal
//     status straight from gno.land/r/gov/dao, so no oracle and no admin are
//     involved. Betting closes automatically once voting ends.
//
//   - Community markets: any yes/no question with a close time. The creator
//     resolves it after the close time, and may not bet on their own market.
//     If the creator does not resolve in time, anyone can void the market and
//     every bettor is refunded in full.
//
// Betting is pari-mutuel (see gno.land/p/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/parimutuel): winners split
// the losing side pro rata. A small fee (default 1%) is taken only when a
// market has both winners and losers.
package verdict

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	pm "gno.land/p/g1ur6vq9feg6ehnvgysf2chm49a6z3yguzf80rjh/parimutuel"
)

const (
	denom = "ugnot"

	// MinBet is 0.1 GNOT.
	MinBet int64 = 100_000

	maxQuestionLen = 200
	minCloseHours  = 1
	maxCloseHours  = 24 * 90 // 90 days
	resolveWindow  = 7 * 24 * time.Hour
	govResolveBy   = 60 * 24 * time.Hour
)

// Kind of market.
type Kind int

const (
	KindCommunity Kind = iota
	KindGovDAO
)

// Market is one yes/no question with its betting pool.
type Market struct {
	ID         int
	Kind       Kind
	Question   string
	Creator    address
	ProposalID int64 // only for KindGovDAO
	CreatedAt  time.Time
	CloseAt    time.Time // community markets: betting closes here
	ResolveBy  time.Time // after this, an unresolved market can be voided
	ResolvedAt time.Time
	Note       string // how it was resolved
	Pool       *pm.Pool
}

// Stats tracks a bettor's lifetime record for the leaderboard.
type Stats struct {
	Wagered  int64
	Returned int64
	Bets     int
	Wins     int
}

// Profit returns returned minus wagered on settled positions.
func (s *Stats) Profit() int64 { return s.Returned - s.Wagered }

var (
	markets    avl.Tree // zero-padded id -> *Market
	govMarkets avl.Tree // proposal id -> market id
	stats      avl.Tree // address -> *Stats
	nextID     = 1

	admin        address
	feeRecipient address
	feeBps       int64 = 100 // 1%

	totalVolume int64
)

func init(cur realm) {
	admin = unsafe.OriginCaller()
	feeRecipient = admin
}

// ---------------------------------------------------------------------------
// Market creation

// CreateMarket opens a community market. closeInHours sets when betting
// closes; the creator then has 7 days to resolve it.
func CreateMarket(cur realm, question string, closeInHours int) int {
	assertUser(cur)
	caller := cur.Previous().Address()

	question = strings.TrimSpace(question)
	if question == "" {
		panic("question is required")
	}
	if len(question) > maxQuestionLen {
		panic(ufmt.Sprintf("question too long (max %d chars)", maxQuestionLen))
	}
	if closeInHours < minCloseHours || closeInHours > maxCloseHours {
		panic(ufmt.Sprintf("closeInHours must be between %d and %d", minCloseHours, maxCloseHours))
	}

	now := time.Now()
	closeAt := now.Add(time.Duration(closeInHours) * time.Hour)
	m := &Market{
		ID:        nextID,
		Kind:      KindCommunity,
		Question:  question,
		Creator:   caller,
		CreatedAt: now,
		CloseAt:   closeAt,
		ResolveBy: closeAt.Add(resolveWindow),
		Pool:      pm.New(feeBps),
	}
	saveNew(m)
	chain.Emit("MarketCreated", "id", strconv.Itoa(m.ID), "kind", "community", "creator", caller.String())
	return m.ID
}

// CreateGovDAOMarket opens "Will GovDAO proposal #pid pass?". The proposal
// must currently be open for votes, and there can only be one market per
// proposal.
func CreateGovDAOMarket(cur realm, pid int64) int {
	assertUser(cur)
	caller := cur.Previous().Address()

	key := strconv.FormatInt(pid, 10)
	if govMarkets.Has(key) {
		panic("a market for this proposal already exists: " + mustGetGovMarketID(key))
	}
	status := govStatus(0, cur, pid)
	if status != statusActive {
		panic("proposal #" + key + " is not open for votes (status: " + status + ")")
	}

	title := govTitle(pid)
	q := "Will GovDAO proposal #" + key + " pass?"
	if title != "" {
		q = "Will GovDAO proposal #" + key + " (" + clamp(title, 120) + ") pass?"
	}

	now := time.Now()
	m := &Market{
		ID:         nextID,
		Kind:       KindGovDAO,
		Question:   q,
		Creator:    caller,
		ProposalID: pid,
		CreatedAt:  now,
		ResolveBy:  now.Add(govResolveBy),
		Pool:       pm.New(feeBps),
	}
	saveNew(m)
	govMarkets.Set(key, m.ID)
	chain.Emit("MarketCreated", "id", strconv.Itoa(m.ID), "kind", "govdao", "proposal", key, "creator", caller.String())
	return m.ID
}

// ---------------------------------------------------------------------------
// Betting

// Bet stakes the attached GNOT (-send) on side "yes" or "no".
func Bet(cur realm, id int, side string) {
	assertUser(cur)
	caller := cur.Previous().Address()
	m := mustGet(id)

	s, err := pm.ParseSide(side)
	if err != nil {
		panic(err.Error())
	}

	sent := unsafe.OriginSend()
	amount := sent.AmountOf(denom)
	if len(sent) != 1 || amount <= 0 {
		panic("attach GNOT only, e.g. -send 1000000ugnot")
	}
	if amount < MinBet {
		panic(ufmt.Sprintf("minimum bet is %s GNOT", fmtGNOT(MinBet)))
	}

	switch m.Kind {
	case KindCommunity:
		if caller == m.Creator {
			panic("the resolver of a community market cannot bet on it")
		}
		if !time.Now().Before(m.CloseAt) {
			panic("betting is closed for this market")
		}
	case KindGovDAO:
		if st := govStatus(0, cur, m.ProposalID); st != statusActive {
			panic("voting has ended for this proposal (status: " + st + "), betting is closed")
		}
	}

	if err := m.Pool.Place(caller, s, amount); err != nil {
		panic(err.Error())
	}

	st := getStats(caller)
	st.Wagered += amount
	st.Bets++
	totalVolume += amount

	chain.Emit("BetPlaced",
		"id", strconv.Itoa(id),
		"side", s.String(),
		"amount", strconv.FormatInt(amount, 10),
		"bettor", caller.String(),
	)
}

// ---------------------------------------------------------------------------
// Resolution

// Settle resolves a GovDAO market from the live proposal status. Anyone can
// call it once the proposal is accepted or denied.
func Settle(cur realm, id int) {
	assertUser(cur)
	m := mustGet(id)
	if m.Kind != KindGovDAO {
		panic("only GovDAO markets settle automatically; the creator resolves community markets")
	}
	assertPending(m)

	st := govStatus(0, cur, m.ProposalID)
	var o pm.Outcome
	switch st {
	case statusAccepted:
		o = pm.Yes
	case statusDenied:
		o = pm.No
	default:
		panic("proposal is still " + st + ", cannot settle yet")
	}
	finalize(cur, m, o, "settled from GovDAO: proposal "+strings.ToLower(st))
}

// Resolve lets the creator of a community market set the outcome
// ("yes", "no" or "void") after betting has closed.
func Resolve(cur realm, id int, outcome string) {
	assertUser(cur)
	caller := cur.Previous().Address()
	m := mustGet(id)
	if m.Kind != KindCommunity {
		panic("GovDAO markets settle from on-chain data: call Settle")
	}
	assertPending(m)
	if caller != m.Creator {
		panic("only the market creator can resolve it")
	}
	now := time.Now()
	if now.Before(m.CloseAt) {
		panic("betting has not closed yet")
	}
	if !now.Before(m.ResolveBy) {
		panic("resolution window has passed; anyone can call VoidExpired")
	}

	var o pm.Outcome
	switch strings.ToLower(strings.TrimSpace(outcome)) {
	case "yes":
		o = pm.Yes
	case "no":
		o = pm.No
	case "void":
		o = pm.Void
	default:
		panic("outcome must be yes, no or void")
	}
	finalize(cur, m, o, "resolved by creator")
}

// VoidExpired refunds everyone when a market was not resolved in time.
func VoidExpired(cur realm, id int) {
	assertUser(cur)
	m := mustGet(id)
	assertPending(m)
	if time.Now().Before(m.ResolveBy) {
		panic("market can still be resolved; void is possible after " + fmtTime(m.ResolveBy))
	}
	finalize(cur, m, pm.Void, "voided: not resolved in time")
}

// AdminVoid lets the admin void an unresolved community market (spam,
// ambiguous or abusive questions). Everyone is refunded in full.
// GovDAO markets cannot be touched by the admin.
func AdminVoid(cur realm, id int, reason string) {
	assertUser(cur)
	assertAdmin(cur)
	m := mustGet(id)
	if m.Kind != KindCommunity {
		panic("GovDAO markets cannot be voided by the admin")
	}
	assertPending(m)
	finalize(cur, m, pm.Void, "voided by admin: "+clamp(reason, 140))
}

func finalize(cur realm, m *Market, o pm.Outcome, note string) {
	final, err := m.Pool.Resolve(o)
	if err != nil {
		panic(err.Error())
	}
	m.ResolvedAt = time.Now()
	m.Note = note
	if final == pm.Void && o != pm.Void {
		m.Note = note + " (winning side was empty, so everyone is refunded)"
	}
	if fee := m.Pool.Fee(); fee > 0 && feeRecipient != "" {
		send(cur, feeRecipient, fee)
	}
	chain.Emit("MarketResolved", "id", strconv.Itoa(m.ID), "outcome", final.String())
}

// ---------------------------------------------------------------------------
// Claiming

// Claim pays out the caller's winnings (or refund) for a resolved market.
func Claim(cur realm, id int) int64 {
	assertUser(cur)
	caller := cur.Previous().Address()
	m := mustGet(id)

	pos := m.Pool.Position(caller)
	amount, err := m.Pool.Claim(caller)
	if err != nil {
		panic(err.Error())
	}
	send(cur, caller, amount)

	st := getStats(caller)
	st.Returned += amount
	if m.Pool.Outcome() != pm.Void && amount > pos.Total() {
		st.Wins++
	}
	if m.Pool.Outcome() == pm.Void {
		// A refund is not a bet: take it out of the record entirely.
		st.Wagered -= pos.Total()
		st.Returned -= amount
	}

	chain.Emit("Claimed", "id", strconv.Itoa(id), "amount", strconv.FormatInt(amount, 10), "bettor", caller.String())
	return amount
}

// ---------------------------------------------------------------------------
// Admin

// SetFee sets the fee for markets created from now on (max 3%).
func SetFee(cur realm, bps int64) {
	assertUser(cur)
	assertAdmin(cur)
	if bps < 0 || bps > 300 {
		panic("fee must be between 0 and 300 bps")
	}
	feeBps = bps
}

// SetFeeRecipient changes where fees are sent.
func SetFeeRecipient(cur realm, addr address) {
	assertUser(cur)
	assertAdmin(cur)
	if !addr.IsValid() {
		panic("invalid address")
	}
	feeRecipient = addr
}

// TransferAdmin hands admin rights to a new address.
func TransferAdmin(cur realm, addr address) {
	assertUser(cur)
	assertAdmin(cur)
	if !addr.IsValid() {
		panic("invalid address")
	}
	admin = addr
}

// ---------------------------------------------------------------------------
// Read-only getters (handy for other realms, bots and frontends)

// MarketCount returns how many markets exist.
func MarketCount() int { return nextID - 1 }

// GetOdds returns the YES share in basis points and the pool sizes.
func GetOdds(id int) (yesBps, yesStake, noStake int64) {
	m := mustGet(id)
	return m.Pool.YesBps(), m.Pool.YesStake(), m.Pool.NoStake()
}

// GetOutcome returns "pending", "yes", "no" or "void".
func GetOutcome(id int) string { return mustGet(id).Pool.Outcome().String() }

// PendingPayout returns what addr could claim right now on market id.
func PendingPayout(id int, addr address) int64 { return mustGet(id).Pool.Payout(addr) }

// MarketForProposal returns the market id for a GovDAO proposal, or 0.
func MarketForProposal(pid int64) int {
	v := govMarkets.Get(strconv.FormatInt(pid, 10))
	if v == nil {
		return 0
	}
	return v.(int)
}

// ---------------------------------------------------------------------------
// helpers

func assertUser(cur realm) {
	// OriginSend only describes a real payment to this realm when the caller
	// is the origin EOA itself (see r/demo/defi/atomicswap for the reasoning).
	if !cur.Previous().IsUserCall() {
		panic("call this function directly (gnokey maketx call / wallet)")
	}
}

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
}

func assertPending(m *Market) {
	if m.Pool.Outcome() != pm.Pending {
		panic("market is already resolved (" + m.Pool.Outcome().String() + ")")
	}
}

func send(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), to, chain.Coins{{denom, amount}})
}

func saveNew(m *Market) {
	markets.Set(idKey(m.ID), m)
	nextID++
}

func mustGet(id int) *Market {
	v := markets.Get(idKey(id))
	if v == nil {
		panic("market not found: " + strconv.Itoa(id))
	}
	return v.(*Market)
}

func mustGetGovMarketID(key string) string {
	return strconv.Itoa(govMarkets.Get(key).(int))
}

func getStats(addr address) *Stats {
	v := stats.Get(addr.String())
	if v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	stats.Set(addr.String(), s)
	return s
}

// idKey zero-pads ids so the avl tree iterates in creation order.
func idKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func clamp(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

