// ---- helpers ---------------------------------------------------------------

// CommitmentHex computes the commitment for a move and salt:
// sha256("<move>:<salt>"), hex encoded. Compute it locally, keep the
// move and salt secret until the reveal.
func CommitmentHex(move int, salt string) string {
	sum := sha256.Sum256([]byte(strconv.Itoa(move) + ":" + salt))
	return hex.EncodeToString(sum[:])
}

func mustDuel(id uint64) *Duel {
	v := duels.Get(strconv.FormatUint(id, 10))
	if v == nil {
		panic("unknown duel id")
	}
	return v.(*Duel)
}

// mustStake returns the ugnot amount sent with the current call and
// enforces the stake bounds.
func mustStake() int64 {
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("send the stake in ugnot")
	}
	amt := sent[0].Amount
	if amt < MinStake || amt > MaxStake {
		panic("stake out of bounds")
	}
	return amt
}

func statsFor(addr address) *Stats {
	key := string(addr)
	if v := stats.Get(key); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	stats.Set(key, s)
	return s
}

// collect returns duels matching keep, newest first.
func collect(keep func(*Duel) bool, limit int) []*Duel {
	var out []*Duel
	duels.ReverseIterateByOffset(0, 500, func(_ string, value any) bool {
		if len(out) >= limit {
			return true
		}
		d := value.(*Duel)
		if keep(d) {
			out = append(out, d)
		}
		return false
	})
	return out
}

func validateCommitment(c string) {
	if len(c) != 64 || !isHex(c) {
		panic("commitment must be 64 hex characters (sha256)")
	}
}

func isHex(s string) bool {
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if !(ch >= '0' && ch <= '9') && !(ch >= 'a' && ch <= 'f') {
			return false
		}
	}
	return true
}

func assertAdmin(cur realm) {
	require(hasAdmin, "realm not initialized")
	require(cur.Previous().Address() == admin, "only the realm admin")
}

func require(check bool, msg string) {
	if !check {
		panic(msg)
	}
}

func duelByPath(id string) *Duel {
	if v := duels.Get(id); v != nil {
		return v.(*Duel)
	}
	return nil
}

func duelTable(title string, list []*Duel) string {
	if len(list) == 0 {
		return ""
	}
	table := mdtable.Table{Headers: []string{"#", "Creator", "Stake", "Deadline", "Details"}}
	for _, d := range list {
		table.Append([]string{
			strconv.FormatUint(d.id, 10),
			short(d.creator.String()),
			coins(d.stake),
			ufmt.Sprintf("height %d", deadline(d)),
			md.Link("detail", "/"+webRoot+":duel/"+strconv.FormatUint(d.id, 10)),
		})
	}
	return md.H2(title) + table.String() + "\n"
}

func recentTable(list []*Duel) string {
	if len(list) == 0 {
		return md.Paragraph("No resolved duels yet — be the first!")
	}
	table := mdtable.Table{Headers: []string{"#", "Players", "Result", "Payout"}}
	for _, d := range list {
		table.Append([]string{
			strconv.FormatUint(d.id, 10),
			short(d.creator.String()) + " vs " + joinerLabel(d),
			resultLabel(d),
			coins(d.payout),
		})
	}
	return table.String() + "\n"
}

func deadline(d *Duel) int64 {
	if d.phase == PhaseOpen {
		return d.joinDeadline
	}
	return d.revealDeadline
}

func deadlineLabel(d *Duel) string {
	if d.phase == PhaseOpen {
		return ufmt.Sprintf("Join deadline: height %d", d.joinDeadline)
	}
	if d.phase == PhaseReveal {
		return ufmt.Sprintf("Reveal deadline: height %d", d.revealDeadline)
	}
	return ufmt.Sprintf("Resolved at height %d", d.resolvedHeight)
}

func statusLabel(d *Duel) string {
	switch d.phase {
	case PhaseOpen:
		return "waiting for an opponent"
	case PhaseReveal:
		return "reveal phase"
	default:
		return "done"
	}
}

func joinerLabel(d *Duel) string {
	if string(d.joiner) == "" {
		return "— (nobody yet)"
	}
	return short(d.joiner.String())
}

func joinerCommitLabel(d *Duel) string {
	if d.joinerCommit == "" {
		return "—"
	}
	return truncate(d.joinerCommit)
}

func moveLabel(move int) string {
	switch move {
	case MoveAle:
		return "🍺 Ale (revealed)"
	case MoveBroom:
		return "🧹 Broom (revealed)"
	case MoveDagger:
		return "🗡️ Dagger (revealed)"
	default:
		return "committed, not revealed yet"
	}
}

func resultLabel(d *Duel) string {
	switch d.result {
	case ResultCreator:
		return "creator wins 🍻"
	case ResultJoiner:
		return "joiner wins 🍻"
	case ResultTie:
		return "tie — both refunded 🤝"
	default:
		return "expired — refunded ⏰"
	}
}

func rakePct() string {
	return ufmt.Sprintf("%d.%02d%%", rakeBps/100, rakeBps%100)
}

func coins(ugnot int64) string {
	if ugnot == 0 {
		return "0 GNOT"
	}
	return ufmt.Sprintf("%d.%06d GNOT", ugnot/1_000_000, ugnot%1_000_000)
}

func short(addr string) string {
	if len(addr) < 14 {
		return addr
	}
	return addr[:8] + "…" + addr[len(addr)-6:]
}

func truncate(s string) string {
	if len(s) <= 16 {
		return s
	}
	return s[:16] + "…"
}

func adminLabel() string {
	if !hasAdmin {
		return "not initialized"
	}
	return admin.String()
}

// Package admitone sells event tickets whose price stays in escrow until the
// holder walks in.
//
// A ticket is a GRC721 token. Buying one locks its price in this realm. The
// holder's own Admit, at the door, releases the price to the organiser. If the
// event is cancelled, every ticket is refunded in full. If a holder never
// shows up, they take back the price minus a no-show fee the organiser fixed
// when creating the event. The organiser can never touch the money in escrow.
//
// Tickets cannot be given or transferred. A holder who cannot go lists the
// ticket on the event's resale desk, at no more than face value plus a capped
// markup. A listing opens to buyers a minute after it is posted, and then the
// first buyer takes it, so handing a seat to a buyer chosen in advance is a
// race the seller can lose rather than a sure thing.
//
// An event can post a one-shot Lamplighter job due at its end, so the no-show
// fees reach the organiser on time without anyone remembering to call Settle.
package admitone

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

const (
	denom = "ugnot"

	// LampFee is what an organiser sends with CreateEvent to have the event
	// settled by a Lamplighter job at its end. Sending nothing is fine too:
	// then anyone can call Settle.
	LampFee int64 = 50000

	MaxCapacity        = 1000
	MaxPrice     int64 = 1000000000000 // 1,000,000 GNOT
	MaxMarkupBps int64 = 5000          // resale at up to face + 50%
	MaxNoShowBps int64 = 10000         // up to the whole price

	MinLength int64 = 60                 // an event lasts at least a minute
	MaxLength int64 = 90 * 24 * 60 * 60  // and at most 90 days
	MaxAhead  int64 = 366 * 24 * 60 * 60 // it starts within a year

	// ResaleDelay is how long a listing waits before anyone can buy it, so that
	// a seller cannot list and sell to a chosen buyer in one transaction.
	ResaleDelay int64 = 60

	// ResaleDeposit is what a resale buyer pays the seller on top of the price,
	// for the storage deposit the ticket already carries: the seller locked it
	// when buying, and the chain hands it to whoever finally refunds or
	// discards the ticket, which will be the buyer.
	ResaleDeposit int64 = 600000

	maxNameLen    = 60
	maxDetailsLen = 280
)

type event struct {
	id         uint64
	name       string
	details    string
	organiser  address
	start, end int64
	price      int64
	capacity   int
	maxPerAddr int
	markupBps  int64
	noShowBps  int64

	minted   int // serials handed out, 1..minted
	live     int // tickets not refunded
	admitted int // live tickets that were admitted
	entered  int // tickets admitted at the door, ever (discarding does not lower it)

	cancelled bool
	settled   bool   // the no-show fees have gone to the organiser
	job       uint64 // the Lamplighter job that settles the event, or 0
	reclaimed bool   // the job has been cancelled and its deposit recovered
}

type ticket struct {
	id         string // "<event>-<serial>", also its GRC721 token id
	ev         *event
	serial     int
	admittedAt int64 // 0 until the holder is admitted
	listed     bool
	listPrice  int64
	listedAt   int64
}

var (
	events  avl.Tree // padded event id -> *event
	tickets avl.Tree // padded "<event>-<serial>" -> *ticket
	byOwner avl.Tree // address + "/" + padded ticket key -> *ticket
	byJob   avl.Tree // padded job id -> *event
	nextID  uint64   = 1

	nft    *grc721.Token
	ledger *grc721.PrivateLedger

	// selfPath is this realm's own package path, recorded when it is deployed.
	selfPath string
)

func init(cur realm) {
	selfPath = cur.PkgPath()
	nft, ledger = grc721.NewToken("Admit One tickets", "ADMIT", 0, cur)
}

// CreateEvent puts an event on sale and returns its id. The caller is the
// organiser. Times are unix seconds. price is in ugnot (0 for a free event,
// where tickets work as an RSVP and an attendance stamp). maxPerAddr caps the
// tickets one address may hold. markupBps caps resale at face value plus that
// many hundredths of a percent; noShowBps is the share of the price the
// organiser keeps from a holder who never shows up.
//
// Send nothing, or exactly LampFee to have a Lamplighter job settle the event
// at its end.
func CreateEvent(cur realm, name, details string, start, end, price int64,
	capacity, maxPerAddr int, markupBps, noShowBps int64) uint64 {
	runtime.AssertOriginCall() // the coins sent are only the caller's on a direct call
	withJob, msg := fundRefusal(unsafe.OriginSend())
	if msg == "" {
		msg = checkEvent(name, details, start, end, price, capacity, maxPerAddr, markupBps, noShowBps, time.Now().Unix())
	}
	if msg != "" {
		panic(msg)
	}

	e := &event{
		id: nextID, name: name, details: details, organiser: cur.Previous().Address(),
		start: start, end: end, price: price, capacity: capacity, maxPerAddr: maxPerAddr,
		markupBps: markupBps, noShowBps: noShowBps,
	}
	nextID++

	if withJob {
		// Post the job that settles the event at its end, and fund it with the
		// fee the organiser sent, in this same call.
		e.job = registry.Register(cross(cur), "Admit One: settle event "+utoa(e.id), end, 0, LampFee, settleJob)
		send(cur, chain.PackageAddress(registry.Path()), LampFee)
		registry.Credit(cross(cur), e.job, LampFee)
		byJob.Set(pad(e.job), e)
	}
	events.Set(pad(e.id), e)
	chain.Emit("EventCreated", "id", utoa(e.id), "organiser", e.organiser.String(),
		"start", itoa(start), "end", itoa(end), "price", itoa(price), "job", utoa(e.job))
	return e.id
}

// Buy sells the next ticket of an event to the caller, who sends exactly the
// price. The price stays here until the holder is admitted. Returns the
// ticket id.
func Buy(cur realm, eventID uint64) string {
	runtime.AssertOriginCall()
	e := mustEvent(eventID)
	mustPay(e.price)
	buyer := cur.Previous().Address()
	if msg := buyRefusal(e, buyer, time.Now().Unix()); msg != "" {
		panic(msg)
	}

	e.minted++
	e.live++
	t := &ticket{id: utoa(e.id) + "-" + strconv.Itoa(e.minted), ev: e, serial: e.minted}
	if err := ledger.Mint(buyer, grc721.TokenID(t.id)); err != nil {
		panic(err)
	}
	tickets.Set(ticketKey(e.id, t.serial), t)
	hold(e, buyer, t, +1)
	chain.Emit("TicketBought", "ticket", t.id, "buyer", buyer.String(), "price", itoa(e.price))
	return t.id
}

// List puts the caller's ticket on the event's resale desk. The price may be
// at most face value plus the event's markup; on a free event it must be 0.
func List(cur realm, ticketID string, price int64) {
	t, holder := mustHold(cur, ticketID)
	e := t.ev
	switch {
	case e.cancelled:
		panic("the event is cancelled")
	case time.Now().Unix() >= e.end:
		panic("the event is over")
	case t.admittedAt != 0:
		panic("an admitted ticket cannot be resold")
	case price < 0 || price > resaleCap(e):
		panic("list at 0 to " + itoa(resaleCap(e)) + " " + denom + ": face value plus at most " + bps(e.markupBps))
	}
	t.listed = true
	t.listPrice = price
	t.listedAt = time.Now().Unix()
	chain.Emit("TicketListed", "ticket", t.id, "seller", holder.String(), "price", itoa(price))
}

// Unlist takes the caller's ticket off the resale desk.
func Unlist(cur realm, ticketID string) {
	t, _ := mustHold(cur, ticketID)
	if !t.listed {
		panic("the ticket is not listed")
	}
	t.listed = false
	t.listPrice = 0
	t.listedAt = 0
	chain.Emit("TicketUnlisted", "ticket", t.id)
}

// BuyListed buys a ticket from the resale desk, once the listing has been up
// for ResaleDelay seconds. The caller sends exactly the listed price plus
// ResaleDeposit; both go straight to the seller. The face value stays in
// escrow with the ticket.
func BuyListed(cur realm, ticketID string) {
	runtime.AssertOriginCall()
	t := mustTicket(ticketID)
	e := t.ev
	buyer := cur.Previous().Address()
	if msg := buyListedRefusal(t, buyer, time.Now().Unix()); msg != "" {
		panic(msg)
	}
	mustPay(t.listPrice + ResaleDeposit)
	seller := ownerOf(t)

	price := t.listPrice
	t.listed = false
	t.listPrice = 0
	t.listedAt = 0
	if err := ledger.TransferFrom(seller, seller, buyer, grc721.TokenID(t.id)); err != nil {
		panic(err)
	}
	hold(e, seller, t, -1)
	hold(e, buyer, t, +1)
	send(cur, seller, price+ResaleDeposit)
	chain.Emit("TicketResold", "ticket", t.id, "seller", seller.String(), "buyer", buyer.String(), "price", itoa(price))
}

// Admit is the holder walking in. It works only while the event is on, and
// releases the ticket's price from escrow to the organiser. The ticket stays
// with the holder, marked admitted: whoever checks the door reads it on the
// ticket's page.
func Admit(cur realm, ticketID string) {
	t, holder := mustHold(cur, ticketID)
	e := t.ev
	now := time.Now().Unix()
	switch {
	case e.cancelled:
		panic("the event is cancelled")
	case now < e.start:
		panic("doors open at " + when(e.start))
	case now >= e.end:
		panic("the event is over")
	case t.admittedAt != 0:
		panic("already admitted")
	}
	t.admittedAt = now
	t.listed = false
	t.listPrice = 0
	t.listedAt = 0
	e.admitted++
	e.entered++
	if e.price > 0 {
		send(cur, e.organiser, e.price)
	}
	chain.Emit("TicketAdmitted", "ticket", t.id, "holder", holder.String())
}

// Cancel calls an event off before it starts. Every ticket becomes refundable
// in full, and the event's Lamplighter job, if any, is cancelled with its fee
// returned to the organiser. Only the organiser can cancel.
func Cancel(cur realm, eventID uint64) {
	e := mustEvent(eventID)
	if cur.Previous().Address() != e.organiser {
		panic("only the organiser can cancel the event")
	}
	if e.cancelled {
		panic("the event is already cancelled")
	}
	if time.Now().Unix() >= e.start {
		panic("an event that has started cannot be cancelled")
	}
	e.cancelled = true
	if e.job != 0 && !e.reclaimed {
		e.reclaimed = true
		byJob.Remove(pad(e.job))
		registry.Cancel(cross(cur), e.job, e.organiser)
	}
	chain.Emit("EventCancelled", "id", utoa(e.id))
}

// Settle pays the organiser the no-show fee of every ticket that was neither
// admitted nor refunded. Anyone can call it once the event is over; the
// event's Lamplighter job, if it has one, does the same.
func Settle(cur realm, eventID uint64) {
	e := mustEvent(eventID)
	mustSettle(e)
	settle(cur, e)
}

// settleJob is the callback the Lamplighter registry holds for every event
// that posted a job. The registry runs any callback for anyone, so the job id
// must be one this realm posted: it says which event to settle.
func settleJob(cur realm, job uint64) error {
	if cur.Previous().PkgPath() != registry.Path() {
		return errors.New("only the lamplighter registry runs this")
	}
	e, ok := byJob.Get(pad(job)).(*event)
	if !ok {
		return errors.New("not a job of this realm")
	}
	if e.settled {
		// Somebody called Settle first. Succeed anyway, so that the job
		// completes, its runner is paid, and it leaves the queue.
		return nil
	}
	if err := settleable(e); err != nil {
		return err
	}
	settle(cur, e)
	return nil
}

func settle(cur realm, e *event) {
	e.settled = true
	due := noShowFee(e) * int64(e.live-e.admitted)
	if due > 0 {
		send(cur, e.organiser, due)
	}
	chain.Emit("EventSettled", "id", utoa(e.id), "noShows", strconv.Itoa(e.live-e.admitted), "paid", itoa(due))
}

// Refund returns a ticket that was not used, and burns it: the full price if
// the event was cancelled, otherwise, once the event is over, the price minus
// the no-show fee. Burning the ticket also hands its storage deposit back to
// the holder.
func Refund(cur realm, ticketID string) {
	t, holder := mustHold(cur, ticketID)
	e := t.ev
	if t.admittedAt != 0 {
		panic("an admitted ticket has been used")
	}
	amount, feeNow := e.price, int64(0)
	if !e.cancelled {
		if time.Now().Unix() < e.end {
			panic("refunds open when the event is cancelled or over")
		}
		fee := noShowFee(e)
		amount -= fee
		if !e.settled {
			// Settle has not run, so this ticket's fee has not been paid yet.
			feeNow = fee
		}
	}

	e.live--
	hold(e, holder, t, -1)
	tickets.Remove(ticketKey(e.id, t.serial))
	if err := ledger.Burn(grc721.TokenID(t.id)); err != nil {
		panic(err)
	}
	if feeNow > 0 {
		send(cur, e.organiser, feeNow)
	}
	if amount > 0 {
		send(cur, holder, amount)
	}
	chain.Emit("TicketRefunded", "ticket", t.id, "holder", holder.String(), "amount", itoa(amount))
}

// Discard burns an admitted ticket once the event is over. The ticket is the
// holder's stamp of having been there; throwing it away hands back the storage
// deposit buying it locked. Nothing else changes: the money already went to the
// organiser at the door.
func Discard(cur realm, ticketID string) {
	t, holder := mustHold(cur, ticketID)
	e := t.ev
	if t.admittedAt == 0 {
		panic("only an admitted ticket can be discarded; refund an unused one")
	}
	if time.Now().Unix() < e.end {
		panic("keep it until the event is over")
	}
	e.live--
	e.admitted--
	hold(e, holder, t, -1)
	tickets.Remove(ticketKey(e.id, t.serial))
	if err := ledger.Burn(grc721.TokenID(t.id)); err != nil {
		panic(err)
	}
	chain.Emit("TicketDiscarded", "ticket", t.id, "holder", holder.String())
}

// Reclaim cancels the finished Lamplighter job of a settled event. Creating
// the event locked a storage deposit from the organiser for that job's state;
// freeing it hands the deposit back to whoever sends this, so only the
// organiser can.
func Reclaim(cur realm, eventID uint64) {
	e := mustEvent(eventID)
	if cur.Previous().Address() != e.organiser {
		panic("only the organiser can reclaim the job's deposit")
	}
	if e.job == 0 || e.reclaimed {
		panic("there is no job to reclaim")
	}
	if !e.settled {
		panic("the event is not settled yet")
	}
	e.reclaimed = true
	byJob.Remove(pad(e.job))
	registry.Cancel(cross(cur), e.job, e.organiser)
}

// ---- queries ---------------------------------------------------------------

// Token is a read-only view of the ticket ledger (GRC721).
func Token() grc721.Teller { return nft.ReadonlyTeller() }

// OwnerOf returns the holder of a ticket.
func OwnerOf(ticketID string) address { return ownerOf(mustTicket(ticketID)) }

// IsAdmitted reports whether a ticket has been used to get in.
func IsAdmitted(ticketID string) bool { return mustTicket(ticketID).admittedAt != 0 }

// Attended reports whether addr holds an admitted ticket for an event. Other
// realms can use it to gate something to the people who were there.
func Attended(eventID uint64, addr address) bool {
	found := false
	prefix := addr.String() + "/" + pad(eventID) + "-"
	byOwner.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		found = v.(*ticket).admittedAt != 0
		return found
	})
	return found
}

// Seats returns how many tickets of an event are held, how many were admitted
// at the door, and the capacity.
func Seats(eventID uint64) (held, entered, capacity int) {
	e := mustEvent(eventID)
	return e.live, e.entered, e.capacity
}

// InEscrow returns the ugnot this realm holds for an event's tickets.
func InEscrow(eventID uint64) int64 { return escrow(mustEvent(eventID)) }

// JobOf returns the Lamplighter job that settles an event, or 0.
func JobOf(eventID uint64) uint64 { return mustEvent(eventID).job }

// ---- helpers ---------------------------------------------------------------

func escrow(e *event) int64 {
	unused := int64(e.live - e.admitted)
	if e.settled {
		return unused * (e.price - noShowFee(e))
	}
	return unused * e.price
}

func noShowFee(e *event) int64 {
	if e.cancelled {
		return 0
	}
	return e.price * e.noShowBps / 10000
}

func resaleCap(e *event) int64 { return e.price + e.price*e.markupBps/10000 }

func settleable(e *event) error {
	switch {
	case e.cancelled:
		return errors.New("event " + utoa(e.id) + " was cancelled")
	case e.settled:
		return errors.New("event " + utoa(e.id) + " is already settled")
	case time.Now().Unix() < e.end:
		return errors.New("event " + utoa(e.id) + " is not over yet")
	}
	return nil
}

func mustSettle(e *event) {
	if err := settleable(e); err != nil {
		panic(err.Error())
	}
}

// mustPay checks that the call carries exactly amount ugnot and nothing else.
func mustPay(amount int64) {
	if msg := payRefusal(unsafe.OriginSend(), amount); msg != "" {
		panic(msg)
	}
}

// The refusals below are plain functions, so that tests can check each one
// without a direct call from a user, which the paying functions require.

func payRefusal(sent chain.Coins, amount int64) string {
	if amount == 0 {
		if len(sent) != 0 {
			return "send nothing: it is free"
		}
		return ""
	}
	if len(sent) != 1 || sent.AmountOf(denom) != amount {
		return "send exactly " + itoa(amount) + " " + denom
	}
	return ""
}

// fundRefusal reads what CreateEvent was sent: nothing, or the fee for a job.
func fundRefusal(sent chain.Coins) (withJob bool, msg string) {
	if len(sent) == 0 {
		return false, ""
	}
	if len(sent) == 1 && sent.AmountOf(denom) == LampFee {
		return true, ""
	}
	return false, "send nothing, or exactly " + itoa(LampFee) + " " + denom + " to have a Lamplighter job settle the event"
}

func checkEvent(name, details string, start, end, price int64, capacity, maxPerAddr int,
	markupBps, noShowBps, now int64) string {
	switch {
	case !validText(name, maxNameLen):
		return "name must be 1 to " + strconv.Itoa(maxNameLen) + " bytes of printable text"
	case details != "" && !validText(details, maxDetailsLen):
		return "details must be at most " + strconv.Itoa(maxDetailsLen) + " bytes of printable text"
	case start < now || start > now+MaxAhead:
		return "start must be between now and a year from now"
	case end-start < MinLength || end-start > MaxLength:
		return "an event lasts 1 minute to 90 days"
	case price < 0 || price > MaxPrice:
		return "price must be 0 to " + itoa(MaxPrice) + " " + denom
	case capacity < 1 || capacity > MaxCapacity:
		return "capacity must be 1 to " + strconv.Itoa(MaxCapacity)
	case maxPerAddr < 1 || maxPerAddr > capacity:
		return "maxPerAddr must be 1 to the capacity"
	case markupBps < 0 || markupBps > MaxMarkupBps:
		return "markupBps must be 0 to " + itoa(MaxMarkupBps)
	case noShowBps < 0 || noShowBps > MaxNoShowBps:
		return "noShowBps must be 0 to " + itoa(MaxNoShowBps)
	}
	return ""
}

func buyRefusal(e *event, buyer address, now int64) string {
	switch {
	case e.cancelled:
		return "the event is cancelled"
	case now >= e.end:
		return "the event is over"
	case e.live >= e.capacity:
		return "sold out"
	case held(e, buyer) >= e.maxPerAddr:
		return capMessage(e)
	}
	return ""
}

func buyListedRefusal(t *ticket, buyer address, now int64) string {
	e := t.ev
	switch {
	case !t.listed:
		return "the ticket is not for sale"
	case now < t.listedAt+ResaleDelay:
		return "the listing opens to buyers in " + itoa(t.listedAt+ResaleDelay-now) + "s"
	case buyer == ownerOf(t):
		return "this is already your ticket"
	case e.cancelled:
		return "the event is cancelled"
	case now >= e.end:
		return "the event is over"
	case held(e, buyer) >= e.maxPerAddr:
		return capMessage(e)
	}
	return ""
}

func capMessage(e *event) string {
	return "one address may hold at most " + strconv.Itoa(e.maxPerAddr) + " tickets for this event"
}

func send(cur realm, to address, amount int64) {
	// Paying an account runs no code, so this cannot call back in here.
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.Coins{{denom, amount}})
}

// held counts the tickets of an event that addr holds. It walks at most
// maxPerAddr+1 entries of the holder index, which is cheaper than storing a
// counter: every stored tree node is storage someone pays a deposit for.
func held(e *event, addr address) int {
	n := 0
	prefix := addr.String() + "/" + pad(e.id) + "-"
	byOwner.Iterate(prefix, prefix+"~", func(_ string, _ any) bool {
		n++
		return n > e.maxPerAddr
	})
	return n
}

// hold records that addr gained (+1) or lost (-1) ticket t.
func hold(e *event, addr address, t *ticket, delta int) {
	k := addr.String() + "/" + ticketKey(e.id, t.serial)
	if delta > 0 {
		byOwner.Set(k, t)
	} else {
		byOwner.Remove(k)
	}
}

func ownerOf(t *ticket) address {
	owner, err := ledger.ReadToken().OwnerOf(grc721.TokenID(t.id))
	if err != nil {
		panic(err)
	}
	return owner
}

// mustHold returns the ticket and its holder, who must be the caller.
func mustHold(cur realm, ticketID string) (*ticket, address) {
	t := mustTicket(ticketID)
	holder := ownerOf(t)
	if cur.Previous().Address() != holder {
		panic("only the holder can do this")
	}
	return t, holder
}

func mustEvent(id uint64) *event {
	e, ok := events.Get(pad(id)).(*event)
	if !ok {
		panic("unknown event " + utoa(id))
	}
	return e
}

func mustTicket(id string) *ticket {
	k, ok := keyOf(id)
	if ok {
		if t, found := tickets.Get(k).(*ticket); found {
			return t
		}
	}
	panic("unknown ticket " + strconv.Quote(id))
}

// keyOf turns a ticket id such as "3-17" into its sorted tree key.
func keyOf(id string) (string, bool) {
	ev, serial, found := strings.Cut(id, "-")
	if !found {
		return "", false
	}
	e, err1 := strconv.ParseUint(ev, 10, 64)
	s, err2 := strconv.Atoi(serial)
	if err1 != nil || err2 != nil || s < 1 {
		return "", false
	}
	return ticketKey(e, s), true
}

func ticketKey(eventID uint64, serial int) string {
	s := strconv.Itoa(serial)
	for len(s) < 5 {
		s = "0" + s
	}
	return pad(eventID) + "-" + s
}

// validText reports whether s is 1 to max bytes of valid, printable text that
// is not blank once invisible characters are stripped (the registry's rule).
func validText(s string, max int) bool {
	if s == "" || len(s) > max || !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		if r < 0x20 || (r >= 0x7f && r <= 0x9f) {
			return false
		}
	}
	return strings.TrimSpace(sanitize.StripBidiAndZeroWidth(s)) != ""
}

func pad(id uint64) string {
	s := utoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func when(t int64) string { return time.Unix(t, 0).UTC().Format("2006-01-02 15:04 UTC") }

// bps formats hundredths of a percent: 250 -> "2.5%", 5000 -> "50%".
func bps(b int64) string {
	s := itoa(b / 100)
	if r := b % 100; r != 0 {
		frac := strconv.FormatInt(r+100, 10)[1:]
		s += "." + strings.TrimRight(frac, "0")
	}
	return s + "%"
}

func utoa(n uint64) string { return strconv.FormatUint(n, 10) }
func itoa(n int64) string  { return strconv.FormatInt(n, 10) }

package admitone

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/g1zjumaghw5cgzhyj46eygvd452p6the6n56dppx/lamplighter/registry/v2"
)

const (
	perPage      = 20  // events per home page, newest first
	shownTickets = 100 // tickets on an event's door list
	shownListed  = 50  // listings on an event's resale desk
	shownHeld    = 200 // tickets on a holder's page

	// depositNote says what buying adds on top of the price. The deposit is the
	// chain's, not the organiser's: it comes back when the ticket is burned.
	depositNote = "plus a storage deposit of about 0.6 GNOT, which comes back when you refund or discard the ticket"
)

// Render serves the realm's pages:
//
//	""              the newest events
//	"page/<n>"      older events, 20 a page
//	"event/<id>"    one event: seats, risks, buying, the resale desk, the door list
//	"ticket/<id>"   one ticket, drawn, with what its holder can do
//	"u/<address>"   the tickets an address holds
func Render(path string) string {
	switch {
	case path == "":
		return renderHome(1)
	case strings.HasPrefix(path, "page/"):
		if n, err := strconv.Atoi(strings.TrimPrefix(path, "page/")); err == nil && n >= 1 {
			return renderHome(n)
		}
	case strings.HasPrefix(path, "event/"):
		id, err := strconv.ParseUint(strings.TrimPrefix(path, "event/"), 10, 64)
		if e, ok := events.Get(pad(id)).(*event); err == nil && ok {
			return renderEvent(e)
		}
	case strings.HasPrefix(path, "ticket/"):
		if k, ok := keyOf(strings.TrimPrefix(path, "ticket/")); ok {
			if t, found := tickets.Get(k).(*ticket); found {
				return renderTicket(t)
			}
		}
		return "# Ticket not found\n\nIt was never sold, or it was refunded and burned.\n\n[All events](" + home() + ")\n"
	case strings.HasPrefix(path, "u/"):
		return renderHolder(strings.TrimPrefix(path, "u/"))
	}
	return "# Not found\n\n[All events](" + home() + ")\n"
}

func renderHome(page int) string {
	now := time.Now().Unix()
	var b strings.Builder
	b.WriteString("# Admit One\n\n")
	b.WriteString("**Event tickets that pay at the door.**\n\n")
	b.WriteString("- Your ticket's price waits in this realm until you walk in. Admitting yourself at the door is what pays the organiser.\n")
	b.WriteString("- If the event is cancelled, you get everything back. If you never show up, you get it back minus a no-show fee the event states up front.\n")
	b.WriteString("- Tickets cannot be passed around privately. If you cannot go, put yours on the resale desk at no more than the capped price, and the first buyer takes it.\n\n")

	start := now + 3600
	b.WriteString("[Create an event](" + txlink.NewLink("CreateEvent").AddArgs(
		"name", "", "details", "",
		"start", itoa(start), "end", itoa(start+3*3600),
		"price", "1000000", "capacity", "20", "maxPerAddr", "2",
		"markupBps", "1000", "noShowBps", "2000").URL() + ")")
	b.WriteString(" · times are unix seconds (now: " + itoa(now) + "); attach " + gnot(LampFee) +
		" to have a [Lamplighter](" + strings.TrimPrefix(registry.Path(), "gno.land") + ") job settle it when it ends.\n\n")

	total := events.Size()
	if total == 0 {
		b.WriteString("No events yet.\n")
		return b.String()
	}
	offset := (page - 1) * perPage
	if offset >= total {
		b.WriteString("No events on page " + strconv.Itoa(page) + ". [Newest events](" + home() + ")\n")
		return b.String()
	}
	b.WriteString("## Events\n\n| # | Event | When | Price | Seats | |\n|---|---|---|---|---|---|\n")
	events.ReverseIterateByOffset(offset, perPage, func(_ string, v any) bool {
		e := v.(*event)
		b.WriteString("| " + utoa(e.id) + " | [" + sanitize.TableCell(e.name) + "](" + eventURL(e) + ") | " +
			when(e.start) + " | " + priceLabel(e.price) + " | " + strconv.Itoa(e.live) + " / " +
			strconv.Itoa(e.capacity) + " | " + status(e, now) + " |\n")
		return false
	})
	var nav []string
	if page > 1 {
		nav = append(nav, "[newer]("+pageURL(page-1)+")")
	}
	if offset+perPage < total {
		nav = append(nav, "[older]("+pageURL(page+1)+")")
	}
	if len(nav) > 0 {
		b.WriteString("\nPage " + strconv.Itoa(page) + " · " + strings.Join(nav, " · ") + "\n")
	}
	return b.String()
}

func renderEvent(e *event) string {
	now := time.Now().Unix()
	id := utoa(e.id)
	var b strings.Builder
	b.WriteString("# " + sanitize.InlineText(e.name) + "\n\n")
	if e.details != "" {
		b.WriteString(sanitize.InlineText(e.details) + "\n\n")
	}
	b.WriteString("**" + status(e, now) + "** · " + when(e.start) + " to " + when(e.end) + "\n\n")

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Price | " + priceLabel(e.price) + " |\n")
	b.WriteString("| Seats | " + strconv.Itoa(e.live) + " held of " + strconv.Itoa(e.capacity) +
		", at most " + strconv.Itoa(e.maxPerAddr) + " per address |\n")
	b.WriteString("| At the door | " + strconv.Itoa(e.entered) + " admitted |\n")
	if e.price > 0 && !e.cancelled {
		b.WriteString("| No-show fee | " + bps(e.noShowBps) + " (" + gnot(noShowFee(e)) + ") |\n")
		b.WriteString("| Resale | up to " + gnot(resaleCap(e)) + " (face + " + bps(e.markupBps) + ") |\n")
	}
	if e.price > 0 {
		b.WriteString("| In escrow | " + gnot(escrow(e)) + " |\n")
	}
	b.WriteString("| Organiser | " + e.organiser.String() + " |\n")
	if e.job != 0 {
		b.WriteString("| Settled by | [Lamplighter job " + utoa(e.job) + "](" +
			strings.TrimPrefix(registry.Path(), "gno.land") + ":job/" + utoa(e.job) + ") at the end |\n")
	}
	b.WriteString("\n")

	if e.price > 0 && !e.cancelled {
		b.WriteString("> **What a ticket risks.** The organiser cannot touch the money held for unused tickets. " +
			"If the event is cancelled, a ticket is refunded in full. If its holder never comes, they get " +
			gnot(e.price-noShowFee(e)) + " back once the event is over. If the event simply never happens and is not " +
			"cancelled, that is also what a holder gets back: the no-show fee is the only amount a buyer trusts the organiser with.\n\n")
	}

	// What can be done now.
	open := !e.cancelled && now < e.end
	switch {
	case e.cancelled:
		b.WriteString("This event was cancelled. Holders: open your ticket and refund it in full.\n\n")
	case open && e.live < e.capacity:
		link := txlink.NewLink("Buy").AddArgs("eventID", id)
		if e.price > 0 {
			link = link.SetSend(itoa(e.price) + denom)
		}
		b.WriteString("[**Buy a ticket for " + priceLabel(e.price) + "**](" + link.URL() + ") (" + depositNote + ")\n\n")
	case open:
		b.WriteString("Sold out. Watch the resale desk below.\n\n")
	case !e.settled:
		b.WriteString("The event is over. [Settle it](" + txlink.NewLink("Settle").AddArgs("eventID", id).URL() +
			"): anyone can, and it pays the organiser the no-show fees. Holders who did not come can then refund their tickets.\n\n")
	default:
		b.WriteString("The event is over and settled. Holders who did not come can refund what is left of their ticket.\n\n")
	}

	var desk, door strings.Builder
	n, listed := 0, 0
	prefix := pad(e.id) + "-"
	tickets.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		t := v.(*ticket)
		if open && t.listed {
			if listed < shownListed {
				desk.WriteString("| [" + t.id + "](" + ticketURL(t) + ") | " + priceLabel(t.listPrice) + " | " + deskAction(t, now) + " |\n")
			}
			listed++
		}
		if n < shownTickets {
			door.WriteString("| [" + t.id + "](" + ticketURL(t) + ") | " + short(ownerOf(t)) + " | " + ticketState(t, now) + " |\n")
		}
		n++
		return false
	})
	if listed > 0 {
		b.WriteString("## Resale desk\n\nA listing opens to buyers " + itoa(ResaleDelay) + " seconds after it is posted; then the first buyer takes it. " +
			"A buyer pays the listed price plus " + gnot(ResaleDeposit) + " to the seller, for the storage deposit the ticket carries, " +
			"which comes back to the buyer when the ticket is refunded or discarded.\n\n")
		b.WriteString("| Ticket | Price | |\n|---|---|---|\n" + desk.String())
		if listed > shownListed {
			b.WriteString("\n" + strconv.Itoa(listed-shownListed) + " more listings not shown.\n")
		}
		b.WriteString("\n")
	}
	if door.Len() > 0 {
		b.WriteString("## Door list\n\n| Ticket | Holder | |\n|---|---|---|\n" + door.String())
		if n > shownTickets {
			b.WriteString("\n" + strconv.Itoa(n-shownTickets) + " more not shown.\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("[All events](" + home() + ")")
	if !e.cancelled && now < e.start {
		b.WriteString(" · organiser: [cancel the event](" + txlink.NewLink("Cancel").AddArgs("eventID", id).URL() + ")")
	}
	if e.job != 0 && e.settled && !e.reclaimed {
		b.WriteString(" · organiser: [reclaim the job's deposit](" + txlink.NewLink("Reclaim").AddArgs("eventID", id).URL() + ")")
	}
	b.WriteString("\n")
	return b.String()
}

// deskAction is the resale desk's action cell for a listing.
func deskAction(t *ticket, now int64) string {
	if wait := t.listedAt + ResaleDelay - now; wait > 0 {
		return "opens in " + itoa(wait) + "s"
	}
	return "[Buy for " + gnot(t.listPrice+ResaleDeposit) + "](" + buyListedURL(t) + ")"
}

func renderTicket(t *ticket) string {
	e := t.ev
	now := time.Now().Unix()
	holder := ownerOf(t)
	var b strings.Builder
	b.WriteString("# Ticket " + t.id + "\n\n")
	b.WriteString(ticketSVG(t, now) + "\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Event | [" + sanitize.TableCell(e.name) + "](" + eventURL(e) + ") |\n")
	b.WriteString("| When | " + when(e.start) + " to " + when(e.end) + " |\n")
	b.WriteString("| Holder | [" + holder.String() + "](" + home() + ":u/" + holder.String() + ") |\n")
	b.WriteString("| State | **" + ticketState(t, now) + "** |\n")
	b.WriteString("| Face value | " + priceLabel(e.price) + " |\n\n")

	b.WriteString("For the holder:\n\n")
	var acts []string
	refund := txlink.NewLink("Refund").AddArgs("ticketID", t.id).URL()
	switch {
	case e.cancelled:
		acts = append(acts, "["+refundLabel(e.price)+"]("+refund+")")
	case t.admittedAt != 0 && now >= e.end:
		acts = append(acts, "keep it as your stamp of having been there, or [discard it]("+
			txlink.NewLink("Discard").AddArgs("ticketID", t.id).URL()+") to take back the storage deposit it locked")
	case t.admittedAt != 0:
		acts = append(acts, "nothing left to do: enjoy the event")
	case now >= e.end:
		acts = append(acts, "["+refundLabel(e.price-noShowFee(e))+"]("+refund+")")
	default:
		if now >= e.start {
			acts = append(acts, "[**Admit me**]("+txlink.NewLink("Admit").AddArgs("ticketID", t.id).URL()+") (at the door; releases the price to the organiser)")
		} else {
			acts = append(acts, "doors open "+when(e.start))
		}
		if t.listed {
			acts = append(acts, "[Take off the resale desk]("+txlink.NewLink("Unlist").AddArgs("ticketID", t.id).URL()+")")
		} else {
			acts = append(acts, "[Put on the resale desk]("+txlink.NewLink("List").AddArgs("ticketID", t.id, "price", itoa(e.price)).URL()+
				") (up to "+priceLabel(resaleCap(e))+")")
		}
	}
	for _, a := range acts {
		b.WriteString("- " + a + "\n")
	}
	if t.listed && now < e.end && !e.cancelled {
		b.WriteString("\nOn the resale desk: " + deskAction(t, now) + "\n")
	}
	return b.String()
}

func renderHolder(addr string) string {
	if !address(addr).IsValid() {
		return "# Not an address\n\n[All events](" + home() + ")\n"
	}
	now := time.Now().Unix()
	var b strings.Builder
	b.WriteString("# Tickets held by " + addr + "\n\n")
	n := 0
	prefix := addr + "/"
	b.WriteString("| Ticket | Event | When | |\n|---|---|---|---|\n")
	byOwner.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		n++
		if n > shownHeld {
			return true
		}
		t := v.(*ticket)
		b.WriteString("| [" + t.id + "](" + ticketURL(t) + ") | [" + sanitize.TableCell(t.ev.name) + "](" + eventURL(t.ev) +
			") | " + when(t.ev.start) + " | " + ticketState(t, now) + " |\n")
		return false
	})
	if n == 0 {
		return "# Tickets held by " + addr + "\n\nNone.\n\n[All events](" + home() + ")\n"
	}
	if n > shownHeld {
		b.WriteString("\nThe oldest " + strconv.Itoa(shownHeld) + " are shown.\n")
	}
	b.WriteString("\n[All events](" + home() + ")\n")
	return b.String()
}

func status(e *event, now int64) string {
	switch {
	case e.cancelled:
		return "cancelled"
	case now < e.start:
		return "on sale"
	case now < e.end:
		return "doors open"
	case e.settled:
		return "over, settled"
	default:
		return "over"
	}
}

func ticketState(t *ticket, now int64) string {
	switch {
	case t.admittedAt != 0:
		return "ADMITTED " + time.Unix(t.admittedAt, 0).UTC().Format("2006-01-02 15:04 UTC")
	case t.ev.cancelled:
		return "refundable (cancelled)"
	case now >= t.ev.end:
		return "unused"
	case t.listed:
		return "for resale at " + priceLabel(t.listPrice)
	default:
		return "valid"
	}
}

func refundLabel(amount int64) string {
	if amount == 0 {
		return "Refund (gives back its storage deposit)"
	}
	return "Refund " + gnot(amount)
}

func home() string { return strings.TrimPrefix(selfPath, "gno.land") }

func pageURL(n int) string {
	if n == 1 {
		return home()
	}
	return home() + ":page/" + strconv.Itoa(n)
}

func eventURL(e *event) string   { return home() + ":event/" + utoa(e.id) }
func ticketURL(t *ticket) string { return home() + ":ticket/" + t.id }

func buyListedURL(t *ticket) string {
	return txlink.NewLink("BuyListed").AddArgs("ticketID", t.id).SetSend(itoa(t.listPrice+ResaleDeposit) + denom).URL()
}

func priceLabel(p int64) string {
	if p == 0 {
		return "free"
	}
	return gnot(p)
}

// gnot formats ugnot as GNOT without trailing zeros.
func gnot(u int64) string {
	s := itoa(u / 1000000)
	if r := u % 1000000; r != 0 {
		frac := strconv.FormatInt(r+1000000, 10)[1:]
		s += "." + strings.TrimRight(frac, "0")
	}
	return s + " GNOT"
}

func short(a address) string {
	s := a.String()
	if len(s) < 14 {
		return s
	}
	return s[:7] + "…" + s[len(s)-4:]
}

package admitone

import (
	"encoding/base64"
	"strconv"
	"strings"
	"time"
)

// ticketSVG draws a ticket as a Markdown image (an SVG data URI, which gnoweb
// allows). The stamp across it is what whoever checks the door looks at.
func ticketSVG(t *ticket, now int64) string {
	e := t.ev
	paper, ink, accent := "#fff4d6", "#3b2a1a", "#c8372d"
	stamp, stampColor := "", ""
	switch {
	case t.admittedAt != 0:
		stamp, stampColor = "ADMITTED", "#1f8f4e"
	case e.cancelled:
		stamp, stampColor = "CANCELLED", "#b3261e"
	case now >= e.end:
		stamp, stampColor = "UNUSED", "#6b6b6b"
	case t.listed:
		stamp, stampColor = "FOR RESALE", "#1f6fb5"
	}
	if stamp != "" {
		paper = "#f3ead2"
	}

	var s strings.Builder
	s.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="640" height="300" viewBox="0 0 640 300" font-family="Georgia, serif">`)
	// Body and stub, with the notches of a ticket meant to be torn.
	s.WriteString(`<path d="M12 12 H628 V130 A20 20 0 0 0 628 170 V288 H12 V170 A20 20 0 0 0 12 130 Z" fill="` + paper + `" stroke="` + ink + `" stroke-width="3"/>`)
	s.WriteString(`<line x1="480" y1="22" x2="480" y2="278" stroke="` + ink + `" stroke-width="2" stroke-dasharray="6 6"/>`)
	s.WriteString(`<rect x="28" y="28" width="436" height="244" fill="none" stroke="` + accent + `" stroke-width="2"/>`)
	s.WriteString(text(246, 76, 40, accent, "bold", "ADMIT ONE"))
	s.WriteString(text(246, 116, 22, ink, "bold", clip(e.name, 30)))
	s.WriteString(text(246, 146, 16, ink, "normal", time.Unix(e.start, 0).UTC().Format("Mon 2 Jan 2006, 15:04 UTC")))
	s.WriteString(text(246, 174, 15, ink, "normal", priceLabel(e.price)+" · ticket "+t.id))
	if stamp != "" {
		// The stamp has a row of its own, so it never hides what is printed.
		s.WriteString(`<g transform="rotate(-5 246 228)">`)
		s.WriteString(`<rect x="106" y="200" width="280" height="56" rx="8" fill="none" stroke="` + stampColor + `" stroke-width="5"/>`)
		s.WriteString(text(246, 240, 32, stampColor, "bold", stamp))
		s.WriteString(`</g>`)
	} else {
		s.WriteString(text(246, 236, 14, ink, "italic", "show this ticket at the door"))
	}
	// The stub.
	s.WriteString(text(556, 104, 14, ink, "normal", "No."))
	s.WriteString(text(556, 162, 50, accent, "bold", strconv.Itoa(t.serial)))
	s.WriteString(text(556, 204, 12, ink, "normal", "of "+strconv.Itoa(e.capacity)))
	s.WriteString(`</svg>`)
	return "![Ticket " + t.id + "](data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(s.String())) + ")"
}

func text(x, y, size int, fill, weight, body string) string {
	return `<text x="` + strconv.Itoa(x) + `" y="` + strconv.Itoa(y) + `" font-size="` + strconv.Itoa(size) +
		`" font-weight="` + weight + `" fill="` + fill + `" text-anchor="middle">` + xmlEscape(body) + `</text>`
}

// clip shortens s to at most n runes, adding an ellipsis.
func clip(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n-1]) + "…"
}

func xmlEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// Package gnomesaver is a "set it and forget it" savings vault on Gno.land.
//
// Every deposit splits automatically: 90% stays spendable (withdrawable any
// time) and 10% goes into time-locked savings, released only after the
// depositor's chosen unlock date. There is no admin, no fee and no token —
// just native GNOT (ugnot) held by the realm itself, with all accounting
// visible on chain.
//
// Rules:
//   - Minimum deposit: 1000 ugnot (0.001 GNOT).
//   - Lock: 0-365 days per deposit (0 = 7-day default). A later deposit can
//     only extend the unlock date, never shorten it.
//   - Spendable balance: withdraw any time, any amount up to the balance.
//   - Locked savings: withdraw only after the unlock time has passed.
package gnomesaver

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

const (
	// SaveRate is the share of every deposit that goes into locked savings.
	SaveRate = 10 // percent
	// MinDeposit is the smallest accepted deposit, in ugnot.
	MinDeposit = 1000
	// MaxLockDays caps the lock a depositor can choose.
	MaxLockDays = 365
	// DefaultLockDays applies when the caller passes 0.
	DefaultLockDays = 7
	// secondsPerDay converts lock days to unix seconds.
	secondsPerDay = 86400
)

// pkgPath is this realm's on-chain path (set at deploy time).
const pkgPath = "gno.land/r/g1w5lxq7snhstdd98dt5wef4e627raayeh8htpa0/gnomesaver/v0"

var (
	spendable  = map[address]int64{} // withdrawable any time
	savings    = map[address]int64{} // locked until unlockAt
	unlockAt   = map[address]int64{} // unix seconds
	seen       = map[address]bool{}
	depositors []address

	totalSaved int64 // all locked savings currently held
	totalSpend int64 // all spendable balances currently held
	totalDep   int64 // number of deposits ever made
)

// split divides a deposit into locked savings and spendable parts.
func split(amount int64) (saved int64, spend int64) {
	saved = amount * SaveRate / 100
	return saved, amount - saved
}

// Deposit splits the sent ugnot: SaveRate% into locked savings, the rest
// into the caller's spendable balance. lockDays (0-365, 0 = 7-day default)
// sets the savings unlock date; it can only be extended, never shortened.
// Returns (saved, spendable) amounts credited by this deposit.
func Deposit(cur realm, lockDays int64) (saved int64, spend int64) {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" {
		panic("send exactly ugnot")
	}
	amount := sent[0].Amount
	if amount < MinDeposit {
		panic("deposit below minimum (1000 ugnot)")
	}
	if lockDays < 0 || lockDays > MaxLockDays {
		panic("lockDays must be 0-365")
	}
	if lockDays == 0 {
		lockDays = DefaultLockDays
	}

	caller := cur.Previous().Address()
	saved, spend = split(amount)

	if !seen[caller] {
		seen[caller] = true
		depositors = append(depositors, caller)
	}
	spendable[caller] += spend
	savings[caller] += saved
	totalSpend += spend
	totalSaved += saved
	totalDep++

	unlock := time.Now().Unix() + lockDays*secondsPerDay
	if unlock > unlockAt[caller] {
		unlockAt[caller] = unlock
	}
	return saved, spend
}

// WithdrawSpendable returns amount ugnot from the caller's spendable balance.
func WithdrawSpendable(cur realm, amount int64) {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	caller := cur.Previous().Address()
	if spendable[caller] < amount {
		panic("insufficient spendable balance")
	}
	spendable[caller] -= amount
	totalSpend -= amount
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// WithdrawSavings returns amount ugnot from the caller's locked savings.
// It aborts while the savings are still locked.
func WithdrawSavings(cur realm, amount int64) {
	if !cur.Previous().IsUserCall() {
		panic("only user-call (maketx call) accepted")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	caller := cur.Previous().Address()
	if time.Now().Unix() < unlockAt[caller] {
		panic("savings still locked")
	}
	if savings[caller] < amount {
		panic("insufficient savings balance")
	}
	savings[caller] -= amount
	totalSaved -= amount
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// BalanceOf returns (spendable, savings) for addr. Read-only.
func BalanceOf(addr address) (spend int64, save int64) {
	return spendable[addr], savings[addr]
}

// UnlockAt returns the unix timestamp after which addr may withdraw savings.
// Read-only.
func UnlockAt(addr address) int64 {
	return unlockAt[addr]
}

// Stats returns (deposits, totalSaved, totalSpendable, users). Read-only.
func Stats() (deposits int64, saved int64, spend int64, users int) {
	return totalDep, totalSaved, totalSpend, len(depositors)
}

// Leaderboard returns a text table of the top 5 savers by locked savings.
// Read-only.
func Leaderboard() string {
	type entry struct {
		addr address
		save int64
	}
	top := make([]entry, 0, 5)
	for _, d := range depositors {
		s := savings[d]
		if s <= 0 {
			continue
		}
		// Insert sorted descending, keep at most 5.
		e := entry{d, s}
		i := 0
		for i < len(top) && top[i].save >= s {
			i++
		}
		if i < 5 {
			top = append(top, entry{})
			copy(top[i+1:], top[i:])
			top[i] = e
			if len(top) > 5 {
				top = top[:5]
			}
		}
	}
	var b strings.Builder
	b.WriteString("Top savers (locked savings, ugnot):\n")
	if len(top) == 0 {
		b.WriteString("No savers yet. Be the first!\n")
		return b.String()
	}
	for i, e := range top {
		b.WriteString(strconv.Itoa(i + 1))
		b.WriteString(". ")
		b.WriteString(e.addr.String())
		b.WriteString(" — ")
		b.WriteString(strconv.FormatInt(e.save, 10))
		b.WriteString(" ugnot\n")
	}
	return b.String()
}

// Render is the gnoweb page for this realm.
func Render(_ string) string {
	dep, saved, spend, users := Stats()
	var b strings.Builder
	b.WriteString("# GnomeSaver — Set it and forget it\n\n")
	b.WriteString("A savings vault on Gno.land. Every deposit splits automatically: ")
	b.WriteString("**90% spendable** (withdraw any time) and **10% locked savings** ")
	b.WriteString("(withdrawable after your chosen unlock date). No admin, no fees, ")
	b.WriteString("no token — just native GNOT held by this realm.\n\n")
	b.WriteString("## Stats\n\n")
	b.WriteString("- Deposits: " + strconv.FormatInt(dep, 10) + "\n")
	b.WriteString("- Total locked savings: " + strconv.FormatInt(saved, 10) + " ugnot\n")
	b.WriteString("- Total spendable: " + strconv.FormatInt(spend, 10) + " ugnot\n")
	b.WriteString("- Savers: " + strconv.Itoa(users) + "\n\n")
	b.WriteString("## How to use\n\n")
	b.WriteString("```\n")
	b.WriteString("gnokey maketx call -pkgpath " + pkgPath + " \\\n")
	b.WriteString("  -func Deposit -args 7 -send 10000ugnot \\\n")
	b.WriteString("  -gas-fee 1000000ugnot -gas-wanted 5000000 \\\n")
	b.WriteString("  -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 <your-key>\n")
	b.WriteString("```\n\n")
	b.WriteString("`Deposit(lockDays)` splits your deposit 90/10 and locks the 10% for ")
	b.WriteString("`lockDays` days (0 = 7 days, max 365). `WithdrawSpendable(amount)` ")
	b.WriteString("takes back spendable funds any time; `WithdrawSavings(amount)` takes ")
	b.WriteString("back locked savings after the unlock date. Minimum deposit: 1000 ugnot.\n\n")
	b.WriteString("## Leaderboard\n\n")
	b.WriteString(Leaderboard())
	return b.String()
}

package gnomesaver

import (
	"chain"
	"testing"
	"time"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func resetState() {
	spendable = map[address]int64{}
	savings = map[address]int64{}
	unlockAt = map[address]int64{}
	seen = map[address]bool{}
	depositors = []address{}
	totalSaved = 0
	totalSpend = 0
	totalDep = 0
}

// fundRealm gives the realm real ugnot in the test VM, so withdrawals
// (banker.SendCoins) have a balance to send from. Deposit accounting
// itself only reads the OriginSend envelope.
func fundRealm() {
	testing.IssueCoins(chain.PackageAddress(pkgPath), chain.Coins{{Denom: "ugnot", Amount: 1000000000}})
}

func TestSplit(t *testing.T) {
	saved, spend := split(10000)
	uassert.Equal(t, int64(1000), saved)
	uassert.Equal(t, int64(9000), spend)

	saved, spend = split(1000)
	uassert.Equal(t, int64(100), saved)
	uassert.Equal(t, int64(900), spend)

	saved, spend = split(1005)
	uassert.Equal(t, int64(100), saved)
	uassert.Equal(t, int64(905), spend)
}

func TestDepositSplits90_10(cur realm, t *testing.T) {
	defer resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 10000}})

	saved, spend := Deposit(cross(cur), 7)
	uassert.Equal(t, int64(1000), saved)
	uassert.Equal(t, int64(9000), spend)

	sp, sv := BalanceOf(alice)
	uassert.Equal(t, int64(9000), sp)
	uassert.Equal(t, int64(1000), sv)

	dep, totSaved, totSpend, users := Stats()
	uassert.Equal(t, int64(1), dep)
	uassert.Equal(t, int64(1000), totSaved)
	uassert.Equal(t, int64(9000), totSpend)
	uassert.Equal(t, 1, users)

	// Unlock is ~7 days out.
	now := time.Now().Unix()
	u := UnlockAt(alice)
	uassert.True(t, u >= now+6*86400 && u <= now+8*86400)
}

