func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

package c4

// Package c4 holds the rules of four-in-a-row on a 7x6 board — nothing about
// players, purses or pages. A disc dropped into a column falls to the lowest
// free row; four of one colour in a line (horizontal, vertical or either
// diagonal) wins; a full board with no line is a draw.
//
// The board is a value: Play returns a new board and never mutates the one it
// was given, so a realm can keep history or replay a game without copying by
// hand. Every function here is pure, which is why the realm can be tested
// against known games move by move.

const (
	// Cols and Rows are the board's size.
	Cols = 7
	Rows = 6

	// Empty is an unoccupied cell; Red and Yellow are the two colours. Red
	// moves first.
	Empty  uint8 = 0
	Red    uint8 = 1
	Yellow uint8 = 2

	// WinLength is how many discs in a line win the game.
	WinLength = 4
)

// Board is the 42 cells, row-major from the top: index = row*Cols + col.
type Board struct {
	Cells [Rows * Cols]uint8
}

// New returns an empty board.
func New() Board {
	return Board{}
}

// Other returns the colour that moves after c.
func Other(c uint8) uint8 {
	if c == Red {
		return Yellow
	}
	return Red
}

// Name returns a short word for a colour, used by pages and JSON.
func Name(c uint8) string {
	if c == Red {
		return "red"
	}
	if c == Yellow {
		return "yellow"
	}
	return "empty"
}

// ValidColour reports whether c is one of the two disc colours.
func ValidColour(c uint8) bool {
	return c == Red || c == Yellow
}

// At reads a cell. Out-of-range coordinates read as Empty, which keeps the
// line scan below from needing bounds checks at every step.
func (b Board) At(row, col int) uint8 {
	if row < 0 || row >= Rows || col < 0 || col >= Cols {
		return Empty
	}
	return b.Cells[row*Cols+col]
}

// LandRow is the row a disc dropped into col would rest on, or -1 when the
// column is full or out of range.
func (b Board) LandRow(col int) int {
	if col < 0 || col >= Cols {
		return -1
	}
	for row := Rows - 1; row >= 0; row-- {
		if b.At(row, col) == Empty {
			return row
		}
	}
	return -1
}

// Legal returns the columns a disc can still be dropped into, left to right.
func (b Board) Legal() []int {
	out := []int{}
	for col := 0; col < Cols; col++ {
		if b.LandRow(col) >= 0 {
			out = append(out, col)
		}
	}
	return out
}

// Full reports whether every column is full.
func (b Board) Full() bool {
	for col := 0; col < Cols; col++ {
		if b.LandRow(col) >= 0 {
			return false
		}
	}
	return true
}

// Play drops a disc of colour cell into column col and returns the new board,
// the row it landed on, and an error string ("" on success). The receiver is
// untouched.
func (b Board) Play(cell uint8, col int) (Board, int, string) {
	if !ValidColour(cell) {
		return b, -1, "colour must be red or yellow"
	}
	if col < 0 || col >= Cols {
		return b, -1, "column must be between 1 and 7"
	}
	row := b.LandRow(col)
	if row < 0 {
		return b, -1, "column is full"
	}
	next := Board{}
	next.Cells = b.Cells
	next.Cells[row*Cols+col] = cell
	return next, row, ""
}

// Winner returns the colour with four in a line, the indices of those four
// cells, and whether there is one. Only the earliest line in a top-left scan
// is reported, which is all a page needs to highlight.
func (b Board) Winner() (uint8, []int, bool) {
	for row := 0; row < Rows; row++ {
		for col := 0; col < Cols; col++ {
			cell := b.At(row, col)
			if cell == Empty {
				continue
			}
			for d := 0; d < len(dirs); d++ {
				dr := dirs[d][0]
				dc := dirs[d][1]
				if b.At(row+dr, col+dc) != cell {
					continue
				}
				if b.At(row+2*dr, col+2*dc) != cell || b.At(row+3*dr, col+3*dc) != cell {
					continue
				}
				line := []int{
					row*Cols + col,
					(row+dr)*Cols + col + dc,
					(row+2*dr)*Cols + col + 2*dc,
					(row+3*dr)*Cols + col + 3*dc,
				}
				return cell, line, true
			}
		}
	}
	return Empty, []int{}, false
}

// HasWinner is Winner without the line.
func (b Board) HasWinner() bool {
	_, _, ok := b.Winner()
	return ok
}

// String encodes the board as 42 characters, row-major from the top, with
// '0' empty, '1' red and '2' yellow. It is the wire form the web UI reads.
func (b Board) String() string {
	out := make([]byte, 0, Rows*Cols)
	for i := 0; i < Rows*Cols; i++ {
		c := b.Cells[i]
		if c > Yellow {
			c = Empty
		}
		out = append(out, byte('0'+c))
	}
	return string(out)
}

// Parse reads the form String writes. Anything that is not 42 cells of 0/1/2
// is refused rather than guessed at.
func Parse(s string) (Board, string) {
	if len(s) != Rows*Cols {
		return New(), "board must be 42 characters"
	}
	b := Board{}
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '0':
			b.Cells[i] = Empty
		case '1':
			b.Cells[i] = Red
		case '2':
			b.Cells[i] = Yellow
		default:
			return New(), "board cells must be 0, 1 or 2"
		}
	}
	return b, ""
}

// dirs are the four line directions that can win: across, down, and the two
// diagonals. Reading along (0,1) and (1,0) is enough for the reverse
// directions too, because the scan starts at both ends of a line.
var dirs = [4][2]int{
	{0, 1},
	{1, 0},
	{1, 1},
	{1, -1},
}

package tavernfour

// gnoweb pages. Every page is rendered from on-chain state, so any visitor —
// player, opponent or passer-by — sees the same board at the same height.

import (
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/c4"
)

// Render dispatches gnoweb paths:
//
//	""             the tavern: open tables, games in play, the ladder
//	"game/<id>"    one table, its board, its clock and the commands it takes
//	"ladder"       every player who has sat down
//	"how"          the rules, the commands, and how the purse works
func Render(path string) string {
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome()
	case parts[0] == "how" && len(parts) == 1:
		return renderHow()
	case parts[0] == "ladder" && len(parts) == 1:
		return renderLadder()
	case parts[0] == "game" && len(parts) == 2:
		id, ok := parseUint(parts[1])
		if !ok {
			return renderNotFound(path)
		}
		return renderGame(id)
	}
	return renderNotFound(path)
}

// ------------------------------------------------------------------- home

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Tavern Four\n\n")
	b.WriteString("**Four in a row, for two, on gno.land — with a purse that settles itself.**\n\n")
	b.WriteString("A gnome chalks a board on the tavern table and puts up a stake. Someone takes ")
	b.WriteString("the other stool by matching it. They drop discs by transaction, one at a time; ")
	b.WriteString("the realm holds the pot and pays it out in the same transaction that makes the ")
	b.WriteString("fourth in a row. No one holds the money, no one can move out of turn, and every ")
	b.WriteString("board can be replayed from the first disc.\n\n")
	b.WriteString("[How it works and how to play](" + gnowebURL(RealmPath) + ":how) · ")
	b.WriteString("[The ladder](" + gnowebURL(RealmPath) + ":ladder)\n\n")

	now := runtime.ChainHeight()

	// Open tables.
	open := 0
	var rows strings.Builder
	rows.WriteString("| table | host | stake | clock | moves |\n|---|---|---|---|---|\n")
	for i := len(games) - 1; i >= 0; i-- {
		g := games[i]
		if g.Status != StatusOpen {
			continue
		}
		open++
		rows.WriteString("| [#" + uitoa(g.ID) + "](" + gameURL(g.ID) + ") | " + cell(nameOf(g.Host, g.HostName)))
		rows.WriteString(" | " + gnot(g.Stake) + " | " + itoa(g.TurnBlocks) + " blocks | — |\n")
	}
	b.WriteString("## Open tables\n\n")
	if open == 0 {
		b.WriteString("Nobody is waiting for a guest. [Open a table](" + gnowebURL(RealmPath) + ":how) ")
		b.WriteString("with a single transaction — the stake comes back if nobody sits down.\n\n")
	} else {
		b.WriteString(rows.String())
		b.WriteString("\n")
	}

	// Games in play.
	live := 0
	var liveRows strings.Builder
	liveRows.WriteString("| table | red | yellow | to move | clock | pot |\n|---|---|---|---|---|---|\n")
	for i := len(games) - 1; i >= 0; i-- {
		g := games[i]
		if g.Status != StatusLive {
			continue
		}
		live++
		liveRows.WriteString("| [#" + uitoa(g.ID) + "](" + gameURL(g.ID) + ") | " + cell(nameOf(g.Host, g.HostName)))
		liveRows.WriteString(" | " + cell(guestNameOf(g)))
		liveRows.WriteString(" | " + discName(colourForSide(g.Turn)))
		left := g.Deadline() - now
		if left < 0 {
			left = 0
		}
		liveRows.WriteString(" | " + itoa(left) + " blocks left")
		liveRows.WriteString(" | " + gnot(g.Pot()) + " |\n")
	}
	b.WriteString("## On the table\n\n")
	if live == 0 {
		b.WriteString("No game is in play right now.\n\n")
	} else {
		b.WriteString(liveRows.String())
		b.WriteString("\n")
	}

	// Recently settled.
	settled := 0
	var doneRows strings.Builder
	doneRows.WriteString("| table | red | yellow | result | moves |\n|---|---|---|---|---|\n")
	for i := len(games) - 1; i >= 0 && settled < 8; i-- {
		g := games[i]
		if g.Status != StatusFinished {
			continue
		}
		settled++
		doneRows.WriteString("| [#" + uitoa(g.ID) + "](" + gameURL(g.ID) + ") | " + cell(nameOf(g.Host, g.HostName)))
		doneRows.WriteString(" | " + cell(guestNameOf(g)))
		doneRows.WriteString(" | " + resultBadge(g))
		doneRows.WriteString(" | " + itoa(int64(len(g.Moves))) + " |\n")
	}
	if settled > 0 {
		b.WriteString("## Recently settled\n\n")
		b.WriteString(doneRows.String())
		b.WriteString("\n")
	}

	// Ladder, top five.
	b.WriteString("## The ladder\n\n")
	rowsL := Ladder()
	if len(rowsL) == 0 {
		b.WriteString("No one has finished a game yet — the first win takes the board.\n")
	} else {
		b.WriteString("| # | player | points | W-L-D | streak | won |\n|---|---|---|---|---|---|\n")
		for i := 0; i < len(rowsL) && i < 5; i++ {
			p := rowsL[i]
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + cell(nameOfP(p)) + " | " + strconv.Itoa(p.Points))
			b.WriteString(" | " + strconv.Itoa(p.Wins) + "-" + strconv.Itoa(p.Losses) + "-" + strconv.Itoa(p.Draws))
			b.WriteString(" | " + strconv.Itoa(p.Streak) + " | " + gnot(p.Won) + " |\n")
		}
		b.WriteString("\n[Full ladder](" + gnowebURL(RealmPath) + ":ladder)\n")
	}
	return b.String()
}

// ------------------------------------------------------------------- game

func renderGame(id uint64) string {
	g := GetGame(id)
	if g == nil {
		return renderNotFound("game/" + uitoa(id))
	}
	height := runtime.ChainHeight()

	var b strings.Builder
	b.WriteString("# Table #" + uitoa(g.ID) + " · " + cell(nameOf(g.Host, g.HostName)) + " vs " + cell(guestNameOf(g)) + "\n\n")
	b.WriteString(statusLine(g, height) + "\n\n")

	// Board.
	lastCol := -1
	if len(g.Moves) > 0 {
		lastCol = g.Moves[len(g.Moves)-1].Col
	}
	b.WriteString(boardTable(g.Board, g.WinLine, lastCol))
	b.WriteString("\n")
	if len(g.Moves) > 0 {
		m := g.Moves[len(g.Moves)-1]
		b.WriteString("Last disc: column " + strconv.Itoa(m.Col+1) + " by " + cell(nameOf(m.By, nameFallback(g, m.By))) +
			" at block " + itoa(m.Height) + ".\n\n")
	}

	// Money and clock.
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| purse | " + gnot(g.Pot()) + " held by the realm" + purseNote(g) + " |\n")
	b.WriteString("| stake | " + gnot(g.Stake) + " each |\n")
	b.WriteString("| seat red | " + cell(nameOf(g.Host, g.HostName)) + " `" + short(g.Host.String()) + "` |\n")
	if g.Guest != "" {
		b.WriteString("| seat yellow | " + cell(guestNameOf(g)) + " `" + short(g.Guest) + "` |\n")
	} else {
		b.WriteString("| seat yellow | *open — take it by matching the stake* |\n")
	}
	b.WriteString("| clock | " + itoa(g.TurnBlocks) + " blocks a move · now " + itoa(height))
	if g.Status == StatusLive {
		left := g.Deadline() - height
		if left < 0 {
			left = 0
		}
		b.WriteString(" · deadline " + itoa(g.Deadline()) + " (" + itoa(left) + " left)")
	}
	b.WriteString(" |\n")
	b.WriteString("| opened | block " + itoa(g.OpenedHeight) + " |\n\n")

	renderActions(&b, g, height)

	// Move list, newest first.
	if len(g.Moves) > 0 {
		b.WriteString("## Moves\n\n")
		b.WriteString("| # | colour | player | column | block |\n|---|---|---|---|---|\n")
		for i := len(g.Moves) - 1; i >= 0; i-- {
			m := g.Moves[i]
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + discName(colourOf(g, m.By)) + " | " + cell(nameOf(m.By, nameFallback(g, m.By))))
			b.WriteString(" | " + strconv.Itoa(m.Col+1) + " | " + itoa(m.Height) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("Every move is a transaction; the board above is the realm's state, not a screenshot. ")
	b.WriteString("A replayed game is in [the how page](" + gnowebURL(RealmPath) + ":how).\n")
	return b.String()
}

func renderActions(b *strings.Builder, g *Game, height int64) {
	b.WriteString("## What this table takes now\n\n")

	switch g.Status {
	case StatusOpen:
		b.WriteString("Waiting for a guest. Matching the stake takes the yellow seat and starts the game:\n\n")
		writeCmd(b, "Join", []string{uitoa(g.ID), "\"your name\""}, g.Stake)
		b.WriteString("The host can close the table and take the stake back:\n\n")
		writeCmd(b, "Cancel", []string{uitoa(g.ID)}, 0)
	case StatusLive:
		b.WriteString("It is " + discName(colourForSide(g.Turn)) + "'s turn — the player to move drops a disc into a column:\n\n")
		writeCmd(b, "Drop", []string{uitoa(g.ID), "4"}, 0)
		b.WriteString("Columns are 1-7, left to right. Open columns: " + openColumns(g.Board) + ".\n\n")
		b.WriteString("Walking away hands the pot to the other seat:\n\n")
		writeCmd(b, "Forfeit", []string{uitoa(g.ID)}, 0)
		left := g.Deadline() - height
		if left <= 0 {
			b.WriteString("**The clock has run out.** The seated player whose turn it is not can take the game:\n\n")
		} else {
			b.WriteString("If the player to move lets the clock run out (" + itoa(left) + " blocks left), the other seat can take the game:\n\n")
		}
		writeCmd(b, "ClaimTimeout", []string{uitoa(g.ID)}, 0)
	case StatusFinished:
		b.WriteString("Settled — " + resultBadge(g) + ". The pot was paid in the transaction that ended the game, ")
		b.WriteString("and the ledger row was written at the same height. Open a new table with `Open` on [the how page](" +
			gnowebURL(RealmPath) + ":how).\n")
	case StatusCancelled:
		b.WriteString("Cancelled by the host before a guest arrived; the stake went back to the host.\n")
	}
}

// ---------------------------------------------------------------- ladder

func renderLadder() string {
	var b strings.Builder
	b.WriteString("# The tavern ladder\n\n")
	b.WriteString("Points are the house's own: **3 for a win, 1 for a draw, 0 for a loss**. ")
	b.WriteString("Ties break on wins, then on fewer games played, so a short unbeaten run outranks a long ")
	b.WriteString("even one. `won` is what the purse paid this player, in ugnot.\n\n")

	rows := Ladder()
	if len(rows) == 0 {
		b.WriteString("Nobody has finished a game yet.\n")
		return b.String()
	}
	b.WriteString("| # | player | points | games | W | L | D | streak | best | won |\n|---|---|---|---|---|---|---|---|---|---|\n")
	for i := 0; i < len(rows); i++ {
		p := rows[i]
		b.WriteString("| " + strconv.Itoa(i+1) + " | " + cell(nameOfP(p)) + " | " + strconv.Itoa(p.Points))
		b.WriteString(" | " + strconv.Itoa(p.Games) + " | " + strconv.Itoa(p.Wins) + " | " + strconv.Itoa(p.Losses))
		b.WriteString(" | " + strconv.Itoa(p.Draws) + " | " + strconv.Itoa(p.Streak) + " | " + strconv.Itoa(p.BestStreak))
		b.WriteString(" | " + gnot(p.Won) + " |\n")
	}
	b.WriteString("\n[Back to the tavern](" + gnowebURL(RealmPath) + ")\n")
	return b.String()
}

// ------------------------------------------------------------------- how

func renderHow() string {
	var b strings.Builder
	b.WriteString("# How Tavern Four works\n\n")
	b.WriteString("## The rules\n\n")
	b.WriteString("- Board 7 columns wide, 6 rows high. You drop a disc into a column and it falls to the lowest free row.\n")
	b.WriteString("- Red (the host) moves first; yellow (the guest) answers. Turns alternate, one transaction each.\n")
	b.WriteString("- Four of your colour in a line — across, down, or either diagonal — wins. A full board with no line is a draw.\n")
	b.WriteString("- A move must come from the player whose turn it is. The realm refuses anything else, so a board cannot be edited by a spectator.\n")
	b.WriteString("- Each move must arrive within the table's clock, counted in blocks. Past it, the other seat may claim the game.\n\n")

	b.WriteString("## Opening a table\n\n")
	b.WriteString("The host sends exactly the stake with the call; the realm holds it until someone joins. ")
	b.WriteString("A stake of `0` opens a friendly table and moves no coins.\n\n")
	writeCmd(&b, "Open", []string{"1000000", "300", "\"Gno Tavern\""}, 1000000)
	b.WriteString("That opens a 1 GNOT table with a 300-block clock, hosted as `Gno Tavern`. The call returns ")
	b.WriteString("the table number, and the host's `1000000ugnot` is now the pot's first half.\n\n")

	b.WriteString("## Where the money lives\n\n")
	b.WriteString("Stakes are paid into the realm's own account — the address of `" + RealmPath + "`. ")
	b.WriteString("The realm keeps a running total of what it holds and pays only out of it, so one table can never ")
	b.WriteString("spend another's pot. Settlement happens in the same transaction as the winning move: there is no ")
	b.WriteString("claim step and no keeper to trust. A cancelled table returns the stake to the host; a draw returns ")
	b.WriteString("each stake.\n\n")
	b.WriteString("| moment | who acts | what the realm does |\n|---|---|---|\n")
	b.WriteString("| open | host | takes the stake into escrow, seats red |\n")
	b.WriteString("| join | guest | takes a matching stake, seats yellow, starts the clock |\n")
	b.WriteString("| move | player to move | drops the disc, checks the line, passes the turn |\n")
	b.WriteString("| win / draw | the move that ends it | pays the pot and records the ladder row, in that transaction |\n")
	b.WriteString("| timeout | the waiting seat | pays the pot after the clock runs out |\n")
	b.WriteString("| cancel | host, before a guest arrives | returns the stake |\n\n")

	b.WriteString("## Reading a board without trusting this page\n\n")
	b.WriteString("The realm exposes the board, the moves and the money as JSON:\n\n")
	b.WriteString("```\n" + RealmPath + ".GameJSON(1)\n" + RealmPath + ".LadderJSON()\n```\n\n")
	b.WriteString("`GameJSON` carries `board` as 42 characters — `0` empty, `1` red, `2` yellow, top row first — ")
	b.WriteString("so a checker can replay every move with the same rules package the realm uses.\n\n")

	b.WriteString("## Playing in a browser\n\n")
	b.WriteString("The project ships a single-file browser table (`web/index.html`) that draws this same board, ")
	b.WriteString("polls the chain and signs `Drop` with the visitor's own wallet — the realm never asks for a key. ")
	b.WriteString("`GameJSON` and `LadderJSON` above are exactly what it reads.\n\n")
	b.WriteString("[Back to the tavern](" + gnowebURL(RealmPath) + ")\n")
	return b.String()
}

// --------------------------------------------------------------- helpers

func boardTable(b c4.Board, win []int, lastCol int) string {
	var s strings.Builder
	s.WriteString("|   | 1 | 2 | 3 | 4 | 5 | 6 | 7 |\n")
	s.WriteString("|---|---|---|---|---|---|---|---|\n")
	for row := 0; row < c4.Rows; row++ {
		s.WriteString("| ")
		s.WriteString(strconv.Itoa(row + 1))
		s.WriteString(" ")
		for col := 0; col < c4.Cols; col++ {
			s.WriteString("| ")
			s.WriteString(disc(b.At(row, col), inLine(win, row*c4.Cols+col)))
			s.WriteString(" ")
		}
		s.WriteString("|\n")
	}
	// A row of arrows under the columns, marking where the last disc fell.
	s.WriteString("|   ")
	for col := 0; col < c4.Cols; col++ {
		if col == lastCol {
			s.WriteString("| ▾ ")
		} else {
			s.WriteString("|   ")
		}
	}
	s.WriteString("|\n")
	return s.String()
}

func disc(cell uint8, winning bool) string {
	glyph := "⚪"
	if cell == c4.Red {
		glyph = "🔴"
	} else if cell == c4.Yellow {
		glyph = "🟡"
	}
	if winning {
		return "**" + glyph + "**"
	}
	return glyph
}

// colourForSide maps a seat name to the disc it plays.
func colourForSide(side string) uint8 {
	if side == SeatGuest {
		return c4.Yellow
	}
	return c4.Red
}

func discName(cell uint8) string {
	if cell == c4.Red {
		return "🔴 red"
	}
	if cell == c4.Yellow {
		return "🟡 yellow"
	}
	return "—"
}

func inLine(line []int, idx int) bool {
	for i := 0; i < len(line); i++ {
		if line[i] == idx {
			return true
		}
	}
	return false
}

func statusLine(g *Game, height int64) string {
	switch g.Status {
	case StatusOpen:
		return "**Waiting for a guest** — " + gnot(g.Stake) + " on the table, " + itoa(g.TurnBlocks) + " blocks a move."
	case StatusLive:
		left := g.Deadline() - height
		if left < 0 {
			left = 0
		}
		return "**In play** — " + discName(colourForSide(g.Turn)) + " to move, " + itoa(left) + " blocks left on the clock."
	case StatusFinished:
		return "**Settled** — " + resultBadge(g)
	case StatusCancelled:
		return "**Cancelled** — the host closed the table and took the stake back."
	}
	return g.Status
}

func resultBadge(g *Game) string {
	switch g.Result {
	case ResultHost:
		return "🔴 " + cell(nameOf(g.Host, g.HostName)) + " wins"
	case ResultGuest:
		return "🟡 " + cell(guestNameOf(g)) + " wins"
	case ResultDraw:
		return "draw"
	}
	return "—"
}

func purseNote(g *Game) string {
	if g.Stake == 0 {
		return " (friendly table, no coins)"
	}
	return ""
}

func openColumns(b c4.Board) string {
	cols := b.Legal()
	if len(cols) == 0 {
		return "none — the board is full"
	}
	out := ""
	for i := 0; i < len(cols); i++ {
		if i > 0 {
			out += ", "
		}
		out += strconv.Itoa(cols[i] + 1)
	}
	return out
}

// writeCmd prints a gnokey command that does one thing on this realm.
func writeCmd(b *strings.Builder, fn string, args []string, send int64) {
	b.WriteString("```\n")
	b.WriteString("gnokey maketx call -pkgpath " + RealmPath + " -func " + fn)
	for i := 0; i < len(args); i++ {
		b.WriteString(" -args " + args[i])
	}
	b.WriteString(" \\\n  -gas-fee 1000000ugnot -gas-wanted 5000000 -broadcast \\\n")
	b.WriteString("  -chainid " + runtime.ChainID() + " -remote https://rpc." + testnetHost() + " YOUR_KEY\n")
	b.WriteString("```\n")
	if send > 0 {
		b.WriteString("*add `-send " + itoa(send) + "ugnot` — the stake goes with the call.*\n")
	}
	b.WriteString("\n")
}

func testnetHost() string {
	if runtime.ChainID() == "onyx-1" {
		return "onyx.testnets.gno.land:443"
	}
	return "rpc.gno.land:443"
}

func gnot(amount int64) string {
	if amount == 0 {
		return "0"
	}
	whole := amount / 1000000
	frac := amount % 1000000
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	f := strconv.FormatInt(frac, 10)
	for len(f) < 6 {
		f = "0" + f
	}
	for len(f) > 0 && f[len(f)-1] == '0' {
		f = f[:len(f)-1]
	}
	return strconv.FormatInt(whole, 10) + "." + f + " GNOT"
}

func nameFallback(g *Game, a address) string {
	if sideOf(g, a) == SeatGuest {
		return g.GuestName
	}
	return g.HostName
}

func nameOfP(p *Player) string {
	if p.Name != "" {
		return p.Name
	}
	return short(p.Address)
}

func short(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-6:]
}

// cell keeps a free-text field from breaking a markdown table.
func cell(s string) string {
	out := ""
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '|' {
			out += "\\|"
		} else if c == '\n' || c == '\r' {
			out += " "
		} else {
			out += string(c)
		}
	}
	return out
}

func gameURL(id uint64) string {
	return gnowebURL(RealmPath) + ":game/" + uitoa(id)
}

// gnowebURL turns a package path into the path part of its gnoweb URL by
// dropping the chain domain: gno.land/r/x/y -> /r/x/y.
func gnowebURL(pkgPath string) string {
	i := strings.Index(pkgPath, "/")
	if i < 0 {
		return "/" + pkgPath
	}
	return pkgPath[i:]
}

func renderNotFound(path string) string {
	return "# Not found\n\nNo page at `" + cell(path) + "`.\n\n[Back to the tavern](" + gnowebURL(RealmPath) + ")\n"
}

func parseUint(s string) (uint64, bool) {
	if s == "" {
		return 0, false
	}
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

// stamp is used by the docs pages: UTC and KST side by side.
func stamp(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02 15:04") + " UTC"
}

package tavernfour

// Tavern Four — four in a row for two, played on gno.land, with a purse that
// settles itself.
//
// A host opens a table with a stake and a clock (in blocks). A guest joins by
// matching the stake, and the two take turns dropping discs by transaction.
// The realm owns the board: it refuses a move from the wrong player, a drop
// into a full column, and anything sent after the game is over. When a line
// appears, or the board fills, the pot is paid out by the realm in the same
// transaction that ended the game — nobody holds the money in between.
//
// The rules themselves (the 7x6 board, gravity, the four line directions) live
// in the imported package p/.../c4 and are pure; this realm is the table, the
// clock, the purse and the pages.

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/c4"
)

const (
	// RealmPath is this realm's own path; scripts/test.sh checks it against
	// gnomod.toml so a copy of this code cannot silently change its address.
	RealmPath = "gno.land/r/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/tavernfour"
	// PackagePath is the imported rules package.
	PackagePath = "gno.land/p/g1k6cl2huxpps9fxls8tqyxknvl7fgq9hua3f2yt/c4"

	// Denom is the only coin this realm accepts. Every stake and every
	// payout is in ugnot, so a table never mixes denominations.
	Denom = "ugnot"

	// MaxStake caps a purse at 10 GNOT per player.
	MaxStake int64 = 10_000_000
	// MinTurnBlocks and MaxTurnBlocks bound the per-move clock: at the
	// testnet's few-second blocks, 20 blocks is about a minute and 2,000 is
	// a couple of hours.
	MinTurnBlocks int64 = 20
	MaxTurnBlocks int64 = 2_000

	// MaxNameLen is the longest table name, in bytes.
	MaxNameLen = 24

	// StatusOpen is a table waiting for a guest; live means both seats are
	// taken and it is somebody's turn; finished and cancelled are final.
	StatusOpen      = "open"
	StatusLive      = "live"
	StatusFinished  = "finished"
	StatusCancelled = "cancelled"

	// ResultHost, ResultGuest and ResultDraw are the three ways a game ends.
	ResultHost  = "host"
	ResultGuest = "guest"
	ResultDraw  = "draw"

	// Red moves first; the host plays red.
	HostColour = c4.Red
	GuestColour = c4.Yellow
)

// Move is one disc, written down as it happened.
type Move struct {
	By     address
	Col    int
	Row    int
	Height int64
	At     int64
}

// Game is one table.
type Game struct {
	ID        uint64
	Host      address
	// Guest is the yellow seat's address as a string, empty until somebody
	// sits down. It is a string rather than an address because a table with
	// no guest would otherwise have to store an empty address, and the VM
	// refuses to persist one ("unexpected node").
	Guest     string
	HostName  string
	GuestName string

	// Stake is what each player put in; Pot is what the realm still holds
	// for this game, which is 2*Stake until it settles.
	Stake int64
	Purse int64

	// TurnBlocks is how long the player to move has, in blocks, before the
	// other may claim the game on the clock.
	TurnBlocks int64

	Board c4.Board
	// Turn is "host", "guest" or "" — the side to move while the game is
	// live, empty otherwise. Keeping it a word rather than an address means
	// a finished game stores nothing that is not a real value.
	Turn   string
	Status string
	Result string

	Moves   []Move
	WinLine []int

	OpenedAt       int64
	StartedAt      int64
	EndedAt        int64
	OpenedHeight   int64
	LastMoveHeight int64
}

// Player is one row of the tavern ladder.
type Player struct {
	Address    string
	Name       string
	Games      int
	Wins       int
	Losses     int
	Draws      int
	Points     int
	Streak     int
	BestStreak int
	Won        int64
	LastPlayed int64
}

var (
	games   []*Game
	byID    = map[uint64]*Game{}
	nextID  uint64
	players []*Player
	byAddr  = map[string]*Player{}

	// escrow is the total the realm holds across every table. It is kept so
	// that a payout can never reach coins that belong to another game.
	escrow int64
)

// ---------------------------------------------------------------- the table

// Open seats a table. The host sends exactly their stake with the call, and
// that stake is held by the realm until a guest arrives. A stake of zero opens
// a friendly game; the realm then moves no coins at all.
func Open(cur realm, stake int64, turnBlocks int64, name string) uint64 {
	caller := callerOf(cur)
	name = cleanName(name)

	require(stake >= 0, "stake cannot be negative")
	require(stake <= MaxStake, "stake is capped at "+itoa(MaxStake)+" ugnot (10 GNOT)")
	require(turnBlocks >= MinTurnBlocks && turnBlocks <= MaxTurnBlocks,
		"turn clock must be "+itoa(MinTurnBlocks)+"-"+itoa(MaxTurnBlocks)+" blocks")

	paid := sentUgnot()
	require(paid == stake, "send exactly the stake with the call: want "+itoa(stake)+" ugnot, got "+itoa(paid))

	nextID++
	g := &Game{
		ID:           nextID,
		Host:         caller,
		HostName:     name,
		Stake:        stake,
		Purse:        paid,
		TurnBlocks:   turnBlocks,
		Board:        c4.New(),
		Status:       StatusOpen,
		Moves:        []Move{},
		WinLine:      []int{},
		OpenedAt:       nowUnix(),
		OpenedHeight:   runtime.ChainHeight(),
		LastMoveHeight: runtime.ChainHeight(),
		Turn:         SeatHost,
	}
	games = append(games, g)
	byID[g.ID] = g
	escrow += paid
	playerOf(caller, name)
	trackName(caller, name)

	chain.Emit("TableOpened", "id", uitoa(g.ID), "host", caller.String(), "stake", itoa(stake), "clock", itoa(turnBlocks))
	println("table #" + uitoa(g.ID) + " opened by " + caller.String() + " at stake " + itoa(stake))
	return g.ID
}

// Join takes the empty seat by matching the host's stake, and starts the game.
// The host (red) moves first.
func Join(cur realm, id uint64, name string) {
	caller := callerOf(cur)
	g := mustGame(id)
	name = cleanName(name)

	require(g.Status == StatusOpen, "this table is not waiting for a guest")
	require(caller != g.Host, "the host cannot take the guest seat")
	require(g.Purse == g.Stake, "the table's purse does not match its stake")

	paid := sentUgnot()
	require(paid == g.Stake, "send exactly the stake to join: want "+itoa(g.Stake)+" ugnot, got "+itoa(paid))

	g.Guest = caller.String()
	g.GuestName = name
	g.Purse += paid
	g.Status = StatusLive
	g.Turn = SeatHost
	g.StartedAt = nowUnix()
	g.LastMoveHeight = runtime.ChainHeight()
	escrow += paid
	playerOf(caller, name)
	trackName(caller, name)

	chain.Emit("TableJoined", "id", uitoa(g.ID), "guest", caller.String(), "stake", itoa(g.Stake))
	println("table #" + uitoa(g.ID) + " joined by " + caller.String() + "; red to move")
}

// Drop puts a disc in a column. Only the player whose turn it is may move, and
// only into a column that still has room.
func Drop(cur realm, id uint64, col int) {
	caller := callerOf(cur)
	g := mustGame(id)

	require(g.Status == StatusLive, "this game is not being played")
	require(sideOf(g, caller) == g.Turn, "it is not your turn")

	next, row, err := g.Board.Play(colourOf(g, caller), col)
	require(err == "", err)

	g.Board = next
	height := runtime.ChainHeight()
	g.Moves = append(g.Moves, Move{By: caller, Col: col, Row: row, Height: height, At: nowUnix()})
	g.LastMoveHeight = height

	winner, line, won := g.Board.Winner()
	if won {
		g.WinLine = line
		if winner == HostColour {
			settle(cur, g, ResultHost, "line")
		} else {
			settle(cur, g, ResultGuest, "line")
		}
		return
	}
	if g.Board.Full() {
		settle(cur, g, ResultDraw, "board full")
		return
	}
	g.Turn = otherSide(g.Turn)

	chain.Emit("DiscDropped", "id", uitoa(g.ID), "by", caller.String(), "col", itoa(int64(col)), "row", itoa(int64(row)))
	println("table #" + uitoa(g.ID) + ": column " + itoa(int64(col)) + " by " + caller.String())
}

// Forfeit hands the game to the other player. It is always allowed on your own
// turn — walking away from the table is a decision, not a stall.
func Forfeit(cur realm, id uint64) {
	caller := callerOf(cur)
	g := mustGame(id)

	require(g.Status == StatusLive, "this game is not being played")
	require(sideOf(g, caller) != "", "only a seated player can forfeit")

	if caller == g.Host {
		settle(cur, g, ResultGuest, "host forfeited")
	} else {
		settle(cur, g, ResultHost, "guest forfeited")
	}
}

// ClaimTimeout takes the game when the player to move has used up the clock.
// Anyone seated may claim, but only against the other seat: a player who has
// run out of time cannot claim against themselves.
func ClaimTimeout(cur realm, id uint64) {
	caller := callerOf(cur)
	g := mustGame(id)

	require(g.Status == StatusLive, "this game is not being played")
	side := sideOf(g, caller)
	require(side != "", "only a seated player can claim the clock")
	require(side != g.Turn, "you cannot claim the clock against yourself")

	deadline := g.LastMoveHeight + g.TurnBlocks
	require(runtime.ChainHeight() > deadline,
		"the clock has not run out yet: block "+itoa(runtime.ChainHeight())+" of "+itoa(deadline))

	if caller == g.Host {
		settle(cur, g, ResultHost, "guest ran out of time")
	} else {
		settle(cur, g, ResultGuest, "host ran out of time")
	}
}

// Cancel closes a table nobody joined and returns the host's stake.
func Cancel(cur realm, id uint64) {
	caller := callerOf(cur)
	g := mustGame(id)

	require(g.Status == StatusOpen, "only a table waiting for a guest can be cancelled")
	require(caller == g.Host, "only the host can cancel the table")

	g.Status = StatusCancelled
	g.EndedAt = nowUnix()
	refund := g.Purse
	g.Purse = 0
	pay(cur, g.Host, refund)
	escrow -= refund

	chain.Emit("TableCancelled", "id", uitoa(g.ID), "refunded", itoa(refund))
	println("table #" + uitoa(g.ID) + " cancelled; " + itoa(refund) + " ugnot returned")
}

// settle ends a game, pays the purse and writes the result down. It runs in the
// same transaction as the move that ended the game, so there is no window in
// which the pot sits waiting for someone to collect it.
func settle(cur realm, g *Game, result string, reason string) {
	g.Status = StatusFinished
	g.Result = result
	g.EndedAt = nowUnix()
	g.Turn = ""

	pot := g.Purse
	g.Purse = 0

	if pot > 0 {
		switch result {
		case ResultHost:
			pay(cur, g.Host, pot)
		case ResultGuest:
			pay(cur, address(g.Guest), pot)
		case ResultDraw:
			half := pot / 2
			pay(cur, g.Host, half)
			pay(cur, address(g.Guest), pot-half)
		}
	}
	escrow -= pot

	record(g, result)

	chain.Emit("GameSettled", "id", uitoa(g.ID), "result", result, "pot", itoa(pot), "reason", reason)
	println("table #" + uitoa(g.ID) + " settled: " + result + " (" + reason + "), pot " + itoa(pot))
}

// pay sends coins out of the realm account. Every payout is against the escrow
// the realm has already received, so a table can only ever pay out what was
// put in.
func pay(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	require(amount <= escrow, "payout exceeds the realm's escrow")
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(chain.PackageAddress(RealmPath), to, chain.NewCoins(chain.NewCoin(Denom, amount)))
}

// ---------------------------------------------------------------- the ladder

// record updates both players' rows after a finished game. Points are the
// tavern's own currency: three for a win, one for a draw, none for a loss. It
// is deliberately not an Elo rating — a board that anyone can read should not
// need a paragraph to explain its numbers.
func record(g *Game, result string) {
	host := playerOf(g.Host, g.HostName)
	guest := playerOf(address(g.Guest), g.GuestName)
	now := nowUnix()

	host.Games++
	guest.Games++
	host.LastPlayed = now
	guest.LastPlayed = now
	trackName(g.Host, g.HostName)
	trackName(address(g.Guest), g.GuestName)

	switch result {
	case ResultHost:
		host.Wins++
		host.Points += 3
		host.Streak++
		if host.Streak > host.BestStreak {
			host.BestStreak = host.Streak
		}
		host.Won += 2 * g.Stake
		guest.Losses++
		guest.Streak = 0
	case ResultGuest:
		guest.Wins++
		guest.Points += 3
		guest.Streak++
		if guest.Streak > guest.BestStreak {
			guest.BestStreak = guest.Streak
		}
		guest.Won += 2 * g.Stake
		host.Losses++
		host.Streak = 0
	case ResultDraw:
		host.Draws++
		guest.Draws++
		host.Points++
		guest.Points++
		host.Streak = 0
		guest.Streak = 0
	}
}

func playerOf(a address, name string) *Player {
	if a.String() == "" {
		return &Player{Address: ""}
	}
	key := a.String()
	p, ok := byAddr[key]
	if !ok {
		p = &Player{Address: key, Name: name}
		players = append(players, p)
		byAddr[key] = p
	}
	return p
}

func trackName(a address, name string) {
	if name == "" {
		return
	}
	p := playerOf(a, name)
	p.Name = name
}

// Ladder returns every player who has played, best first: points, then wins,
// then the smaller number of games (a 3-0 record outranks 3-3).
func Ladder() []*Player {
	out := make([]*Player, len(players))
	copy(out, players)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && ladderBefore(out[j], out[j-1]); j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func ladderBefore(a, b *Player) bool {
	if a.Points != b.Points {
		return a.Points > b.Points
	}
	if a.Wins != b.Wins {
		return a.Wins > b.Wins
	}
	return a.Games < b.Games
}

// ------------------------------------------------------------------- reads

// Escrow is every ugnot the realm holds across all tables. A settlement pays
// out of it and a cancel refunds out of it, so after the last table closes the
// number should be back to zero; anyone can read it and compare it with the
// realm's account balance on the bank.
func Escrow() int64 {
	return escrow
}

// GameCount is the number of tables ever opened.
func GameCount() int {
	return len(games)
}

// GetGame returns a game by id, or nil.
func GetGame(id uint64) *Game {
	g, ok := byID[id]
	if !ok {
		return nil
	}
	return g
}

// PlayerOf returns a ladder row by address string, or nil.
func PlayerOf(addr string) *Player {
	p, ok := byAddr[addr]
	if !ok {
		return nil
	}
	return p
}

// Pot is what the realm still holds for this game.
func (g *Game) Pot() int64 {
	return g.Purse
}

// Deadline is the block by which the player to move must have moved.
func (g *Game) Deadline() int64 {
	return g.LastMoveHeight + g.TurnBlocks
}

// -------------------------------------------------------------- game JSON

// GameJSON returns one game as JSON for the browser table. The names are
// restricted to a safe character set at entry (see cleanName), so no string
// here can need escaping beyond what cleanName already refused.
func GameJSON(id uint64) string {
	g, ok := byID[id]
	if !ok {
		return "{}"
	}

	s := "{"
	s += "\"id\":" + uitoa(g.ID)
	s += ",\"status\":\"" + g.Status + "\""
	s += ",\"result\":\"" + g.Result + "\""
	s += ",\"stake\":" + itoa(g.Stake)
	s += ",\"pot\":" + itoa(g.Purse)
	s += ",\"host\":{\"address\":\"" + g.Host.String() + "\",\"name\":\"" + g.HostName + "\"}"
	s += ",\"guest\":{\"address\":\"" + g.Guest + "\",\"name\":\"" + g.GuestName + "\"}"
	s += ",\"turn\":\"" + turnSide(g) + "\""
	s += ",\"turnAddress\":\"" + seatAddress(g, g.Turn) + "\""
	s += ",\"board\":\"" + g.Board.String() + "\""
	s += ",\"winLine\":" + intListJSON(g.WinLine)
	s += ",\"moves\":["
	for i := 0; i < len(g.Moves); i++ {
		m := g.Moves[i]
		if i > 0 {
			s += ","
		}
		s += "{\"by\":\"" + m.By.String() + "\",\"col\":" + itoa(int64(m.Col)) + ",\"row\":" + itoa(int64(m.Row)) + ",\"height\":" + itoa(m.Height) + "}"
	}
	s += "]"
	s += ",\"openedHeight\":" + itoa(g.OpenedHeight)
	s += ",\"lastMoveHeight\":" + itoa(g.LastMoveHeight)
	s += ",\"turnBlocks\":" + itoa(g.TurnBlocks)
	s += ",\"height\":" + itoa(runtime.ChainHeight())
	s += ",\"deadline\":" + itoa(g.Deadline())
	s += "}"
	return s
}

// LadderJSON returns the ladder as JSON, best first.
func LadderJSON() string {
	rows := Ladder()
	s := "["
	for i := 0; i < len(rows); i++ {
		p := rows[i]
		if i > 0 {
			s += ","
		}
		s += "{\"address\":\"" + p.Address + "\""
		s += ",\"name\":\"" + p.Name + "\""
		s += ",\"games\":" + itoa(int64(p.Games))
		s += ",\"wins\":" + itoa(int64(p.Wins))
		s += ",\"losses\":" + itoa(int64(p.Losses))
		s += ",\"draws\":" + itoa(int64(p.Draws))
		s += ",\"points\":" + itoa(int64(p.Points))
		s += ",\"streak\":" + itoa(int64(p.Streak))
		s += ",\"won\":" + itoa(p.Won)
		s += "}"
	}
	s += "]"
	return s
}

// RecentJSON lists the newest tables, newest first, for the browser lobby.
func RecentJSON(limit int) string {
	if limit <= 0 || limit > 50 {
		limit = 20
	}
	s := "["
	n := 0
	for i := len(games) - 1; i >= 0 && n < limit; i-- {
		g := games[i]
		if n > 0 {
			s += ","
		}
		s += "{\"id\":" + uitoa(g.ID)
		s += ",\"status\":\"" + g.Status + "\""
		s += ",\"host\":\"" + nameOf(g.Host, g.HostName) + "\""
		s += ",\"guest\":\"" + guestNameOf(g) + "\""
		s += ",\"stake\":" + itoa(g.Stake)
		s += ",\"result\":\"" + g.Result + "\""
		s += ",\"moves\":" + itoa(int64(len(g.Moves))) + "}"
		n++
	}
	s += "]"
	return s
}

// ---------------------------------------------------------------- internals

// callerOf is the account that signed the transaction, and the only identity a
// table accepts. It refuses any call whose immediate caller is another realm:
// a game action is a person at the table, not a contract playing on their
// behalf, because the stake and the turn would otherwise be spent by someone
// the player never authorised.
func callerOf(cur realm) address {
	require(cur.IsCurrent(), "invalid realm frame")
	require(cur.Previous().IsUserCall(), "call from a user account, not from another realm")
	require(unsafe.PreviousRealm().IsUserCall(), "call from a user account, not from another realm")
	return unsafe.OriginCaller()
}

// sentUgnot is the coin envelope of this message, refused unless it is purely
// ugnot: a stake paid in some other denom would otherwise be counted as free.
func sentUgnot() int64 {
	coins := unsafe.OriginSend()
	total := int64(0)
	for i := 0; i < len(coins); i++ {
		require(coins[i].Denom == Denom, "only "+Denom+" is accepted")
		total += coins[i].Amount
	}
	return total
}

// SeatHost and SeatGuest name the two seats wherever a seat has to be
// written down: the turn, a JSON field, an event.
const (
	SeatHost  = "host"
	SeatGuest = "guest"
)

// sideOf says which seat an address holds: "host", "guest" or "".
func sideOf(g *Game, who address) string {
	if who == g.Host {
		return SeatHost
	}
	if g.Guest != "" && who == address(g.Guest) {
		return SeatGuest
	}
	return ""
}

// seatAddress is the address in a seat, as a string, or "" for an empty seat.
func seatAddress(g *Game, side string) string {
	switch side {
	case SeatHost:
		return g.Host.String()
	case SeatGuest:
		return g.Guest
	}
	return ""
}

func colourOf(g *Game, who address) uint8 {
	if sideOf(g, who) == SeatGuest {
		return GuestColour
	}
	return HostColour
}

func otherSide(side string) string {
	if side == SeatHost {
		return SeatGuest
	}
	return SeatHost
}

// turnSide names the seat whose turn it is, for pages and JSON.
func turnSide(g *Game) string {
	if g.Status != StatusLive {
		return ""
	}
	return g.Turn
}

// guestNameOf is nameOf for the yellow seat, whose address is a string.
func guestNameOf(g *Game) string {
	if g.GuestName != "" {
		return g.GuestName
	}
	if g.Guest == "" {
		return ""
	}
	return short(g.Guest)
}

func nameOf(a address, fallback string) string {
	if fallback != "" {
		return fallback
	}
	s := a.String()
	if len(s) > 10 {
		return s[:6] + "…" + s[len(s)-4:]
	}
	return s
}

// cleanName keeps table names to printable ASCII without the characters that
// would break a markdown table or a JSON string. It is a whitelist, so any
// text a player sends either survives intact or not at all.
func cleanName(s string) string {
	s = trimSpace(s)
	if len(s) > MaxNameLen {
		s = s[:MaxNameLen]
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
			c == ' ' || c == '-' || c == '_' || c == '.' || c == '\''
		if !ok {
			panic("name may only use letters, digits, spaces and - _ . '")
		}
	}
	if s == "" {
		return "guest"
	}
	return s
}

func mustGame(id uint64) *Game {
	g, ok := byID[id]
	if !ok {
		panic("table #" + uitoa(id) + " does not exist")
	}
	return g
}

func nowUnix() int64 {
	return time.Now().Unix()
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

func uitoa(u uint64) string {
	return strconv.FormatUint(u, 10)
}

func itoa(i int64) string {
	return strconv.FormatInt(i, 10)
}

func intListJSON(xs []int) string {
	s := "["
	for i := 0; i < len(xs); i++ {
		if i > 0 {
			s += ","
		}
		s += itoa(int64(xs[i]))
	}
	return s + "]"
}

func trimSpace(s string) string {
	start := 0
	end := len(s)
	for start < end && (s[start] == ' ' || s[start] == '\t' || s[start] == '\n' || s[start] == '\r') {
		start++
	}
	for end > start && (s[end-1] == ' ' || s[end-1] == '\t' || s[end-1] == '\n' || s[end-1] == '\r') {
		end--
	}
	return s[start:end]
}

// Package tusd is the Charterbook skeleton probe's test token: "Probe Dollar"
// (PUSD), 6 decimals. Test-only, no value. It exists to check, on Onyx, that
// a GRC20 realm passes package approval and works with a fund realm.
package tusd

import (
	"strings"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const faucetAmount int64 = 50_000 * 1_000_000 // 50,000 PUSD

var (
