// Package fund is the Charterbook skeleton probe. It checks three things on
// Onyx before the real build: package approval for the imports we plan to use,
// how session keys look from inside a realm, and an escrow sub-account
// (cur.Sub) that receives a GRC20 deposit and pays it out again.
package fund

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"math/bits"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"

	"gno.land/r/g1thug63es793ckaw63l2704qzp3a92y58kekda0/cbprobe/tusd"
)

const escrowSub = "escrow"

var (
	token    *grc20.Token
	deployer address
	selfPath string
	records  = avl.NewTree() // seq -> string
	seq      int
	escrowIn int64 // internal ledger: deposited and not yet released
)

func init(cur realm) {
	token = grc20reg.MustGet(tusd.TokenKey())
	deployer = cur.Previous().Address()
	selfPath = cur.PkgPath()
}

// WhoAmI records how the caller looks from inside the realm: the origin
// caller, cur.Previous(), and runtime.GetSessionInfo(). Call it once with a
// master key and once with a session key.
func WhoAmI(cur realm) string {
	sessAddr, expires, allow, isSession := runtime.GetSessionInfo()
	line := ufmt.Sprintf("height=%d previous=%s isSession=%t sessionKey=%s expires=%d allowPaths=%s",
		runtime.ChainHeight(), cur.Previous().Address().String(),
		isSession, sessAddr.String(), expires, strings.Join(allow, ","))
	addRecord(line)
	chain.Emit("WhoAmI", "isSession", ufmt.Sprintf("%t", isSession))
	return line
}

// MasterOnly succeeds only when the transaction was signed by a master key.
func MasterOnly(cur realm) string {
	if _, _, _, isSession := runtime.GetSessionInfo(); isSession {
		panic("master key required: session keys are refused")
	}
	addRecord("MasterOnly ok from " + cur.Previous().Address().String())
	return "ok"
}

// SessionOnly succeeds only when the transaction was signed by a session key.
func SessionOnly(cur realm) string {
	sessAddr, _, _, isSession := runtime.GetSessionInfo()
	if !isSession {
		panic("session key required")
	}
	addRecord("SessionOnly ok from session " + sessAddr.String())
	return "ok"
}

// EscrowAddress is the address of the escrow sub-account.
func EscrowAddress() address {
	return chain.DerivePkgSubAddr(selfPath, escrowSub)
}

// Deposit moves amount PUSD from the caller into the escrow sub-account.
// The caller must first Approve this realm for at least amount.
func Deposit(cur realm, amount int64) {
	if amount <= 0 {
		panic("amount must be positive")
	}
	caller := cur.Previous().Address()
	escrow := cur.Sub(escrowSub).Address()
	checkErr(token.RealmTeller(0, cur).TransferFrom(0, cur, caller, escrow, amount))
	escrowIn += amount
	addRecord(ufmt.Sprintf("Deposit %d from %s to escrow %s", amount, caller.String(), escrow.String()))
}

// Release pays amount PUSD out of the escrow sub-account. Deployer only.
func Release(cur realm, to address, amount int64) {
	if cur.Previous().Address() != deployer {
		panic("deployer only")
	}
	if amount <= 0 || amount > escrowIn {
		panic("amount out of range")
	}
	sub := cur.Sub(escrowSub)
	checkErr(token.RealmTeller(0, sub).Transfer(0, sub, to, amount))
	escrowIn -= amount
	addRecord(ufmt.Sprintf("Release %d from escrow to %s", amount, to.String()))
}

// MulDiv returns floor(a*b/c) with a 128-bit intermediate, the arithmetic the
// fund will use for share and NAV calculations.
func MulDiv(a, b, c uint64) uint64 {
	if c == 0 {
		panic("division by zero")
	}
	hi, lo := bits.Mul64(a, b)
	if hi >= c {
		panic("overflow")
	}
	q, _ := bits.Div64(hi, lo, c)
	return q
}

// Hash returns the hex SHA-256 of s.
func Hash(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Charterbook skeleton probe\n\nTest realm on Onyx. Not a fund. No real value.\n\n")
	b.WriteString(ufmt.Sprintf("- Deployer: %s\n- Token: %s\n- Escrow sub-account: %s\n- Escrow balance (token ledger): %d\n- Escrow balance (internal ledger): %d\n\n## Records\n\n",
		deployer.String(), sanitize.InlineText(tusd.TokenKey()), EscrowAddress().String(), token.BalanceOf(EscrowAddress()), escrowIn))
	records.ReverseIterate("", "", func(_ string, v any) bool {
		b.WriteString("- " + sanitize.InlineText(v.(string)) + "\n")
		return false
	})
	return b.String()
}

func addRecord(s string) {
	seq++
	records.Set(ufmt.Sprintf("%06d", seq), s)
}

func checkErr(err error) {
	if err != nil {
		panic(err.Error())
	}
}

package hello_verify_b2

import "strconv"

var (
	counterB int64
	lastNote string
)

// MutateAndPanic mutates state inside hello_verify_b2 and immediately panics.
// Used in Langkah 0 (Tests B2 & B3) to verify cross-realm panic rollback and
// whether recover() or revive() in hello_verify_a2 can catch it on-chain.
func MutateAndPanic(cur realm, note string) {
	counterB++
	lastNote = note
	panic("intentional cross-realm panic from hello_verify_b2: " + note)
}

func CounterB() int64 {
	return counterB
}

func Render(path string) string {
	if path == "json/state" {
		return `{"realm":"hello_verify_b2","counterB":` + strconv.FormatInt(counterB, 10) + `,"lastNote":"` + lastNote + `"}`
	}
	return "# hello_verify_b2\n\n- counterB: `" + strconv.FormatInt(counterB, 10) + "`\n- lastNote: `" + lastNote + "`\n"
}

package hello_verify_b2

import (
	"strings"
	"testing"
)

func TestMutateAndPanic(cur realm, t *testing.T) {
	r := revive(func() {
		MutateAndPanic(cross(cur), "unit")
	})
	if r == nil {
		t.Fatalf("expected abort")
	}
	if s, ok := r.(string); !ok || !strings.Contains(s, "intentional cross-realm panic") {
		t.Fatalf("unexpected abort: %v", r)
	}
}

package hello_verify_a2

import (
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/r/g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv/hello_verify_b2"
)

var (
	realmAddr     address
	blobs         = map[string]string{}
	counterA      int64
	recoveredMsg  string
	revivedMsg    string
)

func init(cur realm) {
	realmAddr = cur.Address()
}

// WriteBlob stores a payload of `size` bytes under `key` (Test B1: storage deposit charge).
// Enforces non-payable check: OriginSend must be empty.
func WriteBlob(cur realm, key string, size int) int {
	if !cur.Previous().IsUserCall() {
		panic("must be direct EOA call")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("non-payable function: do not send coins")
	}
	if size <= 0 || size > 10000 {
		panic("size must be 1..10000")
	}
	blobs[key] = strings.Repeat("X", size)
	return len(blobs[key])
}

// DeleteBlob deletes `key` from `blobs` (Test B1: storage refund test with a 2nd account).
// Intentionally callable by any EOA in this scratch realm so we can test Account A writing
// and Account B deleting, observing who receives the storage deposit refund.
func DeleteBlob(cur realm, key string) bool {
	if !cur.Previous().IsUserCall() {
		panic("must be direct EOA call")
	}
	if len(unsafe.OriginSend()) != 0 {
		panic("non-payable function: do not send coins")
	}
	if _, ok := blobs[key]; !ok {
		panic("key not found: " + key)
	}
	delete(blobs, key)
	return true
}

// DepositMutateAndCallPanicB receives coins (-send), mutates state in A, and calls
// hello_verify_b2.MutateAndPanic (Test B2: full cross-realm rollback check).
func DepositMutateAndCallPanicB(cur realm, note string) {
	if !cur.Previous().IsUserCall() {
		panic("must be direct EOA call")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount <= 0 {
		panic("send single positive ugnot coin")
	}
	counterA++
	hello_verify_b2.MutateAndPanic(cross(cur), "b2:"+note)
}

// DepositMutateAndTryRecoverB receives coins (-send), mutates state in A, installs a
// standard Go defer/recover(), and calls hello_verify_b2.MutateAndPanic (Test B3a).
func DepositMutateAndTryRecoverB(cur realm, note string) (result string) {
	if !cur.Previous().IsUserCall() {
		panic("must be direct EOA call")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount <= 0 {
		panic("send single positive ugnot coin")
	}
	counterA++
	defer func() {
		if r := recover(); r != nil {
			recoveredMsg = "RECOVERED"
			result = "recovered"
		}
	}()
	hello_verify_b2.MutateAndPanic(cross(cur), "b3-recover:"+note)
	return "no-panic"
}

// DepositMutateAndTryReviveB receives coins (-send), mutates state in A, and tries
// Gno builtin revive() around a cross-realm call to hello_verify_b2.MutateAndPanic (Test B3b).
func DepositMutateAndTryReviveB(cur realm, note string) string {
	if !cur.Previous().IsUserCall() {
		panic("must be direct EOA call")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount <= 0 {
		panic("send single positive ugnot coin")
	}
	counterA++
	r := revive(func() {
		hello_verify_b2.MutateAndPanic(cross(cur), "b3-revive:"+note)
	})
	if r != nil {
		revivedMsg = "REVIVED"
		return "revived"
	}
	return "no-abort"
}

func Render(path string) string {
	bal := banker.NewReadonlyBanker().GetCoin(realmAddr, "ugnot")
	if path == "json/state" {
		return `{"realm":"hello_verify_a2","addr":"` + realmAddr.String() +
			`","realmUgnotBal":` + strconv.FormatInt(bal, 10) +
			`,"blobCount":` + strconv.Itoa(len(blobs)) +
			`,"counterA":` + strconv.FormatInt(counterA, 10) +
			`,"recoveredMsg":"` + recoveredMsg +
			`","revivedMsg":"` + revivedMsg + `"}`
	}
	return "# hello_verify_a2\n\n" +
		"- Realm Addr: `" + realmAddr.String() + "`\n" +
		"- Realm `ugnot` Balance: `" + strconv.FormatInt(bal, 10) + "`\n" +
		"- Blob Count: `" + strconv.Itoa(len(blobs)) + "`\n" +
		"- counterA: `" + strconv.FormatInt(counterA, 10) + "`\n" +
		"- recoveredMsg: `" + recoveredMsg + "`\n" +
		"- revivedMsg: `" + revivedMsg + "`\n"
}

package hello_verify_a2

import (
	"chain"
	"strings"
	"testing"
)

func TestA2CompileAndLocalBehavior(cur realm, t *testing.T) {
	alice := address("g1fn0l3ms5puafp37r7v67mx2msjl0ztnyq3a9yv")
	bob := address("g1syuz534wv9mugk5dnvaxvd9yxrzn05ke9dp0gq")

	// B1: Alice writes blob, Bob deletes blob
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(nil)
	n := WriteBlob(cross(cur), "k1", 2000)
	if n != 2000 || len(blobs) != 1 {
		t.Fatalf("expected blob size 2000, got %d", n)
	}
	testing.SetRealm(testing.NewUserRealm(bob))
	testing.SetOriginSend(nil)
	if !DeleteBlob(cross(cur), "k1") || len(blobs) != 0 {
		t.Fatalf("expected blob deleted")
	}

	// Non-payable guard rejects coins
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 1)))
	if r := revive(func() { WriteBlob(cross(cur), "k2", 10) }); r == nil {
		t.Fatalf("expected non-payable WriteBlob to abort when coins sent")
	}

	// B2: Cross-realm panic aborts
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin("ugnot", 500)))
	r2 := revive(func() {
		DepositMutateAndCallPanicB(cross(cur), "unit-b2")
	})
	if r2 == nil {
		t.Fatalf("expected B2 to abort")
	}

	// B3a: defer/recover() does NOT catch cross-realm panic
	r3a := revive(func() {
		DepositMutateAndTryRecoverB(cross(cur), "unit-b3a")
	})
	if r3a == nil {
		t.Fatalf("expected B3a (recover) to still abort across realm boundary")
	}
	if recoveredMsg != "" {
		t.Fatalf("expected recover() NOT to run across realm boundary, got %q", recoveredMsg)
	}

	// B3b: In local gno test mode, ReviveEnabled=true so revive() catches it (we test on onyx-1 where ReviveEnabled=false!)
	res3b := DepositMutateAndTryReviveB(cross(cur), "unit-b3b")
	if res3b != "revived" {
		t.Fatalf("expected local test mode revive() to return 'revived', got %q", res3b)
	}

	if !strings.Contains(Render("json/state"), `"realm":"hello_verify_a2"`) {
		t.Fatalf("unexpected render: %s", Render("json/state"))
	}
}

// Package latch implements a milestone escrow and micro-bounty realm on Gno.land.
// Every ugnot deposited into a deal has a deterministic exit path regardless of
// whether the client, worker, or arbiter stops responding.
package latch

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	ugnotDenom             = "ugnot"
	ugnotPerGNOT           = int64(1_000_000)
	maxDurationMinutes     = int64(525600)
	disputeWindowSeconds   = int64(7 * 86400)
	maxClaimTimeoutSeconds = int64(86400)
	minClaimTimeoutSeconds = int64(60)
	maxMilestones          = 10
	maxTitleRunes          = 80
	maxMilestoneTitleRunes = 60
	maxDeliverableRunes    = 160
	maxInt64               = int64(1<<63 - 1)
)

// DealStatus tracks the lifecycle state of an escrow deal.
type DealStatus string

const (
	DealOpen      DealStatus = "Open"
	DealActive    DealStatus = "Active"
	DealDisputed  DealStatus = "Disputed"
	DealCompleted DealStatus = "Completed"
	DealCancelled DealStatus = "Cancelled"
)

// MilestoneStatus tracks the lifecycle state of an individual milestone.
type MilestoneStatus string

const (
	MilestonePending   MilestoneStatus = "Pending"
	MilestoneSubmitted MilestoneStatus = "Submitted"
	MilestoneReleased  MilestoneStatus = "Released"
	MilestoneRefunded  MilestoneStatus = "Refunded"
)

// Milestone is one payable unit of work inside a Deal.
type Milestone struct {
	Index          int
	Title          string
	Amount         int64
	Status         MilestoneStatus
	DeliverableRef string
}

// Deal represents a multi-milestone escrow or open micro-bounty.
type Deal struct {
	ID              int
	Title           string
	Client          address
	Worker          address
	Arbiter         address
	WasOpenBounty   bool
	TotalDeposited  int64
	Remaining       int64
	CreatedAt       int64
	ClaimedAt       int64
	Deadline        int64
	DisputeDeadline int64
	Milestones      []Milestone
	Status          DealStatus
}

// ProtocolStats holds O(1) incremental counters across all deals.
type ProtocolStats struct {
	TotalDeals     int
	OpenDeals      int
	ActiveDeals    int
	DisputedDeals  int
	CompletedDeals int
	CancelledDeals int
	TotalDeposited int64
	TotalReleased  int64
	TotalRefunded  int64
}

var (
	deals      []Deal
	nextDealID = 1
	stats      ProtocolStats
)

func mustDeal(id int) *Deal {
	if id < 1 || id > len(deals) {
		panic("deal not found")
	}
	return &deals[id-1]
}

func adjustStatusCount(st DealStatus, delta int) {
	switch st {
	case DealOpen:
		stats.OpenDeals += delta
	case DealActive:
		stats.ActiveDeals += delta
	case DealDisputed:
		stats.DisputedDeals += delta
	case DealCompleted:
		stats.CompletedDeals += delta
	case DealCancelled:
		stats.CancelledDeals += delta
	}
}

func setDealStatus(d *Deal, next DealStatus) {
	if d.Status == next {
		return
	}
	if d.Status != "" {
		adjustStatusCount(d.Status, -1)
	}
	d.Status = next
	adjustStatusCount(next, 1)
}

func isBlankRune(r rune) bool {
	if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f' || r == 0x85 || r == 0xa0 || r == 0x1680 || r == 0x2028 || r == 0x2029 || r == 0x202f || r == 0x205f || r == 0x3000 {
		return true
	}
	return r >= 0x2000 && r <= 0x200a
}

func isControlOrInvisible(r rune) bool {
	if r == '\n' || r == '\r' || r == '\t' {
		return false
	}
	if r < 0x20 || r == 0x7f || (r >= 0x80 && r <= 0x9f) {
		return true
	}
	if (r >= 0x200b && r <= 0x200f) || (r >= 0x2028 && r <= 0x202e) || (r >= 0x2060 && r <= 0x206f) || r == 0xfeff {
		return true
	}
	return false
}

func validateText(raw string, maxRunes int, disallowPipe bool) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		panic("text must not be empty")
	}
	if disallowPipe && strings.Contains(trimmed, "|") {
		panic("pipe character '|' is reserved as milestone delimiter")
	}
	var clean strings.Builder
	visible := 0
	for _, r := range trimmed {
		if r == '\n' || r == '\r' || r == '\t' {
			clean.WriteByte(' ')
			continue
		}
		if isControlOrInvisible(r) {
			continue
		}
		clean.WriteRune(r)
		if !isBlankRune(r) {
			visible++
		}
	}
	if visible == 0 {
		panic("text must contain visible characters")
	}
	res := strings.TrimSpace(clean.String())
	if utf8.RuneCountInString(res) > maxRunes {
		panic("text exceeds maximum rune length")
	}
	return res
}

func parseMilestones(titlesCSV string, amountsCSV string) ([]Milestone, int64) {
	rawTitles := strings.Split(titlesCSV, "|")
	rawAmounts := strings.Split(amountsCSV, ",")
	if len(rawTitles) == 0 || len(rawTitles) > maxMilestones {
		panic("milestone count must be between 1 and 10")
	}
	if len(rawTitles) != len(rawAmounts) {
		panic("milestone titles and amounts length mismatch")
	}
	ms := make([]Milestone, len(rawTitles))
	var total int64
	for i := 0; i < len(rawTitles); i++ {
		title := validateText(rawTitles[i], maxMilestoneTitleRunes, true)
		amtStr := strings.TrimSpace(rawAmounts[i])
		amt, err := strconv.ParseInt(amtStr, 10, 64)
		if err != nil || amt <= 0 {
			panic("milestone amount must be a positive integer")
		}
		if total > maxInt64-amt {
			panic("milestone sum overflow")
		}
		total += amt
		ms[i] = Milestone{
			Index:  i,
			Title:  title,
			Amount: amt,
			Status: MilestonePending,
		}
	}
	return ms, total
}

func validateOptionalAddress(addr address, field string) {
	if addr == "" {
		return
	}
	if !addr.IsValid() {
		panic("invalid " + field + " address")
	}
}

func claimTimeoutSeconds(d *Deal) int64 {
	half := (d.Deadline - d.CreatedAt) / 2
	if half < minClaimTimeoutSeconds {
		return minClaimTimeoutSeconds
	}
	if half > maxClaimTimeoutSeconds {
		return maxClaimTimeoutSeconds
	}
	return half
}

func hasSubmittedMilestone(d *Deal) bool {
	for _, m := range d.Milestones {
		if m.Status == MilestoneSubmitted {
			return true
		}
	}
	return false
}

func hasReleasedMilestone(d *Deal) bool {
	for _, m := range d.Milestones {
		if m.Status == MilestoneReleased {
			return true
		}
	}
	return false
}

func finalizeStatus(d *Deal) {
	if d.Remaining != 0 {
		return
	}
	if hasReleasedMilestone(d) {
		setDealStatus(d, DealCompleted)
		return
	}
	setDealStatus(d, DealCancelled)
}

// -----------------------------------------------------------------------------
// Internal testable state transitions
// -----------------------------------------------------------------------------

func createDeal(
	caller address,
	realmAddr address,
	sentAmount int64,
	title string,
	worker address,
	arbiter address,
	durationMinutes int64,
	milestoneTitles string,
	milestoneAmounts string,
	now int64,
) int {
	cleanTitle := validateText(title, maxTitleRunes, false)
	if durationMinutes < 1 || durationMinutes > maxDurationMinutes {
		panic("duration must be between 1 and 525600 minutes")
	}
	validateOptionalAddress(worker, "worker")
	validateOptionalAddress(arbiter, "arbiter")
	if worker != "" && (worker == caller || worker == realmAddr) {
		panic("invalid worker address")
	}
	if arbiter != "" && (arbiter == caller || arbiter == worker || arbiter == realmAddr) {
		panic("invalid arbiter address")
	}
	ms, total := parseMilestones(milestoneTitles, milestoneAmounts)
	if sentAmount <= 0 || sentAmount != total {
		panic("attached ugnot must equal milestone sum")
	}

	status := DealOpen
	wasOpen := true
	if worker != "" {
		status = DealActive
		wasOpen = false
	}
	id := nextDealID
	nextDealID++

	deal := Deal{
		ID:             id,
		Title:          cleanTitle,
		Client:         caller,
		Worker:         worker,
		Arbiter:        arbiter,
		WasOpenBounty:  wasOpen,
		TotalDeposited: total,
		Remaining:      total,
		CreatedAt:      now,
		Deadline:       now + durationMinutes*60,
		Milestones:     ms,
	}
	deals = append(deals, deal)
	d := &deals[len(deals)-1]
	stats.TotalDeals++
	stats.TotalDeposited += total
	setDealStatus(d, status)
	return id
}

func claimDeal(caller address, dealID int, now int64) {
	d := mustDeal(dealID)
	if d.Status != DealOpen {
		panic("deal is not open")
	}
	if now >= d.Deadline {
		panic("deal deadline has passed")
	}
	if caller == d.Client || (d.Arbiter != "" && caller == d.Arbiter) {
		panic("client or arbiter cannot claim bounty")
	}
	d.Worker = caller
	d.ClaimedAt = now
	setDealStatus(d, DealActive)
}

func reclaimInactiveDeal(caller address, dealID int, now int64) {
	d := mustDeal(dealID)
	if caller != d.Client {
		panic("only client can reclaim inactive deal")
	}
	if d.Status != DealActive || !d.WasOpenBounty {
		panic("deal is not an active open bounty")
	}
	if hasSubmittedMilestone(d) || hasReleasedMilestone(d) {
		panic("cannot reclaim after worker progress")
	}
	if now < d.ClaimedAt+claimTimeoutSeconds(d) {
		panic("inactivity window has not elapsed")
	}
	d.Worker = ""
	d.ClaimedAt = 0
	setDealStatus(d, DealOpen)
}

func cancelDeal(caller address, dealID int) int64 {
	d := mustDeal(dealID)
	if caller != d.Client {
		panic("only client can cancel deal")
	}
	if d.Status != DealOpen || d.Remaining <= 0 {
		panic("only open funded deals can be cancelled")
	}
	refund := d.Remaining
	for i := range d.Milestones {
		if d.Milestones[i].Status == MilestonePending {
			d.Milestones[i].Status = MilestoneRefunded
		}
	}
	d.Remaining = 0
	stats.TotalRefunded += refund
	setDealStatus(d, DealCancelled)
	return refund
}

func submitMilestone(caller address, dealID int, milestoneIdx int, deliverableRef string, now int64) {
	d := mustDeal(dealID)
	if d.Status != DealActive {
		panic("deal is not active")
	}
	if caller != d.Worker {
		panic("only worker can submit milestone")
	}
	if now >= d.Deadline {
		panic("deal deadline has passed")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(d.Milestones) {
		panic("milestone index out of range")
	}
	m := &d.Milestones[milestoneIdx]
	if m.Status != MilestonePending && m.Status != MilestoneSubmitted {
		panic("milestone already finalized")
	}
	m.DeliverableRef = validateText(deliverableRef, maxDeliverableRunes, false)
	m.Status = MilestoneSubmitted
}

func releaseMilestone(caller address, dealID int, milestoneIdx int) (address, int64) {
	d := mustDeal(dealID)
	if d.Status != DealActive {
		panic("deal is not active")
	}
	if caller != d.Client {
		panic("only client can release milestone")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(d.Milestones) {
		panic("milestone index out of range")
	}
	m := &d.Milestones[milestoneIdx]
	if m.Status != MilestonePending && m.Status != MilestoneSubmitted {
		panic("milestone already finalized")
	}
	amt := m.Amount
	m.Status = MilestoneReleased
	d.Remaining -= amt
	stats.TotalReleased += amt
	finalizeStatus(d)
	return d.Worker, amt
}

func refundExpired(caller address, dealID int, now int64) int64 {
	d := mustDeal(dealID)
	if caller != d.Client {
		panic("only client can refund expired deal")
	}
	if d.Status != DealOpen && d.Status != DealActive {
		panic("deal cannot be refunded in current status")
	}
	if now < d.Deadline {
		panic("deadline has not passed")
	}
	var refund int64
	for i := range d.Milestones {
		m := &d.Milestones[i]
		if m.Status == MilestonePending || (m.Status == MilestoneSubmitted && d.Arbiter == "") {
			m.Status = MilestoneRefunded
			refund += m.Amount
		}
	}
	if refund <= 0 {
		panic("no refundable milestones")
	}
	d.Remaining -= refund
	stats.TotalRefunded += refund
	finalizeStatus(d)
	return refund
}

func raiseDispute(caller address, dealID int, now int64) {
	d := mustDeal(dealID)
	if d.Status != DealActive {
		panic("deal is not active")
	}
	if d.Arbiter == "" {
		panic("deal has no arbiter")
	}
	if caller != d.Client && caller != d.Worker {
		panic("only client or worker can raise dispute")
	}
	if !hasSubmittedMilestone(d) {
		panic("cannot dispute before at least one milestone is submitted")
	}
	d.DisputeDeadline = now + disputeWindowSeconds
	setDealStatus(d, DealDisputed)
}

func resolveDispute(caller address, dealID int, workerWins bool) (address, int64, address, int64) {
	d := mustDeal(dealID)
	if d.Status != DealDisputed {
		panic("deal is not disputed")
	}
	if caller != d.Arbiter {
		panic("only arbiter can resolve dispute")
	}
	var workerPayout, clientRefund int64
	for i := range d.Milestones {
		m := &d.Milestones[i]
		switch m.Status {
		case MilestonePending:
			m.Status = MilestoneRefunded
			clientRefund += m.Amount
		case MilestoneSubmitted:
			if workerWins {
				m.Status = MilestoneReleased
				workerPayout += m.Amount
			} else {
				m.Status = MilestoneRefunded
				clientRefund += m.Amount
			}
		}
	}
	d.Remaining = 0
	stats.TotalReleased += workerPayout
	stats.TotalRefunded += clientRefund
	finalizeStatus(d)
	return d.Worker, workerPayout, d.Client, clientRefund
}

func resolveDisputeTimeout(caller address, dealID int, now int64) (address, int64, address, int64) {
	d := mustDeal(dealID)
	if d.Status != DealDisputed {
		panic("deal is not disputed")
	}
	if caller != d.Client && caller != d.Worker {
		panic("only client or worker can trigger timeout fallback")
	}
	if now < d.DisputeDeadline {
		panic("dispute timeout has not elapsed")
	}
	var pendingSum, submittedSum int64
	for i := range d.Milestones {
		m := &d.Milestones[i]
		if m.Status == MilestonePending {
			m.Status = MilestoneRefunded
			pendingSum += m.Amount
		} else if m.Status == MilestoneSubmitted {
			submittedSum += m.Amount
		}
	}
	workerPayout := submittedSum / 2
	clientRefund := pendingSum + (submittedSum - workerPayout)
	for i := range d.Milestones {
		if d.Milestones[i].Status == MilestoneSubmitted {
			if workerPayout > 0 {
				d.Milestones[i].Status = MilestoneReleased
			} else {
				d.Milestones[i].Status = MilestoneRefunded
			}
		}
	}
	d.Remaining = 0
	stats.TotalReleased += workerPayout
	stats.TotalRefunded += clientRefund
	finalizeStatus(d)
	return d.Worker, workerPayout, d.Client, clientRefund
}

// -----------------------------------------------------------------------------
// Security guards & exported crossing entrypoints
// -----------------------------------------------------------------------------

func requireDirectUserCall(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user calls only")
	}
	return cur.Previous().Address()
}

func rejectAttachedCoins() {
	if len(unsafe.OriginSend()) != 0 {
		panic("no coins accepted")
	}
}

func sendUgnot(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), to, chain.NewCoins(chain.NewCoin(ugnotDenom, amount)),
	)
}

// CreateDeal creates a new funded deal or open micro-bounty and returns its ID.
func CreateDeal(
	cur realm,
	title string,
	worker address,
	arbiter address,
	durationMinutes int64,
	milestoneTitles string,
	milestoneAmounts string,
) int {
	caller := requireDirectUserCall(cur)
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != ugnotDenom || sent[0].Amount <= 0 {
		panic("attach exactly one ugnot payment")
	}
	return createDeal(
		caller, cur.Address(), sent[0].Amount,
		title, worker, arbiter, durationMinutes,
		milestoneTitles, milestoneAmounts, time.Now().Unix(),
	)
}

// ClaimDeal assigns the caller as worker on an open micro-bounty.
func ClaimDeal(cur realm, dealID int) {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	claimDeal(caller, dealID, time.Now().Unix())
}

// ReclaimInactiveDeal lets the client unassign an inactive claimer on an open bounty.
func ReclaimInactiveDeal(cur realm, dealID int) {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	reclaimInactiveDeal(caller, dealID, time.Now().Unix())
}

// CancelDeal refunds an unclaimed open deal to the client and returns refunded ugnot.
func CancelDeal(cur realm, dealID int) int64 {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	refund := cancelDeal(caller, dealID)
	sendUgnot(cur, caller, refund)
	return refund
}

// SubmitMilestone attaches a deliverable reference to a pending or submitted milestone.
func SubmitMilestone(cur realm, dealID int, milestoneIdx int, deliverableRef string) {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	submitMilestone(caller, dealID, milestoneIdx, deliverableRef, time.Now().Unix())
}

// ReleaseMilestone pays a milestone out to the worker and returns released ugnot.
func ReleaseMilestone(cur realm, dealID int, milestoneIdx int) int64 {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	worker, amt := releaseMilestone(caller, dealID, milestoneIdx)
	sendUgnot(cur, worker, amt)
	return amt
}

// RefundExpired refunds eligible milestones after deadline and returns refunded ugnot.
func RefundExpired(cur realm, dealID int) int64 {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	refund := refundExpired(caller, dealID, time.Now().Unix())
	sendUgnot(cur, caller, refund)
	return refund
}

// RaiseDispute freezes an active arbiter-backed deal with >=1 submitted milestone.
func RaiseDispute(cur realm, dealID int) {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	raiseDispute(caller, dealID, time.Now().Unix())
}

// ResolveDispute settles a disputed deal by arbiter decision.
func ResolveDispute(cur realm, dealID int, workerWins bool) (int64, int64) {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	worker, workerPayout, client, clientRefund := resolveDispute(caller, dealID, workerWins)
	sendUgnot(cur, worker, workerPayout)
	sendUgnot(cur, client, clientRefund)
	return workerPayout, clientRefund
}

// ResolveDisputeTimeout settles a disputed deal 50/50 on submitted milestones after 7 days.
func ResolveDisputeTimeout(cur realm, dealID int) (int64, int64) {
	caller := requireDirectUserCall(cur)
	rejectAttachedCoins()
	worker, workerPayout, client, clientRefund := resolveDisputeTimeout(caller, dealID, time.Now().Unix())
	sendUgnot(cur, worker, workerPayout)
	sendUgnot(cur, client, clientRefund)
	return workerPayout, clientRefund
}

// -----------------------------------------------------------------------------
// Read-only JSON export for vm/qeval
// -----------------------------------------------------------------------------

func escapeJSON(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if r < 0x20 {
				continue
			}
			b.WriteRune(r)
		}
	}
	return b.String()
}

// ExportDealsJSON returns protocol stats and paginated deals (newest first) as JSON.
func ExportDealsJSON(offset int, limit int) string {
	if offset < 0 {
		offset = 0
	}
	if limit < 1 {
		limit = 20
	}
	if limit > 50 {
		limit = 50
	}
	var b strings.Builder
	b.WriteString(`{"stats":{`)
	b.WriteString(`"totalDeals":` + strconv.Itoa(stats.TotalDeals))
	b.WriteString(`,"openDeals":` + strconv.Itoa(stats.OpenDeals))
	b.WriteString(`,"activeDeals":` + strconv.Itoa(stats.ActiveDeals))
	b.WriteString(`,"disputedDeals":` + strconv.Itoa(stats.DisputedDeals))
	b.WriteString(`,"completedDeals":` + strconv.Itoa(stats.CompletedDeals))
	b.WriteString(`,"cancelledDeals":` + strconv.Itoa(stats.CancelledDeals))
	b.WriteString(`,"totalDeposited":` + strconv.FormatInt(stats.TotalDeposited, 10))
	b.WriteString(`,"totalReleased":` + strconv.FormatInt(stats.TotalReleased, 10))
	b.WriteString(`,"totalRefunded":` + strconv.FormatInt(stats.TotalRefunded, 10))
	b.WriteString(`},"total":` + strconv.Itoa(len(deals)) + `,"deals":[`)

	total := len(deals)
	emitted := 0
	for i := total - 1 - offset; i >= 0 && emitted < limit; i-- {
		d := deals[i]
		if emitted > 0 {
			b.WriteByte(',')
		}
		emitted++
		b.WriteString(`{"id":` + strconv.Itoa(d.ID))
		b.WriteString(`,"title":"` + escapeJSON(d.Title) + `"`)
		b.WriteString(`,"client":"` + string(d.Client) + `"`)
		b.WriteString(`,"worker":"` + string(d.Worker) + `"`)
		b.WriteString(`,"arbiter":"` + string(d.Arbiter) + `"`)
		if d.WasOpenBounty {
			b.WriteString(`,"wasOpenBounty":true`)
		} else {
			b.WriteString(`,"wasOpenBounty":false`)
		}
		b.WriteString(`,"totalDeposited":` + strconv.FormatInt(d.TotalDeposited, 10))
		b.WriteString(`,"remaining":` + strconv.FormatInt(d.Remaining, 10))
		b.WriteString(`,"createdAt":` + strconv.FormatInt(d.CreatedAt, 10))
		b.WriteString(`,"claimedAt":` + strconv.FormatInt(d.ClaimedAt, 10))
		b.WriteString(`,"deadline":` + strconv.FormatInt(d.Deadline, 10))
		b.WriteString(`,"disputeDeadline":` + strconv.FormatInt(d.DisputeDeadline, 10))
		b.WriteString(`,"status":"` + string(d.Status) + `"`)
		b.WriteString(`,"milestones":[`)
		for j, m := range d.Milestones {
			if j > 0 {
				b.WriteByte(',')
			}
			b.WriteString(`{"index":` + strconv.Itoa(m.Index))
			b.WriteString(`,"title":"` + escapeJSON(m.Title) + `"`)
			b.WriteString(`,"amount":` + strconv.FormatInt(m.Amount, 10))
			b.WriteString(`,"status":"` + string(m.Status) + `"`)
			b.WriteString(`,"deliverableRef":"` + escapeJSON(m.DeliverableRef) + `"}`)
		}
		b.WriteString(`]}`)
	}
	b.WriteString(`]}`)
	return b.String()
}

