func TestValidationOverflowAndSanitization(t *testing.T) {
	// Invalid addresses & role collisions.
	mustPanic(t, "invalid worker addr", func() {
		createDeal(alice, realmAddr, 100, "Bad", address("not-bech32"), "", 60, "M0", "100", baseNow)
	})
