	})

	// ClaimDeal with 0 coins succeeds.
	testing.SetOriginSend(nil)
	ClaimDeal(cross(cur), id)

	// Non-EOA code realm caller must panic.
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/attacker/proxy"))
	mustAbort(t, "non-EOA rejected", func() {
		SubmitMilestone(cross(cur), id, 0, "https://github.com/org/repo/pull/1")
	})

	// Bob submits and Alice releases via real banker.SendCoins.
	testing.SetRealm(testing.NewUserRealm(bob))
	testing.SetOriginSend(nil)
	SubmitMilestone(cross(cur), id, 0, "https://github.com/org/repo/pull/99")

	ro := banker.NewReadonlyBanker()
	bobBefore := ro.GetCoin(bob, ugnotDenom)

	testing.SetRealm(testing.NewUserRealm(alice))
	testing.SetOriginSend(nil)
	paid := ReleaseMilestone(cross(cur), id, 0)
	if paid != 1_000_000 {
		t.Fatalf("expected paid 1000000, got %d", paid)
	}
	bobAfter := ro.GetCoin(bob, ugnotDenom)
	if bobAfter-bobBefore != 1_000_000 {
		t.Fatalf("expected bob balance +1000000, got %d", bobAfter-bobBefore)
	}

	// Render shows the created deal id.
	out := Render("deal/" + strconv.Itoa(id))
	if !strings.Contains(out, "Crossing live test") {
		t.Fatalf("expected crossing deal in Render, got %s", out)
	}
}

package latch

import (
	"net/url"
	"strconv"
	"strings"
)

const (
	renderPageSize = 6
)

// sanitizeInline neutralizes user-supplied text for safe Markdown inline/table
// output. Truncation happens BEFORE backslash-escaping so a cut never leaves a
// dangling trailing escape character.
func sanitizeInline(s string, maxRunes int) string {
	var folded strings.Builder
	runes := 0
	truncated := false
	for _, r := range s {
		if r == '\n' || r == '\r' || r == '\u0085' || r == '\u2028' || r == '\u2029' {
			if runes >= maxRunes {
				truncated = true
				break
			}
			folded.WriteByte(' ')
			runes++
			continue
		}
		if isControlOrInvisible(r) {
			continue
		}
		if runes >= maxRunes {
			truncated = true
			break
		}
		folded.WriteRune(r)
		runes++
	}
	var out strings.Builder
	for _, r := range folded.String() {
		switch r {
		case '\\', '`', '*', '_', '[', ']', '(', ')', '<', '>', '#', '!', '|', '~':
			out.WriteByte('\\')
		}
		out.WriteRune(r)
	}
	if truncated {
		out.WriteString("...")
	}
	return out.String()
}

func formatGNOT(ugnot int64) string {
	whole := ugnot / ugnotPerGNOT
	frac := ugnot % ugnotPerGNOT
	if frac < 0 {
		frac = -frac
	}
	if frac == 0 {
		return strconv.FormatInt(whole, 10) + " GNOT"
	}
	fracStr := strconv.FormatInt(frac, 10)
	for len(fracStr) < 6 {
		fracStr = "0" + fracStr
	}
	fracStr = strings.TrimRight(fracStr, "0")
	return strconv.FormatInt(whole, 10) + "." + fracStr + " GNOT"
}

func shortAddr(a address) string {
	s := string(a)
	if s == "" {
		return "Open (unclaimed)"
	}
	if len(s) <= 16 {
		return s
	}
	return s[:8] + "..." + s[len(s)-6:]
}

func parsePage(rawPath string, totalPages int) int {
	if totalPages <= 0 {
		return 1
	}
	page := 1
	if u, err := url.Parse(rawPath); err == nil {
		if raw := u.Query().Get("page"); raw != "" {
			if n, err := strconv.Atoi(raw); err == nil {
				page = n
			}
		}
	}
	if page < 1 {
		page = 1
	}
	if page > totalPages {
		page = totalPages
	}
	return page
}

func parseDealRoute(rawPath string) (int, bool) {
	u, err := url.Parse(rawPath)
	if err != nil {
		return 0, false
	}
	p := strings.Trim(u.Path, "/")
	if !strings.HasPrefix(p, "deal/") {
		return 0, false
	}
	idStr := strings.TrimPrefix(p, "deal/")
	if idStr == "" || strings.Contains(idStr, "/") {
		return 0, false
	}
	id, err := strconv.Atoi(idStr)
	if err != nil || id < 1 || id > len(deals) {
		return 0, false
	}
	return id, true
}

func renderDealDetail(id int) string {
	d := mustDeal(id)
	var b strings.Builder
	b.WriteString("# Latch Deal #" + strconv.Itoa(d.ID) + ": " + sanitizeInline(d.Title, maxTitleRunes) + "\n\n")
	b.WriteString("[<- All Deals](?) \n\n")
	b.WriteString("- **Status:** " + string(d.Status) + "\n")
	b.WriteString("- **Escrow:** " + formatGNOT(d.Remaining) + " remaining of " + formatGNOT(d.TotalDeposited) + "\n")
	b.WriteString("- **Client:** `" + string(d.Client) + "`\n")
	b.WriteString("- **Worker:** `" + shortAddr(d.Worker) + "`\n")
	if d.Arbiter == "" {
		b.WriteString("- **Arbiter:** None *(Note: no-arbiter deals allow client post-deadline refund of submitted work)*\n")
	} else {
		b.WriteString("- **Arbiter:** `" + string(d.Arbiter) + "` *(chosen by client at creation)*\n")
	}
	b.WriteString("- **Deadline (Unix):** `" + strconv.FormatInt(d.Deadline, 10) + "`\n")
	if d.DisputeDeadline > 0 {
		b.WriteString("- **Dispute Timeout (Unix):** `" + strconv.FormatInt(d.DisputeDeadline, 10) + "`\n")
	}

	b.WriteString("\n## Milestones\n\n")
	b.WriteString("| # | Title | Amount | Status | Deliverable |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for _, m := range d.Milestones {
		ref := "-"
		if m.DeliverableRef != "" {
			ref = sanitizeInline(m.DeliverableRef, maxDeliverableRunes)
		}
		b.WriteString("| " + strconv.Itoa(m.Index) +
			" | " + sanitizeInline(m.Title, maxMilestoneTitleRunes) +
			" | " + formatGNOT(m.Amount) +
			" | " + string(m.Status) +
			" | " + ref + " |\n")
	}
	b.WriteString("\n---\n")
	b.WriteString("Use **Actions** (`$help`) to call `ClaimDeal`, `ReclaimInactiveDeal`, `SubmitMilestone`, `ReleaseMilestone`, `RaiseDispute`, `ResolveDispute`, `ResolveDisputeTimeout`, `RefundExpired`, or `CancelDeal`.\n")
	return b.String()
}

// Render displays the gnoweb markdown interface for Latch.
func Render(path string) string {
	if id, ok := parseDealRoute(path); ok {
		return renderDealDetail(id)
	}

	var b strings.Builder
	b.WriteString("# Latch — Milestone Escrow & Micro-Bounties\n\n")
	b.WriteString("**Deals:** " + strconv.Itoa(stats.TotalDeals) +
		" | **Open:** " + strconv.Itoa(stats.OpenDeals) +
		" | **Active:** " + strconv.Itoa(stats.ActiveDeals) +
		" | **Disputed:** " + strconv.Itoa(stats.DisputedDeals) +
		" | **Completed:** " + strconv.Itoa(stats.CompletedDeals) +
		" | **Cancelled:** " + strconv.Itoa(stats.CancelledDeals) +
		" | **Deposited:** " + formatGNOT(stats.TotalDeposited) +
		" | **Released:** " + formatGNOT(stats.TotalReleased) +
		" | **Refunded:** " + formatGNOT(stats.TotalRefunded) + "\n\n")

	total := len(deals)
	if total == 0 {
		b.WriteString("_No deals created yet._ Use `CreateDeal` in **Actions** (`$help&func=CreateDeal`) to fund the first milestone deal.\n")
		return b.String()
	}

	totalPages := (total + renderPageSize - 1) / renderPageSize
	page := parsePage(path, totalPages)
	offset := (page - 1) * renderPageSize

	b.WriteString("## Deals (Page " + strconv.Itoa(page) + " of " + strconv.Itoa(totalPages) + ")\n\n")
	b.WriteString("| ID | Title | Status | Remaining | Worker | Arbiter |\n")
	b.WriteString("|---|---|---|---|---|---|\n")

	emitted := 0
	for i := total - 1 - offset; i >= 0 && emitted < renderPageSize; i-- {
		d := deals[i]
		emitted++
		arb := "None"
		if d.Arbiter != "" {
			arb = "`" + shortAddr(d.Arbiter) + "`"
		}
		idStr := strconv.Itoa(d.ID)
		b.WriteString("| [#" + idStr + "](:deal/" + idStr + ")" +
			" | " + sanitizeInline(d.Title, maxTitleRunes) +
			" | " + string(d.Status) +
			" | " + formatGNOT(d.Remaining) +
			" | `" + shortAddr(d.Worker) + "`" +
			" | " + arb + " |\n")
	}

	if totalPages > 1 {
		b.WriteString("\n")
		if page > 1 {
			b.WriteString("[<- Previous](?page=" + strconv.Itoa(page-1) + ") ")
		}
		if page < totalPages {
			b.WriteString("[Next ->](?page=" + strconv.Itoa(page+1) + ")")
		}
		b.WriteString("\n")
	}
	return b.String()
}

// Package engine is the "art as code" contract, version 2 (design §5.2,
// mainnet plan §2.3): what an engine implements, what core hands it, and
// the conformance rules both core and engine authors check against.
//
// v2 adds media engines (uploaded raster/IPFS art that core itself can
// serve as TokenURI), per-collection trait types and a launch gate. Input,
// Trait, SampleInput and SampleSeed are byte-for-byte the v1 definitions,
// so an engine's sample fingerprint does not move when it is re-issued
// against v2.
//
// An engine is registered from its own /r/ adapter realm. Because the
// adapter's methods are declared in that realm, core calling them runs the
// engine with the adapter's authority, never core's (interrealm v2 borrow
// rule #1). Methods receive and return plain values only: an engine never
// gets a reference into core state.
package engine

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
)

// Input is everything an engine may depend on. The first eight fields are
// v1's; Salt and FirstOwner were added in the core-final round
// (2026-11-12). Core fills them only on a token read (TokenURI, TokenCard,
// TokenTraits, …) of a Final collection; RenderWith, RenderWithInput and
// the registration sample leave them "" (so no fingerprint moves).
type Input struct {
	Seed           string // 64-hex final seed (sample seeds in Studio)
	Params         string // collection params, in the engine's own format
	CollectionID   string
	TokenID        string
	MintHeight     int64
	LastMoveHeight int64 // patina: holding time = Height - LastMoveHeight
	Moves          int64 // transfers so far
	Height         int64 // height of the read (fixed by Verify)
	// Salt is the collection's final salt (64 hex; Seed = safe.Seed(cid,
	// tid, Salt)), so a collection-level engine needs no read-back of core.
	Salt string
	// FirstOwner is the address the token was minted to (a sale mint or a
	// creator reserve); it never changes, whoever holds the token now.
	FirstOwner address
}

type Trait struct {
	Type, Value string
}

// Engine kinds (Manifest.Kind).
const (
	// KindSVG: Render is the token's art (an allowlisted SVG).
	KindSVG = "svg"
	// KindMedia: Media is the token's art (a checked raster/SVG file or an
	// ipfs:// CIDv1); Render is the token's "card", an allowlisted SVG that
	// SVG-only clients and gnoweb show.
	KindMedia = "media"
)

type Manifest struct {
	Name, Version, Description, License string
	Author                              address // proven by core.ClaimEngine
	ParamsSchema                        string  // JSON Schema subset; Studio builds its form from it
	// TraitTypes is the engine's default trait list. A collection uses
	// TraitTypes(params), stored by core at CreateCollection when it
	// differs; static engines return this list there.
	TraitTypes  []string
	Living      bool  // Render depends on LastMoveHeight/Moves/Height
	MaxSVGBytes int64 // <= MaxSVGBytes; for a media engine the card's cap
	// FeeBps is the author's fee on every primary and secondary sale of a
	// collection that uses this engine, 0..MaxFeeBps. It is fixed at
	// registration; core snapshots it per collection at Launch, caps it by
	// the platform's engine-fee cap and waives it when the collection's
	// creator is the author.
	FeeBps int64
	// Kind is KindSVG or KindMedia (required).
	Kind string
	// MaxMediaBytes caps Media.Data of a media engine: 1..MaxMediaBytes.
	// 0 for an SVG engine.
	MaxMediaBytes int64
}

// Media is a media engine's art for one token. Exactly one of Data and URI
// is set. Data is the raw file (not base64) as a Go string: strings are
// immutable, so core can check and encode it without copying and without
// the engine being able to change it afterwards.
type Media struct {
	Mime   string // MimePNG | MimeWebP | MimeJPEG | MimeSVG
	Data   string // on-chain bytes, or ""
	URI    string // "ipfs://<CIDv1>" when Data is ""
	Sha256 string // lower-case hex of sha256(file); required with Data, optional with URI
}

// IsZero reports an empty Media (what an SVG engine returns).
func (m Media) IsZero() bool {
	return m.Mime == "" && m.Data == "" && m.URI == "" && m.Sha256 == ""
}

// Engine is implemented by a stateless value declared in the adapter realm.
//
// Contract: deterministic in its arguments; ValidateParams("") must accept
// the engine's defaults; Render returns raw SVG (core does the base64);
// Traits only uses types listed in TraitTypes(params), each at most once.
//
// Where core runs engine code (I-12/I-16): every read; and on a
// state-changing path only in the engine user's own transaction —
// RegisterEngine (Manifest, ValidateParams(""), Render and Traits of the
// sample), CreateCollection (ValidateParams, TraitTypes) and Launch
// (CheckLaunch). Core never hands an engine its cur.
type Engine interface {
	Manifest() Manifest
	ValidateParams(params string) error
	// TraitTypes is the trait list of a collection created with params
	// (already accepted by ValidateParams). Static engines return
	// Manifest().TraitTypes.
	TraitTypes(params string) []string
	// CheckLaunch is the engine's launch gate: an error aborts core.Launch
	// (e.g. an upload collection without a bound store, T14). Everything it
	// needs is passed in; nil for generative engines.
	CheckLaunch(cid, params string, maxSupply int64) error
	Traits(in Input) []Trait
	// Render is the token's art (KindSVG) or its card (KindMedia).
	Render(in Input) string
	// Media is the token's art for KindMedia; Media{} for KindSVG.
	Media(in Input) Media
}

// Limits core enforces on every engine.
const (
	MaxSVGBytes     = 65536
	MaxTraits       = 32
	MaxTraitLen     = 64
	MaxNameLen      = 64
	MaxVersionLen   = 32
	MaxDescLen      = 1024
	MaxLicenseLen   = 64
	MaxParamsSchema = 4096
	MaxFeeBps       = 500 // 5%: hard cap of an engine author's fee

	// Media limits (I-15).
	MaxMediaBytes    = 262144 // on-chain raster per token
	MaxMediaSVGBytes = 16384  // on-chain SVG served as media (AssertSVG cost)
	MaxDim           = 4096   // px per side, decompression-bomb guard
)

// Media types core serves (GIF is refused, uploads D5).
const (
	MimeSVG  = "image/svg+xml"
	MimePNG  = "image/png"
	MimeWebP = "image/webp"
	MimeJPEG = "image/jpeg"
)

// IPFSScheme prefixes Media.URI.
const IPFSScheme = "ipfs://"

// SampleInput is the fixed input of an engine's fingerprint: core renders it
// at registration and stores sha256(svg); anyone can recompute it later.
// Identical to engine/v1's.
func SampleInput() Input {
	return Input{
		Seed:           safe.Sha256Hex(safe.Domain + "|engine-sample|v1"),
		CollectionID:   "0",
		TokenID:        "0",
		MintHeight:     1,
		LastMoveHeight: 1,
		Height:         1,
	}
}

// SampleSeed returns the i-th Studio/conformance sample seed (as v1).
func SampleSeed(i int) string {
	return safe.Sha256Hex(safe.Domain + "|sample|v1|" + strconv.Itoa(i))
}

// ValidateManifest checks sizes, text hygiene, the author address and the
// kind.
func ValidateManifest(m Manifest) error {
	fields := []struct {
		name, value string
		max         int
		required    bool
	}{
		{"name", m.Name, MaxNameLen, true},
		{"version", m.Version, MaxVersionLen, true},
		{"description", m.Description, MaxDescLen, false},
		{"license", m.License, MaxLicenseLen, false},
		{"paramsSchema", m.ParamsSchema, MaxParamsSchema, false},
	}
	for _, f := range fields {
		if f.required && f.value == "" {
			return errors.New("manifest " + f.name + ": must not be empty")
		}
		if err := safe.CheckText(f.value, f.max); err != nil {
			return errors.New("manifest " + f.name + ": " + err.Error())
		}
	}
	if !m.Author.IsValid() {
		return errors.New("manifest author: invalid address")
	}
	if err := ValidateTraitTypes(m.TraitTypes); err != nil {
		return errors.New("manifest: " + err.Error())
	}
	if m.FeeBps < 0 || m.FeeBps > MaxFeeBps {
		return errors.New("manifest feeBps: must be 0.." + strconv.Itoa(MaxFeeBps))
	}
	if m.MaxSVGBytes <= 0 || m.MaxSVGBytes > MaxSVGBytes {
		return errors.New("manifest maxSVGBytes: must be 1.." + strconv.Itoa(MaxSVGBytes))
	}
	switch m.Kind {
	case KindSVG:
		if m.MaxMediaBytes != 0 {
			return errors.New("manifest maxMediaBytes: must be 0 for an svg engine")
		}
	case KindMedia:
		if m.MaxMediaBytes <= 0 || m.MaxMediaBytes > MaxMediaBytes {
			return errors.New("manifest maxMediaBytes: must be 1.." + strconv.Itoa(MaxMediaBytes))
		}
	default:
		return errors.New("manifest kind: must be " + KindSVG + " or " + KindMedia)
	}
	return nil
}

// ValidateTraitTypes checks a trait list: at most MaxTraits non-empty,
// unique names that pass CheckText(MaxTraitLen).
func ValidateTraitTypes(tts []string) error {
	if len(tts) > MaxTraits {
		return errors.New("too many trait types")
	}
	for i, tt := range tts {
		if tt == "" {
			return errors.New("empty trait type")
		}
		if err := safe.CheckText(tt, MaxTraitLen); err != nil {
			return errors.New("trait type: " + err.Error())
		}
		for _, prev := range tts[:i] {
			if prev == tt {
				return errors.New("duplicate trait type " + tt)
			}
		}
	}
	return nil
}

// ValidateTraits checks one Traits() result against the manifest's trait
// list (v1 signature; static engines).
func ValidateTraits(m Manifest, ts []Trait) error {
	return ValidateTraitsFor(m.TraitTypes, ts)
}

// ValidateTraitsFor checks one Traits() result against a collection's
// trait list: known types, each at most once, values CheckText(MaxTraitLen).
func ValidateTraitsFor(tts []string, ts []Trait) error {
	if len(ts) > len(tts) {
		return errors.New("traits: more traits than trait types")
	}
	for i, t := range ts {
		if !contains(tts, t.Type) {
			return errors.New("traits: unknown type: " + t.Type)
		}
		for _, prev := range ts[:i] {
			if prev.Type == t.Type {
				return errors.New("traits: duplicate type " + t.Type)
			}
		}
		if err := safe.CheckText(t.Value, MaxTraitLen); err != nil {
			return errors.New("traits " + t.Type + ": " + err.Error())
		}
	}
	return nil
}

// CheckSVG is the output rule core applies to every render (art of an SVG
// engine, card of a media engine).
func CheckSVG(m Manifest, svg string) error {
	return safe.AssertSVG(svg, int(m.MaxSVGBytes))
}

// CheckMedia is the rule core applies to a media engine's Media before it
// serves it as TokenURI (I-15). Accepted:
//
//   - Data: Mime one of the four media types; SVG <= MaxMediaSVGBytes and
//     AssertSVG; a raster <= min(m.MaxMediaBytes, MaxMediaBytes) whose
//     magic and header dimensions (1..MaxDim) match Mime; Sha256 equal to
//     sha256(Data);
//   - URI: "ipfs://" + a CIDv1 (base32, raw or dag-pb, sha2-256); Mime one
//     of the four types; Sha256 "" or 64 lower-case hex, and for a raw CID
//     equal to the CID's digest.
//
// Everything else — both or neither set, another scheme, CIDv0, an unknown
// mime — is an error.
func CheckMedia(m Manifest, md Media) error {
	if md.Data != "" && md.URI != "" {
		return errors.New("media: data and uri are exclusive")
	}
	if !isMime(md.Mime) {
		return errors.New("media: mime must be one of " + MimePNG + ", " + MimeWebP + ", " + MimeJPEG + ", " + MimeSVG)
	}
	if md.Sha256 != "" && !isLowerHex32(md.Sha256) {
		return errors.New("media: sha256 must be 64 lower-case hex characters")
	}
	if md.Data != "" {
		if md.Sha256 == "" {
			return errors.New("media: sha256 is required with data")
		}
		if md.Mime == MimeSVG {
			if len(md.Data) > MaxMediaSVGBytes {
				return errors.New("media: svg larger than " + strconv.Itoa(MaxMediaSVGBytes) + " bytes")
			}
			if err := safe.AssertSVG(md.Data, MaxMediaSVGBytes); err != nil {
				return err
			}
		} else {
			limit := int64(MaxMediaBytes)
			if m.MaxMediaBytes < limit {
				limit = m.MaxMediaBytes
			}
			if int64(len(md.Data)) > limit {
				return errors.New("media: file larger than " + strconv.FormatInt(limit, 10) + " bytes")
			}
			if err := safe.CheckImage(md.Mime, md.Data); err != nil {
				return err
			}
		}
		if safe.Sha256Hex(md.Data) != md.Sha256 {
			return errors.New("media: sha256 does not match the data")
		}
		return nil
	}
	if md.URI == "" {
		return errors.New("media: neither data nor uri")
	}
	if !strings.HasPrefix(md.URI, IPFSScheme) {
		return errors.New("media: uri must be " + IPFSScheme + "<CIDv1>")
	}
	codec, digest, err := safe.ParseCIDv1(md.URI[len(IPFSScheme):])
	if err != nil {
		return err
	}
	if codec == safe.CodecRaw && md.Sha256 != "" && md.Sha256 != digest {
		return errors.New("media: sha256 does not match the raw CID's digest")
	}
	return nil
}

// Conformance is the self-test engine authors run in their _test.gno
// before registering: manifest, default params and trait types,
// determinism, size, SVG hygiene, traits, media (KindMedia: CheckMedia or
// Media{}; KindSVG: Media{}), and — for non-living engines — independence
// from the living fields.
func Conformance(e Engine, samples int) error {
	m := e.Manifest()
	if err := ValidateManifest(m); err != nil {
		return err
	}
	if err := e.ValidateParams(""); err != nil {
		return errors.New("default params rejected: " + err.Error())
	}
	tts := e.TraitTypes("")
	if err := ValidateTraitTypes(tts); err != nil {
		return errors.New("default trait types: " + err.Error())
	}
	inputs := []Input{SampleInput()}
	for i := 0; i < samples; i++ {
		in := SampleInput()
		in.Seed = SampleSeed(i)
		in.TokenID = strconv.Itoa(i + 1)
		inputs = append(inputs, in)
	}
	for _, in := range inputs {
		svg := e.Render(in)
		if svg != e.Render(in) {
			return errors.New("render is not deterministic for seed " + in.Seed)
		}
		if err := CheckSVG(m, svg); err != nil {
			return errors.New("seed " + in.Seed + ": " + err.Error())
		}
		if err := ValidateTraitsFor(tts, e.Traits(in)); err != nil {
			return errors.New("seed " + in.Seed + ": " + err.Error())
		}
		md := e.Media(in)
		if m.Kind == KindSVG && !md.IsZero() {
			return errors.New("an svg engine returns Media{}")
		}
		if m.Kind == KindMedia && !md.IsZero() {
			if err := CheckMedia(m, md); err != nil {
				return errors.New("seed " + in.Seed + ": " + err.Error())
			}
		}
		if !m.Living {
			moved := in
			moved.Height, moved.Moves, moved.LastMoveHeight = in.Height+1000, in.Moves+3, in.Height+500
			if e.Render(moved) != svg {
				return errors.New("non-living engine depends on Height/Moves/LastMoveHeight")
			}
		}
	}
	return nil
}

func isMime(s string) bool {
	return s == MimePNG || s == MimeWebP || s == MimeJPEG || s == MimeSVG
}

func isLowerHex32(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f') {
			return false
		}
	}
	return true
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

package engine

// Optional gates (core-final round, 2026-11-12). Engine stays exactly as it
// was, so every engine written against it keeps compiling; an engine value
// that also implements CreateGate or LaunchGate gets the collection-level
// facts its plain methods cannot see. Core finds them with a type
// assertion on the registered value and runs them, like ValidateParams and
// CheckLaunch, only in the creator's own transaction (I-16), never with
// core's cur.

// Launch modes as core passes them in Collection.Mode (the same values as
// types.ModeReveal and types.ModeOpen).
const (
	ModeReveal = ""
	ModeOpen   = "open"
)

// Collection is what core tells an engine's gates about one collection.
// Plain values only: an engine never gets a reference into core state.
type Collection struct {
	ID        string  // the collection id (bare, e.g. "12")
	Creator   address // the creator core records (a wallet or a realm, K-2)
	Params    string  // already accepted by ValidateParams
	MaxSupply int64
	// Mode is the launch mode in GateLaunch (ModeReveal or ModeOpen); ""
	// in GateCreate (a Draft has no mode yet).
	Mode string
	// Soulbound: the collection's tokens can never be transferred or
	// approved (fixed at creation).
	Soulbound bool
}

// CreateGate is the create-time check with the creator: core.CreateCollection
// calls GateCreate after ValidateParams and TraitTypes accepted the params;
// an error aborts the creation ("create refused by engine: …"). This is
// where an engine checks who may use which params (e.g. that the creator
// owns the asset store the params name) instead of reading OriginCaller.
type CreateGate interface {
	GateCreate(c Collection) error
}

// LaunchGate is the launch-time check with the launch mode: core.Launch
// calls GateLaunch right after CheckLaunch passed, for both modes; an error
// aborts the launch ("launch refused by engine: …").
type LaunchGate interface {
	GateLaunch(c Collection) error
}

// Package genesis is the platform's first engine: a pure p/ port of
// the prototype's gen1 engine. The RNG stream, trait tables,
// draw order and SVG drawing are byte-for-byte nftgen1's, so a seed renders
// the same artwork here as there; genesis_test.gno pins trait vectors
// computed independently from the same algorithm.
//
// What changed is only the packaging (RA L-7): it is a stateless p/
// package implementing engine/v2, the seed comes from core's commit–reveal
// (so the salt/seed helpers and the gnoweb Render of nftgen1 are gone), and
// the engine takes no params.
package genesis

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/engine/v2"
)

// TraitTypes in the order Traits returns them.
var traitTypes = []string{"Palette", "Shape", "Ground", "Frame", "Finish", "Aura", "Elements", "Symmetry", "Score", "Rarity"}

// MaxSVGBytes: 8 symmetry x 14 elements of the widest primitive plus the
// densest ground and frame stays well under this (gen1 tested < 32,000).
const MaxSVGBytes = 32768

// Manifest describes the engine. Author is left empty: the adapter realm
// that registers this engine sets the address that will ClaimEngine.
func Manifest() engine.Manifest {
	return engine.Manifest{
		Name:    "Genesis",
		Version: "1.0.0",
		Description: "Fully on-chain generative engine, nftgen1 lineage: FNV-1a + splitmix64 stream, " +
			"10 traits, 1,254,400 combinations, score-based rarity over every layer.",
		License:      "CC-BY-NC-4.0",
		ParamsSchema: `{"const":""}`,
		TraitTypes:   append([]string{}, traitTypes...),
		Living:       false,
		MaxSVGBytes:  MaxSVGBytes,
		Kind:         engine.KindSVG,
	}
}

// ValidateParams: genesis has no parameters.
func ValidateParams(params string) error {
	if params != "" {
		return errors.New("genesis takes no params")
	}
	return nil
}

// Traits returns the ten traits of in.Seed in TraitTypes order.
func Traits(in engine.Input) []engine.Trait {
	t := TraitsOf(in.Seed)
	return []engine.Trait{
		{Type: "Palette", Value: t.Palette},
		{Type: "Shape", Value: t.Shape},
		{Type: "Ground", Value: t.Ground},
		{Type: "Frame", Value: t.Frame},
		{Type: "Finish", Value: t.Finish},
		{Type: "Aura", Value: t.Aura},
		{Type: "Elements", Value: strconv.Itoa(t.Elements)},
		{Type: "Symmetry", Value: strconv.Itoa(t.Symmetry)},
		{Type: "Score", Value: strconv.Itoa(t.Score)},
		{Type: "Rarity", Value: t.Rarity},
	}
}

// Render returns the raw SVG for in.Seed.
func Render(in engine.Input) string { return SVG(in.Seed) }

// ---------------------------------------------------------------------------
// Deterministic randomness — FNV-1a over the seed, then a splitmix64 mixer.
// Pure integer math: no floats, no time, no block data.
// ---------------------------------------------------------------------------

const (
	fnvOffset uint64 = 14695981039346656037
	fnvPrime  uint64 = 1099511628211
)

type rng struct {
	state uint64
}

func newRNG(seed string) *rng {
	h := fnvOffset
	for i := 0; i < len(seed); i++ {
		h ^= uint64(seed[i])
		h *= fnvPrime
	}
	if h == 0 {
		h = fnvPrime
	}
	return &rng{state: h}
}

func (r *rng) next() uint64 {
	r.state += 0x9E3779B97F4A7C15
	z := r.state
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

// intn returns a value in [0, n).
func (r *rng) intn(n int) int {
	if n <= 0 {
		return 0
	}
	return int(r.next() % uint64(n))
}

// ---------------------------------------------------------------------------
// Weighted trait tables (weights are explicit; one draw walks the sum).
// ---------------------------------------------------------------------------

type option struct {
	name   string
	weight int
	score  int // contribution to the rarity score
}

func pick(r *rng, table []option) option {
	total := 0
	for _, o := range table {
		total += o.weight
	}
	roll := r.intn(total)
	acc := 0
	for _, o := range table {
		acc += o.weight
		if roll < acc {
			return o
		}
	}
	return table[len(table)-1]
}

type palette struct {
	option
	bg  string
	ink string
	c1  string
	c2  string
	c3  string
}

// Palette weights sum to 100, so a weight reads directly as a percent.
var palettes = []palette{
	{option{"Emerald", 18, 0}, "#04140f", "#7cf2c4", "#10b981", "#34d399", "#065f46"},
	{option{"Amethyst", 18, 0}, "#0b0713", "#e9d5ff", "#8b5cf6", "#c084fc", "#4c1d95"},
	{option{"Abyss", 16, 0}, "#02101c", "#bae6fd", "#0ea5e9", "#38bdf8", "#0c4a6e"},
	{option{"Ember", 14, 0}, "#160806", "#fecaca", "#f97316", "#fb923c", "#7c2d12"},
	{option{"Bone", 12, 0}, "#f5f5f4", "#1c1917", "#78716c", "#a8a29e", "#292524"},
	{option{"Solar", 10, 0}, "#1a1403", "#fef08a", "#eab308", "#facc15", "#713f12"},
	{option{"Obsidian", 8, 2}, "#050505", "#e5e5e5", "#404040", "#737373", "#171717"},
	{option{"Prism", 4, 4}, "#0a0a12", "#fdf4ff", "#22d3ee", "#f472b6", "#a78bfa"},
}

var shapes = []option{
	{"Orbit", 20, 0},
	{"Lattice", 18, 0},
	{"Bloom", 18, 0},
	{"Shard", 16, 0},
	{"Spiral", 14, 0},
	{"Weave", 9, 2},
	{"Rift", 5, 4},
}

var grounds = []option{
	{"Flat", 30, 0},
	{"Halo", 25, 0},
	{"Grid", 22, 0},
	{"Rings", 14, 1},
	{"Scatter", 9, 2},
}

var frames = []option{
	{"None", 55, 0},
	{"Thin", 25, 1},
	{"Double", 14, 2},
	{"Ornate", 6, 4},
}

var finishes = []option{
	{"Matte", 50, 0},
	{"Gloss", 28, 1},
	{"Glow", 16, 2},
	{"Foil", 6, 4},
}

var auras = []option{
	{"None", 78, 0},
	{"Soft", 14, 2},
	{"Bright", 6, 4},
	{"Nova", 2, 7},
}

// TraitSet is the decoded properties of a seed. The SVG builder and the
// trait list both read this one struct, so picture and metadata cannot
// describe different artwork.
type TraitSet struct {
	Palette  string
	Shape    string
	Ground   string
	Frame    string
	Finish   string
	Aura     string
	Elements int
	Symmetry int
	Score    int
	Rarity   string
}

// Tier cut-offs, chosen on nftgen1's 1000-seed simulation: Common 21.4% /
// Uncommon 44.4% / Rare 25.2% / Legendary 7.6% / Mythic 1.4%.
const (
	scoreMythic    = 12
	scoreLegendary = 8
	scoreRare      = 5
	scoreUncommon  = 2
)

func derive(seed string) (TraitSet, palette) {
	r := newRNG(seed)

	// Draw order is part of the contract: changing it changes every token.
	p := palettes[0]
	{
		total := 0
		for _, q := range palettes {
			total += q.weight
		}
		roll := r.intn(total)
		acc := 0
		for _, q := range palettes {
			acc += q.weight
			if roll < acc {
				p = q
				break
			}
		}
	}
	shape := pick(r, shapes)
	ground := pick(r, grounds)
	frame := pick(r, frames)
	finish := pick(r, finishes)
	aura := pick(r, auras)

	t := TraitSet{
		Palette:  p.name,
		Shape:    shape.name,
		Ground:   ground.name,
		Frame:    frame.name,
		Finish:   finish.name,
		Aura:     aura.name,
		Elements: 5 + r.intn(10), // 5..14
		Symmetry: 2 + r.intn(7),  // 2..8
	}

	score := p.score + shape.score + ground.score + frame.score + finish.score + aura.score
	if t.Elements >= 13 {
		score++
	}
	if t.Symmetry >= 7 {
		score++
	}
	t.Score = score

	switch {
	case score >= scoreMythic:
		t.Rarity = "Mythic"
	case score >= scoreLegendary:
		t.Rarity = "Legendary"
	case score >= scoreRare:
		t.Rarity = "Rare"
	case score >= scoreUncommon:
		t.Rarity = "Uncommon"
	default:
		t.Rarity = "Common"
	}
	return t, p
}

// TraitsOf returns the decoded traits for a seed.
func TraitsOf(seed string) TraitSet {
	t, _ := derive(seed)
	return t
}

func finishStroke(finish string) int {
	switch finish {
	case "Gloss":
		return 4
	case "Glow":
		return 5
	case "Foil":
		return 6
	default: // Matte
		return 3
	}
}

func auraRing(aura string) (int, int) { // width, opacity percent
	switch aura {
	case "Soft":
		return 4, 22
	case "Bright":
		return 8, 38
	case "Nova":
		return 14, 60
	default:
		return 0, 0
	}
}

// SVG renders the artwork for a seed as a standalone SVG document.
func SVG(seed string) string {
	t, p := derive(seed)
	r := newRNG(seed + "|art") // separate stream: trait draws never shift the art

	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">`)
	b.WriteString(ufmt.Sprintf(`<rect width="512" height="512" fill="%s"/>`, p.bg))

	// --- ground layer ---
	switch t.Ground {
	case "Halo":
		b.WriteString(ufmt.Sprintf(
			`<circle cx="256" cy="256" r="200" fill="none" stroke="%s" stroke-width="1" opacity="0.35"/>`, p.c3))
	case "Grid":
		for i := 64; i < 512; i += 64 {
			b.WriteString(ufmt.Sprintf(
				`<line x1="%d" y1="0" x2="%d" y2="512" stroke="%s" stroke-width="1" opacity="0.18"/>`, i, i, p.c3))
			b.WriteString(ufmt.Sprintf(
				`<line x1="0" y1="%d" x2="512" y2="%d" stroke="%s" stroke-width="1" opacity="0.18"/>`, i, i, p.c3))
		}
	case "Rings":
		for rad := 60; rad <= 240; rad += 45 {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="256" cy="256" r="%d" fill="none" stroke="%s" stroke-width="1" opacity="0.22"/>`, rad, p.c3))
		}
	case "Scatter":
		for i := 0; i < 40; i++ {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="%d" cy="%d" r="2" fill="%s" opacity="0.30"/>`,
				16+r.intn(480), 16+r.intn(480), p.c3))
		}
	}

	// --- aura layer ---
	if w, op := auraRing(t.Aura); w > 0 {
		b.WriteString(ufmt.Sprintf(
			`<circle cx="256" cy="256" r="230" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
			p.ink, w, op))
	}

	// --- composition: one pass, mirrored Symmetry times ---
	stroke := finishStroke(t.Finish)
	step := 360 / t.Symmetry
	for s := 0; s < t.Symmetry; s++ {
		b.WriteString(ufmt.Sprintf(`<g transform="rotate(%d 256 256)">`, s*step))
		for e := 0; e < t.Elements; e++ {
			color := p.c1
			switch r.intn(3) {
			case 1:
				color = p.c2
			case 2:
				color = p.ink
			}
			x := 96 + r.intn(320)
			y := 96 + r.intn(320)
			size := 12 + r.intn(70)
			opacity := 40 + r.intn(55) // percent, integer only
			if t.Finish == "Glow" || t.Finish == "Foil" {
				opacity = 55 + r.intn(40)
			}

			switch t.Shape {
			case "Orbit":
				b.WriteString(ufmt.Sprintf(
					`<circle cx="%d" cy="%d" r="%d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, color, stroke, opacity))
			case "Lattice":
				b.WriteString(ufmt.Sprintf(
					`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, size, color, stroke-1, opacity))
			case "Bloom":
				b.WriteString(ufmt.Sprintf(
					`<circle cx="%d" cy="%d" r="%d" fill="%s" opacity="0.%d"/>`,
					x, y, size/2, color, opacity))
			case "Shard":
				b.WriteString(ufmt.Sprintf(
					`<polygon points="%d,%d %d,%d %d,%d" fill="%s" opacity="0.%d"/>`,
					x, y, x+size, y+size/2, x+size/3, y+size, color, opacity))
			case "Weave":
				b.WriteString(ufmt.Sprintf(
					`<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, x+size, y+size/3, color, stroke, opacity))
				b.WriteString(ufmt.Sprintf(
					`<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x+size, y, x, y+size/3, color, stroke, opacity))
			case "Rift":
				b.WriteString(ufmt.Sprintf(
					`<path d="M%d %d l %d %d l %d %d l %d %d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size/2, -size/3, size/3, size, size/2, -size/2,
					color, stroke, opacity))
			default: // Spiral
				b.WriteString(ufmt.Sprintf(
					`<path d="M%d %d q %d %d %d %d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, -size, size*2, 0, color, stroke, opacity))
			}
		}
		b.WriteString(`</g>`)
	}

	// --- frame layer, drawn last so it always sits on top ---
	switch t.Frame {
	case "Thin":
		b.WriteString(ufmt.Sprintf(
			`<rect x="12" y="12" width="488" height="488" fill="none" stroke="%s" stroke-width="2" opacity="0.55"/>`, p.ink))
	case "Double":
		b.WriteString(ufmt.Sprintf(
			`<rect x="10" y="10" width="492" height="492" fill="none" stroke="%s" stroke-width="3" opacity="0.60"/>`, p.ink))
		b.WriteString(ufmt.Sprintf(
			`<rect x="24" y="24" width="464" height="464" fill="none" stroke="%s" stroke-width="1" opacity="0.45"/>`, p.c2))
	case "Ornate":
		b.WriteString(ufmt.Sprintf(
			`<rect x="8" y="8" width="496" height="496" fill="none" stroke="%s" stroke-width="4" opacity="0.70"/>`, p.ink))
		b.WriteString(ufmt.Sprintf(
			`<rect x="22" y="22" width="468" height="468" fill="none" stroke="%s" stroke-width="2" opacity="0.55"/>`, p.c2))
		for _, c := range [][2]int{{8, 8}, {504, 8}, {8, 504}, {504, 504}} {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="%d" cy="%d" r="10" fill="none" stroke="%s" stroke-width="3" opacity="0.80"/>`,
				c[0], c[1], p.c1))
		}
	}

	b.WriteString(`</svg>`)
	return b.String()
}

package core

import (
	"chain"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
)

// Engine access policy (I-19, docs/mainnet/engine-access-policy.md).
//
// An engine's author decides who may open collections with it:
//
//   - closed   ("signature engine") only the author. Every registration
//     starts closed: nothing an author did not choose to share is usable
//     by others, and a squat copy stays useless to everyone else.
//   - licensed only the author and the creators the author licensed
//     (GrantLicence), each for a bounded number of collections and,
//     optionally, at a licence fee instead of the manifest's.
//   - open     ("tool engine") anyone.
//
// The policy is judged once, in CreateCollection, and never again: a
// policy change, a revoked or used-up licence leaves every collection
// already created (Drafts included) as it is. Only the claimed manifest
// author changes a policy or a licence; no admin op touches them (the
// admin's engine.deprecate still stops new collections for everyone).
//
// For every policy, a collection whose engine and params are byte-identical
// to an earlier collection's is refused unless its creator is that earlier
// collection's current creator (paramsTaken). Empty params (the engine's
// defaults) are exempt: an engine without params (genesis) would otherwise
// back one collection ever.

// Policies.
const (
	PolicyClosed   = "closed"
	PolicyLicensed = "licensed"
	PolicyOpen     = "open"
)

// How a collection's creator was allowed to use the engine (collection
// JSON "access", CollectionCreated.access).
const (
	AccessAuthor  = "author"
	AccessLicence = "licence"
	AccessOpen    = "open"
)

const (
	MaxLicencesPerEngine  = 1000 // live licences of one engine (GrantLicence of a new holder)
	MaxLicenceCollections = 1000 // collections one licence allows
	LicenceFeeDefault     = -1   // GrantLicence feeBps: the manifest's FeeBps applies
)

type licence struct {
	maxCollections int64
	used           int64 // collections created under this licence
	feeBps         int64 // LicenceFeeDefault or 0..EngineFeeCapBps, snapshotted into each collection
	grantedHeight  int64 // last GrantLicence of this holder
}

var (
	licences    avl.Tree // engine id + ":" + holder -> *licence
	paramsTaken avl.Tree // paramsKey(engine id, params) -> cid of the first collection with them
)

// SetEnginePolicy sets who may create collections with engine id: "closed",
// "licensed" or "open". The claimed manifest author only; refused for a
// deprecated or superseded engine (it backs no new collection anyway).
func SetEnginePolicy(cur realm, id, policy string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	assertEngineAuthor(cur, rec, "set its policy")
	assertEngineNotRetired(rec)
	if policy != PolicyClosed && policy != PolicyLicensed && policy != PolicyOpen {
		panic("policy must be \"" + PolicyClosed + "\", \"" + PolicyLicensed + "\" or \"" + PolicyOpen + "\"")
	}
	rec.policy = policy
	chain.Emit("EnginePolicySet", "id", id, "policy", policy)
}

// GrantLicence lets holder create up to maxCollections (1..
// MaxLicenceCollections) collections with engine id while its policy is
// "licensed". feeBps is LicenceFeeDefault (-1, the manifest fee) or
// 0..EngineFeeCapBps: the engine-author fee of the holder's collections,
// snapshotted at their creation (a sale still pays at most the platform
// cap). Granting again to a holder updates maxCollections (not below the
// used count) and feeBps and keeps the used count. Claimed author only;
// not on a deprecated or superseded engine. A grant does not change the
// policy.
func GrantLicence(cur realm, id string, holder address, maxCollections, feeBps int64) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	assertEngineAuthor(cur, rec, "grant a licence")
	assertEngineNotRetired(rec)
	if !holder.IsValid() {
		panic("invalid licence holder address")
	}
	if holder == rec.manifest.Author {
		panic("the engine's author needs no licence")
	}
	if maxCollections < 1 || maxCollections > MaxLicenceCollections {
		panic("maxCollections must be 1.." + itoa(MaxLicenceCollections))
	}
	if feeBps != LicenceFeeDefault && (feeBps < 0 || feeBps > EngineFeeCapBps) {
		panic("licence feeBps must be -1 (the manifest fee) or 0.." + itoa(EngineFeeCapBps))
	}
	key := licenceKey(id, holder)
	l, _ := licences.Get(key).(*licence)
	if l == nil {
		if rec.licences >= MaxLicencesPerEngine {
			panic("engine has " + itoa(MaxLicencesPerEngine) + " licences; revoke one first")
		}
		l = &licence{}
		licences.Set(key, l)
		rec.licences++
	} else if maxCollections < l.used {
		panic("maxCollections must be at least the " + itoa(l.used) +
			" collections already created under this licence (revoke it to stop it)")
	}
	l.maxCollections, l.feeBps, l.grantedHeight = maxCollections, feeBps, height()
	chain.Emit("LicenceGranted", "id", id, "holder", holder.String(),
		"maxCollections", itoa(maxCollections), "feeBps", itoa(feeBps))
}

// RevokeLicence removes holder's licence on engine id. Collections already
// created under it are not affected. Claimed author only (also on a
// deprecated or superseded engine).
func RevokeLicence(cur realm, id string, holder address) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	assertEngineAuthor(cur, rec, "revoke a licence")
	key := licenceKey(id, holder)
	v := licences.Get(key)
	if v == nil {
		panic(holder.String() + " holds no licence on " + id)
	}
	licences.Remove(key)
	rec.licences--
	chain.Emit("LicenceRevoked", "id", id, "holder", holder.String(), "used", itoa(v.(*licence).used))
}

func assertEngineAuthor(cur realm, rec *engineRecord, what string) {
	if caller(cur) != rec.manifest.Author {
		panic("only the engine's author " + rec.manifest.Author.String() + " can " + what)
	}
	if !rec.claimed {
		panic("engine is not claimed by its author yet")
	}
}

func assertEngineNotRetired(rec *engineRecord) {
	if rec.deprecated {
		panic("engine is deprecated")
	}
	if rec.superseded {
		panic("engine is superseded by " + rec.supersededBy)
	}
}

func licenceKey(id string, holder address) string { return id + ":" + holder.String() }

// paramsKey identifies an (engine, params) pair in bounded space.
func paramsKey(id, params string) string {
	return safe.Sha256Hex(safe.Domain + "|params|v1|" + id + "|" + params)
}

// createGrant is what CreateCollection learned from the access gate.
type createGrant struct {
	access string
	lic    *licence // the licence used (AccessLicence), else nil
	fee    int64    // engine fee override snapshotted into the collection, or LicenceFeeDefault
	key    string   // paramsKey, "" for empty params
	reuse  bool     // key already held by this creator
}

// createAccess is the engine side of CreateCollection's gate: engine
// usable (claimed, live), creator allowed by the policy, params not held
// by another creator. It returns the refusal text ("" = allowed) and
// writes nothing; CreateCollection panics with that text and CreateRefusal
// returns it.
func createAccess(rec *engineRecord, creator address, params string) (createGrant, string) {
	g := createGrant{fee: LicenceFeeDefault}
	switch {
	case !rec.claimed:
		return g, "engine is not claimed by its author yet"
	case rec.deprecated:
		return g, "engine is deprecated"
	case rec.superseded:
		return g, "engine is superseded by " + rec.supersededBy
	}
	switch {
	case creator == rec.manifest.Author:
		g.access = AccessAuthor
	case rec.policy == PolicyOpen:
		g.access = AccessOpen
	case rec.policy == PolicyLicensed:
		l, _ := licences.Get(licenceKey(rec.id, creator)).(*licence)
		if l == nil {
			return g, "engine " + rec.id + " is licensed: " + creator.String() +
				" holds no licence from its author " + rec.manifest.Author.String()
		}
		if l.used >= l.maxCollections {
			return g, "the licence of " + creator.String() + " on " + rec.id + " is used up (" +
				itoa(l.used) + "/" + itoa(l.maxCollections) + " collections)"
		}
		g.access, g.lic, g.fee = AccessLicence, l, l.feeBps
	default:
		return g, "engine " + rec.id + " is closed: only its author " + rec.manifest.Author.String() +
			" creates collections with it"
	}
	if params == "" {
		return g, ""
	}
	g.key = paramsKey(rec.id, params)
	if v := paramsTaken.Get(g.key); v != nil {
		first := mustCollection(v.(string))
		if first.creator != creator {
			return g, "engine " + rec.id + " with these params already backs collection " + first.id +
				" of another creator; choose other params"
		}
		g.reuse = true
	}
	return g, ""
}

// --- reads ---------------------------------------------------------------------

// EnginePolicy is engine id's policy: "closed", "licensed" or "open".
func EnginePolicy(id string) string { return mustEngine(id).policy }

// Licensed reports whether holder holds a licence on engine id with room
// for another collection (whatever the current policy).
func Licensed(id string, holder address) bool {
	mustEngine(id)
	l, _ := licences.Get(licenceKey(id, holder)).(*licence)
	return l != nil && l.used < l.maxCollections
}

// Licence is holder's licence on engine id as JSON
// {engine, holder, maxCollections, used, feeBps, grantedHeight}, or null.
func Licence(id string, holder address) string {
	mustEngine(id)
	v := licences.Get(licenceKey(id, holder))
	if v == nil {
		return "null"
	}
	w := &safe.JSONWriter{}
	writeLicence(w, id, holder.String(), v.(*licence))
	return w.String()
}

// Licences pages engine id's licences in holder-address order.
func Licences(id string, offset, limit int64) string {
	mustEngine(id)
	w := &safe.JSONWriter{}
	w.BeginArray()
	prefix := id + ":"
	skipped, written, want := int64(0), int64(0), clampLimit(limit)
	licences.Iterate(prefix, prefix+"\xff", func(k string, v any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		writeLicence(w, id, k[len(prefix):], v.(*licence))
		written++
		return written >= want
	})
	w.EndArray()
	return w.String()
}

func writeLicence(w *safe.JSONWriter, id, holder string, l *licence) {
	w.BeginObject()
	w.StrField("engine", id)
	w.StrField("holder", holder)
	w.IntField("maxCollections", l.maxCollections)
	w.IntField("used", l.used)
	w.IntField("feeBps", l.feeBps)
	w.IntField("grantedHeight", l.grantedHeight)
	w.EndObject()
}

// ParamsTaken is the cid of the first collection created with engine id and
// exactly these params, or "" (always "" for empty params).
func ParamsTaken(id, params string) string {
	if params == "" {
		return ""
	}
	if v := paramsTaken.Get(paramsKey(id, params)); v != nil {
		return v.(string)
	}
	return ""
}

// CreateRefusal is why CreateCollection would refuse creator on engine id
// with params now, as core's own text, or "" when the engine gates pass:
// unknown engine, create paused, unclaimed/deprecated/superseded, the
// policy, a used-up licence, params of another creator. The engine's own
// ValidateParams and the spec's other fields are not judged here.
func CreateRefusal(id string, creator address, params string) string {
	v := engines.Get(id)
	if v == nil {
		return "unknown engine " + id
	}
	if Paused("create") {
		return "paused: create"
	}
	_, why := createAccess(v.(*engineRecord), creator, params)
	return why
}

package core

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/types/v2"
)

// Admin (design §2.5.2, §7.5). The admin can only change the parameters
// listed in validateOp, each inside a hard cap, after a public timelock;
// it can pause new activity for a bounded time. It can never move, approve
// or burn a token, touch a collection's configuration, or receive funds
// (I-1). With no collection yet there is nothing to protect, so ops execute
// without delay — that is how the platform is configured after deploy.
//
// The initial admin and treasury come from config.gno (per chain; the
// admin is the bootstrap deployer and is handed to the 2/3 multisig with
// admin.transfer before minter.add, plan §5.7).
// SA-I6: CreateFee starts at 0 here so tests and bootstrap stay simple;
// the bootstrap sets fee.create (1 GNOT, decision §6-5).
var (
	admin        = initialAdmin
	pendingAdmin address
	fees         = types.Fees{
		PrimaryBps: 250, SecondaryBps: 250, EngineCapBps: EngineFeeCapBps,
		Treasury: initialTreasury,
	}
	beacon address
	// listingDeposit is the deposit return market/v1 pins into each new
	// listing at List and charges the buyer for the seller (CV-L2): the
	// listing's storage (4,077 B, measured) x the chain's storage price
	// (100 ugnot/B on Onyx and gnoland-1). Re-set with listing.deposit
	// (timelocked, <= ListingDepositCap) if the vm storage_price changes.
	listingDeposit int64    = 407_700
	minters        avl.Tree // minter pkgpath -> *minterRecord
	ops            avl.Tree // safe.PadInt(op id) -> *pendingOp
	opCount        int64
	pauses         avl.Tree // scope -> *pauseRecord

	// deniedPayees is every address refused as a payee or treasury beyond
	// core's own (SA-L5, M-17): the static platform realms (config.gno),
	// every minter ever approved, and payee.deny entries. It only grows
	// (I-18).
	deniedPayees avl.Tree // address -> *deniedPayee
	deniedOrder  avl.Tree // safe.PadInt(seq) -> address (DeniedPayees pages)
	deniedCount  int64
	deniedByOps  int64
)

type deniedPayee struct {
	path, source string // source: "static", "minter" or "op"
}

// pauseRecord is one scope's pause and its budget (SA-L2): within a window
// of PauseWindowBlocks a scope can be paused for at most MaxPauseBlocks in
// total; a pause cannot be renewed while it runs. Worst case two budgets
// meet at a window boundary (<= 2 x MaxPauseBlocks in a row), never more.
type pauseRecord struct {
	windowStart int64
	used        int64 // blocks of budget charged in this window
	until       int64 // exclusive
}

type minterRecord struct {
	deprecated bool
}

type pendingOp struct {
	id       int64
	op, arg  string
	proposed int64
}

// Ops and their argument formats.
const (
	OpFeeCreate       = "fee.create"           // ugnot, <= CreateFeeCap
	OpFeePrimary      = "fee.primary"          // bps, <= ProtocolFeeCapBps
	OpFeeSecondary    = "fee.secondary"        // bps, <= ProtocolFeeCapBps
	OpFeeEngine       = "fee.engine"           // bps, <= EngineFeeCapBps: platform cap on engine-author fees
	OpTreasury        = "treasury"             // address
	OpBeacon          = "beacon"               // address, or "" to disable new beacon launches
	OpMinterAdd       = "minter.add"           // realm pkgpath
	OpMinterDeprecate = "minter.deprecate"     // realm pkgpath: no new collections
	OpEngineReview    = "engine.review"        // engine id: reviewed badge (UI only)
	OpAdminTransfer   = "admin.transfer"       // address; the new admin must AcceptAdmin
	OpRandomnessAdd   = "randomness.add"       // registered provider path: creators may launch with it
	OpRandomnessDepr  = "randomness.deprecate" // provider path: no new launches; running ones finish
	OpListingDeposit  = "listing.deposit"      // ugnot, <= ListingDepositCap: market deposit return for new listings
	OpEngineDeprecate = "engine.deprecate"     // engine id: no new collections (proven re-wrap or squat, ENG-M1)
	OpPayeeDeny       = "payee.deny"           // realm pkgpath: refused as payee/treasury from now on (I-18: no op removes)
)

var pauseScopes = []string{"create", "mint", "trade"}

func ProposeOp(cur realm, op, arg string) string {
	assertNoDeposit(cur)
	assertAdmin(cur)
	validateOp(op, arg)
	opCount++
	p := &pendingOp{id: opCount, op: op, arg: arg, proposed: height()}
	ops.Set(safe.PadInt(p.id, cidWidth), p)
	id := itoa(p.id)
	chain.Emit("OpProposed", "id", id, "op", op, "arg", arg, "earliest", itoa(earliestExecution(p)))
	return id
}

// ExecuteOp applies a proposed op once its timelock has passed. The delay is
// judged at execution, so an op proposed during bootstrap still waits the
// full timelock if a collection appeared in the meantime.
func ExecuteOp(cur realm, opID string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	p := mustOp(opID)
	if height() < earliestExecution(p) {
		panic("timelocked until height " + itoa(earliestExecution(p)))
	}
	validateOp(p.op, p.arg)
	applyOp(p.op, p.arg)
	ops.Remove(safe.PadInt(p.id, cidWidth))
	chain.Emit("OpExecuted", "id", opID, "op", p.op, "arg", p.arg)
}

func CancelOp(cur realm, opID string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	p := mustOp(opID)
	ops.Remove(safe.PadInt(p.id, cidWidth))
	chain.Emit("OpCancelled", "id", opID)
}

func AcceptAdmin(cur realm) {
	assertNoDeposit(cur)
	who := caller(cur)
	if pendingAdmin == "" || who != pendingAdmin {
		panic("no pending admin transfer to this address")
	}
	chain.Emit("AdminTransferred", "from", admin.String(), "to", who.String())
	admin = who
	pendingAdmin = ""
}

// Pause stops new activity in one scope for the rest of its budget (at
// most MaxPauseBlocks per PauseWindowBlocks). It never blocks exits (I-2)
// and cannot be renewed while it runs (SA-L2).
func Pause(cur realm, scope string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	assertScope(scope)
	h := height()
	r := pauseOf(scope)
	if h < r.until {
		panic("already paused until height " + itoa(r.until) + "; a pause cannot be renewed")
	}
	if h >= r.windowStart+PauseWindowBlocks {
		r.windowStart, r.used = h, 0
	}
	left := MaxPauseBlocks - r.used
	if left <= 0 {
		panic("pause budget of " + scope + " is spent until height " + itoa(r.windowStart+PauseWindowBlocks))
	}
	r.used += left
	r.until = h + left
	pauses.Set(scope, r)
	chain.Emit("Paused", "scope", scope, "until", itoa(r.until))
}

// Unpause ends a pause early and gives the unused blocks back to the budget.
func Unpause(cur realm, scope string) {
	assertNoDeposit(cur)
	assertAdmin(cur)
	assertScope(scope)
	h := height()
	r := pauseOf(scope)
	if h < r.until {
		r.used -= r.until - h
	}
	r.until = 0
	chain.Emit("Unpaused", "scope", scope)
}

func pauseOf(scope string) *pauseRecord {
	if v := pauses.Get(scope); v != nil {
		return v.(*pauseRecord)
	}
	return &pauseRecord{windowStart: -PauseWindowBlocks}
}

// Paused reports whether scope ("create", "mint", "trade") is paused now.
func Paused(scope string) bool {
	v := pauses.Get(scope)
	return v != nil && height() < v.(*pauseRecord).until
}

// PauseBudget is the scope's pause record as JSON: {until, used,
// windowStart, windowEnd, left}.
func PauseBudget(scope string) string {
	assertScope(scope)
	r := pauseOf(scope)
	used := r.used
	if height() >= r.windowStart+PauseWindowBlocks && height() >= r.until {
		used = 0
	}
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.IntField("until", r.until)
	w.IntField("used", used)
	w.IntField("windowStart", r.windowStart)
	w.IntField("windowEnd", r.windowStart+PauseWindowBlocks)
	w.IntField("left", MaxPauseBlocks-used)
	w.EndObject()
	return w.String()
}

func assertNotPaused(scope string) {
	if Paused(scope) {
		panic("paused: " + scope)
	}
}

func assertScope(scope string) {
	for _, s := range pauseScopes {
		if s == scope {
			return
		}
	}
	panic("pause scope must be one of " + strings.Join(pauseScopes, ", "))
}

func assertAdmin(cur realm) {
	if caller(cur) != admin {
		panic("admin only")
	}
}

func bootstrapping() bool { return collCount == 0 }

func earliestExecution(p *pendingOp) int64 {
	if bootstrapping() {
		return p.proposed
	}
	return p.proposed + TimelockBlocks
}

func mustOp(opID string) *pendingOp {
	v := ops.Get(safe.PadInt(safe.ParseID("opID", opID), cidWidth))
	if v == nil {
		panic("unknown op " + opID)
	}
	return v.(*pendingOp)
}

// validateOp is the closed list of admin powers (I-1).
func validateOp(op, arg string) {
	switch op {
	case OpFeeCreate:
		n := parseAmount(arg)
		if n > CreateFeeCap {
			panic("create fee above cap " + itoa(CreateFeeCap))
		}
	case OpFeePrimary, OpFeeSecondary:
		safe.AssertBps(op, parseAmount(arg), ProtocolFeeCapBps)
	case OpFeeEngine:
		safe.AssertBps(op, parseAmount(arg), EngineFeeCapBps)
	case OpListingDeposit:
		if parseAmount(arg) > ListingDepositCap {
			panic("listing deposit above cap " + itoa(ListingDepositCap))
		}
	case OpTreasury, OpAdminTransfer:
		if !address(arg).IsValid() {
			panic(op + ": invalid address")
		}
		if op == OpTreasury {
			assertSpendable(op, address(arg), "", "") // SA-L5
		}
	case OpBeacon:
		if arg != "" && !address(arg).IsValid() {
			panic(op + ": invalid address")
		}
	case OpMinterAdd:
		safe.AssertText("minter", arg, 256)
		if !strings.HasPrefix(arg, runtime.ChainDomain()+"/r/") || strings.Contains(arg, "#") {
			panic("minter must be a realm path")
		}
		if minters.Has(arg) {
			panic("minter already added")
		}
	case OpMinterDeprecate:
		if !minters.Has(arg) {
			panic("unknown minter")
		}
	case OpEngineReview:
		mustEngine(arg)
	case OpEngineDeprecate:
		if mustEngine(arg).deprecated {
			panic("engine is already deprecated")
		}
	case OpPayeeDeny:
		safe.AssertText("payee realm", arg, 256)
		if !strings.HasPrefix(arg, runtime.ChainDomain()+"/r/") || strings.Contains(arg, "#") {
			panic("payee.deny takes a realm path")
		}
		if deniedPayees.Has(chain.PackageAddress(arg).String()) {
			panic("realm is already denied as a payee")
		}
		if deniedByOps >= MaxDeniedPayees {
			panic("payee deny list is full (" + itoa(MaxDeniedPayees) + " entries)")
		}
	case OpRandomnessAdd:
		if mustProvider(arg).active {
			panic("randomness provider already approved")
		}
	case OpRandomnessDepr:
		if !mustProvider(arg).active {
			panic("randomness provider is not approved")
		}
	default:
		panic("unknown op " + strconv.Quote(op))
	}
}

func applyOp(op, arg string) {
	switch op {
	case OpFeeCreate:
		fees.CreateFee = parseAmount(arg)
	case OpFeePrimary:
		fees.PrimaryBps = parseAmount(arg)
	case OpFeeSecondary:
		fees.SecondaryBps = parseAmount(arg)
	case OpFeeEngine:
		fees.EngineCapBps = parseAmount(arg)
	case OpListingDeposit:
		listingDeposit = parseAmount(arg)
	case OpTreasury:
		fees.Treasury = address(arg)
	case OpBeacon:
		beacon = address(arg)
	case OpMinterAdd:
		minters.Set(arg, &minterRecord{})
		denyPayee(arg, "minter")
	case OpMinterDeprecate:
		minters.Get(arg).(*minterRecord).deprecated = true
	case OpEngineReview:
		mustEngine(arg).reviewed = true
	case OpEngineDeprecate:
		rec := mustEngine(arg)
		rec.deprecated, rec.deprecatedBy = true, "admin"
		chain.Emit("EngineDeprecated", "id", arg, "by", "admin")
	case OpPayeeDeny:
		denyPayee(arg, "op")
		deniedByOps++
		chain.Emit("PayeeDenied", "path", arg, "address", chain.PackageAddress(arg).String())
	case OpAdminTransfer:
		pendingAdmin = address(arg)
	case OpRandomnessAdd:
		mustProvider(arg).active = true
		activeProviders++
	case OpRandomnessDepr:
		mustProvider(arg).active = false
		activeProviders--
	}
}

func assertActiveMinter(path string) {
	v := minters.Get(path)
	if v == nil {
		panic("caller " + strconv.Quote(path) + " is not an approved minter")
	}
	if v.(*minterRecord).deprecated {
		panic("minter " + path + " is deprecated")
	}
}

func parseAmount(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 0 {
		panic("expected a non-negative integer, got " + strconv.Quote(s))
	}
	return n
}

// --- payee deny set (SA-L5, M-17, I-18) -----------------------------------------

// initDeniedPayees adds the static platform realms next to core.
func initDeniedPayees() {
	base := strings.TrimSuffix(selfPath, "/core")
	for _, sib := range staticDeniedRealms {
		denyPayee(base+"/"+sib, "static")
	}
}

// denyPayee adds path's package address to the deny set (idempotent).
func denyPayee(path, source string) {
	key := chain.PackageAddress(path).String()
	if deniedPayees.Has(key) {
		return
	}
	deniedPayees.Set(key, &deniedPayee{path: path, source: source})
	deniedCount++
	deniedOrder.Set(safe.PadInt(deniedCount, cidWidth), key)
}

// IsDeniedPayee reports whether addr is in the payee deny set (static
// platform realms, approved minters, payee.deny). Core's own addresses and
// a collection's sub-addresses and engine adapter are refused as well
// (assertSpendable) but are not listed here.
func IsDeniedPayee(addr address) bool { return deniedPayees.Has(addr.String()) }

// DeniedPayees pages the deny set as JSON: [{path, address, source}].
func DeniedPayees(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	deniedOrder.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		key := v.(string)
		d := deniedPayees.Get(key).(*deniedPayee)
		w.BeginObject()
		w.StrField("path", d.path)
		w.StrField("address", key)
		w.StrField("source", d.source)
		w.EndObject()
		return false
	})
	w.EndArray()
	return w.String()
}

package core

import (
	"chain"
	"chain/runtime"

	"gno.land/p/nt/grc721/royalty/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/seqid/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/engine/v2"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/types/v2"
)

// --- bound minter only -------------------------------------------------------
//
// A collection is created by an admin-approved minter realm and stays bound
// to it: only that realm can launch, abort, reserve and mint (I-5). The
// minter is trusted to pass the real creator; core trusts nothing else it
// is given and validates every field (I-13).

// CreateCollection stores a Draft collection and returns its id. Nobody can
// mint a Draft, so a creator can configure phases across several messages
// without a race (OA B2).
func CreateCollection(cur realm, creator address, spec types.CollectionSpec) string {
	minter := cur.Previous().PkgPath()
	assertActiveMinter(minter)
	assertNotPaused("create")
	if !creator.IsValid() {
		panic("invalid creator address")
	}
	safe.AssertNonEmptyText("name", spec.Name, MaxNameLen)
	safe.AssertSymbol("symbol", spec.Symbol)
	safe.AssertText("description", spec.Description, MaxDescriptionLen)
	safe.AssertText("params", spec.Params, MaxParamsLen)
	if spec.MaxSupply <= 0 || spec.MaxSupply > MaxSupplyCap {
		panic("maxSupply must be 1.." + itoa(MaxSupplyCap))
	}
	safe.AssertBps("royaltyBps", spec.RoyaltyBps, RoyaltyCapBps)
	if spec.Soulbound && spec.RoyaltyBps != 0 {
		panic("a non-transferable collection has no secondary sales; royaltyBps must be 0")
	}
	primary := safe.ParsePayees("primaryPayees", spec.PrimaryPayees, MaxPayees)
	royal := safe.ParsePayees("royaltyPayees", spec.RoyaltyPayees, MaxPayees)
	next := itoa(collCount + 1)
	assertPayees("primaryPayees", primary, next, spec.EngineID)
	assertPayees("royaltyPayees", royal, next, spec.EngineID)

	rec := mustEngine(spec.EngineID)
	// I-19: claimed and live engine, creator allowed by its policy, params
	// not another creator's; judged before any engine code runs.
	g, why := createAccess(rec, creator, spec.Params)
	if why != "" {
		panic(why)
	}
	// I-16: the creator's own transaction runs the engine they chose.
	if err := rec.impl.ValidateParams(spec.Params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	tts := collectionTraitTypes(rec, spec.Params)
	// The engine's optional create gate gets the creator explicitly (no
	// OriginCaller read in the engine; a realm creator works too, K-2).
	if g, ok := rec.impl.(engine.CreateGate); ok {
		err := g.GateCreate(engine.Collection{ID: next, Creator: creator, Params: spec.Params,
			MaxSupply: spec.MaxSupply, Soulbound: spec.Soulbound})
		if err != nil {
			panic("create refused by engine: " + err.Error())
		}
	}

	collCount++
	cid := itoa(collCount)

	// Each collection gets its own sub-realm identity, so Token.ID() and every
	// grc721 event carry "…/core#c/<cid>" (design §2.3; verified by
	// spike/subtoken and core tests on gno v1.7.0).
	tok, led := grc721.NewToken(spec.Name, spec.Symbol, seqid.ID(uint64(collCount)), cur.Sub("c/"+cid))
	st := &tokenState{soulbound: spec.Soulbound}
	led.RegisterExtension(&lockExt{cid: cid, st: st})
	roy, royLed := royalty.NewRoyalty(led, RoyaltyCapBps)
	if spec.RoyaltyBps > 0 {
		if err := royLed.SetDefaultRoyalty(royaltyAddress(cid), spec.RoyaltyBps); err != nil {
			panic(err)
		}
	}

	c := &collection{
		id:            cid,
		name:          spec.Name,
		symbol:        spec.Symbol,
		description:   spec.Description,
		creator:       creator,
		engineID:      spec.EngineID,
		params:        spec.Params,
		traitTypes:    tts,
		soulbound:     spec.Soulbound,
		maxSupply:     spec.MaxSupply,
		nextTID:       1,
		royaltyBps:    spec.RoyaltyBps,
		primaryPayees: primary,
		royaltyPayees: royal,
		minter:        minter,
		state:         types.StateDraft,
		createdHeight: height(),
		access:        g.access,
		licenceFee:    g.fee,
		token:         tok,
		ledger:        led,
		roy:           roy,
		st:            st,
	}
	collections.Set(collKey(cid), c)
	byCreator.Set(creator.String()+":"+collKey(cid), cid)
	byEngine.Set(spec.EngineID+":"+collKey(cid), cid)
	rec.collections++
	if g.key != "" && !g.reuse {
		paramsTaken.Set(g.key, cid)
	}
	if g.lic != nil {
		g.lic.used++
	}

	chain.Emit("CollectionCreated",
		"cid", cid, "creator", creator.String(), "minter", minter,
		"engine", spec.EngineID, "token", tok.ID(), "access", g.access, "soulbound", boolStr(spec.Soulbound))
	return cid
}

// Launch freezes the configuration (I-6): sale window, reveal window and the
// creator's commitment. The sale must start in the future so a beacon can
// commit before the first mint.
func Launch(cur realm, cid string, l types.LaunchSpec) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	h := height()
	if c.state != types.StateDraft {
		panic("only a draft can be launched")
	}
	if l.StartHeight <= h {
		panic("startHeight must be in the future")
	}
	if l.EndHeight < l.StartHeight || l.EndHeight-l.StartHeight > MaxSaleBlocks {
		panic("sale window must be 0.." + itoa(MaxSaleBlocks) + " blocks")
	}
	if l.Mode == types.ModeOpen {
		launchOpen(c, l)
		return
	}
	if l.Mode != types.ModeReveal {
		panic("mode must be \"\" (commit-reveal) or \"" + types.ModeOpen + "\"")
	}
	if l.RevealWindow < RevealWindowMin || l.RevealWindow > RevealWindowMax {
		panic("revealWindow must be " + itoa(RevealWindowMin) + ".." + itoa(RevealWindowMax) + " blocks")
	}
	commit := safe.AssertHex("creatorCommit", l.CreatorCommit, 32)
	// Commitments are domain-separated by chain, collection and role
	// (safe.Commit), so only this collection's own history matters: a secret
	// that went public here is never accepted again (SA-L1, RA M-5).
	if isBurned(c, commit) {
		panic("this commitment's secret was already revealed; derive a new secret")
	}
	source := l.BeaconSource
	if l.UseBeacon {
		if source == "" {
			source = types.BeaconCommitted
		}
		if source == types.BeaconCommitted {
			if beacon == "" {
				panic("no beacon is configured; launch without useBeacon or with an approved randomness provider")
			}
		} else {
			assertActiveProvider(source)
		}
	} else {
		if source != "" {
			panic("beaconSource needs useBeacon")
		}
		// SA-M2: without the beacon the creator alone knows the only secret
		// and can grind the last mint for the map it wants. While the
		// platform has a beacon or an approved randomness provider, nobody
		// may opt out.
		if beaconAvailable() {
			panic("the platform beacon is configured; launch with useBeacon")
		}
	}

	checkLaunch(c, types.ModeReveal)

	c.prov = &provenance{creatorCommit: commit, acc: safe.InitialEntropy(runtime.ChainID(), c.id)}
	c.startHeight, c.endHeight, c.revealWindow = l.StartHeight, l.EndHeight, l.RevealWindow
	c.useBeacon = l.UseBeacon
	c.beaconSource = source
	c.mode = types.ModeReveal
	schedule(c)
}

// launchOpen is Launch in open mode (I-17): no commitment, no beacon or
// provider, no reveal window. The salt is public (openSalt) and anyone may
// finalize once the sale is Closed.
func launchOpen(c *collection, l types.LaunchSpec) {
	if l.CreatorCommit != "" || l.UseBeacon || l.BeaconSource != "" {
		panic("an open launch has no creatorCommit, useBeacon or beaconSource")
	}
	if l.RevealWindow != 0 {
		panic("an open launch has revealWindow 0")
	}
	checkLaunch(c, types.ModeOpen)
	c.prov = &provenance{acc: safe.InitialEntropy(runtime.ChainID(), c.id)}
	c.startHeight, c.endHeight, c.revealWindow = l.StartHeight, l.EndHeight, 0
	c.useBeacon, c.beaconSource = false, ""
	c.mode = types.ModeOpen
	schedule(c)
}

// checkLaunch refuses an engine that was deprecated or superseded after the
// Draft was made (WP-J J-1: I-14's "no new sales" covers Launch and every
// relaunch after AbortLaunch, not only CreateCollection; a collection that
// is already Scheduled or later is not touched), then runs the engine's
// launch gate (I-16: the creator's own tx; everything the engine needs is
// passed in). An engine that implements engine.LaunchGate is then asked
// again with the launch mode (e.g. an engine that only works in reveal
// mode refuses an open launch).
func checkLaunch(c *collection, mode string) {
	rec := mustEngine(c.engineID)
	assertEngineUsable(rec)
	if err := rec.impl.CheckLaunch(c.id, c.params, c.maxSupply); err != nil {
		panic("launch refused by engine: " + err.Error())
	}
	if g, ok := rec.impl.(engine.LaunchGate); ok {
		err := g.GateLaunch(engine.Collection{ID: c.id, Creator: c.creator, Params: c.params,
			MaxSupply: c.maxSupply, Mode: mode, Soulbound: c.soulbound})
		if err != nil {
			panic("launch refused by engine: " + err.Error())
		}
	}
}

// assertEngineUsable is the engine gate of Launch: claimed, not deprecated,
// not superseded (CreateCollection's createAccess starts with the same
// checks and texts). The access policy is not judged again (I-19).
func assertEngineUsable(rec *engineRecord) {
	if !rec.claimed {
		panic("engine is not claimed by its author yet")
	}
	assertEngineNotRetired(rec)
}

// schedule snapshots the fees and moves c to Scheduled (both modes).
func schedule(c *collection) {
	c.primaryBps = fees.PrimaryBps
	c.engineAuthor, c.engineBps = engineFeeQuote(c)
	c.state = types.StateScheduled
	commit := ""
	if c.prov != nil {
		commit = c.prov.creatorCommit
	}
	chain.Emit("CollectionScheduled",
		"cid", c.id, "start", itoa(c.startHeight), "end", itoa(c.endHeight),
		"revealWindow", itoa(c.revealWindow), "useBeacon", boolStr(c.useBeacon),
		"beaconSource", c.beaconSource, "creatorCommit", commit,
		"engineAuthor", c.engineAuthor.String(), "engineFeeBps", itoa(c.engineBps),
		"mode", modeName(c.mode))
}

// modeName is the mode as shown in events and JSON ("reveal" or "open").
func modeName(m string) string {
	if m == types.ModeOpen {
		return types.ModeOpen
	}
	return "reveal"
}

// collectionTraitTypes asks the engine for the collection's trait list
// (I-16) and returns a core-owned copy, or nil when it equals the
// manifest's (nothing extra stored).
func collectionTraitTypes(rec *engineRecord, params string) []string {
	tts := rec.impl.TraitTypes(params)
	if err := engine.ValidateTraitTypes(tts); err != nil {
		panic("trait types rejected: " + err.Error())
	}
	if sameList(tts, rec.manifest.TraitTypes) {
		return nil
	}
	return append([]string{}, tts...)
}

func sameList(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// traitTypesOf is c's effective trait list (shared; callers copy before
// handing it out).
func traitTypesOf(c *collection) []string {
	if c.traitTypes != nil {
		return c.traitTypes
	}
	return mustEngine(c.engineID).manifest.TraitTypes
}

// AbortLaunch returns a launched collection to Draft while nothing has been
// minted — the way out when a beacon never commits. A commitment whose
// secret was revealed is burned for this collection; unrevealed ones (the
// beacon's deterministic one included) may be committed again (SA-L1).
func AbortLaunch(cur realm, cid string) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	refresh(c, height())
	if c.state == types.StateDraft || c.state == types.StateFinal {
		panic("only a launched, unfinished collection can be aborted")
	}
	if c.minted() > 0 {
		panic("tokens were minted; the launch can no longer be aborted")
	}
	if c.prov.creatorRevealed {
		c.burnedCommits = append(c.burnedCommits, c.prov.creatorCommit)
	}
	if c.prov.beaconRevealed {
		c.burnedCommits = append(c.burnedCommits, c.prov.beaconCommit)
	}
	c.prov = nil
	c.startHeight, c.endHeight, c.revealWindow, c.closeHeight = 0, 0, 0, 0
	c.useBeacon, c.beaconSource, c.mode = false, "", types.ModeReveal
	c.engineBps, c.engineAuthor = 0, ""
	c.state = types.StateDraft
	chain.Emit("CollectionState", "cid", c.id, "state", c.state.String())
}

// ReserveTo mints the creator's reserve before the sale starts. Reserve
// mints feed the entropy like any mint, appear in Provenance, and do not
// count toward wallet caps.
func ReserveTo(cur realm, cid string, to address, n int64) (first, last int64) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	assertNotPaused("mint")
	h := height()
	refresh(c, h)
	if c.state != types.StateScheduled {
		panic("reserve is only possible after launch and before the sale starts")
	}
	if c.mode == types.ModeOpen {
		panic("an open collection has no creator reserve")
	}
	// SA-M2: a reserve is the creator's own allocation; it needs a map the
	// creator cannot steer, i.e. the beacon.
	if !c.useBeacon {
		panic("a creator reserve needs a beacon launch")
	}
	// A reserve is a mint, and the beacon may only commit while nothing is
	// minted: reserving first would leave the collection unmintable and
	// unabortable (found on Onyx, collection 1). A randomness provider has
	// nothing to commit: its value is drawn only after the reveal starts.
	if awaitingBeaconCommit(c) {
		panic("waiting for the beacon commitment; reserve after the beacon commits")
	}
	assertMintCount(c, n)
	if c.reserved+n > c.maxSupply*MaxReserveBps/safe.BpsDenominator {
		panic("reserve would exceed " + itoa(MaxReserveBps/100) + "% of supply")
	}
	first, last = mintBatchTo(c, to, n, h)
	c.reserved += n
	c.reservedTo.Set(to.String(), reservedTo(c, to)+n)
	emitBatch("Reserved", c, to, first, last)
	return first, last
}

// MintTo mints n tokens during the sale. The minter has already checked
// phase, price, allowlist and wallet cap; core re-checks only what it owns:
// state, supply and the beacon commitment (I-5). The lifetime counter of
// I-9 is the grc721 balance itself (mintedBy).
func MintTo(cur realm, cid string, to address, n int64) (first, last int64) {
	c := mustCollection(cid)
	assertBoundMinter(cur, c)
	assertNotPaused("mint")
	h := height()
	refresh(c, h)
	if c.state != types.StateMinting {
		panic("collection is not minting (state " + c.state.String() + ")")
	}
	if awaitingBeaconCommit(c) {
		panic("waiting for the beacon commitment; minting has not opened")
	}
	assertMintCount(c, n)
	first, last = mintBatchTo(c, to, n, h)
	if c.minted() == c.maxSupply {
		c.closeHeight = h
		c.state = types.StateClosed
		chain.Emit("CollectionState", "cid", c.id, "state", c.state.String())
	}
	emitBatch("MintBatch", c, to, first, last)
	return first, last
}

func assertMintCount(c *collection, n int64) {
	if n <= 0 || n > MaxMintPerTx {
		panic("count must be 1.." + itoa(MaxMintPerTx))
	}
	if c.minted()+n > c.maxSupply {
		panic("only " + itoa(c.maxSupply-c.minted()) + " tokens left")
	}
}

// mintBatchTo is the only place tokens come into existence.
func mintBatchTo(c *collection, to address, n, h int64) (first, last int64) {
	first = c.nextTID
	last = first + n - 1
	for tid := first; tid <= last; tid++ {
		if err := c.ledger.Mint(to, grc721.TokenID(itoa(tid))); err != nil {
			panic(err)
		}
	}
	c.nextTID = last + 1
	c.st.appendTokens(first, last, h)
	c.st.appendOwners(first, last, to)
	c.prov.acc = safe.MixEntropy(c.prov.acc, to, h, first, last)
	return first, last
}

// mintedBy is addr's lifetime count of sale mints (I-9) while the
// collection is not Final: before Final no token can move or burn (I-11,
// lockExt) and tokens only come from mintBatchTo, so the grc721 balance is
// exactly sale mints + reserves received. This replaces a stored counter
// (~2 KB per new wallet, storage-cost-analysis P2). After Final the
// balance moves freely and no minter needs the count any more: -1.
func mintedBy(c *collection, addr address) int64 {
	if c.st.final {
		return -1
	}
	bal, err := c.token.BalanceOf(addr)
	if err != nil {
		return 0
	}
	return bal - reservedTo(c, addr)
}

func reservedTo(c *collection, addr address) int64 {
	if v := c.reservedTo.Get(addr.String()); v != nil {
		return v.(int64)
	}
	return 0
}

// awaitingBeaconCommit: a committed-beacon launch whose beacon has not
// committed yet; nothing may be minted (or reserved) before it does.
func awaitingBeaconCommit(c *collection) bool {
	return c.useBeacon && c.beaconSource == types.BeaconCommitted && c.prov.beaconCommit == ""
}

// CloseMint materializes Closed once the sale window has passed. Anyone may
// call it; reveals and Finalize work without it.
func CloseMint(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	refresh(c, height())
	if c.state != types.StateClosed {
		panic("the sale is not over (state " + c.state.String() + ")")
	}
}

// --- creator -----------------------------------------------------------------

// TransferCreator starts a two-step handover (RA M-11).
func TransferCreator(cur realm, cid string, to address) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	if !to.IsValid() {
		panic("invalid address")
	}
	c.pendingCreator = to
	chain.Emit("CreatorTransferStarted", "cid", c.id, "from", c.creator.String(), "to", to.String())
}

func AcceptCreator(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	who := caller(cur)
	if c.pendingCreator == "" || who != c.pendingCreator {
		panic("no pending creator transfer to this address")
	}
	byCreator.Remove(c.creator.String() + ":" + collKey(c.id))
	byCreator.Set(who.String()+":"+collKey(c.id), c.id)
	chain.Emit("CreatorTransferred", "cid", c.id, "from", c.creator.String(), "to", who.String())
	c.creator = who
	c.pendingCreator = ""
}

// SetPayees changes the royalty split after Final. The primary-sale split is
// frozen with the sale (I-6); the royalty receiver stays the collection's
// sub-treasury, so third-party markets are unaffected. Royalties earned so
// far are first paid to the current payees (SA-I4).
func SetPayees(cur realm, cid, payees string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	if c.state != types.StateFinal {
		panic("royalty payees can change only after the collection is final")
	}
	ps := safe.ParsePayees("royaltyPayees", payees, MaxPayees)
	assertPayees("royaltyPayees", ps, c.id, c.engineID)
	distribute(cur, c)
	c.royaltyPayees = ps
	chain.Emit("RoyaltyPayees", "cid", c.id, "payees", payees)
}

// assertPayees refuses payees that can never spend what they receive
// (SA-L5): the platform's own realms and sub-addresses. cid is the
// collection being configured, engineID its engine adapter.
func assertPayees(field string, ps []types.Payee, cid, engineID string) {
	for _, p := range ps {
		assertSpendable(field, p.Addr, cid, engineID)
	}
}

// assertSpendable panics for core, core's sub-addresses of collection cid
// (token identity c/<cid>, royalty treasury roy/<cid>), the engine adapter,
// and every address of the deny set: the static platform realms next to
// core, every minter ever approved and every payee.deny realm (I-18). None
// of them has a path that spends an incoming payment, so the coins would be
// stranded (I-3).
func assertSpendable(field string, addr address, cid, engineID string) {
	bad := []address{chain.PackageAddress(selfPath)}
	if cid != "" {
		bad = append(bad, chain.DerivePkgSubAddr(selfPath, "c/"+cid), royaltyAddress(cid))
	}
	if engineID != "" {
		bad = append(bad, chain.PackageAddress(engineID))
	}
	for _, b := range bad {
		if addr == b {
			panic(field + ": " + addr.String() + " is a platform realm address that cannot spend; use a wallet")
		}
	}
	if v := deniedPayees.Get(addr.String()); v != nil {
		d := v.(*deniedPayee)
		if d.source == "minter" {
			panic(field + ": " + addr.String() + " is the minter realm " + d.path + "; use a wallet")
		}
		panic(field + ": " + addr.String() + " is the platform realm " + d.path + " that cannot spend; use a wallet")
	}
}

func assertCreator(cur realm, c *collection) {
	if caller(cur) != c.creator {
		panic("only the collection's creator can do this")
	}
}

func assertBoundMinter(cur realm, c *collection) {
	if cur.Previous().PkgPath() != c.minter {
		panic("only the collection's bound minter (" + c.minter + ") can do this")
	}
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

