// Hard limits. They are constants on purpose: nobody, admin included, can
// raise them after deploy (block counts assume ~3.54 s blocks, RA M-1).
const (
	ProtocolFeeCapBps  = 500           // 5% of any sale
	RoyaltyCapBps      = 1000          // 10% (RA M-3)
	CreateFeeCap       = 1_000_000_000 // 1,000 GNOT in ugnot
	MaxPayees          = 4
	MaxSupplyCap       = 10_000
	MaxMintPerTx       = 10               // hypothesis: measure n=10 gas/deposit on Onyx
	MaxReserveBps      = 1000             // creator reserve <= 10% of supply
	MaxSaleBlocks      = 732_000          // ~30 days
	RevealWindowMin    = 1_017            // ~1 hour
	RevealWindowMax    = 170_000          // ~7 days
	BeaconGraceBlocks  = 254              // beacon may reveal first in the window's last ~15 min (< RevealWindowMin, so the creator always gets to go first)
	TimelockBlocks     = 48_800           // ~48 hours
	MaxPauseBlocks     = 195_000          // ~8 days: pause budget per scope and window
	PauseWindowBlocks  = 732_000          // ~30 days (SA-L2)
	EngineFeeCapBps    = engine.MaxFeeBps // 5%: hard cap of an engine author's fee (platform cap <= this)
	ProviderWaitBlocks = 24_400           // ~24 h: Finalize waits this long after the deadline (or the round's binding) for a provider's round before falling back (CV-M1)
	ListingDepositCap  = 5_000_000        // 5 GNOT: hard cap of the market's listing deposit return (op listing.deposit, CV-L2)

	MaxNameLen        = 64
	MaxDescriptionLen = 1024
	MaxParamsLen      = 1024
	MinSecretLen      = 32
	MaxSecretLen      = 256
	MaxPageSize       = 50

	// Engine registry (ENG-M1, I-14).
	ReservationTTLBlocks = 170_000 // ~7 days: a fingerprint reservation is usable this long
	UnclaimedHoldBlocks  = 24_400  // ~1 day: an unclaimed record stops blocking the same art after this
	MinReserveSaltLen    = 32
	MaxReserveSaltLen    = 256

	// MaxDeniedPayees bounds the payee.deny entries (each payee check
	// looks the address up once; the bound only caps admin-made growth).
	MaxDeniedPayees = 64
)

// CoreVersion tells indexers and frontends which core they read (M-26).
const CoreVersion = "sinopia-core/4"

// Provenance badges (design §4.3).
const (
	BadgeBoth        = "2/2"
	BadgeCreatorOnly = "creator-only"
	BadgeBeaconOnly  = "beacon-only"
	BadgeFallback    = "fallback"
	BadgeOpen        = "open" // open mode: no secrets, never a fair launch (I-17)
)

type collection struct {
	id, name, symbol, description string
	creator, pendingCreator       address
	engineID, params              string
	traitTypes                    []string // the collection's trait list when it differs from the manifest's (nil = manifest)
	mode                          string   // types.ModeReveal or types.ModeOpen, set at Launch
	soulbound                     bool     // non-transferable, fixed at creation (I-20)
	maxSupply                     int64
	nextTID                       int64 // next token id; minted so far = nextTID-1
	reserved                      int64
	royaltyBps                    int64
	primaryPayees, royaltyPayees  []types.Payee
	minter                        string
	state                         types.State
	startHeight, endHeight        int64
	revealWindow                  int64
	closeHeight                   int64 // sell-out height, or endHeight once time ran out
	useBeacon                     bool
	beaconSource                  string // with useBeacon: types.BeaconCommitted or a randomness provider path
	createdHeight                 int64
	primaryBps                    int64    // protocol fee snapshot at Launch (SA-I5)
	engineBps                     int64    // engine-author fee snapshot at Launch (0 when creator == author)
	engineAuthor                  address  // who receives engineBps
	access                        string   // AccessAuthor, AccessLicence or AccessOpen: how the creator could use the engine (I-19)
	licenceFee                    int64    // engine fee of the licence it was created under, or LicenceFeeDefault (manifest fee)
	burnedCommits                 []string // commitments whose secret went public; never accepted again here (SA-L1)
	approvals                     avl.Tree // "o:"+owner+":"+operator -> int64 nonce (SA-L3; token nonces are packed in st)
	prov                          *provenance
	token                         *grc721.Token
	ledger                        *grc721.PrivateLedger
	roy                           *royalty.Royalty
	st                            *tokenState
	reservedTo                    avl.Tree // address -> int64 reserve tokens received (MintedBy = balance - this, I-9)
}

func (c *collection) minted() int64 { return c.nextTID - 1 }

var (
	// selfPath is this realm's package path, captured once in init so read
	// functions can derive sub-addresses without a cur.
	selfPath string

	collections avl.Tree // safe.PadInt(cid) -> *collection
	byCreator   avl.Tree // creator + ":" + padded cid -> cid
	collCount   int64
)

func init(cur realm) {
	selfPath = cur.PkgPath()
	initDeniedPayees()
}

// Version is CoreVersion (M-26).
func Version() string { return CoreVersion }

const cidWidth = 10

// collKey accepts a collection id as "<cid>" or as its token sub-path
// "c/<cid>" (the form a wallet derives from Token.ID(), "…/core#c/<cid>";
// K-1). Every function that takes a cid resolves it through
// mustCollection and then uses c.id only.
func collKey(cid string) string {
	if len(cid) > 2 && cid[0] == 'c' && cid[1] == '/' {
		cid = cid[2:]
	}
	return safe.PadInt(safe.ParseID("cid", cid), cidWidth)
}

func mustCollection(cid string) *collection {
	v := collections.Get(collKey(cid))
	if v == nil {
		panic("unknown collection " + strconv.Quote(cid))
	}
	return v.(*collection)
}

// stateAt is the effective state at height h; the stored state lags until
// the next write materializes it (refresh).
func stateAt(c *collection, h int64) types.State {
	switch c.state {
	case types.StateScheduled:
		if h > c.endHeight {
			return types.StateClosed
		}
		if h >= c.startHeight {
			return types.StateMinting
		}
	case types.StateMinting:
		if h > c.endHeight {
			return types.StateClosed
		}
	}
	return c.state
}

func refresh(c *collection, h int64) {
	s := stateAt(c, h)
	if s == c.state {
		return
	}
	if s == types.StateClosed && c.closeHeight == 0 {
		c.closeHeight = c.endHeight
	}
	c.state = s
	chain.Emit("CollectionState", "cid", c.id, "state", s.String())
}

// revealDeadline is when anyone may finalize without the missing secrets.
// It is at most endHeight + RevealWindowMax, which bounds the transfer
// lock (I-11).
func revealDeadline(c *collection) int64 {
	closed := c.closeHeight
	if closed == 0 {
		closed = c.endHeight
	}
	return closed + c.revealWindow
}

func caller(cur realm) address {
	return cur.Previous().Address()
}

// assertNoDeposit refuses coins on functions that take none, so nothing can
// get stuck in core (RA L-1). The origin-send envelope belongs to the first
// realm of the call; it is only ours to judge when a wallet called us.
func assertNoDeposit(cur realm) {
	if cur.Previous().IsUserCall() && !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func height() int64 { return runtime.ChainHeight() }

package core

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/engine/v2"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
)

// Engine registry ("art as code", design §5).
//
// An engine registers itself from its own /r/ adapter realm; its id is that
// realm's package path, so nobody can register in someone else's name. The
// stored interface value's methods are declared in the adapter, so every
// call runs with the adapter's authority, not core's (interrealm v2 borrow
// rule #1): engine code cannot write core state. It also cannot call back
// into a core mutator: all of core's state-changing functions are crossing
// and need a live cur the engine never has.
//
// Honest limits, surfaced to users rather than hidden:
//   - an adapter realm with state could change its art later; the sample
//     fingerprint (VerifyEngine) detects a change of the sample, and review
//     means reading the adapter for statelessness;
//   - a private (re-deployable) adapter cannot register: the VM aborts the
//     registration when core's state would retain the private realm's type
//     (spike A9, observed in gno v1.7.0 test mode; confirm on Onyx).
type engineRecord struct {
	id               string
	impl             engine.Engine
	manifest         engine.Manifest // core-owned copy
	fingerprint      string          // sha256 of Render(SampleInput())
	claimed          bool
	deprecated       bool
	deprecatedBy     string // "author" or "admin" (engine.deprecate)
	superseded       bool   // a reserved registration of the same art won (I-14)
	supersededBy     string // engine id
	reviewed         bool
	registeredHeight int64
	reservation      string // reservationSource, reservationCommit or ""
	priority         int64  // 0 (in source), the reservation height, or registeredHeight
	collections      int64  // collections created on this engine (CollectionsByEngine)
	policy           string // PolicyClosed (at registration), PolicyLicensed or PolicyOpen (access.gno, I-19)
	licences         int64  // live licences (<= MaxLicencesPerEngine)
}

// Engine statuses (EngineStatus, engine JSON "status").
const (
	EngineUnclaimed  = "unclaimed"
	EngineUnverified = "unverified"
	EngineReviewed   = "reviewed"
	EngineDeprecated = "deprecated"
	EngineSuperseded = "superseded"
)

const (
	reservationSource = "source" // fingerprint reserved in config.gno
	reservationCommit = "commit" // backed by a ReserveFingerprint commitment
)

var (
	engines       avl.Tree // engine id -> *engineRecord
	engineOrder   avl.Tree // safe.PadInt(seq) -> engine id
	byFingerprint avl.Tree // fingerprint + ":" + engine id -> "" (CV-L3)
	byEngine      avl.Tree // engine id + ":" + padded cid -> cid (CollectionsByEngine, M-18)
	engineCount   int64

	// reservations: author + ":" + commit -> *fpReservation (ENG-M1). Keyed
	// by author so copying a pending commitment from the mempool only
	// creates a useless entry under the copier's own address.
	reservations avl.Tree
)

type fpReservation struct {
	height int64
}

// RegisterEngine stores the calling realm's engine (I-16: the manifest,
// default params and one sample render with its traits, in the engine's
// own registration transaction). The record is immutable afterwards except
// for the claim/deprecate/review/superseded flags, the collection count and
// the access policy (access.gno: every engine starts closed).
//
// salt is "" or the salt of a ReserveFingerprint commitment made by the
// manifest author (ENG-M1 rule 2). Fingerprint rules (I-14), with signer =
// OriginCaller:
//   - every registration must be signed by its manifest author (signer ==
//     Manifest.Author; WP-J J-2: otherwise a tx the author of a live engine
//     signs into a foreign realm could register a re-wrap of that art under
//     another author, since CV-L3 exempts the author's own versions);
//   - a fingerprint reserved in source (config.gno) registers only with
//     signer == Manifest.Author == its reserved author;
//   - a live record of the same art by another author (not deprecated, not
//     superseded) blocks the registration (CV-L3) unless this registration
//     is reserved in source, or backed by a reservation made before that
//     record's own priority (so the record was registered after the
//     reservation's commit; WP-J J-3), or the record is unclaimed and older
//     than UnclaimedHoldBlocks; such records are marked superseded instead.
func RegisterEngine(cur realm, e engine.Engine, salt string) string {
	id := cur.Previous().PkgPath()
	if !strings.HasPrefix(id, runtime.ChainDomain()+"/r/") || strings.Contains(id, "#") {
		panic("an engine registers from its own realm (an /r/ package, not a sub-realm or wallet)")
	}
	if e == nil {
		panic("nil engine")
	}
	if engines.Has(id) {
		panic("engine already registered: " + id + " (publish a new version under a new path)")
	}
	m := copyManifest(e.Manifest())
	if err := engine.ValidateManifest(m); err != nil {
		panic(err)
	}
	if err := e.ValidateParams(""); err != nil {
		panic("engine must accept empty params (its defaults): " + err.Error())
	}
	sample := e.Render(engine.SampleInput())
	if err := engine.CheckSVG(m, sample); err != nil {
		panic("sample render: " + err.Error())
	}
	if err := engine.ValidateTraits(m, e.Traits(engine.SampleInput())); err != nil {
		panic("sample traits: " + err.Error())
	}

	fp := safe.Sha256Hex(sample)
	h := height()
	signer := unsafe.OriginCaller()
	kind, priority, resKey := registrationPriority(fp, m.Author, signer, salt, h)
	losers := conflicts(fp, m.Author, kind, priority, h)
	// every check passed: consume the reservation, then write
	if resKey != "" {
		reservations.Remove(resKey)
	}
	rec := &engineRecord{
		id:               id,
		impl:             e,
		manifest:         m,
		fingerprint:      fp,
		registeredHeight: h,
		reservation:      kind,
		priority:         priority,
		policy:           PolicyClosed,
	}
	engines.Set(id, rec)
	byFingerprint.Set(fp+":"+id, "")
	engineCount++
	engineOrder.Set(safe.PadInt(engineCount, cidWidth), id)
	chain.Emit("EngineRegistered", "id", id, "author", m.Author.String(), "feeBps", itoa(m.FeeBps),
		"fingerprint", rec.fingerprint, "kind", m.Kind, "reservation", kind)
	for _, l := range losers {
		l.superseded, l.supersededBy = true, id
		chain.Emit("EngineSuperseded", "id", l.id, "by", id)
	}
	return id
}

// registrationPriority applies the reservation rules and returns the
// registration's kind, priority (lower wins) and the reservation key it
// consumes ("" for none). It writes nothing.
func registrationPriority(fp string, author, signer address, salt string, h int64) (string, int64, string) {
	if reserved, ok := reservedAuthorOf(fp); ok {
		if signer != reserved || author != reserved {
			panic("fingerprint " + fp + " is reserved for " + reserved.String() +
				"; only that author may register it (signed by and named in the manifest)")
		}
		return reservationSource, 0, ""
	}
	if signer != author {
		panic("an engine registration must be signed by the manifest author " + author.String())
	}
	if salt == "" {
		return "", h, ""
	}
	if len(salt) < MinReserveSaltLen || len(salt) > MaxReserveSaltLen {
		panic("reservation salt must be " + itoa(MinReserveSaltLen) + ".." + itoa(MaxReserveSaltLen) + " bytes")
	}
	safe.AssertText("salt", salt, MaxReserveSaltLen)
	commit := ReservationCommit(runtime.ChainID(), fp, author, salt)
	key := author.String() + ":" + commit
	v := reservations.Get(key)
	if v == nil {
		panic("no fingerprint reservation of " + author.String() + " matches this engine and salt")
	}
	r := v.(*fpReservation)
	if h <= r.height {
		panic("the reservation is usable from height " + itoa(r.height+1))
	}
	if h > r.height+ReservationTTLBlocks {
		panic("the reservation expired at height " + itoa(r.height+ReservationTTLBlocks))
	}
	return reservationCommit, r.height, key
}

// conflicts returns the live records of the same art by other authors that
// this registration (by author, who signed it) supersedes, and panics on one
// that blocks it (CV-L3, I-14). A deprecated or superseded record never
// blocks.
//
// A commit reservation (priority = its ReserveFingerprint height) beats only
// a record with a later priority: a plain record registered after the
// commit height, or a record backed by a later reservation. A record
// registered at or before the commit height — claimed or not — is never
// superseded by it (WP-J J-3; rec.priority <= rec.registeredHeight, so a
// later priority implies a later registration). Unclaimed records still
// expire after UnclaimedHoldBlocks for every registration.
func conflicts(fp string, author address, kind string, priority, h int64) []*engineRecord {
	var losers []*engineRecord
	byFingerprint.Iterate(fp+":", fp+";", func(k string, _ any) bool {
		rec := mustEngine(k[len(fp)+1:])
		if rec.deprecated || rec.superseded || rec.manifest.Author == author {
			return false
		}
		switch {
		case kind == reservationSource:
		case !rec.claimed && h > rec.registeredHeight+UnclaimedHoldBlocks:
		case kind == reservationCommit && rec.priority > priority && rec.registeredHeight > priority:
		default:
			panic("engine renders the same art as " + rec.id + "; only its author " + rec.manifest.Author.String() +
				" may register another version (or deprecate it first)")
		}
		losers = append(losers, rec)
		return false
	})
	return losers
}

// reservedAuthorOf is fp's in-source reserved author (config.gno).
func reservedAuthorOf(fp string) (address, bool) {
	for _, r := range reservedFingerprints {
		if r.fingerprint == fp {
			return r.author, true
		}
	}
	return "", false
}

// ReserveFingerprint records a commitment to register an engine whose art
// is not public yet (ENG-M1 rule 2):
//
//	commit = ReservationCommit(chainId, fingerprint, author, salt)
//
// with salt 32..256 bytes. The caller (a wallet) is the author; the
// reservation is usable from the next block for ReservationTTLBlocks by a
// RegisterEngine(…, salt) signed by that author with that Manifest.Author.
// The commitment reveals nothing, so it cannot be front-run.
func ReserveFingerprint(cur realm, commitHex string) {
	assertNoDeposit(cur)
	if !cur.Previous().IsUserCall() {
		panic("reserve a fingerprint from the author's wallet")
	}
	author := caller(cur)
	commit := safe.AssertHex("commit", commitHex, 32)
	key := author.String() + ":" + commit
	h := height()
	if v := reservations.Get(key); v != nil && h <= v.(*fpReservation).height+ReservationTTLBlocks {
		panic("this commitment is already reserved until height " + itoa(v.(*fpReservation).height+ReservationTTLBlocks))
	}
	reservations.Set(key, &fpReservation{height: h})
	chain.Emit("FingerprintReserved", "author", author.String(), "commit", commit,
		"height", itoa(h), "expires", itoa(h+ReservationTTLBlocks))
}

// ReservationCommit is the commitment ReserveFingerprint takes:
// sha256("art|fpres|v1|" + chainID + "|" + fp + "|" + author + "|" + salt).
func ReservationCommit(chainID, fp string, author address, salt string) string {
	return safe.Sha256Hex(safe.Domain + "|fpres|v1|" + chainID + "|" + fp + "|" + author.String() + "|" + salt)
}

// Reservation is the reservation of author for commitHex as JSON
// {author, commit, height, validFrom, expires, active}, or null.
func Reservation(author address, commitHex string) string {
	v := reservations.Get(author.String() + ":" + commitHex)
	if v == nil {
		return "null"
	}
	r := v.(*fpReservation)
	h := height()
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("author", author.String())
	w.StrField("commit", commitHex)
	w.IntField("height", r.height)
	w.IntField("validFrom", r.height+1)
	w.IntField("expires", r.height+ReservationTTLBlocks)
	w.BoolField("active", h > r.height && h <= r.height+ReservationTTLBlocks)
	w.EndObject()
	return w.String()
}

// ReservedAuthor is fp's in-source reserved author, or "".
func ReservedAuthor(fp string) address {
	a, _ := reservedAuthorOf(fp)
	return a
}

// ReservedFingerprints is the in-source table as JSON [{name, fingerprint, author}].
func ReservedFingerprints() string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	for _, r := range reservedFingerprints {
		w.BeginObject()
		w.StrField("name", r.name)
		w.StrField("fingerprint", r.fingerprint)
		w.StrField("author", r.author.String())
		w.EndObject()
	}
	w.EndArray()
	return w.String()
}

// ClaimEngine proves the manifest author controls that address. Unclaimed
// engines cannot back a collection.
func ClaimEngine(cur realm, id string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	if caller(cur) != rec.manifest.Author {
		panic("only the manifest author " + rec.manifest.Author.String() + " can claim this engine")
	}
	rec.claimed = true
	chain.Emit("EngineClaimed", "id", id)
}

// DeprecateEngine stops new collections; existing ones keep rendering.
func DeprecateEngine(cur realm, id string) {
	assertNoDeposit(cur)
	rec := mustEngine(id)
	if !rec.claimed || caller(cur) != rec.manifest.Author {
		panic("only the engine's author can deprecate it")
	}
	rec.deprecated, rec.deprecatedBy = true, "author"
	chain.Emit("EngineDeprecated", "id", id, "by", "author")
}

// --- engine-author fee ---------------------------------------------------------
//
// An engine's author earns FeeBps (manifest, fixed at registration, <=
// EngineFeeCapBps) of every primary and secondary sale of a collection that
// uses the engine, capped by the platform's fees.EngineCapBps. A collection
// snapshots the fee at Launch (like the protocol fee, SA-I5) and later sales
// pay min(snapshot, current platform cap), so neither the author nor the
// admin can raise it on a running collection. No fee when the creator is
// the author: the creator's own payees already get the sale.

// engineFeeOf is the engine's fee under the current platform cap.
func engineFeeOf(rec *engineRecord) int64 {
	if rec.manifest.FeeBps < fees.EngineCapBps {
		return rec.manifest.FeeBps
	}
	return fees.EngineCapBps
}

// engineFeeQuote is what c would snapshot at a Launch now.
func engineFeeQuote(c *collection) (address, int64) {
	rec := mustEngine(c.engineID)
	author := rec.manifest.Author
	if author == c.creator {
		return author, 0
	}
	if c.licenceFee == LicenceFeeDefault {
		return author, engineFeeOf(rec)
	}
	if c.licenceFee < fees.EngineCapBps {
		return author, c.licenceFee
	}
	return author, fees.EngineCapBps
}

// collectionEngineFee is the fee a sale of c pays now: the Launch snapshot
// bounded by the current cap; before Launch, the current quote.
func collectionEngineFee(c *collection) (address, int64) {
	if c.prov == nil {
		return engineFeeQuote(c)
	}
	if c.engineBps < fees.EngineCapBps {
		return c.engineAuthor, c.engineBps
	}
	return c.engineAuthor, fees.EngineCapBps
}

// EngineFee is the engine-author share of cid's sales: the author and the
// bps a sale pays now (0 when the creator is the author). mint/v1 and
// market/v1 pay safe.BpsOf(amount, bps) to author.
func EngineFee(cid string) (author address, bps int64) {
	return collectionEngineFee(mustCollection(cid))
}

func mustEngine(id string) *engineRecord {
	v := engines.Get(id)
	if v == nil {
		panic("unknown engine " + id)
	}
	return v.(*engineRecord)
}

// copyManifest gives core its own copy: the engine's slice was allocated in
// the engine realm.
func copyManifest(m engine.Manifest) engine.Manifest {
	out := m
	out.TraitTypes = append([]string{}, m.TraitTypes...)
	return out
}

// --- engine reads (Studio, Verify) -------------------------------------------

// RenderWith renders any registered engine for arbitrary params and seed as
// a data URI — Studio previews and the Verify button. For a media engine it
// is the card.
func RenderWith(id, params, seed string) string {
	return renderChecked(mustEngine(id), studioInput(params, seed))
}

// RenderWithInput is RenderWith for a full Input, so living engines can be
// verified off chain and against their TS twins (M-24). CollectionID and
// TokenID are "0" and Salt "" as in every studio render; firstOwner is
// passed through as Input.FirstOwner ("" = none).
func RenderWithInput(id, params, seed string, mintHeight, lastMove, moves, h int64, firstOwner address) string {
	in := studioInput(params, seed)
	in.MintHeight, in.LastMoveHeight, in.Moves, in.Height = mintHeight, lastMove, moves, h
	in.FirstOwner = firstOwner
	return renderChecked(mustEngine(id), in)
}

func renderChecked(rec *engineRecord, in engine.Input) string {
	if err := rec.impl.ValidateParams(in.Params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	svg := rec.impl.Render(in)
	if err := engine.CheckSVG(rec.manifest, svg); err != nil {
		return dataURI(placeholderSVG(rec.manifest.Name, "Engine output rejected"))
	}
	return dataURI(svg)
}

// EngineTraits returns a core-owned copy of the engine's traits for seed,
// checked against TraitTypes(params).
func EngineTraits(id, params, seed string) []engine.Trait {
	rec := mustEngine(id)
	if err := rec.impl.ValidateParams(params); err != nil {
		panic("params rejected by engine: " + err.Error())
	}
	tts := rec.impl.TraitTypes(params)
	if err := engine.ValidateTraitTypes(tts); err != nil {
		panic("trait types rejected: " + err.Error())
	}
	ts := rec.impl.Traits(studioInput(params, seed))
	if err := engine.ValidateTraitsFor(tts, ts); err != nil {
		panic("engine traits rejected: " + err.Error())
	}
	return append([]engine.Trait{}, ts...)
}

func TraitsWith(id, params, seed string) string {
	w := &safe.JSONWriter{}
	writeTraits(w, EngineTraits(id, params, seed))
	return w.String()
}

// VerifyEngine re-renders the sample and compares it with the fingerprint
// stored at registration.
func VerifyEngine(id string) bool {
	rec := mustEngine(id)
	return safe.Sha256Hex(rec.impl.Render(engine.SampleInput())) == rec.fingerprint
}

// EngineManifest is the typed read for other realms (gallery).
func EngineManifest(id string) engine.Manifest { return copyManifest(mustEngine(id).manifest) }

// EngineStatus is "unclaimed", "unverified", "reviewed", "deprecated" or
// "superseded".
func EngineStatus(id string) string { return engineStatus(mustEngine(id)) }

func engineStatus(rec *engineRecord) string {
	switch {
	case rec.deprecated:
		return EngineDeprecated
	case rec.superseded:
		return EngineSuperseded
	case !rec.claimed:
		return EngineUnclaimed
	case rec.reviewed:
		return EngineReviewed
	}
	return EngineUnverified
}

// Engine is the record as JSON.
func Engine(id string) string {
	w := &safe.JSONWriter{}
	writeEngine(w, mustEngine(id))
	return w.String()
}

func Engines(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	engineOrder.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		writeEngine(w, mustEngine(v.(string)))
		return false
	})
	w.EndArray()
	return w.String()
}

// EnginesByFingerprint pages every record with fingerprint fp, in path
// order (the deploy check's squat scan).
func EnginesByFingerprint(fp string, offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	skipped, written, want := int64(0), int64(0), clampLimit(limit)
	byFingerprint.Iterate(fp+":", fp+";", func(k string, _ any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		writeEngine(w, mustEngine(k[len(fp)+1:]))
		written++
		return written >= want
	})
	w.EndArray()
	return w.String()
}

// CollectionsByEngine pages the collections created on engine id, in
// creation order (M-18). The count is the engine JSON's "collections".
func CollectionsByEngine(id string, offset, limit int64) string {
	mustEngine(id)
	w := &safe.JSONWriter{}
	w.BeginArray()
	prefix := id + ":"
	skipped, written, want := int64(0), int64(0), clampLimit(limit)
	byEngine.Iterate(prefix, prefix+"\xff", func(_ string, v any) bool {
		if skipped < offset {
			skipped++
			return false
		}
		writeCollection(w, mustCollection(v.(string)))
		written++
		return written >= want
	})
	w.EndArray()
	return w.String()
}

func writeEngine(w *safe.JSONWriter, rec *engineRecord) {
	m := rec.manifest
	w.BeginObject()
	w.StrField("id", rec.id)
	w.StrField("pkgPath", rec.id) // the adapter realm; read its source (and imports) with vm/qfile
	w.StrField("name", m.Name)
	w.StrField("version", m.Version)
	w.StrField("description", m.Description)
	w.StrField("license", m.License)
	w.StrField("author", m.Author.String())
	w.IntField("feeBps", m.FeeBps)
	w.IntField("effectiveFeeBps", engineFeeOf(rec))
	w.StrField("paramsSchema", m.ParamsSchema)
	w.Key("traitTypes")
	writeStrings(w, m.TraitTypes)
	w.BoolField("living", m.Living)
	w.IntField("maxSvgBytes", m.MaxSVGBytes)
	w.StrField("kind", m.Kind)
	w.IntField("maxMediaBytes", m.MaxMediaBytes)
	w.StrField("fingerprint", rec.fingerprint)
	w.StrField("status", engineStatus(rec))
	w.IntField("registeredHeight", rec.registeredHeight)
	w.StrField("reservation", rec.reservation)
	w.IntField("priority", rec.priority)
	w.StrField("supersededBy", rec.supersededBy)
	w.StrField("deprecatedBy", rec.deprecatedBy)
	w.IntField("collections", rec.collections)
	w.StrField("policy", rec.policy)
	w.IntField("licences", rec.licences)
	w.EndObject()
}

func writeStrings(w *safe.JSONWriter, list []string) {
	w.BeginArray()
	for _, t := range list {
		w.Str(t)
	}
	w.EndArray()
}

func studioInput(params, seed string) engine.Input {
	in := engine.SampleInput()
	in.Seed = seed
	in.Params = params
	in.Height = height()
	return in
}

package core

import (
	"chain"
	"chain/runtime"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/types/v2"
)

// Commit–reveal v2 (design §4.2–4.3, closes RA H-3, M-5, M-6).
//
// The map is fixed by three inputs: the creator's secret sc, the beacon's
// secret sb and the public mint-entropy accumulator acc. Neither committer
// knows the other's secret while minting is open, so neither can time the
// last mint for a good map. Order of reveals:
//
//  1. nothing is accepted before Closed (an early reveal informs the other
//     side);
//  2. the creator may reveal until revealDeadline - BeaconGraceBlocks; the
//     beacon follows at any time before the deadline;
//  3. inside the last BeaconGraceBlocks only the beacon may reveal. If the
//     creator stayed silent, the beacon's reveal finalizes at once
//     ("beacon-only"), so the creator never sees sb while it can still
//     choose (SA-M1; this also closes the mempool race of a creator
//     front-running the beacon's grace reveal);
//  4. after revealDeadline anyone finalizes with whatever was revealed.
//
// What stays open, by design: the beacon, as last revealer after the
// creator, can still choose between revealing and not (one bit). It runs
// public code and the badge shows the outcome. The transfer lock
// (tokens.gno) keeps anyone from trading on early knowledge until Final.
//
// The second secret sb comes from the committed beacon (below) or, when the
// collection was launched with a randomness provider, from the provider's
// round bound after the creator's turn (randomness.gno); the order rules and
// badges are the same.
//
// A collection launched without the beacon (only possible while no beacon
// or provider is configured, SA-M2) gives the creator the whole choice of the map; it
// can have no creator reserve and is never reported as a fair launch
// (FairLaunch, Provenance "fair").
type provenance struct {
	creatorCommit, beaconCommit string
	acc                         string
	creatorSecret, beaconSecret string
	creatorRevealed             bool
	beaconRevealed              bool
	salt, badge                 string
	finalHeight                 int64
	round                       int64 // randomness provider round (0 = none bound yet; randomness.gno)
	roundHeight                 int64 // height the round was bound at; its value is taken only later (CV-I6)
}

const (
	roleCreator = "creator"
	roleBeacon  = "beacon"
)

// BeaconCommit is the beacon's commitment, before any token exists.
func BeaconCommit(cur realm, cid, commitHex string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if beacon == "" || caller(cur) != beacon {
		panic("only the configured beacon can commit")
	}
	if c.state == types.StateDraft || c.prov == nil || !c.useBeacon || usesProvider(c) {
		panic("this collection is not waiting for a beacon")
	}
	if c.prov.beaconCommit != "" {
		panic("the beacon already committed")
	}
	if c.minted() > 0 {
		panic("too late: tokens were minted before the beacon committed")
	}
	commit := safe.AssertHex("commit", commitHex, 32)
	if isBurned(c, commit) {
		panic("this commitment's secret was already revealed for this collection")
	}
	c.prov.beaconCommit = commit
	chain.Emit("BeaconCommitted", "cid", c.id, "commit", commit)
}

func RevealCreatorSecret(cur realm, cid, secret string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	assertCreator(cur, c)
	assertNotOpen(c)
	h := height()
	assertRevealOpen(c, h)
	if c.prov.creatorRevealed {
		panic("the creator secret is already revealed")
	}
	if c.useBeacon {
		// SA-M1: once the grace period starts only the beacon may reveal, so
		// the creator can never reveal after seeing sb.
		if c.prov.beaconRevealed {
			panic("the beacon revealed first; the outcome is fixed")
		}
		if h >= revealDeadline(c)-BeaconGraceBlocks {
			panic("the creator's reveal window ended at height " + itoa(revealDeadline(c)-BeaconGraceBlocks-1) +
				"; only the beacon may reveal now")
		}
	}
	assertSecret(c, roleCreator, secret, c.prov.creatorCommit)
	c.prov.creatorSecret = secret
	c.prov.creatorRevealed = true
	chain.Emit("CreatorRevealed", "cid", c.id, "secret", secret)
	if usesProvider(c) && c.prov.round == 0 {
		// CV-M1: the reveal binds the provider's round in the same tx, so
		// nobody can delay, time or skip the request afterwards. If the
		// provider cannot name a fresh round now, anyone binds one later
		// (RequestRandomness, Finalize); the creator's secret is public then.
		bindRound(c, h)
	}
	if revealsComplete(c) && c.minted() > 0 { // SEC-F1: 0 mints stays Closed (abortable)
		finalize(c, h)
	}
}

func RevealBeaconSecret(cur realm, cid, secret string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	if beacon == "" || caller(cur) != beacon {
		panic("only the configured beacon can reveal")
	}
	h := height()
	assertRevealOpen(c, h)
	if !c.useBeacon || usesProvider(c) || c.prov.beaconCommit == "" {
		panic("this collection has no beacon commitment")
	}
	if c.prov.beaconRevealed {
		panic("the beacon secret is already revealed")
	}
	if c.minted() == 0 { // SEC-F1 (SA-I9): a 0-mint sale stays abortable
		panic("nothing was minted; the creator may abort and relaunch instead")
	}
	if !c.prov.creatorRevealed && h < revealDeadline(c)-BeaconGraceBlocks {
		panic("the beacon reveals after the creator, or in the window's last " + itoa(BeaconGraceBlocks) + " blocks")
	}
	assertSecret(c, roleBeacon, secret, c.prov.beaconCommit)
	c.prov.beaconSecret = secret
	c.prov.beaconRevealed = true
	chain.Emit("BeaconRevealed", "cid", c.id, "secret", secret)
	// After the creator: both secrets are in (2/2). First, in the grace
	// period: the creator can no longer reveal, so the map is fixed now
	// (beacon-only) — nobody is left holding a choice (SA-M1).
	finalize(c, h)
}

// Finalize is permissionless and never paused (I-2): immediately once every
// expected secret is revealed, otherwise after revealDeadline (fallback).
// For a provider collection it first binds or consumes the provider's round
// (settleProvider) and falls back only when the provider failed to deliver.
func Finalize(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("only a closed collection can be finalized (state " + c.state.String() + ")")
	}
	if !revealsComplete(c) && h <= revealDeadline(c) {
		panic("the reveal window is open until height " + itoa(revealDeadline(c)))
	}
	// SA-I9: a sale that minted nothing stays Closed, so its creator can
	// still abort and relaunch; nobody else can lock it into Final.
	if c.minted() == 0 {
		panic("nothing was minted; the creator may abort and relaunch instead")
	}
	// CV-M1: a provider collection consumes its round whoever calls; the
	// fallback needs the provider to have failed for ProviderWaitBlocks.
	if usesProvider(c) && settleProvider(c, h) {
		return
	}
	finalize(c, h)
}

func assertRevealOpen(c *collection, h int64) {
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("secrets are accepted only after the sale closed (state " + c.state.String() + ")")
	}
	if h > revealDeadline(c) {
		panic("the reveal window closed; call Finalize")
	}
}

func assertSecret(c *collection, role, secret, commit string) {
	if len(secret) < MinSecretLen || len(secret) > MaxSecretLen {
		panic("secret must be " + itoa(MinSecretLen) + ".." + itoa(MaxSecretLen) + " bytes")
	}
	safe.AssertText("secret", secret, MaxSecretLen)
	if safe.Commit(runtime.ChainID(), c.id, role, secret) != commit {
		panic("secret does not match the " + role + " commitment")
	}
}

func revealsComplete(c *collection) bool {
	if c.mode == types.ModeOpen {
		return true // nothing to reveal: Finalize once Closed (I-17)
	}
	return c.prov.creatorRevealed && (!c.useBeacon || c.prov.beaconRevealed)
}

func assertNotOpen(c *collection) {
	if c.mode == types.ModeOpen {
		panic("an open collection has no secrets")
	}
}

// openSalt is an open collection's salt: public from Launch, so anyone can
// compute every token's art before minting (I-17).
func openSalt(cid string) string {
	return safe.Sha256Hex(safe.Domain + "|open|v1|" + runtime.ChainID() + "|" + cid)
}

// finalize runs at most once per collection (I-10): every caller checks
// state Closed, and this sets Final.
func finalize(c *collection, h int64) {
	p := c.prov
	p.salt = safe.Salt(c.id, p.creatorSecret, p.beaconSecret, p.acc)
	switch {
	case c.mode == types.ModeOpen:
		p.salt = openSalt(c.id)
		p.badge = BadgeOpen
	case p.creatorRevealed && p.beaconRevealed:
		p.badge = BadgeBoth
	case p.creatorRevealed:
		p.badge = BadgeCreatorOnly
	case p.beaconRevealed:
		p.badge = BadgeBeaconOnly
	default:
		p.badge = BadgeFallback
	}
	p.finalHeight = h
	c.state = types.StateFinal
	c.st.final = true
	chain.Emit("CollectionFinal", "cid", c.id, "salt", p.salt, "badge", p.badge)
}

// VerifyProvenance recomputes every commitment and the salt from public
// data. True only for a Final collection whose record is consistent.
func VerifyProvenance(cid string) bool {
	c := mustCollection(cid)
	if c.state != types.StateFinal {
		return false
	}
	p := c.prov
	if c.mode == types.ModeOpen {
		return p.salt == openSalt(c.id)
	}
	chainID := runtime.ChainID()
	if p.creatorRevealed && safe.Commit(chainID, c.id, roleCreator, p.creatorSecret) != p.creatorCommit {
		return false
	}
	if p.beaconRevealed && !usesProvider(c) && safe.Commit(chainID, c.id, roleBeacon, p.beaconSecret) != p.beaconCommit {
		return false
	}
	// A provider's value was checked when consumed (FulfillRandomness or
	// Finalize) against the provider's verified round (p.round); it is recomputable off chain
	// from the provider's public source (e.g. the drand round).
	return p.salt == safe.Salt(c.id, p.creatorSecret, p.beaconSecret, p.acc)
}

// FairLaunch is true only for a Final, consistent collection whose map no
// single party could choose: launched with the beacon and finalized with
// both secrets or with the beacon's alone (after the creator stayed
// silent). Creator-only collections (no beacon: the creator alone knew the
// only secret and could steer the last mint, SA-M2) and fallbacks are not
// fair launches, even when VerifyProvenance is true.
func FairLaunch(cid string) bool {
	c := mustCollection(cid)
	if c.mode == types.ModeOpen || !VerifyProvenance(cid) || !c.useBeacon {
		return false
	}
	return c.prov.badge == BadgeBoth || c.prov.badge == BadgeBeaconOnly
}

func isBurned(c *collection, commit string) bool {
	for _, b := range c.burnedCommits {
		if b == commit {
			return true
		}
	}
	return false
}

// Provenance is the whole record as JSON; secrets and salt stay "" until
// revealed / final.
func Provenance(cid string) string {
	c := mustCollection(cid)
	w := &safe.JSONWriter{}
	w.BeginObject()
	w.StrField("cid", c.id)
	w.StrField("chainId", runtime.ChainID())
	w.StrField("state", stateAt(c, height()).String())
	w.IntField("minted", c.minted())
	w.IntField("reserved", c.reserved)
	if p := c.prov; p != nil {
		w.StrField("mode", modeName(c.mode))
		w.BoolField("useBeacon", c.useBeacon)
		w.StrField("beaconSource", c.beaconSource)
		w.IntField("round", p.round)
		w.IntField("roundHeight", p.roundHeight)
		w.StrField("creatorCommit", p.creatorCommit)
		w.StrField("beaconCommit", p.beaconCommit)
		w.StrField("entropy", p.acc)
		w.StrField("creatorSecret", p.creatorSecret)
		w.StrField("beaconSecret", p.beaconSecret)
		w.StrField("salt", p.salt)
		w.StrField("badge", p.badge)
		w.IntField("revealDeadline", revealDeadline(c))
		w.IntField("finalHeight", p.finalHeight)
		w.BoolField("verified", VerifyProvenance(cid))
		w.BoolField("fair", FairLaunch(cid))
	}
	w.EndObject()
	return w.String()
}

// Salt is cid's final salt (hex), "" before Final (M-5: the upload adapter
// and other readers no longer parse Provenance JSON).
func Salt(cid string) string {
	c := mustCollection(cid)
	if c.state != types.StateFinal {
		return ""
	}
	return c.prov.salt
}

package core

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/safe/v2"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia4/types/v2"
)

// Pluggable randomness sources (beacon v2).
//
// A collection launched with useBeacon picks its second entropy source at
// Launch (LaunchSpec.BeaconSource, frozen by I-6):
//
//   - types.BeaconCommitted: the platform beacon's commit-reveal
//     (provenance.gno; BeaconCommit before the first mint,
//     RevealBeaconSecret after the creator).
//   - the package path of a randomness provider realm: a public random
//     value nobody can know in advance, e.g. a drand round relayed and
//     BLS-verified on chain (gnolang/gno#6268 p/drand + r/drand). Nothing
//     is committed before the sale; the round is fixed by the creator's
//     reveal (same transaction) or, for a silent creator, in the grace
//     period / at the deadline, and its value is then consumed by whoever
//     calls first (FulfillRandomness or Finalize): no caller can skip it.
//
// Before any provider is approved (randomness.add) a keeper must run that
// requests in the grace period for silent creators and fulfills bound
// rounds as soon as they are published (README "Randomness keeper").
//
// A provider realm registers itself (its id is its package path, as for
// engines) and is usable only after the admin approves it through the
// timelocked op randomness.add; randomness.deprecate stops new launches,
// running collections finish with it. So a drand provider plugs in without
// a core redeploy. Its methods are declared in its own realm, so core
// calling them runs the provider with the provider's authority (interrealm
// v2 borrow rule #1): it cannot write core state, and with no cur it cannot
// call a core mutator.
//
// Order with a provider (same guarantees as the committed beacon, SA-M1;
// CV-M1: the outcome never depends on who calls, or when):
//
//  1. the creator reveals until revealDeadline - BeaconGraceBlocks; the
//     reveal itself binds the collection to provider.Target() in the same
//     transaction, a round nobody knows yet (its secret is public now, so
//     nobody holding a choice learns anything new later);
//  2. a silent creator: RequestRandomness (anyone, a keeper) inside the
//     grace period, or the first Finalize after revealDeadline, binds the
//     round instead — the creator's window is closed by then;
//  3. once the provider has the bound round (and not in the binding
//     block, CV-I6), FulfillRandomness or Finalize (anyone, before or
//     after the deadline) takes its value as the beacon secret and the
//     collection is Final (2/2 after the creator, beacon-only otherwise).
//     After the deadline Finalize refuses to fall back while the bound
//     round may still arrive;
//  4. fallback (creator-only / fallback badge, never a FairLaunch) only
//     once the provider failed to deliver for ProviderWaitBlocks after the
//     deadline or the binding, whichever is later.
//
// A provider that panics aborts the calling transaction (a realm-boundary
// panic cannot be recovered); if an approved provider breaks, the admin
// deprecates it and, after the wait, Finalize stops calling it.
type RandomnessProvider interface {
	// Name is a short label for UIs, e.g. "drand quicknet".
	Name() string
	// Target is the round a request made in the current block is bound
	// to. Its value must be unknowable to anyone at this block (a round
	// published strictly in the future). Read-only.
	Target() int64
	// Randomness is round's verified value as 64 lowercase hex characters
	// (32 bytes), or "" while it is not available. Read-only.
	Randomness(round int64) string
}

type providerRecord struct {
	id               string
	name             string
	impl             RandomnessProvider
	active           bool // approved by the admin and not deprecated
	registeredHeight int64
}

var (
	providers       avl.Tree // provider pkgpath -> *providerRecord
	activeProviders int64
)

const MaxProviderNameLen = 64

// RegisterRandomnessProvider stores the calling realm's provider. It is
// inert until the admin approves it (randomness.add, timelocked).
func RegisterRandomnessProvider(cur realm, p RandomnessProvider) string {
	assertNoDeposit(cur)
	id := cur.Previous().PkgPath()
	if !strings.HasPrefix(id, runtime.ChainDomain()+"/r/") || strings.Contains(id, "#") {
		panic("a randomness provider registers from its own realm (an /r/ package, not a sub-realm or wallet)")
	}
	if p == nil {
		panic("nil provider")
	}
	if providers.Has(id) {
		panic("randomness provider already registered: " + id)
	}
	name := p.Name()
	safe.AssertNonEmptyText("provider name", name, MaxProviderNameLen)
	providers.Set(id, &providerRecord{id: id, name: name, impl: p, registeredHeight: height()})
	chain.Emit("RandomnessProviderRegistered", "id", id, "name", name)
	return id
}

func mustProvider(id string) *providerRecord {
	v := providers.Get(id)
	if v == nil {
		panic("unknown randomness provider " + id)
	}
	return v.(*providerRecord)
}

func assertActiveProvider(id string) {
	if !mustProvider(id).active {
		panic("randomness provider " + id + " is not approved")
	}
}

// beaconAvailable: some unpredictable second source exists, so no launch
// may opt out of it (SA-M2).
func beaconAvailable() bool { return beacon != "" || activeProviders > 0 }

func usesProvider(c *collection) bool {
	return c.useBeacon && c.beaconSource != types.BeaconCommitted
}

// RequestRandomness binds a provider-backed collection whose creator stayed
// silent to the provider's next unknowable round (a creator's reveal binds
// it itself). Permissionless and never paused (I-2); after the deadline the
// first Finalize binds instead.
func RequestRandomness(cur realm, cid string) int64 {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	assertRevealOpen(c, h)
	if !usesProvider(c) {
		panic("this collection does not use a randomness provider")
	}
	if c.minted() == 0 { // SEC-F1 (SA-I9): a 0-mint sale stays abortable
		panic("nothing was minted; the creator may abort and relaunch instead")
	}
	p := c.prov
	if p.round != 0 {
		panic("randomness already requested for round " + itoa(p.round))
	}
	if !p.creatorRevealed && h < revealDeadline(c)-BeaconGraceBlocks {
		panic("randomness is requested after the creator reveals, or in the window's last " +
			itoa(BeaconGraceBlocks) + " blocks")
	}
	if !bindRound(c, h) {
		panic("randomness provider returned an invalid or already published round; retry in a later block")
	}
	return p.round
}

// FulfillRandomness takes the bound round's value from the provider as the
// beacon secret and finalizes (2/2 after the creator, beacon-only when it
// stayed silent). Permissionless and never paused (I-2); works before and
// after the deadline while the collection is Closed.
func FulfillRandomness(cur realm, cid string) {
	assertNoDeposit(cur)
	c := mustCollection(cid)
	h := height()
	refresh(c, h)
	if c.state != types.StateClosed {
		panic("secrets are accepted only after the sale closed (state " + c.state.String() + ")")
	}
	if !usesProvider(c) {
		panic("this collection does not use a randomness provider")
	}
	if c.minted() == 0 { // SEC-F1 (SA-I9): a 0-mint sale stays abortable
		panic("nothing was minted; the creator may abort and relaunch instead")
	}
	p := c.prov
	if p.round == 0 {
		panic("randomness was not requested yet")
	}
	if h <= p.roundHeight {
		panic("round " + itoa(p.round) + " was bound in this block; fulfill it in a later one")
	}
	v := mustProvider(c.beaconSource).impl.Randomness(p.round)
	if v == "" {
		panic("round " + itoa(p.round) + " is not available from the provider yet")
	}
	consumeRound(c, safe.AssertHex("randomness", v, 32), h)
}

// bindRound fixes the collection's round to provider.Target() at height h.
// It refuses (false) a non-positive round or one whose value the provider
// already has: that value would be known before binding (CV-I6).
func bindRound(c *collection, h int64) bool {
	impl := mustProvider(c.beaconSource).impl
	round := impl.Target()
	if round <= 0 || isRandomness(impl.Randomness(round)) {
		return false
	}
	c.prov.round, c.prov.roundHeight = round, h
	chain.Emit("RandomnessRequested", "cid", c.id, "provider", c.beaconSource, "round", itoa(round))
	return true
}

func consumeRound(c *collection, v string, h int64) {
	p := c.prov
	p.beaconSecret = v
	p.beaconRevealed = true
	chain.Emit("BeaconRevealed", "cid", c.id, "provider", c.beaconSource, "round", itoa(p.round), "secret", v)
	finalize(c, h)
}

// providerWaitEnd is the last height at which Finalize still waits for the
// provider: ProviderWaitBlocks after the deadline or the binding.
func providerWaitEnd(c *collection) int64 {
	from := revealDeadline(c)
	if c.prov.roundHeight > from {
		from = c.prov.roundHeight
	}
	return from + ProviderWaitBlocks
}

// settleProvider is Finalize's provider step after the deadline (CV-M1).
// It returns true when Finalize is done: the round was bound now (a later
// Finalize or FulfillRandomness takes its value), or its value finalized
// the collection. It returns false only when the provider is provably
// unavailable — no usable value after providerWaitEnd — and Finalize falls
// back (creator-only / fallback, never a FairLaunch). While the bound round
// may still arrive it refuses, so nobody can pick the fallback by not
// fulfilling. After the wait a deprecated provider is not called at all
// (escape hatch for a provider whose code aborts every call).
func settleProvider(c *collection, h int64) bool {
	p := c.prov
	waited := h > providerWaitEnd(c)
	if waited && !mustProvider(c.beaconSource).active {
		return false
	}
	if p.round == 0 {
		if bindRound(c, h) {
			return true
		}
		if waited {
			return false
		}
		panic("the randomness provider cannot bind a round now; retry later (fallback after height " +
			itoa(providerWaitEnd(c)) + ")")
	}
	if h > p.roundHeight {
		if v := mustProvider(c.beaconSource).impl.Randomness(p.round); isRandomness(v) {
			consumeRound(c, safe.AssertHex("randomness", v, 32), h)
			return true
		}
	}
	if waited {
		return false
	}
	panic("waiting for randomness round " + itoa(p.round) + " (FulfillRandomness once it is published; fallback after height " +
		itoa(providerWaitEnd(c)) + ")")
}

// isRandomness: a provider value core accepts (64 hex characters).
func isRandomness(v string) bool {
	if len(v) != 64 {
		return false
	}
	for i := 0; i < len(v); i++ {
		c := v[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

// RandomnessProviders lists registered providers (by path) as JSON:
// [{id, name, active, registeredHeight}]. Registration is open, so only
// "active" ones (admin-approved) can be chosen at Launch.
func RandomnessProviders(offset, limit int64) string {
	w := &safe.JSONWriter{}
	w.BeginArray()
	providers.IterateByOffset(int(offset), int(clampLimit(limit)), func(_ string, v any) bool {
		r := v.(*providerRecord)
		w.BeginObject()
		w.StrField("id", r.id)
		w.StrField("name", r.name)
		w.BoolField("active", r.active)
		w.IntField("registeredHeight", r.registeredHeight)
		w.EndObject()
		return false
	})
	w.EndArray()
	return w.String()
}

