		}
		o.WriteString(`<circle cx="` + itoa(sx) + `" cy="` + itoa(sy) + `" r="54" fill="` + sc + `" opacity=".18"/><circle cx="` + itoa(sx) + `" cy="` + itoa(sy) + `" r="34" fill="` + sc + `" opacity=".85"/>`)
	}
	// the maquette's shadow on the sheet, away from the sun
	sdx := 0
	if d.light == lMorning {
		sdx = 26
